# ============================================================
# APP-LOCAL CONFIG (not shared with quiz.py)
# ============================================================
# PIN SYSTEM
# v-RAM-fix: cap in-memory PIL-image page caches (pdf_cache/qbm_cache) so an
# abandoned upload flow (user never finishes channel-select) can't leak heavy
# decoded images forever. Self-overwrites per uid, but this adds a hard
# ceiling + oldest-key eviction as a safety net.
_PAGE_CACHE_MAX_ENTRIES = 50

def _cap_page_cache(cache: dict) -> None:
    while len(cache) > _PAGE_CACHE_MAX_ENTRIES:
        cache.pop(next(iter(cache)), None)

# SPEED: cache raw downloaded PDF bytes by file_id so re-running /pdf on the
# SAME file (retry, different page range, re-generate) skips the Telegram
# download entirely. Small cap + oldest-eviction, same safety pattern as
# _cap_page_cache. In-memory only — resets on deploy/restart, which is fine
# since it's purely a speed optimization, never a correctness dependency.
_PDF_BYTES_CACHE_MAX = 40  # HF has 16GB RAM (not Render free tier) — safe to hold more raw PDFs
_pdf_bytes_cache = {}  # file_id -> bytes

# SPEED: Telegram's file_id changes on every re-upload/re-forward of the SAME
# file, but file_unique_id stays identical for identical file content across
# uploads (Telegram guarantees this). This secondary index lets a fresh
# upload of a PDF the user already sent before still hit the bytes cache,
# instead of re-downloading just because the file_id differs this time.
_pdf_unique_id_index = {}  # file_unique_id -> file_id (points into _pdf_bytes_cache)

def _cap_pdf_bytes_cache() -> None:
    while len(_pdf_bytes_cache) > _PDF_BYTES_CACHE_MAX:
        evicted_fid = next(iter(_pdf_bytes_cache))
        _pdf_bytes_cache.pop(evicted_fid, None)
        # Also drop any unique_id index entries pointing at the evicted file_id
        for uid, fid in list(_pdf_unique_id_index.items()):
            if fid == evicted_fid:
                _pdf_unique_id_index.pop(uid, None)

# SPEED+DURABILITY: disk-persisted L2 cache, keyed by file_unique_id (stable
# across re-uploads) -> content-addressed sha256 filename. Unlike the
# in-memory cache above, this survives a bot process restart (idle-sleep/
# wake, crash-recover) since it lives on disk, not RAM -- only wiped by a
# full redeploy/rebuild that resets the filesystem. Cheap: no external
# storage/bandwidth cost, just local disk the process already has.
_PDF_DISK_CACHE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "pdf_cache")
_PDF_DISK_CACHE_MAX = 60
_PDF_DISK_INDEX_PATH = os.path.join(_PDF_DISK_CACHE_DIR, "_index.json")

def _pdf_disk_index_load() -> dict:
    try:
        with open(_PDF_DISK_INDEX_PATH, "r") as f:
            return json.load(f)
    except Exception:
        return {}

def _pdf_disk_index_save(idx: dict) -> None:
    try:
        os.makedirs(_PDF_DISK_CACHE_DIR, exist_ok=True)
        with open(_PDF_DISK_INDEX_PATH, "w") as f:
            json.dump(idx, f)
    except Exception as e:
        logger.warning(f"[PDF DiskCache] index save failed: {e}")

def _pdf_disk_cache_get(file_unique_id: str):
    if not file_unique_id:
        return None
    idx = _pdf_disk_index_load()
    sha = idx.get(file_unique_id)
    if not sha:
        return None
    path = os.path.join(_PDF_DISK_CACHE_DIR, f"{sha}.pdf")
    try:
        with open(path, "rb") as f:
            data = f.read()
        os.utime(path, None)  # bump mtime for LRU-ish eviction below
        return data
    except Exception:
        return None

def _pdf_disk_cache_put(file_unique_id: str, data: bytes) -> None:
    if not file_unique_id or not data:
        return
    try:
        os.makedirs(_PDF_DISK_CACHE_DIR, exist_ok=True)
        sha = hashlib.sha256(data).hexdigest()
        path = os.path.join(_PDF_DISK_CACHE_DIR, f"{sha}.pdf")
        if not os.path.exists(path):
            with open(path, "wb") as f:
                f.write(data)
        idx = _pdf_disk_index_load()
        idx[file_unique_id] = sha
        _pdf_disk_index_save(idx)
        # Evict oldest-by-mtime PDF files beyond the cap
        files = [f for f in os.listdir(_PDF_DISK_CACHE_DIR) if f.endswith(".pdf")]
        if len(files) > _PDF_DISK_CACHE_MAX:
            files.sort(key=lambda f: os.path.getmtime(os.path.join(_PDF_DISK_CACHE_DIR, f)))
            for f in files[:len(files) - _PDF_DISK_CACHE_MAX]:
                evicted_sha = f[:-4]
                try:
                    os.remove(os.path.join(_PDF_DISK_CACHE_DIR, f))
                except Exception:
                    pass
                for uid_k, sha_v in list(idx.items()):
                    if sha_v == evicted_sha:
                        idx.pop(uid_k, None)
            _pdf_disk_index_save(idx)
    except Exception as e:
        logger.warning(f"[PDF DiskCache] write failed: {e}")

async def _download_pdf_cached(file_id: str, progress_cb=None, chat_id: int = None,
                                message_id: int = None, file_unique_id: str = None) -> bytes:
    cached = _pdf_bytes_cache.get(file_id)
    if cached is not None:
        logger.info(f"[PDF Cache] hit for file_id={file_id[:16]}... skipping download")
        return cached
    # Same file content re-uploaded under a new file_id -> still skip download
    # by matching on the stable file_unique_id instead.
    if file_unique_id:
        prior_fid = _pdf_unique_id_index.get(file_unique_id)
        if prior_fid and prior_fid in _pdf_bytes_cache:
            logger.info(f"[PDF Cache] hit via file_unique_id={file_unique_id[:16]}... (re-upload) skipping download")
            data = _pdf_bytes_cache[prior_fid]
            _pdf_bytes_cache[file_id] = data  # also index under new file_id for this session
            _cap_pdf_bytes_cache()
            return data
        # In-memory missed (likely a restart since last time) -> check disk.
        disk_data = await asyncio.to_thread(_pdf_disk_cache_get, file_unique_id)
        if disk_data is not None:
            logger.info(f"[PDF DiskCache] hit via file_unique_id={file_unique_id[:16]}... (post-restart) skipping download")
            _pdf_bytes_cache[file_id] = disk_data
            _pdf_unique_id_index[file_unique_id] = file_id
            _cap_pdf_bytes_cache()
            return disk_data
    data = await download_tg_file(file_id, progress_cb=progress_cb, chat_id=chat_id, message_id=message_id)
    _pdf_bytes_cache[file_id] = data
    if file_unique_id:
        _pdf_unique_id_index[file_unique_id] = file_id
        await asyncio.to_thread(_pdf_disk_cache_put, file_unique_id, data)
    _cap_pdf_bytes_cache()
    return data

# SPEED: cache RENDERED page images by (content_hash, page_range) so a re-run
# of /pdf on the same file+range skips pdf2image rasterization too (the
# heaviest CPU step). Keyed by a hash of the actual PDF bytes (not file_id),
# so this also hits when the same PDF is re-uploaded under a new file_id.
_PDF_RENDER_CACHE_MAX = 15
_pdf_render_cache = {}  # (content_hash, page_range) -> pages list

def _cap_pdf_render_cache() -> None:
    while len(_pdf_render_cache) > _PDF_RENDER_CACHE_MAX:
        _pdf_render_cache.pop(next(iter(_pdf_render_cache)), None)

def _render_pdf_cached(file_id: str, pdf_bytes: bytes, page_range: str = None):
    """Wraps pdf_to_images_safe with a render cache keyed by (content_hash, page_range)
    -- content_hash (not file_id) so a re-upload of the identical PDF still hits."""
    content_hash = hashlib.sha256(pdf_bytes).hexdigest()
    key = (content_hash, page_range or "ALL")
    cached = _pdf_render_cache.get(key)
    if cached is not None:
        logger.info(f"[Render Cache] hit for hash={content_hash[:12]}...:{key[1]} — skipping rasterization")
        return True, cached
    ok, pages = pdf_to_images_safe(pdf_bytes, page_range)
    if ok and pages:
        _pdf_render_cache[key] = pages
        _cap_pdf_render_cache()
    return ok, pages

PIN_ENABLED = {}  # chat_id -> bool (in-memory, also saved to DB)
PDF_AUTO_ENABLED = {}  # chat_id -> bool (in-memory, also saved to DB) — /pdf on|off

# ============================================================
# /cancel — instantly stop any running activity for this chat (bot stays alive)
# ============================================================
import contextvars
import itertools
CANCEL_FLAGS = {}  # chat_id -> bool, checked by long loops between steps
ACTIVE_JOB_LABEL = {}  # chat_id -> human-readable label of the job currently running
CURRENT_JOB_ID = {}  # chat_id -> int, id of the job currently running in that chat
_job_id_counter = itertools.count(1)
_current_job_chat_id_ctx = contextvars.ContextVar("_current_job_chat_id_ctx", default=None)
_qbm_key_offset_ctx = contextvars.ContextVar("_qbm_key_offset_ctx", default=0)

def is_cancelled(chat_id=None):
    if chat_id is None:
        chat_id = _current_job_chat_id_ctx.get()
    if chat_id is None:
        return False
    return CANCEL_FLAGS.get(chat_id, False)

def clear_cancel(chat_id):
    CANCEL_FLAGS[chat_id] = False

def new_job_id(chat_id) -> int:
    """প্রতিটা নতুন job (/pdf, /qbm, /tf, /txt ...) শুরু হওয়ার সময় একটা
    ইউনিক job_id নেয়। এই id-টা ওই job-এর নিজস্ব cancel button-এ বসানো থাকে,
    তাই আগের কোনো (শেষ হয়ে যাওয়া) job-এর পুরনো button চাপলে কিছু হয় না —
    শুধু বর্তমানে চলমান job-এর button-ই কাজ করে।"""
    jid = next(_job_id_counter)
    CURRENT_JOB_ID[chat_id] = jid
    return jid

def _cancel_kb(chat_id, job_id=None) -> dict:
    """প্রতিটা কমান্ডের নিজস্ব (per-job) inline 'Cancel' বাটন — এই বাটনে
    ওই job-এর job_id বসানো থাকে। ট্যাপ করলে শুধু ওই নির্দিষ্ট job-ই বন্ধ হয়;
    যদি ইতিমধ্যে অন্য নতুন job শুরু হয়ে যায় (বা এটা আগেই শেষ হয়ে থাকে),
    এই পুরনো বাটন আর কাজ করবে না।"""
    if job_id is None:
        job_id = CURRENT_JOB_ID.get(chat_id, 0)
    return {"inline_keyboard": [[{"text": "🛑 Cancel", "callback_data": f"jobcancel_{chat_id}_{job_id}"}]]}


def set_active_job(chat_id, label):
    ACTIVE_JOB_LABEL[chat_id] = label

def clear_active_job(chat_id):
    ACTIVE_JOB_LABEL.pop(chat_id, None)

async def handle_cancel_command(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg.get("from", {}).get("id")
    if not await db_is_owner_or_admin(uid):
        return
    CANCEL_FLAGS[chat_id] = True
    running_label = ACTIVE_JOB_LABEL.get(chat_id)
    if running_label:
        await send_msg(chat_id, "🛑 বন্ধ করা হলো।\nযে কাজ থামলো: " + running_label)
    else:
        await send_msg(chat_id, "🛑 এই মুহূর্তে এই চ্যাটে cancel-able কোনো কাজ চলছে না।")

