# ============================================================
# MULTI-AI MODEL ROTATION (Vision MCQ generation)
# Order: Gemini (via pdf_handler) → NVIDIA Llama 3.2 11B Vision
#        → OpenRouter Qwen2-VL 72B → Nemotron Nano Omni → Gemma → Hugging Face
# Missing keys are skipped silently — never raise.
# ============================================================
import base64 as _b64_ai
from pdf_handler import generate_mcq_from_image as _gemini_gen_mcq

def _img_to_data_url(img) -> str:
    try:
        buf = BytesIO()
        if hasattr(img, "save"):
            img.save(buf, format="JPEG", quality=85)
            data = buf.getvalue()
        elif isinstance(img, (bytes, bytearray)):
            data = bytes(img)
        else:
            data = bytes(img)
        return "data:image/jpeg;base64," + _b64_ai.b64encode(data).decode()
    except Exception as e:
        logger.warning(f"[img_to_data_url] JPEG encode failed, retrying as PNG: {e}")
        try:
            buf2 = BytesIO()
            if hasattr(img, "save"):
                img.convert("RGB").save(buf2, format="PNG")
                return "data:image/png;base64," + _b64_ai.b64encode(buf2.getvalue()).decode()
        except Exception as e2:
            logger.error(f"[img_to_data_url] PNG retry also failed: {e2}")
        return ""


def _img_to_data_url_groq(img, mcq_count_hint=None, prompt_len_hint=None) -> str:
    """Groq's qwen3.6-27b has an 8000 TPM (tokens-per-minute) hard limit per
    key, shared across prompt + image + output combined. The MAIN QBM
    extraction prompt is a fixed ~2400 tokens, but Call 2 (miss-check) and
    Call 3 (verify) build a DIFFERENT, size-VARYING prompt that embeds the
    already-extracted MCQ list as JSON -- this can be several thousand
    tokens on pages with 25-30+ MCQs, and using the fixed 2400 estimate for
    those calls chronically underbudgets the prompt, leaving almost nothing
    for the image and blowing the 8000 TPM limit (this was the cause of the
    /auto 429 "TPM/per-request-too-large" errors on Call 2/3, since those
    callers were passing their own large prompt but the sizer still assumed
    the fixed 2400 number for the short static prompt).
    FIX: callers with a variable-size prompt now pass prompt_len_hint (the
    actual prompt string) so its real token count is used instead of the
    hardcoded 2400 default (which remains the correct estimate only for the
    static main extraction prompt when prompt_len_hint is not given)."""
    try:
        if not hasattr(img, "save"):
            return _img_to_data_url(img)
        image = img
        if hasattr(image, "convert"):
            image = image.convert("RGB")
        orig_w, orig_h = image.size
        if prompt_len_hint:
            # ~3.5 chars/token was the original ASCII-calibrated ratio, but
            # Call 2/3 prompts embed Bangla question text (q_summary), and
            # Bangla Unicode tokenizes far denser in BPE tokenizers (~1.3-1.8
            # chars/token, not 2.6+) -- the old 2.6 ratio was still too
            # generous for Bangla-heavy prompts and chronically underbudgeted
            # them, causing the persistent 413/429 "Requested 8141/8691"
            # errors on pages with many MCQs. Detect Bangla content (any char
            # in the Bengali Unicode block) and use a much tighter ratio.
            _has_bangla = any('\u0980' <= ch <= '\u09FF' for ch in prompt_len_hint[:500])
            _chars_per_token = 1.6 if _has_bangla else 2.6
            PROMPT_TOKENS = max(400, int(len(prompt_len_hint) / _chars_per_token) + 300)
        else:
            # Measured from the compacted static QBM_EXTRACT_PROMPT_DEFAULT
            # (~8k chars / 3.5) + margin. Only accurate for that fixed prompt.
            PROMPT_TOKENS = 2400
        SAFETY_MARGIN = 1500  # 2026-08-07: 2200 + 4500-cap output left almost no
        # image budget for /tf's long Bangla prompt (~1850 tokens with the
        # min/max hint prefix) — reserved total hit 7943/8000, so the image
        # got squeezed to the 300-token floor and requests still landed at
        # ~7500+/8000, causing live 429 TPM errors. Lowered output cap
        # (150/MCQ, max 3500) + this smaller margin restores real headroom
        # (~1350 tokens for the image) while still leaving buffer for
        # rotator-collision retries.
        if isinstance(mcq_count_hint, (tuple, list)) and len(mcq_count_hint) == 2:
            est_count = mcq_count_hint[1]
        elif isinstance(mcq_count_hint, (int, float)) and mcq_count_hint:
            est_count = mcq_count_hint
        else:
            est_count = 25  # default full-page mode target ceiling
        # Output tokens per MCQ — MUST match _post_openai_compat's
        # dynamic_max_tokens formula exactly (max(900, min(4500, count*180+300))),
        # since that's the actual max_tokens value sent to Groq and counted
        # against the 8000 TPM budget. A mismatch here means this sizer
        # underestimates the real reserved output, silently overshooting
        # the TPM limit regardless of how small the image gets.
        est_output_tokens = max(900, min(3800, int(est_count) * 175 + 300))
        TOKEN_BUDGET = max(300, 8000 - PROMPT_TOKENS - est_output_tokens - SAFETY_MARGIN)
        # qwen3.6-27b vision tokenization is roughly proportional to
        # (width/28)*(height/28) patches + a fixed base overhead.
        # Use a conservative multiplier (1.15x) since observed 413s show
        # the real token count runs higher than the raw patch estimate.
        for max_dim, quality in [
            (max(orig_w, orig_h), 85),   # try full resolution first
            (1280, 80),
            (1024, 75),
            (896, 65),
            (768, 60),
            (640, 50),
            (512, 45),
            (384, 40),
            (256, 35),
            (192, 30),
        ]:
            w, h = orig_w, orig_h
            if max(w, h) > max_dim:
                scale = max_dim / max(w, h)
                w, h = max(1, int(w * scale)), max(1, int(h * scale))
            est_tokens = int((w / 28) * (h / 28) * 1.6) + 300
            is_last = (max_dim == 192)
            if est_tokens <= TOKEN_BUDGET or is_last:
                resized = image.resize((w, h)) if (w, h) != (orig_w, orig_h) else image
                buf = BytesIO()
                resized.save(buf, format="JPEG", quality=quality)
                return "data:image/jpeg;base64," + _b64_ai.b64encode(buf.getvalue()).decode()
        # Fallback (shouldn't reach here given the 192 floor above)
        buf = BytesIO()
        scale = 192 / max(orig_w, orig_h)
        w, h = max(1, int(orig_w * scale)), max(1, int(orig_h * scale))
        image.resize((w, h)).save(buf, format="JPEG", quality=30)
        return "data:image/jpeg;base64," + _b64_ai.b64encode(buf.getvalue()).decode()
    except Exception as e:
        logger.warning(f"[img_to_data_url_groq] resize failed, falling back to full-size: {e}")
        return _img_to_data_url(img)

async def _safe_error_reply(chat_id, e: Exception, context: str = ""):
    """SECURITY: never leak raw exception text to the user — log full detail,
    notify owner privately, and show the user a generic Bengali fallback."""
    logger.error(f"[ERROR]{f' [{context}]' if context else ''}: {e}", exc_info=True)
    try:
        await notify_owner(f"🚨 QuizBot ERROR{f' [{context}]' if context else ''}:\n{e}"[:4000])
    except Exception:
        pass
    await send_msg(chat_id, "❌ কিছু একটা সমস্যা হয়েছে। একটু পর আবার চেষ্টা করুন।")


