async def _gen_hf(img, topic, count):
    """Hugging Face Inference API — free tier vision fallback (last resort)."""
    data_url = _img_to_data_url(img)
    if not data_url:
        return []
    keys = hf_rotator.ordered_keys()
    if not keys:
        return []
    model = os.environ.get("HF_VISION_MODEL", "meta-llama/Llama-3.2-11B-Vision-Instruct")
    payload = {
        "model": model,
        "messages": [{
            "role": "user",
            "content": [
                {"type": "text", "text": _build_mcq_prompt(topic, count)},
                {"type": "image_url", "image_url": {"url": data_url}}
            ]
        }],
        "max_tokens": 8192,
        "temperature": 0.3,
    }
    for key in keys:
        headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
        try:
            async with httpx.AsyncClient(timeout=30) as c:
                r = await c.post(
                    "https://router.huggingface.co/v1/chat/completions",
                    headers=headers, json=payload
                )
                if r.status_code == 429:
                    hf_rotator.mark_rate_limited(key)
                    continue
                if r.status_code >= 400:
                    logger.warning(f"[AI-ROT] hf HTTP {r.status_code}: {r.text[:200]}")
                    continue
                j = r.json()
                txt = j.get("choices", [{}])[0].get("message", {}).get("content", "") or ""
        except Exception as e:
            logger.warning(f"[AI-ROT] hf err: {e}")
            continue
        parsed = _parse_mcq_json(txt)
        if parsed:
            hf_rotator.mark_healthy(key)
            return parsed
    return []

_AI_PROVIDERS_ORDER = ["nvidia", "openrouter_qwen", "nemotron", "gemma", "hf"]

_AI_FALLBACK_FNS = {
    "nvidia":          _gen_nvidia,
    "openrouter_qwen": _gen_openrouter_qwen,
    "nemotron":        _gen_nemotron,
    "gemma":           _gen_gemma,
    "hf":              _gen_hf,
}

_THIN_EXPLANATION_PATTERNS = [
    r'^সঠিক\s*উত্তর\s*[:\-—]?\s*[a-dA-D১-৪]?\s*[.।]?$',
    r'^উত্তর\s*[:\-—]?\s*[a-dA-D১-৪]?\s*[.।]?$',
    r'^the\s*(correct\s*)?answer\s*is\s*[a-d]?\.?$',
    r'^answer\s*[:\-—]\s*[a-d]\.?$',
    r'^option\s*[a-d]\s*is\s*(the\s*)?correct\.?$',
]

def _is_thin_explanation(exp: str) -> bool:
    """
    Detects an explanation that ONLY names the answer (Part 1) with no
    source-derived surrounding context (Part 2) — heuristic check used to
    catch cases where the model ignored the two-part explanation rule.
    """
    e = (exp or "").strip()
    if not e:
        return True
    # strip any already-attached <img> tag before judging length/content
    e_no_img = re.sub(r'<img[^>]*>', '', e, flags=re.IGNORECASE).strip()
    if not e_no_img:
        return True
    if len(e_no_img) < 60:  # a genuine all-4-options explanation rarely fits under this
        return True
    for pat in _THIN_EXPLANATION_PATTERNS:
        if re.match(pat, e_no_img, re.IGNORECASE):
            return True
    return False

async def _repair_thin_explanations(mcqs: list, img, topic: str) -> list:
    """
    Targeted, single-pass repair for MCQs whose explanation only names the
    answer with no source-derived context — re-asks the model for JUST the
    explanation of those specific questions (not the whole page again), with
    an even stricter reminder of the two-part rule. Falls back to leaving the
    original explanation untouched if the repair call fails or still comes
    back thin (never blocks the MCQ from being delivered).
    """
    thin = [m for m in (mcqs or []) if _is_thin_explanation(m.get("explanation", ""))]
    if not thin:
        return mcqs
    questions_block = "\n".join(
        f'{i+1}. Q: {m["question"]}\n'
        f'   Options: A) {m["options"][0]}  B) {m["options"][1]}  '
        f'C) {m["options"][2]}  D) {m["options"][3]}\n'
        f'   Correct: {m["answer"]}'
        for i, m in enumerate(thin)
    )
    repair_prompt = (
        f"Topic: {topic}\n"
        f"For EACH numbered question below, write a proper explanation using the "
        f"attached source image. A valid explanation must briefly cover ALL 4 "
        f"options: (1) confirm the correct option and why it's right, (2) briefly "
        f"say why each of the other 3 options is wrong. Use the source image when "
        f"it has info about a wrong option; if the source has nothing on a "
        f"specific wrong option, use general knowledge to briefly explain why "
        f"it's incorrect — never leave any option unaddressed. Same language "
        f"as the source (Bengali or English). ~150-280 characters each.\n\n"
        f"{questions_block}\n\n"
        f"Return STRICT JSON array only, same order, no prose. "
        f"🚨 No <think>/reasoning text before the JSON — start immediately with '[': "
        f'[{{"explanation":"..."}}, ...]'
    )
    try:
        fixed_txt = await _gen_groq_raw_text(img, repair_prompt)
        fixed = _parse_explanation_only_json(fixed_txt)
        if fixed and len(fixed) == len(thin):
            for m, new_exp in zip(thin, fixed):
                if new_exp and not _is_thin_explanation(new_exp):
                    m["explanation"] = new_exp
    except Exception as e:
        logger.warning(f"[ExplanationRepair] failed, keeping originals: {e}")
    return mcqs

def _parse_explanation_only_json(text: str) -> list:
    if not text:
        return []
    s = text.strip()
    if s.startswith("```"):
        s = re.sub(r"^```(?:json)?\s*", "", s)
        s = re.sub(r"\s*```$", "", s)
    a, b = s.find("["), s.rfind("]")
    if a != -1 and b != -1 and b > a:
        s = s[a:b+1]
    try:
        data = json.loads(s)
    except Exception:
        return []
    if not isinstance(data, list):
        return []
    return [str(it.get("explanation", "")).strip()[:500] if isinstance(it, dict) else "" for it in data]

async def _gemini_verify_raw_text(img, prompt: str) -> str:
    """Same job as _gen_groq_raw_text but via Gemini — used to get a second,
    provider-diverse opinion on missed-content verification. Best-effort:
    empty string on any failure, never raises (caller treats empty as
    'nothing extra found')."""
    try:
        if not key_rotator.keys:
            return ""
        from google import genai as gai
        from google.genai import types
        from pdf_handler import image_to_base64
        _ordered = key_rotator.ordered_keys()
        key = _ordered[0] if _ordered else key_rotator.get_key()
        key_rotator.record_call(key)
        client = gai.Client(api_key=key)
        img_b64 = image_to_base64(img)

        def _call():
            return client.models.generate_content(
                model="gemini-3.6-flash",
                contents=[
                    types.Part.from_text(text=prompt),
                    types.Part.from_bytes(data=base64.b64decode(img_b64), mime_type="image/jpeg")
                ]
            )
        response = await asyncio.wait_for(asyncio.to_thread(_call), timeout=20)
        key_rotator.mark_healthy(key)
        return response.text or ""
    except Exception as e:
        err_str = str(e)
        if "429" in err_str or "RESOURCE_EXHAUSTED" in err_str or "quota" in err_str.lower():
            key_rotator.mark_rate_limited(key)
        elif "SUSPENDED" in err_str.upper() or "API_KEY_INVALID" in err_str.upper():
            key_rotator.mark_banned(key)
        logger.warning(f"[GeminiVerify] failed: {e}")
        return ""

async def _gen_groq_raw_text(img, prompt: str, mcq_count_hint=None) -> str:
    keys = groq_key_rotator.ordered_keys()
    data_url = _img_to_data_url_groq(img, prompt_len_hint=prompt) if keys else None
    if not keys:
        logger.warning("[GroqVerify] no Groq keys available")
    elif not data_url:
        logger.warning("[GroqVerify] image-to-data-url conversion failed")
    best_invalid_txt = ""  # longest non-empty-but-unparseable response, kept as
    # a last-resort fallback so a single key's truncated/malformed JSON
    # doesn't waste the whole attempt if every other key also fails.
    if keys and data_url:
        for key in keys:
            txt, status = await _post_openai_compat(
                "https://api.groq.com/openai/v1/chat/completions",
                key, "qwen/qwen3.6-27b",
                data_url, prompt, mcq_count_hint=mcq_count_hint
            )
            if txt:
                # 2026-08-07 bug: a key returning HTTP 200 with a non-empty
                # but truncated/malformed JSON body (e.g. Groq's dynamic
                # output cap cutting a response mid-string) used to be
                # treated as success here and returned immediately —
                # skipping all remaining Groq keys (and the NVIDIA/
                # OpenRouter/Nemotron/Gemma fallback below) even though 11
                # of 12 keys were never touched. This burned through the
                # daily TPD budget on just a handful of /tf pages. FIX:
                # validate the JSON here before accepting it as a real
                # success; on failure, keep trying the next key.
                try:
                    if _parse_mcq_json(txt):
                        groq_key_rotator.mark_healthy(key)
                        return txt
                    else:
                        logger.warning(f"[GroqVerify] key {key[:12]}... returned empty MCQ list, trying next key")
                except Exception as e:
                    logger.warning(f"[GroqVerify] key {key[:12]}... returned unparseable JSON ({e}), trying next key")
                    if len(txt) > len(best_invalid_txt):
                        best_invalid_txt = txt
                continue
            if status == 429:
                is_tpm_only = _key_429_is_tpm.get(key) is True
                groq_key_rotator.mark_rate_limited(key, daily_exhausted=not is_tpm_only)
                logger.warning(f"[GroqVerify] key {key[:12]}... rate-limited (429, daily_exhausted={not is_tpm_only}), trying next key")
            else:
                logger.warning(f"[GroqVerify] key {key[:12]}... failed (status={status}), trying next key")
    logger.warning("[GroqVerify] all Groq keys exhausted; trying NVIDIA/OpenRouter/Nemotron/Gemma fallback")
    # All Groq keys exhausted/failing -- rotate through other vision providers
    # instead of silently returning empty (previously killed the whole call).
    for rotator, url, model in (
        (nvidia_rotator, "https://integrate.api.nvidia.com/v1/chat/completions", "meta/llama-3.2-11b-vision-instruct"),
        (or_qwen_rotator, "https://openrouter.ai/api/v1/chat/completions", "google/gemma-4-31b-it:free"),
        (nemotron_rotator, "https://integrate.api.nvidia.com/v1/chat/completions", "nvidia/llama-3.1-nemotron-51b-instruct"),
        (gemma_rotator, "https://api.groq.com/openai/v1/chat/completions", "gemma2-9b-it"),
    ):
        if not rotator.ordered_keys():
            logger.warning(f"[GroqVerify] {rotator.label} has no keys configured, skipping")
            continue
        fb_data_url = data_url or _img_to_data_url_groq(img, prompt_len_hint=prompt)
        if not fb_data_url:
            break
        for key in rotator.ordered_keys():
            txt, status = await _post_openai_compat(url, key, model, fb_data_url, prompt, mcq_count_hint=mcq_count_hint)
            if txt:
                try:
                    if _parse_mcq_json(txt):
                        rotator.mark_healthy(key)
                        logger.info(f"[GroqVerify] fallback provider {rotator.label} succeeded")
                        return txt
                    else:
                        logger.warning(f"[GroqVerify] {rotator.label} key returned empty MCQ list, trying next")
                except Exception as e:
                    logger.warning(f"[GroqVerify] {rotator.label} key returned unparseable JSON ({e}), trying next")
                    if len(txt) > len(best_invalid_txt):
                        best_invalid_txt = txt
                continue
            if status == 429:
                rotator.mark_rate_limited(key)
    if best_invalid_txt:
        logger.warning(f"[GroqVerify] every provider exhausted; returning longest unparseable response ({len(best_invalid_txt)} chars) as last resort")
        return best_invalid_txt
    logger.error("[GroqVerify] every fallback provider exhausted, returning empty")
    return ""

_TF_PATTERNS_BN = ("বললে ভুল হবে", "সত্য বললে", "মিথ্যা বললে")


def _detect_chok_boxes(img) -> list:
    """
    CV-based box/cell detection for /chok pages using OpenCV contour detection.
    Finds rectangular bordered regions (ছক/box/table cells) on the page and
    returns their bounding boxes in normalized 0-1000 coordinates, ranked
    largest-area-first (roughly reading order isn't guaranteed, but size
    filtering removes noise). Zero AI cost — pure local CV, runs in a thread.

    This gives a REAL, deterministic box count independent of what the AI
    vision model claims to see, so we can code-verify "MCQ count >= box
    count" instead of trusting the AI's self-report alone.

    Best-effort: on any failure (bad image, no opencv, no boxes found),
    returns [] and callers must treat that as "unknown box count" — NOT as
    "zero boxes required".
    """
    try:
        import cv2
        import numpy as np
        arr = np.array(img.convert("L"))  # grayscale
        h, w = arr.shape[:2]
        # Adaptive threshold handles uneven scan lighting better than a fixed one
        thresh = cv2.adaptiveThreshold(
            arr, 255, cv2.ADAPTIVE_THRESH_MEAN_C, cv2.THRESH_BINARY_INV, 25, 10
        )
        # Morphological close to connect broken box borders (dashed/faint lines)
        kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3))
        closed = cv2.morphologyEx(thresh, cv2.MORPH_CLOSE, kernel, iterations=2)
        contours, _ = cv2.findContours(closed, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)

        page_area = w * h
        boxes = []
        for c in contours:
            x, y, cw, ch = cv2.boundingRect(c)
            area = cw * ch
            # Filter: must be a meaningfully sized rectangular region — not a
            # single character/line (too small) and not the whole page/a huge
            # background block (too large). These thresholds are deliberately
            # loose since textbook ছক boxes vary a lot in size.
            if area < page_area * 0.003 or area > page_area * 0.5:
                continue
            aspect = cw / max(ch, 1)
            if aspect > 25 or aspect < 0.03:
                continue  # skip degenerate slivers (stray table gridlines etc.)
            boxes.append((x, y, x + cw, y + ch, area))

        if not boxes:
            return []

        # De-duplicate near-identical/nested boxes (common with nested
        # borders/double-lines in scanned textbooks) by suppressing boxes
        # that are >90% contained inside a larger already-kept box.
        boxes.sort(key=lambda b: -b[4])
        kept = []
        for bx in boxes:
            x0, y0, x1, y1, _ = bx
            nested = False
            for kx0, ky0, kx1, ky1, _ in kept:
                ix0, iy0 = max(x0, kx0), max(y0, ky0)
                ix1, iy1 = min(x1, kx1), min(y1, ky1)
                if ix1 > ix0 and iy1 > iy0:
                    inter = (ix1 - ix0) * (iy1 - iy0)
                    this_area = (x1 - x0) * (y1 - y0)
                    if inter / max(this_area, 1) > 0.9:
                        nested = True
                        break
            if not nested:
                kept.append(bx)

        # Normalize to 0-1000 scale (matches _ocr_bbox_lookup convention)
        norm = []
        for x0, y0, x1, y1, _ in kept:
            norm.append([
                round(x0 / w * 1000), round(y0 / h * 1000),
                round(x1 / w * 1000), round(y1 / h * 1000),
            ])
        return norm
    except Exception as e:
        logger.warning(f"[ChokBoxDetect] detection failed, treating as unknown: {e}")
        return []


def _chok_box_coverage_note(img, mcqs: list) -> str:
    """
    Cross-checks CV-detected box count against a heuristic estimate of how
    many boxes the current MCQ set actually represents (proxy: total MCQ
    count, since ~80% are meant to be 1-per-box). If detected box count
    clearly exceeds current MCQ count, injects an explicit numeric
    instruction into the verify prompt so the AI isn't just trusting its own
    mental box-count — it gets a code-derived number to react to.
    Returns "" if detection found nothing (fails open — never blocks/reduces
    output) or coverage already looks sufficient.
    """
    try:
        boxes = _detect_chok_boxes(img)
    except Exception:
        boxes = []
    if not boxes:
        return ""
    box_count = len(boxes)
    n = len(mcqs or [])
    if n >= box_count:
        return ""
    gap = box_count - n
    return (
        f"\nCV BOX-DETECTION RESULT (independent of your own visual count): "
        f"automated detection found approximately {box_count} distinct "
        f"bordered box/cell regions on this page, but only {n} MCQs exist so "
        f"far — that means AT LEAST {gap} box(es) are almost certainly still "
        f"unrepresented. Go through the page again region by region and add "
        f"MCQs for whichever boxes are missing until total MCQs >= {box_count}. "
        f"This automated count can occasionally include a false positive "
        f"(e.g. a decorative border), so use judgment, but treat a large gap "
        f"like this as a strong signal of real missed boxes, not noise."
    )


async def _extra_marking_audit(mcqs: list, img, topic: str, page_num) -> list:
    """
    Final code-level safety net for /extra. The Call-1 prompt already says
    "only hand-marked lines", but a vision model can occasionally slip and
    pull a fact from plain/unmarked text nearby. This is a strict SECOND
    pass: shows the same image + the exact MCQs already generated, and
    asks the model to independently verify each one's source line was
    genuinely hand-marked (highlighter/pen underline/circle/box/star) --
    any MCQ traced to unmarked text is dropped. Runs once, bounded.
    """
    if not mcqs:
        return mcqs
    try:
        numbered = "\n".join(f"{idx+1}. {m.get('question','')[:150]}" for idx, m in enumerate(mcqs))
        audit_prompt = (
            f"You are STRICTLY auditing whether each MCQ below was really "
            f"sourced from a HAND-MARKED line on this page (Topic: {topic}) -- "
            f"marked = highlighter color, pen underline, hand-drawn circle/box/"
            f"bracket, or star/tick pointing to it, added ON TOP of the book's "
            f"original printing. Plain/unmarked text (even if bold/italic in "
            f"the original printing, or definitions/important-looking facts) "
            f"does NOT count as marked.\n\n"
            f"MCQs to audit:\n{numbered}\n\n"
            f"For EACH numbered MCQ, check: can you find the exact source line/"
            f"phrase on the page THIS MCQ is based on, AND is that specific "
            f"line/phrase visibly hand-marked (not just plain text)?\n\n"
            f"Return a STRICT JSON array of the numbers (1-indexed, matching "
            f"the list above) that FAILED this check -- i.e. MCQs whose "
            f"source line is NOT actually hand-marked and should be removed. "
            f"Format: [2, 5] (just the numbers, or [] if every MCQ above is "
            f"correctly sourced from marked content). No prose, JSON only."
        )
        txt = await _gen_groq_raw_text(img, audit_prompt)
        if not txt:
            return mcqs
        import json as _json
        cleaned = txt.strip()
        if cleaned.startswith("```"):
            cleaned = cleaned.strip("`")
            if cleaned.lower().startswith("json"):
                cleaned = cleaned[4:]
        cleaned = cleaned.strip()
        try:
            bad_indices = _json.loads(cleaned)
        except Exception:
            m = re.search(r'\[[\d,\s]*\]', cleaned)
            bad_indices = _json.loads(m.group(0)) if m else []
        if not isinstance(bad_indices, list) or not bad_indices:
            return mcqs
        bad_set = {int(x) for x in bad_indices if isinstance(x, (int, float)) or (isinstance(x, str) and x.strip().isdigit())}
        if not bad_set:
            return mcqs
        kept = [m for idx, m in enumerate(mcqs) if (idx + 1) not in bad_set]
        removed = len(mcqs) - len(kept)
        if removed:
            logger.info(f"[ExtraMarkingAudit] page {page_num}: removed {removed} MCQ(s) traced to unmarked text")
        return kept
    except Exception as e:
        logger.warning(f"[ExtraMarkingAudit] page {page_num} skipped: {e}")
        return mcqs


async def _chok_final_cv_enforcement(mcqs: list, img, topic: str, page_num) -> list:
    """
    Final code-level safety net for /chok, run AFTER the normal verify pass.
    Re-checks CV-detected box count vs current MCQ count. If a gap still
    remains (verify pass either wasn't triggered by this specific number, or
    the model under-delivered on its addition), fires ONE bounded, targeted
    extra call asking specifically for the shortfall count, then appends
    whatever comes back. Runs once only (no loop) to bound latency — this is
    a best-effort second safety net on top of the verify pass, not a
    guarantee generator, since CV detection itself can misfire (over/under
    count on decorative borders, faint scan lines, etc).
    """
    try:
        boxes = await asyncio.to_thread(_detect_chok_boxes, img)
        if not boxes:
            return mcqs
        box_count = len(boxes)
        n = len(mcqs or [])
        if n >= box_count:
            return mcqs
        gap = box_count - n
        existing_qs = "\n".join(f"- {m.get('question','')[:100]}" for m in (mcqs or [])[:60])
        fix_prompt = (
            f"CV box-detection found {box_count} distinct box/cell regions on this ছক "
            f"page (Topic: {topic}), but only {n} MCQs exist — a gap of at least {gap}. "
            f"Existing questions already covered:\n{existing_qs or '(none)'}\n\n"
            f"Scan the page box-by-box one final time and return ONLY the ADDITIONAL "
            f"new MCQs for boxes/cells not yet represented above (never duplicate "
            f"existing questions) — aim to close this gap of {gap}. All info must come "
            f"from the source page. STRICT JSON array only: "
            f'[{{"question":"...","options":["...","...","...","..."],'
            f'"answer":"A","explanation":"..."}}]. If truly nothing more to add, '
            f"return exactly: []"
        )
        txt = await _gen_groq_raw_text(img, fix_prompt)
        extra = _parse_mcq_json(txt) if txt else []
        if extra:
            extra = _cap_mcq_options(extra, 4)
            extra = _validate_mcq_structure(extra)
            existing_q_texts = {(m.get("question") or "").strip().lower()[:60] for m in (mcqs or [])}
            new_items = []
            for m in extra:
                qk = (m.get("question") or "").strip().lower()[:60]
                if qk and qk not in existing_q_texts:
                    new_items.append(m)
                    existing_q_texts.add(qk)
            if new_items:
                logger.info(f"[ChokCVEnforce] page {page_num}: added {len(new_items)} more MCQs to close CV box-gap")
                mcqs = list(mcqs or []) + new_items
    except Exception as e:
        logger.warning(f"[ChokCVEnforce] page {page_num} skipped: {e}")
    return mcqs


def _detect_page_text_lines(img) -> list:
    """
    OCR-based (pytesseract, zero AI cost, local CPU) detection of distinct
    text lines on a page for /bangla mode. Reuses the same block/par/line
    grouping approach as _ocr_bbox_lookup, but here the goal is simply a
    real, deterministic LINE COUNT — independent of what the AI vision model
    claims to see — so code can verify "MCQ count >= real line count" rather
    than trusting the AI's own line-by-line self-report alone.

    Filters out very short/noise "lines" (e.g. stray single characters,
    page numbers) so the count roughly tracks genuine content lines.

    Best-effort: on any failure (OCR unavailable, blank page, etc) returns
    [] and callers must treat that as "unknown line count" — NOT as "zero
    lines required".
    """
    try:
        import pytesseract
        try:
            data = pytesseract.image_to_data(img, lang="ben+eng", output_type=pytesseract.Output.DICT)
        except pytesseract.TesseractError:
            data = pytesseract.image_to_data(img, lang="eng", output_type=pytesseract.Output.DICT)

        lines = {}
        n = len(data.get("text", []))
        for i in range(n):
            word = (data["text"][i] or "").strip()
            if not word:
                continue
            key = (data["block_num"][i], data["par_num"][i], data["line_num"][i])
            if key not in lines:
                lines[key] = []
            lines[key].append(word)

        # Keep only lines with meaningful content (>=2 chars total, not just
        # a lone page-number digit or punctuation mark)
        real_lines = []
        for words in lines.values():
            joined = " ".join(words)
            if len(joined.strip()) >= 3:
                real_lines.append(joined)
        return real_lines
    except Exception as e:
        logger.warning(f"[BanglaLineDetect] detection failed, treating as unknown: {e}")
        return []


def _bangla_line_coverage_note(img, mcqs: list) -> str:
    """
    Cross-checks OCR-detected real text-line count against current MCQ count
    for /bangla mode. If detected line count clearly exceeds current MCQ
    count, returns an explicit numeric instruction to append to a verify
    prompt so the model reacts to a code-derived number instead of only its
    own self-reported line-by-line pass.
    Returns "" if detection found nothing (fails open) or coverage already
    looks sufficient — never blocks/reduces output.
    """
    try:
        lines = _detect_page_text_lines(img)
    except Exception:
        lines = []
    if not lines:
        return ""
    line_count = len(lines)
    n = len(mcqs or [])
    # A single MCQ can legitimately cover more than one OCR "line" (e.g. a
    # multi-line sentence), so use a conservative ratio rather than a strict
    # 1:1 — flag a gap only when MCQ count is well below the line count.
    expected_min = max(1, round(line_count * 0.5))
    if n >= expected_min:
        return ""
    gap = expected_min - n
    return (
        f"\nOCR LINE-DETECTION RESULT (independent of your own visual count): "
        f"automated OCR found approximately {line_count} distinct text lines "
        f"on this page, but only {n} MCQs exist so far — well below the "
        f"expected minimum of ~{expected_min}. That means at least {gap} more "
        f"lines/portions are almost certainly still unused. Go through the "
        f"page again line by line and add MCQs for whichever lines/portions "
        f"are missing. This automated count can occasionally include noise "
        f"(headers, page numbers, OCR misreads), so use judgment, but treat "
        f"a large gap like this as a strong signal of real unused content, "
        f"not noise."
    )


async def _bangla_verify_and_enforce(mcqs: list, img, topic: str, page_num) -> list:
    """
    Code-level enforcement pass for /bangla, mirroring /chok's dual-layer
    approach (AI self-audit + CV/OCR cross-check + one bounded extra call).
    Runs AFTER the normal generation call. Checks OCR line-coverage; if a
    real gap is detected, fires ONE targeted extra call asking the model to
    scan again and cover the missing lines, then appends new MCQs found.
    Runs once only (no loop) to bound latency.
    """
    try:
        lines = await asyncio.to_thread(_detect_page_text_lines, img)
        if not lines:
            return mcqs
        line_count = len(lines)
        n = len(mcqs or [])
        expected_min = max(1, round(line_count * 0.5))
        if n >= expected_min:
            return mcqs
        gap = expected_min - n
        existing_qs = "\n".join(f"- {m.get('question','')[:100]}" for m in (mcqs or [])[:60])
        fix_prompt = (
            f"OCR line-detection found approximately {line_count} distinct text "
            f"lines on this page (Topic: {topic}), but only {n} MCQs exist — "
            f"well short of the expected minimum coverage. Existing questions "
            f"already covered:\n{existing_qs or '(none)'}\n\n"
            f"Scan the page LINE BY LINE one final time and return ONLY the "
            f"ADDITIONAL new MCQs for lines/portions not yet represented above "
            f"(never duplicate existing questions) — there is NO maximum cap, "
            f"cover as many remaining lines as genuinely have distinct content. "
            f"All info must come from the source page. STRICT JSON array only: "
            f'[{{"question":"...","options":["...","...","...","..."],'
            f'"answer":"A","explanation":"..."}}]. If truly nothing more to add, '
            f"return exactly: []"
        )
        txt = await _gen_groq_raw_text(img, fix_prompt)
        extra = _parse_mcq_json(txt) if txt else []
        if extra:
            extra = _cap_mcq_options(extra, 4)
            extra = _validate_mcq_structure(extra)
            existing_q_texts = {(m.get("question") or "").strip().lower()[:60] for m in (mcqs or [])}
            new_items = []
            for m in extra:
                qk = (m.get("question") or "").strip().lower()[:60]
                if qk and qk not in existing_q_texts:
                    new_items.append(m)
                    existing_q_texts.add(qk)
            if new_items:
                logger.info(f"[BanglaEnforce] page {page_num}: added {len(new_items)} more MCQs to close OCR line-gap")
                mcqs = list(mcqs or []) + new_items
    except Exception as e:
        logger.warning(f"[BanglaEnforce] page {page_num} skipped: {e}")
    return mcqs


def _classify_chok_mcq_type(m: dict) -> str:
    """Zero-cost regex classification of an MCQ into chok's 4 buckets.
    Used only for ratio-auditing in chok mode — never blocks/filters output."""
    q = (m.get("question") or "")
    opts = m.get("options") or []
    if any(p in q for p in _TF_PATTERNS_BN):
        return "tf"
    opt_lens = [len(str(o)) for o in opts] if opts else []
    avg_opt_len = (sum(opt_lens) / len(opt_lens)) if opt_lens else 0
    if len(q) <= 40 and avg_opt_len >= 25:
        return "short_q_long_opt"
    # heuristic for multi-box combined: question mentions multiple distinct
    # nouns/topics joined by connectors, or options are unusually long/dense
    # combining several facts (rough proxy: avg option length very high AND
    # question itself references comparison/combination).
    combine_markers = ("এবং", "ও ", "উভয়", "সবগুলো", "কোনটি সঠিক", "মিলিয়ে")
    if avg_opt_len >= 35 and any(cm in q for cm in combine_markers):
        return "multi_box"
    return "standard"


def _chok_ratio_gap_note(mcqs: list) -> str:
    """Returns a short instruction string describing which type-buckets are
    under target ratio AND whether the code-verifiable safety-net floor is
    unmet, to append to the chok verify prompt. Empty string means everything
    checkable from code is satisfied — no extra instruction needed.

    IMPORTANT: code cannot see the page image, so it cannot count actual boxes.
    15 here is only a SAFETY-NET minimum (never go below this), not the real
    target — the real, binding floor is "one MCQ per box, however many boxes
    there are" as instructed in the Call-1 prompt (_build_chok_prompt), which
    can be 22, 35, or more. This function only catches the case where the
    count fell below even the conservative 15 safety net.
    """
    n = len(mcqs or [])
    baseline = max(n, 15)
    counts = {"standard": 0, "tf": 0, "multi_box": 0, "short_q_long_opt": 0}
    for m in mcqs:
        counts[_classify_chok_mcq_type(m)] += 1
    targets = {"tf": 0.05, "multi_box": 0.10, "short_q_long_opt": 0.05}
    gaps = []
    for key, pct in targets.items():
        need = max(0, round(baseline * pct) - counts[key])
        if need > 0:
            label = {"tf": "সত্য/মিথ্যা style", "multi_box": "multi-box combined",
                      "short_q_long_opt": "short-question-long-option"}[key]
            gaps.append(f"{need} more {label} MCQ(s)")
    floor_gap = 15 - n
    notes = []
    if floor_gap > 0:
        notes.append(
            f"SAFETY-NET FLOOR NOT MET: this ছক page has only {n} MCQs, below "
            f"even the conservative 15 minimum. Add at least {floor_gap} more "
            f"MCQ(s) now. REMINDER: 15 is only a safety-net minimum — the real, "
            f"binding requirement is ONE MCQ PER BOX on this page (if this page "
            f"has 22 boxes, you need 22+; if 35 boxes, 35+). Re-check whether "
            f"every box/cell is individually represented, not just whether the "
            f"count reaches 15."
        )
    if gaps:
        notes.append(
            f"TYPE-MIX GAP: current set is short on required variety — "
            f"{'; '.join(gaps)}. Prioritize these types among the additional "
            f"MCQs you return (still following per-box source-fidelity rules)."
        )
    if not notes:
        return ""
    return "\n" + "\n".join(notes)


from pdf_handler import MCQ_PROCESSING_QUEUE_LOCK as _MCQ_PROCESSING_QUEUE_LOCK
# All MCQ generation (image and text) funnels through generate_mcq_from_image /
# generate_mcq_from_text below, both of which acquire this lock — so every
# /img, /pdf, /csv, quiz-master MCQ job runs strictly one-at-a-time (queued),
# while unrelated commands (menu, settings, admin, etc.) are completely
# unaffected and continue running in parallel.

MIN_MCQ = 10
MAX_MCQ = 20

def _dedupe_mcqs(mcqs: list) -> list:
    """Remove duplicate MCQs (same question text) so retry-merges don't inflate count with repeats."""
    seen = set()
    out = []
    for m in (mcqs or []):
        q = (m.get('question') or m.get('q') or '').strip().lower()
        key = ''.join(q.split())
        if key and key in seen:
            continue
        if key:
            seen.add(key)
        out.append(m)
    return out

async def generate_mcq_from_image(img, topic, page_num, mcq_count=None, exclude_groq_keys: set = None, key_offset: int = 0):
    """
    Smart wrapper: Gemini first (primary), then Groq fallback (internal key rotation via pdf_handler).
    On failure → rotate through NVIDIA / OpenRouter Qwen VL / Nemotron / Gemma.
    Missing API keys are skipped silently. Never raises.
    Queued: only one MCQ-generation job runs at a time across the whole bot.
    Always generates fresh — no same-image cache reuse.
    AtlasBot-style: single generation call, retry only if under MIN_MCQ
    (max 2 extra attempts) — no mandatory per-page verify/repair call.
    Also accepts/exposes tried Groq keys via _LAST_TRIED_GROQ_KEYS (see below)
    so an OUTER retry (e.g. pdf_generate_all_pages' one-more-try-on-empty-page)
    can skip keys already burned in this call instead of getting a fresh
    5-key budget as if nothing happened.
    """
    async with _MCQ_PROCESSING_QUEUE_LOCK:
        out, tried_groq_keys = await _generate_mcq_from_image_raw(img, topic, page_num, mcq_count, exclude_groq_keys=exclude_groq_keys, key_offset=key_offset)
        out = _cap_mcq_options(out, 4)
        out = _validate_mcq_structure(out)
        if _TF_MODE.get():
            out = _tf_validate_and_filter(out)
        out = _dedupe_mcqs(out) if "_dedupe_mcqs" in globals() else out

        if isinstance(mcq_count, (tuple, list)) and len(mcq_count) == 2:
            _rng_min, _rng_max = mcq_count[0], mcq_count[1]
        elif isinstance(mcq_count, (int, float)) and mcq_count:
            _rng_min = _rng_max = int(mcq_count)
        elif _EXTRA_MODE.get():
            # /extra output is entirely content-driven by how much is
            # actually hand-marked on the page -- could legitimately be 0
            # (unmarked page) or just 1-2 (a single marked phrase). No
            # floor to retry toward, unlike the normal MIN_MCQ target.
            _rng_min, _rng_max = 0, None
        else:
            _rng_min, _rng_max = MIN_MCQ, MAX_MCQ

        # AtlasBot-style count-enforcement retry loop — up to 2 extra attempts
        # if the page came back thin, instead of a mandatory verify call.
        # exclude_groq_keys accumulates across attempts so a thin-page retry
        # never re-tries a Groq key already tried in an earlier attempt on
        # this SAME page — without this, a 3-attempt page could touch up to
        # 15 key-slots (3 attempts x 5-key cap) even though there are only
        # 12 keys total, effectively burning every key at least once per page.
        attempts = 0
        while len(out) < _rng_min and attempts < 2:
            attempts += 1
            logger.info(f"[MCQGen] page {page_num}: only {len(out)} MCQs (attempt {attempts}) — retrying for more")
            retry_out, retry_tried = await _generate_mcq_from_image_raw(img, topic, page_num, mcq_count, exclude_groq_keys=tried_groq_keys)
            tried_groq_keys = tried_groq_keys | retry_tried
            retry_out = _cap_mcq_options(retry_out, 4)
            retry_out = _validate_mcq_structure(retry_out)
            if _TF_MODE.get():
                retry_out = _tf_validate_and_filter(retry_out)
            retry_out = _dedupe_mcqs(retry_out) if "_dedupe_mcqs" in globals() else retry_out
            if len(retry_out) > len(out):
                out = retry_out

        if _rng_max and len(out) > _rng_max:
            out = out[:_rng_max]

        # chok/bangla are special coverage-audit modes — keep their dedicated
        # verify/enforcement passes since they check literal box/line coverage,
        # not just count. Normal mode skips all extra calls (AtlasBot parity).
        if _CHOK_MODE.get():
            out = await _chok_final_cv_enforcement(out, img, topic, page_num)
        if _BANGLA_MODE.get():
            out = await _bangla_verify_and_enforce(out, img, topic, page_num)
        if _EXTRA_MODE.get():
            out = await _extra_marking_audit(out, img, topic, page_num)

        out = _validate_mcq_structure(out)
        # Side-channel for outer retry callers (pdf_generate_all_pages'
        # _run_one) so a fully-empty-page outer retry doesn't get a fresh
        # 5-key Groq budget as if nothing happened -- see docstring above.
        # Kept out of the return signature to avoid touching the ~10+
        # existing call sites that unpack a single value.
        _LAST_TRIED_GROQ_KEYS["keys"] = tried_groq_keys
        return out


async def _verify_and_fix_page(mcqs: list, img, topic: str, page_num, mcq_count=None) -> list:
    """
    2ND CALL — verification pass over what CALL 1 produced. Checks:
      (a) did call 1 miss any highlighted/underlined/marked/boxed content,
      (b) is the MCQ count reasonably close to target (~15/page avg),
      (c) did call 1 follow the prompt rules (real info only, no junk).
    If verification finds gaps, requests ADDITIONAL mcqs only for the missed
    content (never re-generates the whole page) and appends them. Best-effort:
    any failure here just returns the original call-1 output untouched.
    """
    try:
        count_min = count_max = None
        if isinstance(mcq_count, (tuple, list)) and len(mcq_count) == 2:
            count_min, count_max = mcq_count[0], mcq_count[1]
            count_target = count_max
        elif isinstance(mcq_count, (int, float)) and mcq_count:
            count_target = int(mcq_count)
            count_max = int(mcq_count)  # exact-count also acts as a hard cap
        else:
            count_target = 15
        current_n = len(mcqs or [])
        # If a strict range was given and we're already at/above max, don't
        # ask verify to add more — would violate the user's upper bound.
        if count_max and current_n >= count_max:
            return mcqs
        existing_qs = "\n".join(f"- {m.get('question','')[:100]}" for m in (mcqs or [])[:40])
        max_extra_note = (
            f"\nHARD CAP: do not return more than {count_max - current_n} additional "
            f"MCQ(s) — the page's total must not exceed {count_max}."
            if count_max is not None else ""
        )
        if _CHOK_MODE.get():
            # Cheap local CV check first (zero API cost) — if Call 1 already
            # produced at least as many MCQs as there are real detected boxes,
            # there is (by definition of the box-driven floor) nothing left
            # for verify to plausibly add. Skipping saves a full Groq/Gemini
            # round-trip per page in the common case Call 1 already did well,
            # with no accuracy loss — the final CV-enforcement pass re-checks
            # this exact same condition anyway, so nothing goes unaudited.
            _boxes_precheck = await asyncio.to_thread(_detect_chok_boxes, img)
            if _boxes_precheck and current_n >= len(_boxes_precheck):
                return mcqs
            ratio_gap_note = _chok_ratio_gap_note(mcqs)
            cv_box_note = await asyncio.to_thread(_chok_box_coverage_note, img, mcqs)
            verify_prompt = (
                f"You are STRICTLY auditing ছক/box MCQ coverage for this page (Topic: {topic}).\n"
                f"CALL 1 already extracted {current_n} MCQs.{max_extra_note} "
                f"Existing questions already covered:\n{existing_qs or '(none)'}\n\n"
                f"MANDATORY BOX-BY-BOX AUDIT (not optional):\n"
                f"- List EVERY box/cell/marked area/row/column on this page mentally, one by one.\n"
                f"- For EACH box, check: is there at least one MCQ above that clearly covers "
                f"THIS specific box's content? If not, that box was MISSED — this is a hard "
                f"failure that must be fixed.\n"
                f"- Pay special attention to the LAST row/box and BOTTOM of the page — most "
                f"commonly missed.\n"
                f"- Also check: are there enough MULTI-BOX combined MCQs (mixing 2-3+ boxes) "
                f"to cover the full ছক collectively, and at least one সত্য/মিথ্যা style MCQ?"
                f"{ratio_gap_note}{cv_box_note}\n\n"
                f"If ANY box was missed, or the mix is incomplete, return ONLY the ADDITIONAL "
                f"new MCQs needed (one per missed box minimum, never duplicate existing "
                f"questions above) as STRICT JSON array: [{{\"question\":\"...\",\"options\":"
                f"[\"...\",\"...\",\"...\",\"...\"],\"answer\":\"A\",\"explanation\":\"...\"}}]. "
                f"If every box is genuinely already covered, return exactly: []\n"
                f"Never invent facts not present on the page. No prose, JSON only."
            )
        elif _BANGLA_MODE.get():
            line_gap_note = await asyncio.to_thread(_bangla_line_coverage_note, img, mcqs)
            verify_prompt = (
                f"You are STRICTLY auditing MAXIMUM-SOURCE-UTILIZATION MCQ coverage for "
                f"this page (Topic: {topic}). There is NO maximum MCQ cap on this page.\n"
                f"CALL 1 already extracted {current_n} MCQs.{max_extra_note} "
                f"Existing questions already covered:\n{existing_qs or '(none)'}\n\n"
                f"MANDATORY LINE-BY-LINE AUDIT (not optional):\n"
                f"- Go through this page LINE BY LINE, PARAGRAPH BY PARAGRAPH, POINT BY "
                f"POINT, CELL BY CELL — for EACH one, check: is there at least one MCQ "
                f"above that clearly covers this specific line/portion's content? If "
                f"not, it was MISSED — this is a hard failure that must be fixed.\n"
                f"- Pay special attention to the LAST lines/bottom of the page and "
                f"footnotes — most commonly missed.\n"
                f"- Check every highlighted/underlined/marked/boxed/ছক item and every "
                f"table/ছক cell individually.\n"
                f"{line_gap_note}\n\n"
                f"If ANY line/portion was missed, return ONLY the ADDITIONAL new MCQs "
                f"needed (one per missed line/portion minimum, never duplicate existing "
                f"questions above, NO upper limit on how many you add) as STRICT JSON "
                f"array: [{{\"question\":\"...\",\"options\":[\"...\",\"...\",\"...\",\"...\"],"
                f"\"answer\":\"A\",\"explanation\":\"...\"}}]. "
                f"If every line is genuinely already covered, return exactly: []\n"
                f"Never invent facts not present on the page. No prose, JSON only."
            )
        else:
            verify_prompt = (
            f"You are STRICTLY auditing MCQ coverage for this page (Topic: {topic}).\n"
            f"CALL 1 already extracted {current_n} MCQs (target ~{count_target}/page).{max_extra_note} "
            f"Existing questions already covered:\n{existing_qs or '(none)'}\n\n"
            f"MANDATORY SYSTEMATIC SCAN (do this before answering, not optional):\n"
            f"- Mentally divide the page into regions (top/middle/bottom, and left/right "
            f"if multi-column) and check EACH region separately against the list above.\n"
            f"- Pay special attention to the LAST paragraph/box/row on the page and the "
            f"BOTTOM of the page — these are the most commonly missed areas.\n"
            f"- Check every highlighted/underlined/marked/boxed/ছক item individually — "
            f"if it's not represented above, it was missed.\n"
            f"- Check every table/ছক cell individually, not just at a glance.\n"
            f"Only after this region-by-region pass, decide:\n"
            f"1. Any highlighted/underlined/marked/boxed/ছক content NOT yet covered above?\n"
            f"2. Any distinct real-info fact on the page not yet turned into an MCQ?\n"
            f"3. Is {current_n} clearly below what the page's content could support?\n\n"
            f"If you find genuinely MISSING content, return ONLY the ADDITIONAL new MCQs "
            f"(never duplicate the existing ones above) as a STRICT JSON array matching this "
            f"schema: [{{\"question\":\"...\",\"options\":[\"...\",\"...\",\"...\",\"...\"],"
            f"\"answer\":\"A\",\"explanation\":\"...\"}}]. "
            f"If nothing is missing and coverage is already complete, return exactly: []\n"
            f"Never invent facts not present on the page. No prose, JSON only."
        )
        # Two independent verify passes from DIFFERENT providers (Groq +
        # Gemini) run concurrently — genuine second-opinion diversity catches
        # misses a single model's blind spots would let through, at the cost
        # of one extra parallel call (not sequential, so latency impact is
        # small since both run at once).
        groq_task = _spawn_task(_gen_groq_raw_text(img, verify_prompt))
        gemini_task = _spawn_task(_gemini_verify_raw_text(img, verify_prompt))
        extra_txt, extra_txt_gemini = await asyncio.gather(groq_task, gemini_task)

        extra = _parse_mcq_json(extra_txt) if extra_txt else []
        extra_g = _parse_mcq_json(extra_txt_gemini) if extra_txt_gemini else []

        combined_extra = list(extra)
        if extra_g:
            existing_q_texts = {(m.get("question") or "").strip().lower()[:60] for m in combined_extra}
            for m in extra_g:
                qk = (m.get("question") or "").strip().lower()[:60]
                if qk and qk not in existing_q_texts:
                    combined_extra.append(m)
                    existing_q_texts.add(qk)

        if combined_extra:
            combined_extra = _cap_mcq_options(combined_extra, 4)
            logger.info(f"[Verify] page {page_num}: call-2 added {len(combined_extra)} missed MCQs (groq={len(extra)}, gemini_extra={len(combined_extra)-len(extra)})")
            mcqs = (mcqs or []) + combined_extra
            # Code-level hard cap: AI can still overshoot the prompt's max
            # instruction, so trim here to guarantee the strict range is
            # never violated regardless of model compliance.
            if count_max and len(mcqs) > count_max:
                mcqs = mcqs[:count_max]
    except Exception as e:
        logger.warning(f"[Verify] page {page_num} verification skipped: {e}")
    return mcqs



def _ocr_bbox_lookup(img, mcqs: list) -> dict:
    """
    ZERO extra AI/API cost — runs Tesseract OCR once on the page (local CPU,
    already installed in the Dockerfile), groups words into lines with their
    pixel bounding boxes, then fuzzy-matches each MCQ's question text against
    those OCR lines to find where on the page it came from.
    Returns {question_text: [x_min,y_min,x_max,y_max]} normalized 0-1000,
    for whatever it can confidently match (skips low-confidence matches).
    """
    if not mcqs:
        return {}
    try:
        import pytesseract
        w, h = img.size
        try:
            data = pytesseract.image_to_data(img, lang="ben+eng", output_type=pytesseract.Output.DICT)
        except pytesseract.TesseractError as te:
            # ben traineddata not installed yet on this running container
            # (e.g. before a fresh deploy picks up the updated Dockerfile) —
            # fall back to English-only rather than crashing the whole pass.
            logger.warning(f"[OCRBBoxLookup] ben+eng unavailable ({te}); falling back to eng")
            data = pytesseract.image_to_data(img, lang="eng", output_type=pytesseract.Output.DICT)

        # Group words into lines using (block, par, line) keys, keep bbox + text per line
        lines = {}
        n = len(data.get("text", []))
        for i in range(n):
            word = (data["text"][i] or "").strip()
            if not word:
                continue
            key = (data["block_num"][i], data["par_num"][i], data["line_num"][i])
            x, y, ww, hh = data["left"][i], data["top"][i], data["width"][i], data["height"][i]
            if key not in lines:
                lines[key] = {"text": [], "x0": x, "y0": y, "x1": x + ww, "y1": y + hh}
            L = lines[key]
            L["text"].append(word)
            L["x0"] = min(L["x0"], x)
            L["y0"] = min(L["y0"], y)
            L["x1"] = max(L["x1"], x + ww)
            L["y1"] = max(L["y1"], y + hh)

        line_list = [(" ".join(v["text"]), v) for v in lines.values() if v["text"]]
        if not line_list:
            return {}

        out = {}
        for m in mcqs:
            q = (m.get("question") or "").strip()
            if not q:
                continue
            # Match against the EXPLANATION text, not the question — the
            # explanation's supporting evidence (a law/definition/paragraph)
            # is often located elsewhere on the page than the question line
            # itself, so matching on the question was marking the wrong spot.
            exp_text = re.sub(r'<img\b[^>]*>', '', m.get("explanation") or "", flags=re.IGNORECASE).strip()
            q_key = (exp_text or q)[:80]
            best_ratio = 0.0
            best_box = None
            best_idx = None
            # Find the best matching single line, then extend a small window
            # around it (question text usually spans 1-3 OCR lines).
            for idx, (ltext, lbox) in enumerate(line_list):
                ratio = difflib.SequenceMatcher(None, q_key.lower(), ltext.lower()).ratio()
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_box = lbox
                    best_idx = idx
            # STRICT REQUIREMENT: the explanation image must ALWAYS show the
            # source line — never skip to an unmarked fallback. Try matching
            # both the explanation text and the question text, keep whichever
            # scores higher, and use it regardless of confidence (best-effort
            # is still far better than no mark at all).
            q_text_key = q[:80]
            best_ratio_q = 0.0
            best_box_q = None
            best_idx_q = None
            for idx, (ltext, lbox) in enumerate(line_list):
                ratio = difflib.SequenceMatcher(None, q_text_key.lower(), ltext.lower()).ratio()
                if ratio > best_ratio_q:
                    best_ratio_q = ratio
                    best_box_q = lbox
                    best_idx_q = idx
            if best_ratio_q > best_ratio:
                best_ratio = best_ratio_q
                best_box = best_box_q
                best_idx = best_idx_q
            if best_box is None:
                continue  # no OCR lines at all on this page — nothing to mark

            # Extend window: include 1 line before/after to capture full context
            x0, y0, x1, y1 = best_box["x0"], best_box["y0"], best_box["x1"], best_box["y1"]
            for j in (best_idx - 1, best_idx + 1):
                if 0 <= j < len(line_list):
                    _, lb = line_list[j]
                    x0 = min(x0, lb["x0"]); y0 = min(y0, lb["y0"])
                    x1 = max(x1, lb["x1"]); y1 = max(y1, lb["y1"])

            # Normalize to 0-1000 scale (same convention as exp_bbox elsewhere)
            bbox_norm = [
                int((x0 / w) * 1000), int((y0 / h) * 1000),
                int((x1 / w) * 1000), int((y1 / h) * 1000)
            ]
            out[q] = bbox_norm
        return out
    except Exception as e:
        logger.warning(f"[OCRBBoxLookup] failed: {e}")
        return {}


async def _attach_explanation_images_if_missing(mcqs: list, img) -> list:
    """
    সব image-mode AI provider (Groq/NVIDIA/Qwen/Nemotron/Gemma/Gemini) একই জায়গা
    দিয়ে যায় এখানে — যাদের explanation-এ এখনো <img> tag নাই (Gemini path আগেই
    attach করে ফেলে, তাই সেগুলো স্কিপ হবে) তাদের exp_bbox থাকলে crop+upload করে।

    Non-Gemini providers rarely return a usable exp_bbox (prompt-only bbox
    instructions aren't reliable for them) — for those MCQs, a ZERO-cost local
    OCR + fuzzy-text-match pass (Tesseract, already installed) locates the
    source region instead of any extra AI call. If OCR match confidence is
    too low, the FULL page image is attached instead of leaving explanation
    with no visual reference at all.
    """
    try:
        from pdf_handler import crop_explanation_image, image_to_base64
        from atlas_mhtml import upload_to_imgbb
    except Exception:
        return mcqs

    pending = [m for m in (mcqs or [])
               if "<img" not in (m.get("explanation", "") or "").lower() and not m.get("exp_bbox")]

    ocr_bboxes = {}
    if pending:
        ocr_bboxes = await asyncio.to_thread(_ocr_bbox_lookup, img, pending)

    full_img_url = None  # lazily uploaded once, reused for every remaining miss
    full_img_attempted = False

    for m in mcqs or []:
        exp = m.get("explanation", "") or ""
        if "<img" in exp.lower():
            continue  # আগে থেকেই attach হয়ে গেছে (Gemini extraction path)

        bbox = m.get("exp_bbox") or ocr_bboxes.get(m.get("question", ""))
        url = ""
        top_pct = bottom_pct = None
        if bbox:
            try:
                result = await asyncio.to_thread(crop_explanation_image, img, bbox)
                url = result.get("url", "")
                top_pct = result.get("top_pct")
                bottom_pct = result.get("bottom_pct")
            except Exception as e:
                logger.warning(f"[ExplanationCrop] wrapper-attach failed: {e}")

        if not url:
            if full_img_url is None and not full_img_attempted:
                for _try in range(2):
                    try:
                        b64 = await asyncio.to_thread(image_to_base64, img)
                        full_img_url = await asyncio.to_thread(upload_to_imgbb, b64) or ""
                        if full_img_url:
                            break
                    except Exception as e:
                        logger.warning(f"[ExplanationCrop] full-image fallback attempt {_try+1} failed: {e}")
                full_img_attempted = True
            url = full_img_url or ""

        if url:
            crop_attrs = ""
            if top_pct is not None and bottom_pct is not None:
                crop_attrs = f' data-crop-top="{top_pct}" data-crop-bottom="{bottom_pct}"'
            m["explanation"] = f'{exp} <img src="{url}"{crop_attrs}>'.strip()

    return mcqs


def _strip_option_prefix(text: str) -> str:
    """Removes leading option labels like 'A.', 'B)', 'ক.', 'খ)', 'a.', etc.
    so the model's own numbering never leaks into the displayed option text."""
    if not text:
        return text
    return re.sub(r'^\s*[A-Da-dক-ঘ]\s*[).।:]\s*', '', str(text)).strip()

def _cap_mcq_options(mcqs: list, max_opts: int = 4) -> list:
    """v4.4: some AI providers occasionally return 5 options (E) instead of 4.
    Trim every mcq down to max_opts here — single choke point so /img's
    Telegram poll, Web Exam page, Quiz Solve, and CSV export all stay
    consistent without needing separate truncation logic in each consumer.
    Also strips any leading option-label prefix (A./ক./a) etc.) the model
    may have echoed into the option text itself — same choke point."""
    if not mcqs:
        return mcqs
    ans_map = {0: "A", 1: "B", 2: "C", 3: "D", 4: "E"}
    rev_map = {"A": 0, "B": 1, "C": 2, "D": 3, "E": 4}
    for m in mcqs:
        opts = m.get("options", [])
        opts = [_strip_option_prefix(o) for o in opts]
        if len(opts) > max_opts:
            ans_letter = m.get("answer", "A")
            ans_idx = rev_map.get(ans_letter, 0)
            # If the correct answer happens to be option 5 (E), keep it in range
            # by swapping it into slot 4 (D) before trimming, so we never lose
            # the right answer off the end.
            if ans_idx >= max_opts:
                opts = opts[:max_opts - 1] + [opts[ans_idx]]
                m["answer"] = ans_map[max_opts - 1]
            else:
                opts = opts[:max_opts]
        m["options"] = opts
    return mcqs


async def _generate_mcq_from_image_raw(img, topic, page_num, mcq_count=None, exclude_groq_keys: set = None, key_offset: int = 0):
    # Groq is the TRUE primary now (2026-08-07: Gemini free-tier daily quota
    # (20 req/day on gemini-3.6-flash) kept exhausting mid-run and killing
    # pagewise generation). Groq is tried first, alone; Gemini is only
    # invoked if Groq fails or comes back empty (sequential, not raced), so
    # Groq's result is used whenever Groq succeeds, with no latency penalty
    # from waiting on Gemini.
    #
    # EXCEPTION: /extra flips this order (Gemini primary, Groq fallback) --
    # this mode depends entirely on correctly distinguishing hand-marked
    # (highlighter/pen) content from plain printed text, a fine-grained
    # visual-detail task where Gemini's vision tends to be more reliable
    # than Groq's vision models, per explicit user preference for this mode.
    _LAST_GROQ_ERROR["reason"] = ""
    _LAST_GEMINI_ERROR["reason"] = ""
    _LAST_FALLBACK_ERROR["reason"] = ""

    if _EXTRA_MODE.get():
        try:
            gemini_out = await _gemini_gen_mcq(img, topic, page_num, mcq_count)
        except Exception as e:
            _LAST_GEMINI_ERROR["reason"] = f"{type(e).__name__}: {e}"
            classify_ai_error(e, "gemini", page_num)
            logger.warning(f"[AI-ROT] /extra gemini (primary) failed (page {page_num}): {e}")
            gemini_out = []

        if gemini_out:
            logger.info(f"[AI-ROT] /extra page {page_num} satisfied by provider=gemini (primary)")
            _track_provider_use("gemini", page_num)
            for _m in gemini_out:
                _m.setdefault("_provider", "Gemini")
            return gemini_out, set()

        logger.warning(f"[AI-ROT] /extra gemini empty (page {page_num}); trying groq")
        try:
            groq_out, groq_tried = await _gen_groq(img, topic, mcq_count, exclude_keys=exclude_groq_keys, key_offset=key_offset)
        except Exception as e:
            _LAST_GROQ_ERROR["reason"] = f"{type(e).__name__}: {e}"
            classify_ai_error(e, "groq", page_num)
            logger.warning(f"[AI-ROT] /extra groq (fallback) failed (page {page_num}): {e}")
            groq_out, groq_tried = [], set()

        if groq_out:
            logger.info(f"[AI-ROT] /extra page {page_num} satisfied by provider=groq (fallback)")
            _track_provider_use("groq", page_num)
            for _m in groq_out:
                _m.setdefault("_provider", "Groq")
            return groq_out, groq_tried
        # fall through to the shared fallback-provider rotation below
        # (groq_tried already set from the attempt above, either branch)

    else:
        try:
            groq_out, groq_tried = await _gen_groq(img, topic, mcq_count, exclude_keys=exclude_groq_keys, key_offset=key_offset)
        except Exception as e:
            _LAST_GROQ_ERROR["reason"] = f"{type(e).__name__}: {e}"
            classify_ai_error(e, "groq", page_num)
            logger.warning(f"[AI-ROT] groq failed (page {page_num}): {e}")
            groq_out, groq_tried = [], set()

        if groq_out:
            logger.info(f"[AI-ROT] page {page_num} satisfied by provider=groq (primary)")
            _track_provider_use("groq", page_num)
            for _m in groq_out:
                _m.setdefault("_provider", "Groq")
            return groq_out, groq_tried

        logger.warning(f"[AI-ROT] groq empty (page {page_num}); trying gemini")
        try:
            gemini_out = await _gemini_gen_mcq(img, topic, page_num, mcq_count)
        except Exception as e:
            _LAST_GEMINI_ERROR["reason"] = f"{type(e).__name__}: {e}"
            classify_ai_error(e, "gemini", page_num)
            logger.warning(f"[AI-ROT] gemini failed (page {page_num}): {e}")
            gemini_out = []

        if gemini_out:
            logger.info(f"[AI-ROT] page {page_num} satisfied by provider=gemini (fallback)")
            _track_provider_use("gemini", page_num)
            for _m in gemini_out:
                _m.setdefault("_provider", "Gemini")
            return gemini_out, groq_tried

    logger.warning(f"[AI-ROT] groq+gemini both empty (page {page_num}); rotating to fallbacks")

    # 3) Fallback providers (skip silently if key missing / call fails)
    fallback_errors = []
    for prov in _AI_PROVIDERS_ORDER:
        fn = _AI_FALLBACK_FNS.get(prov)
        if not fn:
            continue
        try:
            out = await fn(img, topic, mcq_count)
            if out:
                logger.info(f"[AI-ROT] page {page_num} satisfied by provider={prov}")
                _track_provider_use(prov, page_num)
                for _m in out:
                    _m.setdefault("_provider", prov.title())
                return out, groq_tried
            fallback_errors.append(f"{prov}: খালি ফলাফল")
            record_empty_parse("fallback")
        except Exception as e:
            logger.warning(f"[AI-ROT] provider {prov} crashed: {e}")
            fallback_errors.append(f"{prov}: {type(e).__name__}: {e}")
            classify_ai_error(e, "fallback", page_num)
            continue

    _LAST_FALLBACK_ERROR["reason"] = "; ".join(fallback_errors) if fallback_errors else "কোনো fallback provider configure করা নেই"
    logger.error(f"[AI-ROT] all providers exhausted for page {page_num}")
    return [], groq_tried


def _get_last_generation_error() -> str:
    """Combines whatever exact reasons each provider left behind into one
    human-readable string for dashboard/owner-alert display."""
    parts = []
    if _LAST_GROQ_ERROR["reason"]:
        parts.append(f"Groq: {_LAST_GROQ_ERROR['reason']}")
    if _LAST_GEMINI_ERROR["reason"]:
        parts.append(f"Gemini: {_LAST_GEMINI_ERROR['reason']}")
    if _LAST_FALLBACK_ERROR["reason"]:
        parts.append(f"Fallbacks: {_LAST_FALLBACK_ERROR['reason']}")
    return " | ".join(parts) if parts else "সব provider থেকে খালি ফলাফল এসেছে (no exception, but 0 MCQ returned)"


