async def handle_compress(msg: dict):
    """PDF-e reply kore /compress dile — image quality bhalo rekhe (mildest
    downsample+re-encode pass) file size kombe. Hard target nei, /rename-er
    50MB-limit compression theke alada: eta shudhu size kombe, quality
    priority."""
    chat_id = msg["chat"]["id"]
    reply = msg.get("reply_to_message")
    if not reply:
        await send_msg(chat_id, "❌ Kono PDF file e reply kore likho:\n<code>/compress</code>")
        return
    doc = reply.get("document")
    if not doc or doc.get("mime_type") != "application/pdf":
        await send_msg(chat_id, "❌ Ei command khali PDF file-e reply kore use kora jay।")
        return

    file_id = doc["file_id"]
    filename = doc.get("file_name") or "document.pdf"

    status = await send_msg(chat_id, "⏳ PDF download hocche...")
    status_id = status.get("result", {}).get("message_id") if status.get("ok") else None

    try:
        file_bytes = await download_tg_file(
            file_id, chat_id=reply["chat"]["id"], message_id=reply["message_id"]
        )
    except Exception as e:
        text = f"❌ Download failed: {e}"
        if status_id: await edit_msg(chat_id, status_id, text)
        else: await send_msg(chat_id, text)
        return

    orig_size = len(file_bytes)
    if status_id:
        await edit_msg(chat_id, status_id, "🗜️ Compress kora hocche (quality bhalo rekhe)...")

    try:
        out_bytes = await asyncio.to_thread(compress_pdf_to_target, file_bytes, quality_first=True)
    except Exception as e:
        text = f"❌ Compress failed: {e}"
        if status_id: await edit_msg(chat_id, status_id, text)
        else: await send_msg(chat_id, text)
        return

    new_size = len(out_bytes)
    saved_pct = round((1 - new_size / orig_size) * 100, 1) if orig_size else 0

    if new_size >= orig_size:
        text = "ℹ️ Ei PDF-e compress korar moto beshi kichu nei (image kom / already optimized)।"
        if status_id: await edit_msg(chat_id, status_id, text)
        else: await send_msg(chat_id, text)
        return

    if status_id:
        await edit_msg(chat_id, status_id, f"📤 Upload hocche... ({saved_pct}% size kombeche)")

    if not filename.lower().endswith(".pdf"):
        filename += ".pdf"
    new_filename = filename[:-4] + "_compressed.pdf" if filename.lower().endswith(".pdf") else filename + "_compressed"

    result = await send_document(
        chat_id, out_bytes, new_filename,
        caption=(f"✅ Compressed: {orig_size/1024/1024:.1f}MB → {new_size/1024/1024:.1f}MB "
                 f"({saved_pct}% kombeche)"),
        mime_type="application/pdf",
        reply_to_message_id=msg.get("message_id")
    )
    if not result.get("ok"):
        text = f"❌ Upload failed: {result.get('error') or result.get('description')}"
        if status_id: await edit_msg(chat_id, status_id, text)
        else: await send_msg(chat_id, text)



async def handle_rename(msg: dict):
    """Kono file (document/video/audio/photo) e reply kore /rename NewName
    dile - Telegram e already-uploaded file "rename" kora jay na (API-tei
    support nei), tai file ta re-download kore notun filename diye
    re-upload kora hoy - eta e Telegram-e "rename" korar ekmatro upay."""
    chat_id = msg["chat"]["id"]
    reply = msg.get("reply_to_message")
    text = msg.get("text", "")
    rest = re.sub(r'(?i)^/rename', '', text).strip()

    # /rename NewName.ext /wm WatermarkText — /wm er por ja ache shob watermark text,
    # tar age ja ache shob filename (Bangla/multi-word space thakleo thik thakbe)
    wm_split = re.split(r'(?i)\s*/wm\s+', rest, maxsplit=1)
    new_name = wm_split[0].strip()
    wm_text = wm_split[1].strip() if len(wm_split) > 1 else ""

    if not reply:
        await send_msg(chat_id, "❌ Kono file (document/video/audio/photo) e reply kore likho:\n<code>/rename NewName.ext\n/wm WatermarkText</code>")
        return
    if not new_name:
        await send_msg(chat_id, "❌ Notun name dao:\n<code>/rename NewName.ext\n/wm WatermarkText</code>")
        return
    # Telegram filenames don't allow these - strip to be safe
    new_name = re.sub(r'[\\/:*?"<>|]', '_', new_name)

    doc = reply.get("document")
    video = reply.get("video")
    audio = reply.get("audio")
    photo = reply.get("photo")

    def _ext_from_filename(fname: str) -> str:
        if not fname or "." not in fname:
            return ""
        return "." + fname.rsplit(".", 1)[-1]

    def _ext_from_mime(mime: str) -> str:
        # fallback guess when no original filename/extension is available at all
        return {
            "video/mp4": ".mp4", "video/x-matroska": ".mkv", "video/quicktime": ".mov",
            "audio/mpeg": ".mp3", "audio/mp4": ".m4a", "audio/ogg": ".ogg",
            "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp",
            "application/pdf": ".pdf", "application/zip": ".zip",
        }.get(mime, "")

    if doc:
        file_id = doc["file_id"]
        mime = doc.get("mime_type", "application/octet-stream")
        orig_ext = _ext_from_filename(doc.get("file_name", "")) or _ext_from_mime(mime)
    elif video:
        file_id = video["file_id"]
        mime = video.get("mime_type", "video/mp4")
        orig_ext = _ext_from_filename(video.get("file_name", "")) or _ext_from_mime(mime) or ".mp4"
    elif audio:
        file_id = audio["file_id"]
        mime = audio.get("mime_type", "audio/mpeg")
        orig_ext = _ext_from_filename(audio.get("file_name", "")) or _ext_from_mime(mime) or ".mp3"
    elif photo:
        file_id = photo[-1]["file_id"]  # largest resolution
        mime = "image/jpeg"
        orig_ext = ".jpg"  # Telegram compressed photos are always jpeg regardless of original
    else:
        await send_msg(chat_id, "❌ Ei message type support kore na — document/video/audio/photo e reply koro।")
        return

    if "." not in new_name and orig_ext:
        new_name += orig_ext

    status = await send_msg(chat_id, "⏳ File download hocche...")
    status_id = status.get("result", {}).get("message_id") if status.get("ok") else None

    try:
        file_bytes = await download_tg_file(
            file_id, chat_id=reply["chat"]["id"], message_id=reply["message_id"]
        )
    except Exception as e:
        if status_id:
            await edit_msg(chat_id, status_id, f"❌ Download failed: {e}")
        else:
            await send_msg(chat_id, f"❌ Download failed: {e}")
        return

    # Telegram bots can only upload up to 50MB. If it's a PDF over that,
    # auto-compress (downsample+re-encode embedded images) before upload
    # instead of failing outright.
    TG_MAX_UPLOAD = 50 * 1024 * 1024
    compressed = False
    if len(file_bytes) > TG_MAX_UPLOAD and mime == "application/pdf":
        if status_id:
            await edit_msg(chat_id, status_id, "🗜️ File 50MB er beshi — compress kora hocche...")
        try:
            file_bytes = await asyncio.to_thread(compress_pdf_to_target, file_bytes)
            compressed = True
        except Exception as e:
            logger.warning(f"[rename] compression failed: {e}")
        if len(file_bytes) > TG_MAX_UPLOAD:
            size_mb = len(file_bytes) / 1024 / 1024
            msg_text = (f"❌ Compress korar porew file {size_mb:.1f}MB — 50MB limit paar hocche. "
                        f"Ei PDF-e onek high-res image ache, aro kombe na without visible quality loss.")
            if status_id:
                await edit_msg(chat_id, status_id, msg_text)
            else:
                await send_msg(chat_id, msg_text)
            return

    watermarked = False
    if wm_text and mime == "application/pdf":
        if status_id:
            await edit_msg(chat_id, status_id, f"🖋️ Watermark apply hocche: {wm_text}...")
        try:
            file_bytes = add_watermark_to_pdf(file_bytes, wm_text)
            watermarked = True
        except Exception as e:
            logger.warning(f"[rename] watermark failed: {e}")

    if status_id:
        note = " (compress kora hoyeche, image quality kichuta kome geche)" if compressed else ""
        note += f" | watermark: {wm_text}" if watermarked else ""
        await edit_msg(chat_id, status_id, f"📤 '{new_name}' name e upload hocche...{note}")

    _caption_name = new_name.rsplit(".", 1)[0] if "." in new_name else new_name
    caption = f"✅{_caption_name}" + (" (compressed)" if compressed else "")
    result = await send_document(
        chat_id, file_bytes, new_name,
        caption=caption,
        mime_type=mime,
        reply_to_message_id=msg.get("message_id")
    )
    if result.get("ok"):
        if status_id:
            await tg_post("deleteMessage", {"chat_id": chat_id, "message_id": status_id})
    else:
        err = result.get("description") or result.get("error") or "unknown error"
        if status_id:
            await edit_msg(chat_id, status_id, f"❌ Upload failed: {err}")
        else:
            await send_msg(chat_id, f"❌ Upload failed: {err}")


async def handle_tagQ(msg: dict):
    chat_id = msg["chat"]["id"]
    text = re.sub(r'(?i)^/tagq', '', msg.get("text", "")).strip()
    if text:
        await sb_exec(lambda: sb.table("quiz_settings").upsert({"id": 1, "tag": text}).execute())
        await db_save_settings_field("tag", text)
        await send_msg(chat_id, f"✅ Tag set:\n{text}")
    else:
        s = await db_get_settings()
        await send_msg(chat_id, f"🔖 Current tag:\n{s.get('tag') or 'None'}\n\nSet: /tagQ [text]")

