# ============================================================
# FEATURE 5: /channel, /channelist
# ============================================================
async def handle_channel(msg: dict):
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    if text.strip() == "/channelist":
        return await _show_channel_list(chat_id)
    args = text.replace("/channel", "").strip()
    if not args or args == "list":
        return await _show_channel_list(chat_id)
    parts = args.split(maxsplit=1)
    channel_id = parts[0]
    custom_name = parts[1] if len(parts) > 1 else None
    if "t.me/" in channel_id:
        channel_id = "@" + channel_id.split("/")[-1]
    if channel_id.startswith("@") or channel_id.startswith("-100"):
        display = custom_name or channel_id
        await db_save_channel(channel_id, display)
        await send_msg(chat_id, f"✅ Channel added: {channel_id}\n📛 Name: {display}")
    else:
        await send_msg(chat_id,
            "❌ Invalid!\n\n"
            "<b>Usage:</b>\n"
            "<code>/channel @name</code>\n"
            "<code>/channel -100xxx Custom Name</code>\n"
            "<code>/channelist</code> — list all"
        )

async def _show_channel_list(chat_id, edit_message_id=None):
    channels = await db_get_channels()
    if not channels:
        txt = ("📢 No channels saved!\n\n"
               "Add: <code>/channel @name</code>\n"
               "Add: <code>/channel -100xxx Custom Name</code>")
        if edit_message_id:
            await tg_post("editMessageText", {"chat_id": chat_id, "message_id": edit_message_id, "text": txt, "parse_mode": "HTML"})
        else:
            await send_msg(chat_id, txt)
        return
    txt = "📢 <b>Saved Channels</b>\n\nচ্যানেল সিলেক্ট করলে Edit/Delete অপশন পাবে:"
    buttons = []
    for ch in channels:
        ch_id = ch.get("channel_id", "")
        ch_name = ch.get("channel_name", ch_id)
        buttons.append([{"text": f"📢 {ch_name}", "callback_data": f"chsel_{ch_id}"}])
    reply_markup = {"inline_keyboard": buttons}
    if edit_message_id:
        await tg_post("editMessageText", {"chat_id": chat_id, "message_id": edit_message_id, "text": txt,
                                            "parse_mode": "HTML", "reply_markup": reply_markup})
    else:
        await send_msg(chat_id, txt, reply_markup=reply_markup)

async def _show_channel_actions(chat_id, message_id, channel_id):
    channels = await db_get_channels()
    ch = next((c for c in channels if c.get("channel_id") == channel_id), None)
    if not ch:
        await tg_post("editMessageText", {"chat_id": chat_id, "message_id": message_id, "text": "❌ Channel পাওয়া যায়নি, হয়তো delete হয়ে গেছে।"})
        return
    ch_name = ch.get("channel_name", channel_id)
    txt = f"📢 <b>{ch_name}</b>\n🔗 <code>{channel_id}</code>\n\nকী করতে চাও?"
    buttons = [
        [{"text": "✏️ Name Update", "callback_data": f"chren_{channel_id}"}],
        [{"text": "🗑️ Delete", "callback_data": f"chdel_{channel_id}"}],
        [{"text": "⬅️ Back", "callback_data": "chback"}]
    ]
    await tg_post("editMessageText", {"chat_id": chat_id, "message_id": message_id, "text": txt,
                                        "parse_mode": "HTML", "reply_markup": {"inline_keyboard": buttons}})

# ============================================================
# FEATURE: /getid — public/private channel/group link থেকে auto ID বের করা
# ============================================================
async def handle_getid(msg: dict):
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "").strip()
    reply = msg.get("reply_to_message")

    target = text.replace("/getid", "", 1).strip()

    # Forwarded message থেকে ID (reply-mode) — channel/group অথবা user, দুটোই handle
    if not target and reply:
        fwd_chat = reply.get("forward_from_chat")
        fwd_user = reply.get("forward_from")

        if fwd_chat:
            cid = fwd_chat.get("id")
            ctype = fwd_chat.get("type", "")
            cname = fwd_chat.get("title") or fwd_chat.get("username") or ""
            await send_msg(chat_id,
                f"✅ <b>ID পাওয়া গেছে!</b>\n\n"
                f"📛 নাম: {cname}\n"
                f"🆔 ID: <code>{cid}</code>\n"
                f"📂 Type: {ctype}"
            )
            return

        if fwd_user:
            uid_f = fwd_user.get("id")
            fname = fwd_user.get("first_name", "")
            lname = fwd_user.get("last_name", "")
            uname_f = fwd_user.get("username", "")
            full_name = f"{fname} {lname}".strip()
            txt = (
                f"✅ <b>User ID পাওয়া গেছে!</b>\n\n"
                f"📛 নাম: {full_name}\n"
                f"🆔 ID: <code>{uid_f}</code>"
            )
            if uname_f:
                txt += f"\n🔗 Username: @{uname_f}"
            await send_msg(chat_id, txt)
            return

        await send_msg(chat_id,
            "❌ এই মেসেজে forward info নাই।\n\n"
            "📌 সম্ভাব্য কারণ: যাকে forward করেছো, সে তার Privacy Settings-এ "
            "\"Forwarded Messages\" এ নিজের নাম/অ্যাকাউন্ট লুকিয়ে রেখেছে — "
            "সেক্ষেত্রে Telegram নিজেই এই তথ্য কাউকে দেয় না।\n\n"
            "Public/private channel link পাঠাও অথবা অন্য কোনো forwarded message-এ reply করো।"
        )
        return

    if not target:
        await send_msg(chat_id,
            "❌ Link/username দাও!\n\n"
            "<b>Usage:</b>\n"
            "<code>/getid https://t.me/channelname</code>\n"
            "<code>/getid @channelname</code>\n"
            "<code>/getid https://t.me/+AbCdEfGhIjK</code> (private invite link — API ID/HASH লাগবে)\n"
            "<code>/getid -1001234567890</code>\n\n"
            "📌 Private channel/group হলে বটকে আগে member/admin করে নিতে হবে।"
        )
        return

    # Private invite link (t.me/+xxx বা t.me/joinchat/xxx) — সরাসরি resolve করা যায় না,
    # বট আগে থেকে member/admin হলেই getChat কাজ করবে; না হলে instruct করবো।
    is_private_invite = bool(re.search(r't\.me/(\+|joinchat/)', target))

    # চেষ্টা ১: username/link কে @username বা numeric ID তে normalize করা
    resolved = target
    m = re.search(r't\.me/([A-Za-z0-9_]+)$', target)
    if m and not is_private_invite:
        resolved = "@" + m.group(1)
    elif target.startswith("t.me/") or target.startswith("https://t.me/") or target.startswith("http://t.me/"):
        # username pattern না মিললে (private link) as-is রাখা
        pass
    elif not target.startswith("@") and not target.startswith("-100") and not target.lstrip("-").isdigit():
        resolved = "@" + target.lstrip("@")

    if is_private_invite:
        from core import resolve_private_invite_link
        result = await resolve_private_invite_link(target)
        if result.get("ok"):
            txt = (
                f"✅ <b>ID পাওয়া গেছে!</b> (private invite link থেকে)\n\n"
                f"📛 নাম: {result.get('title', '')}\n"
                f"🆔 ID: <code>{result.get('id')}</code>\n"
                f"📂 Type: {result.get('type', '')}"
            )
            if result.get("username"):
                txt += f"\n🔗 Username: @{result['username']}"
            await send_msg(chat_id, txt)
        else:
            await send_msg(chat_id,
                f"❌ Private invite link resolve করা যায়নি!\n\n"
                f"Reason: {result.get('error', 'unknown')}\n\n"
                f"📌 বিকল্প: ওই channel/group থেকে যেকোনো একটা মেসেজ এই চ্যাটে forward করে "
                f"সেই forwarded মেসেজে <code>/getid</code> reply করো।"
            )
        return

    r = await tg_post("getChat", {"chat_id": resolved})
    if not r.get("ok"):
        desc = r.get("description", "")
        await send_msg(chat_id,
            f"❌ ID বের করা যায়নি!\n\n"
            f"Reason: {desc}\n\n"
            f"📌 সম্ভাব্য কারণ:\n"
            f"• বট ওই channel/group-এ নেই\n"
            f"• Channel/username ভুল\n"
            f"• Private হলে বটকে আগে add করতে হবে"
        )
        return

    result = r["result"]
    cid = result.get("id")
    ctype = result.get("type", "")
    cname = result.get("title") or result.get("username") or ""
    uname = result.get("username", "")

    txt = (
        f"✅ <b>ID পাওয়া গেছে!</b>\n\n"
        f"📛 নাম: {cname}\n"
        f"🆔 ID: <code>{cid}</code>\n"
        f"📂 Type: {ctype}"
    )
    if uname:
        txt += f"\n🔗 Username: @{uname}"
    await send_msg(chat_id, txt)


async def handle_pin(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "").strip()
    if not await db_is_owner_or_admin(uid):
        await send_msg(chat_id, "❌ Admin only!")
        return
    # /pin on|off applies to the CHANNEL (via -c), not the DM chat where this
    # is typed — try_pin_message() checks pin_{channel_id}, so the setting
    # must be stored under that same key or it silently never applies.
    c_match = re.search(r'-c\s+(\S+)', text)
    target_id = c_match.group(1) if c_match else chat_id
    arg = re.sub(r'-c\s+\S+', '', text).replace("/pin", "").strip().lower()
    if arg == "on":
        await db_set_pin_setting(target_id, True)
        PIN_ENABLED[target_id] = True
        await send_msg(chat_id, f"📌 Auto-pin চালু ({target_id})! First image, summary, ও PDF pin হবে।")
    elif arg == "off":
        await db_set_pin_setting(target_id, False)
        PIN_ENABLED[target_id] = False
        await send_msg(chat_id, f"📌 Auto-pin বন্ধ ({target_id})!")
    else:
        current = await db_get_pin_setting(target_id)
        await send_msg(chat_id, f"📌 Pin status ({target_id}): {'✅ ON' if current else '❌ OFF'}\n\nChange: /pin on -c @channel | /pin off -c @channel")

async def try_pin_message(chat_id, message_id: int):
    """Channel-এ message pin করার চেষ্টা করে"""
    enabled = PIN_ENABLED.get(chat_id)
    if enabled is None:
        enabled = await db_get_pin_setting(chat_id)
        PIN_ENABLED[chat_id] = enabled
    if enabled:
        r = await tg_post("pinChatMessage", {
            "chat_id": chat_id,
            "message_id": message_id,
            "disable_notification": True
        })
        if not r or not r.get("ok"):
            err_desc = (r or {}).get("description", "no response")
            logger.warning(f"[Pin] FAILED chat={chat_id} msg={message_id}: {err_desc}")
            try:
                await notify_owner(
                    f"⚠️ Auto-pin failed (chat={chat_id}, msg_id={message_id})\n"
                    f"Reason: {err_desc}\n"
                    f"সম্ভবত bot-কে channel-এ 'Pin Messages' admin permission দেওয়া নেই।"
                )
            except Exception:
                pass
    else:
        logger.info(f"[Pin] Skipped (disabled for chat={chat_id})")

