def _build_solve_sheet_html(topic: str, page: int, mcqs: list, answers: dict = None) -> str:
    answers = answers or {}
    labels = ["A", "B", "C", "D"]
    items = ""
    for i, q in enumerate(mcqs):
        ci = {"A": 0, "B": 1, "C": 2, "D": 3}.get(q.get("answer", "A"), 0)
        ua = answers.get(str(i))
        ans_label = labels[ci] if ci < 4 else str(ci + 1)
        ans_text = q.get("options", ["", "", "", ""])[ci] if ci < len(q.get("options", [])) else ""
        exp = _strip_img_tag(q.get("explanation", ""))

        opts_html = ""
        for j, opt in enumerate(q.get("options", [])):
            label = labels[j] if j < 4 else str(j + 1)
            cls = "opt"
            mark = ""
            if j == ci:
                cls += " correct"
                mark = " ✓"
            elif ua is not None and j == ua and ua != ci:
                cls += " wrong"
                mark = " ✗"
            opts_html += f'<div class="{cls}">({label}) {opt}{mark}</div>'

        items += f"""<div class="card">
  <div class="qno">{i+1:02d}.</div>
  <div class="qtxt">{q.get('question','')}</div>
  <div class="opts-wrap">{opts_html}</div>
  <div class="ans-row"><span class="ans-badge">['{ans_label}']</span></div>
  {f'<div class="exp-box"><b>ব্যাখ্যা:</b> {exp}</div>' if exp else ''}
</div>"""

    return f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<style>
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400;600;700;800&display=swap');
@page{{size:A4;margin:8mm 10mm;}}
*{{margin:0;padding:0;box-sizing:border-box;}}
body{{font-family:'Noto Sans Bengali',sans-serif;background:#fff;font-size:12.5px;}}
.hdr{{text-align:center;padding:10px 14px;background:#1a237e;color:#fff;margin-bottom:12px;border-radius:8px;}}
.hdr h1{{font-size:18px;font-weight:800;}}
.hdr .sub{{font-size:12.5px;color:#c5cae9;margin-top:3px;}}
.grid{{display:grid;grid-template-columns:1fr 1fr;gap:10px;}}
.card{{background:#fff;border:1.5px solid #c5cae9;border-radius:8px;padding:9px 10px;break-inside:avoid;page-break-inside:avoid;}}
.qno{{font-size:11.5px;font-weight:800;color:#1a237e;margin-bottom:3px;}}
.qtxt{{font-size:13.5px;font-weight:700;color:#111;margin-bottom:7px;line-height:1.6;}}
.opts-wrap{{display:flex;flex-direction:column;gap:3px;margin-bottom:7px;}}
.opt{{font-size:12.5px;color:#333;padding:2px 6px;border-radius:4px;border:1px solid #e0e0e0;line-height:1.5;}}
.opt.correct{{background:#e8f5e9;border-color:#43a047;color:#1b5e20;font-weight:700;}}
.opt.wrong{{background:#ffebee;border-color:#e53935;color:#b71c1c;font-weight:600;}}
.ans-row{{margin-bottom:4px;}}
.ans-badge{{font-size:11.5px;font-weight:800;color:#1b5e20;background:#f1f8e9;border:1px solid #81c784;border-radius:4px;padding:1px 7px;}}
.exp-box{{font-size:12px;color:#1a237e;background:#e8eaf6;border-left:3px solid #3949ab;padding:5px 7px;border-radius:0 5px 5px 0;line-height:1.55;}}
.footer{{text-align:center;font-size:10px;color:#9e9e9e;margin-top:12px;}}
</style></head>
<body>
<div class="hdr">
  <h1>📋 ATLAS Solve Sheet</h1>
  <div class="sub">🎯 {topic} &nbsp;|&nbsp; 📄 Page No: {fmt_page(page)} &nbsp;|&nbsp; 📝 {len(mcqs)} MCQ</div>
</div>
<div class="grid">{items}</div>
<div class="footer">🚀 ATLAS Special MCQ System — Atlascourses.com</div>
</body></html>"""

# ============================================================
# FEATURE: /tf COMMAND (ported 1:1 from AtlasBot)
# ============================================================
async def handle_tf(msg: dict):
    """/tf — ported 1:1 from AtlasBot's /tf: reply to a PDF, page-by-page
    generate True/False (সত্য-মিথ্যা) style MCQs using AtlasBot's exact
    PROMPT_02, with a live-updating dashboard (per-page MCQ count + time
    + elapsed), then send ONE final CSV of all pages' MCQs combined —
    no per-page photo/quiz/poll. Same -p/-c/-t/-m/[N] flags as AtlasBot."""
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ PDF ফাইলে reply করে <code>/tf</code> দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/tf -p 1-5 -c @channel -m \"Topic Name\" [10]</code>\n"
            "<code>/tf -p 2 -c -100xxx -t 447 -m \"Group Topic\" [10]</code>\n\n"
            "📌 -p = page range (না দিলে সব page)\n"
            "📌 -c = channel/group id (না দিলে এই চ্যাটেই পাঠাবে)\n"
            "📌 -m = topic name\n"
            "📌 -t = group topic/thread id (শুধু -c এ group id দিলে)\n"
            "📌 [N] = প্রতি পেইজে কতগুলো MCQ (ঐচ্ছিক)"
        )
        return

    params = parse_pdf_command(text)
    topic = params["topic"] or "✅ সত্য-মিথ্যার প্রশ্ন"
    page_range = params["page_range"]
    target_chat_id = params["channel_id"] or chat_id
    thread_id = params.get("thread_id")
    per_page_count = params["mcq_count"]
    # [N-M] রেঞ্জ ব্র্যাকেট এতদিন /tf-এ silently ignore হচ্ছিল (শুধু অন্য
    # command handler-গুলোতে mcq_count_min/max ব্যবহার হতো) — এখন এখানেও min
    # enforce করা হচ্ছে যাতে user একটা রেঞ্জ দিলে সেটা মানা হয়।
    per_page_min = params.get("mcq_count_min") or 7
    per_page_max = params.get("mcq_count_max")
    _tf_skip_state = {"gemini_dead": False, "groq_dead": False}  # shared across pages this run

    document = reply["document"]
    file_id = document["file_id"]
    file_unique_id = document.get("file_unique_id")
    file_size = document.get("file_size", 0)

    status_r = await send_msg(chat_id, "⏳ PDF ডাউনলোড হচ্ছে...")
    status_msg_id = status_r.get("result", {}).get("message_id")

    try:
        # /tf always downloads + renders fresh — no cache lookup, so a
        # re-run on the same PDF always regenerates from the live file
        # instead of reusing a previously cached render/MCQ result.
        pdf_bytes = await download_tg_file(file_id, chat_id=chat_id, message_id=reply["message_id"])
        ok, pages = await asyncio.to_thread(pdf_to_images_safe, pdf_bytes, page_range)
        if not ok:
            await send_msg(chat_id, pages)
            return
        if not pages:
            await send_msg(chat_id, "❌ Page পাওয়া যায়নি!")
            return

        total_pages = len(pages)

        ok_count = 0
        fail_count = 0
        all_mcqs_for_csv = []  # collect every page's MCQs to build one final CSV
        page_stats = []  # (page_no, mcq_count_or_None, seconds_taken, provider_or_None) — live dashboard rows
        overall_start = time.monotonic()
        _last_update = [0.0]

        def _fmt_secs(s: float) -> str:
            return f"{s:.1f}s" if s < 60 else f"{int(s // 60)}m {s % 60:.0f}s"

        def _build_dashboard() -> str:
            elapsed = time.monotonic() - overall_start
            lines = [f"⏳ Processing... ({len(page_stats)}/{total_pages} page)",
                      f"🎯 Topic: {topic}",
                      f"⏱️ Elapsed: {_fmt_secs(elapsed)}", "",
                      "📄 Page | MCQ | Model | Time"]
            for p_no, m_count, secs, prov in page_stats[-15:]:
                status_icon = "✅" if m_count is not None else "❌"
                mcq_str = str(m_count) if m_count is not None else "fail"
                prov_str = prov if prov else "-"
                lines.append(f"{status_icon} {p_no} | {mcq_str} | {prov_str} | {_fmt_secs(secs)}")
            if len(page_stats) > 15:
                lines.insert(4, f"... ({len(page_stats) - 15} আগের row লুকানো)")
            return "\n".join(lines)

        for idx, page_entry in enumerate(pages, 1):
            # pdf_to_images() returns a list of (page_number, PIL.Image)
            # tuples, not raw images — unpack to get the actual page number
            # (for accurate dashboard rows) and the Image object.
            if isinstance(page_entry, tuple):
                page_no, page_img = page_entry
            else:
                page_no, page_img = idx, page_entry
            if is_cancelled(chat_id):
                break

            page_start = time.monotonic()
            if status_msg_id:
                try:
                    now = time.monotonic()
                    if now - _last_update[0] >= 1.2 or idx == 1:
                        await edit_msg(chat_id, status_msg_id, _build_dashboard())
                        _last_update[0] = now
                except Exception:
                    pass

            # Retry each page up to 3 times before giving up — a page should
            # essentially never end up empty in the final CSV. If a
            # [min-max] range was given, a result under the minimum also
            # triggers a retry instead of being silently accepted.
            # Exception: if both Gemini and Groq are confirmed exhausted for
            # this run (all keys 429'd on quota), skip retrying entirely —
            # further attempts cannot succeed until tomorrow's quota reset.
            mcqs = []
            provider_used = None
            last_err = None
            if _tf_skip_state["gemini_dead"] and _tf_skip_state["groq_dead"]:
                last_err = "all providers exhausted for today"
            else:
                for attempt in range(1, 4):
                    if _tf_skip_state["gemini_dead"] and _tf_skip_state["groq_dead"]:
                        last_err = "all providers exhausted for today"
                        break
                    try:
                        mcqs, provider_used = await _generate_tf_mcq_atlas(
                            page_img, page_no, per_page_min, per_page_max, skip_state=_tf_skip_state
                        )
                        mcqs = _cap_mcq_options(mcqs, 4)
                        mcqs = _validate_mcq_structure(mcqs)
                        mcqs = _dedupe_mcqs(mcqs) if "_dedupe_mcqs" in globals() else mcqs
                        if mcqs and per_page_min and len(mcqs) < per_page_min:
                            last_err = f"only {len(mcqs)} MCQ, need >= {per_page_min}"
                            logger.warning(f"[/tf] page {page_no} attempt {attempt}: {last_err}")
                            if attempt < 3:
                                continue
                        if mcqs:
                            break
                        last_err = "empty result"
                    except Exception as e:
                        last_err = str(e)
                        logger.warning(f"[/tf] page {page_no} attempt {attempt} failed: {e}")
                    if attempt < 3:
                        await asyncio.sleep(1.5 * attempt)  # small backoff between retries

            if not mcqs:
                fail_count += 1
                page_stats.append((page_no, None, time.monotonic() - page_start, None))
                logger.error(f"[/tf] page {page_no} failed after 3 attempts: {last_err}")
                if _tf_skip_state["gemini_dead"] and _tf_skip_state["groq_dead"] and not _tf_skip_state.get("notified"):
                    _tf_skip_state["notified"] = True
                    try:
                        await send_msg(chat_id,
                            "⚠️ Gemini ও Groq — দুটোরই আজকের quota শেষ হয়ে গেছে "
                            "(daily limit exhausted)। বাকি page-গুলো এখনই skip করা হচ্ছে, "
                            "যা successful হয়েছে সেটার CSV নিচে পাঠানো হবে। আগামীকাল quota "
                            "reset হলে বাকি page-গুলো আবার /tf দিয়ে চালান।"
                        )
                    except Exception:
                        pass
                continue

            if per_page_max and per_page_max > 0:
                mcqs = mcqs[:per_page_max]
            elif per_page_count and per_page_count > 0:
                mcqs = mcqs[:per_page_count]

            all_mcqs_for_csv.extend(mcqs)
            ok_count += 1
            page_stats.append((page_no, len(mcqs), time.monotonic() - page_start, provider_used))

        total_elapsed = time.monotonic() - overall_start

        # Permanent per-page breakdown — every page's MCQ count and which AI
        # provider (Gemini/Groq) generated it, not just the last-15-rows live
        # view, so it survives after processing finishes.
        breakdown_lines = ["📋 Page-wise MCQ breakdown:"]
        for p_no, m_count, secs, prov in page_stats:
            icon = "✅" if m_count is not None else "❌"
            mcq_str = str(m_count) if m_count is not None else "fail"
            prov_str = f" [{prov}]" if prov else ""
            breakdown_lines.append(f"{icon} Page {p_no}: {mcq_str} MCQ{prov_str} ({_fmt_secs(secs)})")
        breakdown_text = "\n".join(breakdown_lines)

        if status_msg_id:
            try:
                await edit_msg(chat_id, status_msg_id,
                    f"🏁 সম্পন্ন! ✅ {ok_count} page সফল"
                    + (f", ❌ {fail_count} page ব্যর্থ" if fail_count else "")
                    + f"\n⏱️ মোট সময়: {_fmt_secs(total_elapsed)}"
                    + f"\n📝 মোট MCQ: {len(all_mcqs_for_csv)}"
                )
            except Exception:
                pass

        # Send the permanent breakdown as its own message (survives even
        # though the dashboard message above only shows a summary).
        try:
            if len(breakdown_text) > 4000:
                # Telegram message length safety — split into chunks
                for i in range(0, len(breakdown_lines), 40):
                    chunk = "\n".join(breakdown_lines[i:i+40])
                    await send_msg(chat_id, chunk)
            else:
                await send_msg(chat_id, breakdown_text)
        except Exception as e:
            logger.warning(f"[/tf] breakdown send failed: {e}")

        # Final CSV export — same format used across the bot's CSV pipeline
        # (questions,option1,option2,option3,option4,answer,explanation;
        # answer = 1/2/3/4 for A/B/C/D).
        if all_mcqs_for_csv:
            try:
                import io as _io_tf, csv as _csv_tf
                csv_buf = _io_tf.StringIO()
                writer = _csv_tf.writer(csv_buf)
                writer.writerow(["questions", "option1", "option2", "option3", "option4", "option5", "answer", "explanation", "type", "section"])
                ans_map = {0: "1", 1: "2", 2: "3", 3: "4", "A": "1", "B": "2", "C": "3", "D": "4"}
                for m in all_mcqs_for_csv:
                    opts = (m.get('options', []) + ["", "", "", "", ""])[:5]
                    ans = m.get('answer', 0)
                    if isinstance(ans, str):
                        ans_val = ans_map.get(ans.strip().upper(), "1")
                    else:
                        try:
                            ans_val = ans_map.get(int(ans), "1")
                        except (TypeError, ValueError):
                            ans_val = "1"
                    writer.writerow([
                        m.get('question', ''), opts[0], opts[1], opts[2], opts[3], opts[4],
                        ans_val, m.get('explanation', ''), "1", "1"
                    ])
                csv_bytes = csv_buf.getvalue().encode('utf-8-sig')
                _pr_label = page_range if page_range else f"1-{total_pages}"
                _pr_tag = _pr_label.replace(" ", "")
                send_doc_kwargs = {
                    "chat_id": target_chat_id, "file_bytes": csv_bytes,
                    "filename": f"tf_{topic[:30]}_p{_pr_tag}.csv",
                    "caption": f"📄 {topic}\n📃 Page: {_pr_label}\n📝 মোট MCQ: {len(all_mcqs_for_csv)} ({ok_count} page)"
                }
                if thread_id:
                    send_doc_kwargs["message_thread_id"] = thread_id
                await send_document(**send_doc_kwargs)
            except Exception as e:
                logger.error(f"[/tf] CSV export error: {e}")
    except Exception as e:
        logger.error(f"[/tf] Error: {e}")
        await _safe_error_reply(chat_id, e)


# ============================================================
# FEATURE 7B: /extra COMMAND — fully standalone, no _EXTRA_MODE, no
# handle_pdf/pdf_generate_all_pages/generate_mcq_from_image reuse. Only
# shares low-level utilities (download/render/dashboard/raw AI-provider
# calls) and the generic process_pdf_pages poster.
# ============================================================
def _build_extra_prompt_standalone(topic: str) -> str:
    """/extra's own prompt builder — completely independent of
    _build_mcq_prompt/_build_extra_prompt (no shared prompt-selector
    contextvar chain). STRICT FILTER: only hand-marked (highlighter/pen
    underline/circle/box/star) content, everything else ignored."""
    return (
        f"You are an expert MCQ-extraction engine for Bengali/English academic "
        f"textbook pages (medical/HSC/admission-standard quality).\n"
        f"Topic: {topic}\n\n"
        f"═══════════════════════════════\n"
        f"🟥 STRICT FILTER — ONLY HAND-MARKED CONTENT, NOTHING ELSE\n"
        f"═══════════════════════════════\n"
        f"This page may contain a LOT of printed text, but you must generate "
        f"MCQs ONLY from the specific lines/words/paragraphs that have an "
        f"EXTRA mark added on top of the book's original printing by hand or "
        f"highlighter pen:\n"
        f"- Highlighter color over the text (any color — yellow, green, "
        f"orange, pink, blue, etc.)\n"
        f"- Pen underline drawn under the text (any ink color)\n"
        f"- A box, circle, or bracket drawn around the text by hand\n"
        f"- A star, tick, or other hand-drawn mark next to the text pointing "
        f"to it\n\n"
        f"🚫 DO NOT generate any MCQ from plain/unmarked text, even if it "
        f"looks important, is a definition, is bold/italic in the ORIGINAL "
        f"book printing, or seems exam-relevant. Bold/italic that is part "
        f"of the book's own original typesetting is NOT a hand-mark — only "
        f"count marks that are clearly added on top, in a different "
        f"ink/highlighter color or hand-drawn stroke, distinguishable from "
        f"the book's own printing.\n\n"
        f"If NO hand-marks exist anywhere on this page, return exactly [] — "
        f"zero MCQs is a completely valid and expected result.\n\n"
        f"For each hand-marked line/phrase found, generate ONE high-quality "
        f"MCQ (4 options, correct answer, short Bengali explanation).\n\n"
        f"OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown.\n"
        f'[{{"question":"...","options":{{"A":"...","B":"...","C":"...","D":"..."}},'
        f'"answer":"A/B/C/D","explanation":"..."}}]'
    )


async def _extra_gen_from_image(img, topic, page_num, key_offset: int = 0, exclude_groq_keys: set = None):
    """/extra's OWN generation call — completely standalone, does not go
    through generate_mcq_from_image/_generate_mcq_from_image_raw or the
    _EXTRA_MODE contextvar. Gemini first (primary), Groq fallback if
    Gemini gave a technical failure (not a genuine empty result). Most
    /extra pages legitimately have 0 hand-marked MCQs -- a valid "[]"
    response from either provider is trusted immediately and does NOT
    trigger burning through more keys/providers, since that would just be
    wasted spend chasing a result that was never going to be non-empty.
    Count is NEVER user-settable (content-driven)."""
    prompt = _build_extra_prompt_standalone(topic)
    tried_keys = set()
    gemini_ok = False
    try:
        txt = await _gemini_verify_raw_text(img, prompt)
        if txt:
            out = _qbm_parse_json(txt)
            gemini_ok = True  # got a real response (even if it parsed to [])
        else:
            out = []
    except Exception as e:
        logger.warning(f"[Extra-Standalone] gemini failed page {page_num}: {e}")
        out = []

    # Only fall to Groq on a TECHNICAL failure (Gemini gave nothing back at
    # all) -- a genuine "[]" from Gemini is trusted as-is, no key burn.
    if not out and not gemini_ok:
        try:
            groq_keys = groq_key_rotator.ordered_keys(offset=key_offset)
            if exclude_groq_keys:
                fresh = [k for k in groq_keys if k not in exclude_groq_keys]
                groq_keys = fresh if fresh else groq_keys
            data_url = None
            for key in groq_keys[:5]:
                tried_keys.add(key)
                if data_url is None:
                    data_url = _img_to_data_url_groq(img, prompt_len_hint=prompt)
                txt, status = await _post_openai_compat(
                    "https://api.groq.com/openai/v1/chat/completions",
                    key, "qwen/qwen3.6-27b", data_url, prompt
                )
                if txt:
                    # Any real response (even parses to []) is trusted --
                    # stop here, don't keep burning keys chasing MCQs that
                    # genuinely don't exist on this page.
                    out = _qbm_parse_json(txt)
                    groq_key_rotator.mark_healthy(key)
                    break
                if status == 429:
                    groq_key_rotator.mark_rate_limited(key)
                # status/txt empty (technical failure) -- try next key
        except Exception as e:
            logger.warning(f"[Extra-Standalone] groq failed page {page_num}: {e}")
            out = []

    out = _cap_mcq_options(out, 4)
    out = _validate_mcq_structure(out)
    out = _dedupe_mcqs(out) if "_dedupe_mcqs" in globals() else out

    if out:
        out = await _extra_marking_audit(out, img, topic, page_num)
        out = _validate_mcq_structure(out)

    # got_real_response: True if EITHER provider actually answered (even []).
    # False only means both Gemini and Groq had a genuine technical failure
    # (exception/empty transport) -- that's the only case worth retrying.
    got_real_response = gemini_ok or bool(tried_keys)
    return out, tried_keys, got_real_response


async def extra_generate_all_pages(
    chat_id: int, pages: list, topic: str,
    file_name: str, status_msg_id: int = None
) -> list:
    """/extra's OWN page-loop — completely standalone copy, not calling
    pdf_generate_all_pages. Same 2-page-parallel + page-pairing idea (since
    /extra pages are often mostly empty) but self-contained."""
    if len(pages) > 1:
        pages = _pair_pages_for_extra(pages)

    page_status = [{"page": p, "done": False, "current": False, "mcq": 0} for p, _ in pages]
    start_time = time.time()
    results_by_idx = [None] * len(pages)
    _active_jobs["count"] = _active_jobs.get("count", 0) + 1
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, f"EXTRA MCQ generation ({file_name}, parallel)")

    _EXTRA_PARALLEL_PAGES = 2
    sem = asyncio.Semaphore(_EXTRA_PARALLEL_PAGES)
    lock = asyncio.Lock()
    total_mcq_box = {"n": 0}
    _slot_counter = {"n": 0}

    async def _run_one(idx, page_num, img):
        if is_cancelled(chat_id):
            return
        async with sem:
            if is_cancelled(chat_id):
                return
            async with lock:
                slot = _slot_counter["n"] % _EXTRA_PARALLEL_PAGES
                _slot_counter["n"] += 1
                page_status[idx]["current"] = True
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq_box["n"], 0), reply_markup=_cancel_kb(chat_id))

            mcqs = []
            tried = set()
            got_real = False
            try:
                mcqs, tried, got_real = await _extra_gen_from_image(img, topic, page_num, key_offset=slot)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                logger.error(f"[Extra Generate] Page {page_num} error: {e}; retrying once")

            if not mcqs and not got_real and not is_cancelled(chat_id):
                try:
                    await asyncio.sleep(1)
                    mcqs, _, _ = await _extra_gen_from_image(img, topic, page_num, key_offset=slot, exclude_groq_keys=tried)
                except asyncio.CancelledError:
                    raise
                except Exception as e:
                    logger.error(f"[Extra Generate] Page {page_num} retry also failed: {e}")

            if is_cancelled(chat_id):
                return
            async with lock:
                results_by_idx[idx] = (page_num, img, mcqs)
                total_mcq_box["n"] += len(mcqs)
                page_status[idx]["current"] = False
                page_status[idx]["done"] = True
                page_status[idx]["mcq"] = len(mcqs)
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq_box["n"], 0), reply_markup=_cancel_kb(chat_id))

    async def _watch_cancel(tasks):
        while not all(t.done() for t in tasks):
            if is_cancelled(chat_id):
                for t in tasks:
                    if not t.done():
                        t.cancel()
                return
            await asyncio.sleep(0.3)

    try:
        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, 0, 0), reply_markup=_cancel_kb(chat_id))
        tasks = [_spawn_task(_run_one(idx, page_num, img)) for idx, (page_num, img) in enumerate(pages)]
        watcher = _spawn_task(_watch_cancel(tasks))
        await asyncio.gather(*tasks, return_exceptions=True)
        watcher.cancel()
    finally:
        _active_jobs["count"] = max(0, _active_jobs.get("count", 1) - 1)

    return [r for r in results_by_idx if r is not None]


async def handle_extra(msg: dict):
    """/extra — fully standalone command, independent of handle_pdf and
    _EXTRA_MODE. PDF-এ reply করে দিলে শুধু hand-marked (highlighter/pen
    underline/circle/star) content থেকে MCQ generate করে; unmarked সব
    ignore করে। Own lock, own generation loop, own dashboard — shares only
    low-level utilities (download/render/dashboard/AI-provider calls) and
    the generic process_pdf_pages poster."""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _handle_extra_impl(msg)


async def _handle_extra_impl(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    uname = msg["from"].get("first_name", "User")
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ PDF ফাইলে reply করে <code>/extra</code> দাও!\n\n"
            "<b>Example:</b>\n"
            "<code>/extra -p 1-5 -c @channel -m \"Topic\"</code>\n"
            "<code>/extra -p 2 -c -100xxx -t 447 -m \"Group Topic\"</code>\n\n"
            "শুধুমাত্র কলম/হাইলাইটার দিয়ে দাগ/মার্ক করা লাইন থেকেই MCQ বানাবে — "
            "বাকি সব লাইন (মার্ক না করা) সম্পূর্ণ বাদ যাবে। কোনো মার্ক না থাকলে "
            "সেই পেজে ০টা MCQ হবে।\n"
            "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে",
            parse_mode="HTML"
        )
        return

    file_name = reply["document"].get("file_name", "document.pdf")
    if not file_name.lower().endswith(".pdf"):
        await send_msg(chat_id, "❌ শুধু PDF file support করে!")
        return

    params = parse_pdf_command(text)
    topic = params["topic"]
    if not topic:
        m_t = re.search(r'-t\s+"([^"]+)"', text) or re.search(r"-t\s+'([^']+)'", text) or re.search(r'-t\s+(\S+)', text)
        if m_t:
            topic = m_t.group(1)
    topic = topic or DEFAULT_TOPIC
    page_range = params["page_range"]
    channel_id = params["channel_id"]
    thread_id = params.get("thread_id")
    file_id = reply["document"]["file_id"]
    file_unique_id = reply["document"].get("file_unique_id")
    file_size = reply["document"].get("file_size", 0)

    status_r = await send_msg(chat_id, "⏳ PDF download হচ্ছে...")
    status_msg_id = status_r.get("result", {}).get("message_id")

    try:
        pdf_bytes = await _download_pdf_cached(file_id, chat_id=chat_id,
                                                message_id=reply["message_id"], file_unique_id=file_unique_id)

        if page_range:
            parts = page_range.split("-")
            req_first = int(parts[0])
            req_last = int(parts[1]) if len(parts) > 1 else req_first
        else:
            total_pages = await asyncio.to_thread(get_pdf_page_count, pdf_bytes)
            req_first, req_last = 1, total_pages

        ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
        if not ok:
            await send_msg(chat_id, pages)
            return
        if not pages:
            await send_msg(chat_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ Hand-marked content খোঁজা হচ্ছে...")

        generated_pages = await extra_generate_all_pages(chat_id, pages, topic, file_name, status_msg_id)
        pdf_bytes = None

        if channel_id:
            await process_pdf_pages(chat_id, uid, uname, generated_pages, topic, None,
                channel_id, False, file_name, status_msg_id, thread_id=thread_id, skip_generate=True)
            return

        channels = await db_get_channels()
        if not channels:
            await process_pdf_pages(chat_id, uid, uname, generated_pages, topic, None,
                None, True, file_name, status_msg_id, thread_id=thread_id, skip_generate=True)
            return

        app.state.pdf_cache = getattr(app.state, "pdf_cache", {})
        app.state.pdf_cache[f"pdf_img_{uid}"] = generated_pages
        _cap_page_cache(app.state.pdf_cache)
        await sb_exec(lambda: sb.table("quiz_sessions").upsert({
            "key": f"pdf_pending_{uid}",
            "data": json.dumps({"topic": topic, "mcq_count": None, "file_name": file_name, "status_msg_id": status_msg_id, "thread_id": thread_id, "file_id": file_id, "page_range": page_range}),
            "updated_at": int(time.time())
        }).execute())

        total_mcq_found = sum(len(mcqs) for _, _, mcqs in generated_pages)

        try:
            all_mcqs_flat = [m for _, _, mcqs in generated_pages for m in mcqs]
            if all_mcqs_flat:
                csv_bytes = _mcqs_to_csv_bytes(all_mcqs_flat)
                await send_document(chat_id, csv_bytes, f"{topic}_mcq.csv",
                    caption=f"📄 {topic} — {len(all_mcqs_flat)} MCQ", mime_type="text/csv")
        except Exception as csv_err:
            logger.warning(f"[Extra] CSV auto-send failed: {csv_err}")

        page_breakdown = "\n".join(
            f"✅ Page {fmt_page(p)}: {len(mcqs)} MCQ ✓" for p, _, mcqs in generated_pages
        )
        kb = {"inline_keyboard": []}
        for ch in channels:
            ch_id = ch.get("channel_id", "")
            ch_name = ch.get("channel_name", ch_id)
            kb["inline_keyboard"].append([{"text": f"📢 {ch_name}", "callback_data": f"pdfch_{ch_id}_{uid}"}])
        kb["inline_keyboard"].append([{"text": "📄 CSV File Only", "callback_data": f"pdfch_csv_{uid}"}])
        await send_msg(chat_id,
            f"✅ <b>Extra Extraction Complete!</b>\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            f"📝 Total MCQ: {total_mcq_found}  |  📋 Pages: {len(generated_pages)}\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{page_breakdown}\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🎯 Topic: {topic}\n\nChannel select করো:",
            reply_markup=kb)

    except Exception as e:
        logger.error(f"[Extra] Handle error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)
        await notify_owner(f"[Extra] Error for user {uid}:\n{e}")


# ============================================================
# FEATURE 8: /pdf COMMAND
# ============================================================
async def handle_pdf(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    uname = msg["from"].get("first_name", "User")
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")
    if not reply or not reply.get("document"):
        if _CHOK_MODE.get():
            await send_msg(chat_id,
                "❌ PDF ফাইলে reply করে <code>/chok</code> দাও!\n\n"
                "<b>Example:</b>\n"
                "<code>/chok -p 1-5 -c @channel -m \"Topic\"</code>\n"
                "<code>/chok -p 2 -c -100xxx -t 447 -m \"Group Topic\"</code>\n\n"
                "ছক/বক্স/টেবিল PDF-এর জন্য বিশেষায়িত — প্রতিটা বক্স থেকে MCQ (mixed style)।\n"
                "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে"
            )
        elif _BANGLA_MODE.get():
            await send_msg(chat_id,
                "❌ PDF ফাইলে reply করে <code>/bangla</code> দাও!\n\n"
                "<b>Example:</b>\n"
                "<code>/bangla -p 1-5 -c @channel -m \"Topic\" [10]</code>\n"
                "<code>/bangla -p 2 -c -100xxx -t 447 -m \"Group Topic\" [10]</code>\n\n"
                "প্রতিটা লাইন/অংশ থেকে MCQ বানাবে, কোনো maximum limit নেই।\n"
                "<code>[N]</code> = প্রতি পেইজে কতগুলো MCQ বানাতে হবে (ঐচ্ছিক)\n"
                "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে"
            )
        elif _TF_MODE.get():
            await send_msg(chat_id,
                "❌ PDF ফাইলে reply করে <code>/tf</code> দাও!\n\n"
                "<b>Example:</b>\n"
                "<code>/tf -p 1-5 -c @channel -m \"Topic\"</code>\n"
                "<code>/tf -p 2 -c -100xxx -t 447 -m \"Group Topic\"</code>\n\n"
                "True/False style MCQ বানাবে (\"নিচের কোনটিকে সত্য/মিথ্যা বললে ভুল "
                "হবে/হবে না\" প্যাটার্ন) — পেইজপ্রতি ১০-২০টি, content অনুযায়ী।\n"
                "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে"
            )
        elif _EXTRA_MODE.get():
            await send_msg(chat_id,
                "❌ PDF ফাইলে reply করে <code>/extra</code> দাও!\n\n"
                "<b>Example:</b>\n"
                "<code>/extra -p 1-5 -c @channel -m \"Topic\"</code>\n"
                "<code>/extra -p 2 -c -100xxx -t 447 -m \"Group Topic\"</code>\n\n"
                "শুধুমাত্র কলম/হাইলাইটার দিয়ে দাগ/মার্ক করা লাইন থেকেই MCQ বানাবে — "
                "বাকি সব লাইন (মার্ক না করা) সম্পূর্ণ বাদ যাবে। কোনো মার্ক না থাকলে "
                "সেই পেজে ০টা MCQ হবে।\n"
                "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে"
            )
        else:
            await send_msg(chat_id,
                "❌ PDF ফাইলে reply করে <code>/pdf</code> দাও!\n\n"
                "<b>Example:</b>\n"
                "<code>/pdf -p 1-5 -c @channel -m \"Topic\" [10]</code>\n"
                "<code>/pdf -p 2 -c -100xxx -t 447 -m \"Group Topic\" [10]</code>\n\n"
                "<code>[N]</code> = প্রতি পেইজে কতগুলো MCQ বানাতে হবে (ঐচ্ছিক)\n"
                "<code>-t</code> থ্রেড আইডি কোটেশন সহ/ছাড়া দুই ভাবেই দেওয়া যাবে"
            )
        return
    params = parse_pdf_command(text)
    topic = params["topic"]
    if not topic:
        m_t = re.search(r'-t\s+"([^"]+)"', text) or re.search(r"-t\s+'([^']+)'", text) or re.search(r'-t\s+(\S+)', text)
        if m_t:
            topic = m_t.group(1)
    topic = topic or DEFAULT_TOPIC
    page_range = params["page_range"]
    channel_id = params["channel_id"]
    mcq_count = params["mcq_count"]
    if params.get("mcq_count_min") and params.get("mcq_count_max"):
        mcq_count = (params["mcq_count_min"], params["mcq_count_max"])
    if _CHOK_MODE.get():
        # /chok count is NEVER user-settable — always content/box-driven per
        # the user's explicit instruction. Any number typed after /chok is
        # ignored entirely so it can never cap or override the mandatory
        # 15+ per-box MCQ generation.
        mcq_count = None
    if _TF_MODE.get():
        # /tf count is NEVER user-settable — the prompt itself mandates a
        # content-driven 10-20 range, same reasoning as /chok above.
        mcq_count = None
    if _EXTRA_MODE.get():
        # /extra count is content-driven by how much is actually
        # hand-marked on the page (could legitimately be 0) — never
        # user-settable, same reasoning as /chok/tf above.
        mcq_count = None
    thread_id = params.get("thread_id")
    file_name = reply["document"].get("file_name", "document.pdf")
    file_id = reply["document"]["file_id"]
    file_unique_id = reply["document"].get("file_unique_id")
    file_size = reply["document"].get("file_size", 0)

    status_r = await send_msg(chat_id, "⏳ PDF download হচ্ছে...")
    status_msg_id = status_r.get("result", {}).get("message_id")

    try:
        if status_msg_id:
            size_mb = round(file_size / 1024 / 1024, 1) if file_size else "?"
            await edit_msg(chat_id, status_msg_id,
                f"⏳ PDF download হচ্ছে...\n📄 File: {file_name}\n📦 Size: {size_mb} MB\n[░░░░░░░░░░ 0%]")

        _last_pct5820 = {"v": -1}
        def _dl_progress5820(done, total):
            if not status_msg_id or not total:
                return
            pct = int(done * 100 / total)
            if pct - _last_pct5820["v"] < 10 and pct != 100:
                return
            _last_pct5820["v"] = pct
            bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
            size_mb = round(file_size / 1024 / 1024, 1) if file_size else "?"
            _spawn_task(edit_msg(chat_id, status_msg_id,
                f"⏳ PDF download হচ্ছে...\n📄 File: {file_name}\n📦 Size: {size_mb} MB\n[{bar} {pct}%]"))

        pdf_bytes = await _download_pdf_cached(file_id, progress_cb=_dl_progress5820, chat_id=chat_id, message_id=reply["message_id"], file_unique_id=file_unique_id)

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ Download complete!\n📄 File: {file_name}\n[██████████ 100%]\n⏳ PDF → Images converting...")

        # ── Auto-chunking: only when channel_id is already known (-c given).
        # If no channel_id, we must NOT bypass the channel-picker below —
        # so batching for that case is handled inside the no-channel branch.
        if channel_id and page_range:
            parts = page_range.split("-")
            req_first = int(parts[0])
            req_last = int(parts[1]) if len(parts) > 1 else req_first
        elif channel_id:
            total_pages = await asyncio.to_thread(get_pdf_page_count, pdf_bytes)
            req_first, req_last = 1, total_pages
        else:
            req_first = req_last = None

        if channel_id and (req_last - req_first + 1) > _PDF_MAX_PAGES_PER_CALL:
            for batch_start in range(req_first, req_last + 1, _PDF_MAX_PAGES_PER_CALL):
                batch_end = min(batch_start + _PDF_MAX_PAGES_PER_CALL - 1, req_last)
                batch_range = f"{batch_start}-{batch_end}"
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        f"⏳ Batch {batch_start}-{batch_end}/{req_last} processing...")
                ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, batch_range)
                if not ok:
                    await send_msg(chat_id, pages)
                    continue
                if not pages:
                    continue
                await process_pdf_pages(chat_id, uid, uname, pages, topic, mcq_count,
                    channel_id, False, file_name, None, thread_id=thread_id, skip_generate=False)
            return

        if channel_id:
            ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
            # HF has 16GB RAM (not Render's constrained free tier) — safe to
            # keep pdf_bytes alive; also needed now for the render cache key.
            if not ok:
                await send_msg(chat_id, pages)
                return
            if not pages:
                await send_msg(chat_id, "❌ Page পাওয়া যায়নি!")
                return

            if status_msg_id:
                await edit_msg(chat_id, status_msg_id,
                    f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ MCQ Generation শুরু হচ্ছে...")

        if not channel_id:
            # ── No -c given: decode + generate in RAM-safe batches of
            # _PDF_MAX_PAGES_PER_CALL pages at a time (avoids decoding the
            # entire PDF's pages into memory upfront for large docs).
            # Channel selection happens only AFTER all batches are generated.
            if page_range:
                parts = page_range.split("-")
                req_first = int(parts[0])
                req_last = int(parts[1]) if len(parts) > 1 else req_first
            else:
                total_pages = await asyncio.to_thread(get_pdf_page_count, pdf_bytes)
                req_first, req_last = 1, total_pages

            generated_pages = []
            for batch_start in range(req_first, req_last + 1, _PDF_MAX_PAGES_PER_CALL):
                batch_end = min(batch_start + _PDF_MAX_PAGES_PER_CALL - 1, req_last)
                batch_range = f"{batch_start}-{batch_end}"
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        f"⏳ Batch {batch_start}-{batch_end}/{req_last} generating MCQ...")
                ok, batch_pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, batch_range)
                if not ok:
                    await send_msg(chat_id, batch_pages)
                    continue
                if not batch_pages:
                    continue
                batch_result = await pdf_generate_all_pages(
                    chat_id, batch_pages, topic, mcq_count, file_name, status_msg_id
                )
                generated_pages.extend(batch_result)
            pdf_bytes = None  # RAM fix: raw PDF no longer needed after all batches decoded

            channels = await db_get_channels()
            if not channels:
                await process_pdf_pages(chat_id, uid, uname, generated_pages, topic, mcq_count,
                    None, True, file_name, status_msg_id, thread_id=thread_id, skip_generate=True)
                return
            app.state.pdf_cache = getattr(app.state, "pdf_cache", {})
            app.state.pdf_cache[f"pdf_img_{uid}"] = generated_pages
            _cap_page_cache(app.state.pdf_cache)
            await sb_exec(lambda: sb.table("quiz_sessions").upsert({
                "key": f"pdf_pending_{uid}",
                "data": json.dumps({"topic": topic, "mcq_count": mcq_count, "file_name": file_name, "status_msg_id": status_msg_id, "thread_id": thread_id, "file_id": file_id, "page_range": page_range}),
                "updated_at": int(time.time())
            }).execute())

            total_mcq_found = sum(len(mcqs) for _, _, mcqs in generated_pages)

            # ✅ CSV auto-send — channel-select button dekhanor age-i, kono
            # click chara automatically CSV file pathiye dey.
            try:
                all_mcqs_flat = [m for _, _, mcqs in generated_pages for m in mcqs]
                if all_mcqs_flat:
                    csv_bytes = _mcqs_to_csv_bytes(all_mcqs_flat)
                    await send_document(chat_id, csv_bytes, f"{topic}_mcq.csv",
                        caption=f"📄 {topic} — {len(all_mcqs_flat)} MCQ", mime_type="text/csv")
            except Exception as csv_err:
                logger.warning(f"[PDF] CSV auto-send failed: {csv_err}")

            page_breakdown = "\n".join(
                f"✅ Page {fmt_page(p)}: {len(mcqs)} MCQ ✓" for p, _, mcqs in generated_pages
            )
            kb = {"inline_keyboard": []}
            for ch in channels:
                ch_id = ch.get("channel_id", "")
                ch_name = ch.get("channel_name", ch_id)
                kb["inline_keyboard"].append([{"text": f"📢 {ch_name}", "callback_data": f"pdfch_{ch_id}_{uid}"}])
            kb["inline_keyboard"].append([{"text": "📄 CSV File Only", "callback_data": f"pdfch_csv_{uid}"}])
            await send_msg(chat_id,
                f"✅ <b>Generation Complete!</b>\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"📝 Total MCQ: {total_mcq_found}  |  📋 Pages: {len(generated_pages)}\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{page_breakdown}\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🎯 Topic: {topic}\n\nChannel select করো:",
                reply_markup=kb)
            return

        # ── Channel already known (-c flag) → stream per-page: ──
        # generate MCQ for a page and send its poll immediately,
        # instead of waiting for the whole PDF to finish generating.
        await process_pdf_pages(chat_id, uid, uname, pages, topic, mcq_count,
            channel_id, False, file_name, status_msg_id, thread_id=thread_id, skip_generate=False)
    except Exception as e:
        logger.error(f"[PDF] Handle error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)
        await notify_owner(f"[PDF] Error for user {uid}:\n{e}")

# ============================================================
# FEATURE 9: PROCESS PDF PAGES
# ============================================================
def _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls):
    elapsed = int(time.time() - start_time)
    mins, secs = divmod(elapsed, 60)
    done = sum(1 for s in page_status if s["done"])
    total = len(page_status)
    pct = int(done / total * 100) if total else 0
    bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
    lines = [
        "⏳ <b>ATLAS PDF Processing...</b>",
        "━━━━━━━━━━━━━━━━━━━━━━",
        f"📄 File: {file_name}", f"🎯 Topic: {topic}", f"📋 Pages: {total} total",
        "━━━━━━━━━━━━━━━━━━━━━━"
    ]
    for s in page_status:
        if s["done"]:
            if s.get("failed") or s["mcq"] == 0:
                err = (s.get("error") or "").strip()
                err_short = (err[:80] + "…") if len(err) > 80 else err
                if err_short:
                    lines.append(f"⚠️ Page {fmt_page(s['page'])}: 0 MCQ — {err_short}")
                else:
                    lines.append(f"⚠️ Page {fmt_page(s['page'])}: 0 MCQ (content না পাওয়া গেছে)")
            else:
                model_tag = s.get("model", "")
                model_str = f" ({model_tag})" if model_tag else ""
                lines.append(f"✅ Page {fmt_page(s['page'])}: {s['mcq']} MCQ{model_str} ✓")
        elif s["current"]:
            lines.append(f"⏳ Page {fmt_page(s['page'])}: Processing...")
        else:
            lines.append(f"⬜ Page {fmt_page(s['page'])}: Waiting")
    lines += [
        "━━━━━━━━━━━━━━━━━━━━━━",
        f"📊 Progress: {pct}% [{bar}]",
        f"⏱️ Elapsed: {mins}:{secs:02d}",
        f"📝 MCQ done: {total_mcq}",
        f"🔄 Polls sent: {total_polls}"
    ]
    return "\n".join(lines)

def _pair_pages_for_extra(pages: list) -> list:
    """Combine consecutive pages 2-at-a-time into a single vertically-
    stacked composite image, for /extra mode's low-yield-per-page case.
    Odd page out (if any) at the end is left unpaired. Returns a new
    list of (label, composite_img) in the same shape pdf_generate_all_pages
    already expects, so no other code needs to change."""
    from PIL import Image as _PILImg
    paired = []
    i = 0
    while i < len(pages):
        if i + 1 < len(pages):
            (p1, img1), (p2, img2) = pages[i], pages[i + 1]
            w = max(img1.width, img2.width)
            gap = 12
            h = img1.height + gap + img2.height
            composite = _PILImg.new("RGB", (w, h), (255, 255, 255))
            composite.paste(img1, (0, 0))
            composite.paste(img2, (0, img1.height + gap))
            paired.append((f"{p1}-{p2}", composite))
            i += 2
        else:
            p1, img1 = pages[i]
            paired.append((str(p1), img1))
            i += 1
    return paired


async def pdf_generate_all_pages(
    chat_id: int, pages: list, topic: str, mcq_count: int,
    file_name: str, status_msg_id: int = None
) -> list:
    """
    /qbm-এর মতোই Phase 1 -- channel select/posting-এর আগে সব page-এর MCQ
    generate করে ফেলে। Returns list of (page_num, img, mcqs) tuples.
    """
    if _EXTRA_MODE.get() and len(pages) > 1:
        # /extra pages usually have very few (or zero) marked lines each --
        # one full AI call per page would waste most of the call's budget
        # on empty output. Combine 2 consecutive pages into a single
        # stacked composite image and process them together in ONE call,
        # roughly halving total API calls for this mode. Page numbers are
        # kept as "N-M" labels so results/dashboard/CSV still show which
        # original pages contributed each MCQ batch.
        pages = _pair_pages_for_extra(pages)

    page_status = [{"page": p, "done": False, "current": False, "mcq": 0} for p, _ in pages]
    start_time = time.time()
    results_by_idx = [None] * len(pages)
    _active_jobs["count"] = _active_jobs.get("count", 0) + 1
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, f"PDF MCQ generation ({file_name}, parallel)")

    # 2 pages in parallel: each concurrent slot uses a key_offset so they
    # start from different Groq keys (round-robin, see ordered_keys(offset=))
    # instead of both hammering the same first key. This roughly halves
    # wall-clock time per page-batch without increasing the number of keys
    # tried per page (same 5-key cap each), so key spend stays the same
    # while total throughput doubles. Previously this was strictly
    # sequential (1 at a time) specifically to avoid same-key TPM collisions
    # — the offset makes 2-way parallelism safe against that same collision.
    _PDF_PARALLEL_PAGES = 2
    sem = asyncio.Semaphore(_PDF_PARALLEL_PAGES)
    lock = asyncio.Lock()
    total_mcq_box = {"n": 0}
    _slot_counter = {"n": 0}

    async def _run_one(idx, page_num, img):
        if is_cancelled(chat_id):
            return
        async with sem:
            if is_cancelled(chat_id):
                return
            async with lock:
                slot = _slot_counter["n"] % _PDF_PARALLEL_PAGES
                _slot_counter["n"] += 1
                page_status[idx]["current"] = True
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq_box["n"], 0), reply_markup=_cancel_kb(chat_id))

            mcqs = []
            try:
                mcqs = await generate_mcq_from_image(img, topic, page_num, mcq_count, key_offset=slot)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                logger.error(f"[PDF Generate] Page {page_num} error: {e}; retrying once")

            # Strict no-page-miss guarantee: a page landing empty (crash or
            # every provider returned nothing) gets ONE retry before being
            # accepted as genuinely empty — protects against a single
            # transient failure silently dropping a whole page's MCQs.
            # Carries forward the Groq keys already tried in the first call
            # (via _LAST_TRIED_GROQ_KEYS) so this retry doesn't get a fresh
            # 5-key budget — without this, one fully-empty page could touch
            # up to 6 generation cycles (inner 3-attempt loop x this outer
            # retry), re-trying already-cooling keys each time.
            if not mcqs and not is_cancelled(chat_id):
                first_call_tried = set(_LAST_TRIED_GROQ_KEYS.get("keys") or set())
                try:
                    await asyncio.sleep(1)
                    mcqs = await generate_mcq_from_image(img, topic, page_num, mcq_count, exclude_groq_keys=first_call_tried, key_offset=slot)
                except asyncio.CancelledError:
                    raise
                except Exception as e:
                    logger.error(f"[PDF Generate] Page {page_num} retry also failed: {e}")

            if is_cancelled(chat_id):
                return
            async with lock:
                results_by_idx[idx] = (page_num, img, mcqs)
                total_mcq_box["n"] += len(mcqs)
                page_status[idx]["current"] = False
                page_status[idx]["done"] = True
                page_status[idx]["mcq"] = len(mcqs)
                _model_counts = {}
                for _m in (mcqs or []):
                    _prov = _m.get("_provider", "Unknown")
                    _model_counts[_prov] = _model_counts.get(_prov, 0) + 1
                if _model_counts:
                    page_status[idx]["model"] = ", ".join(f"{k}:{v}" for k, v in _model_counts.items())
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq_box["n"], 0), reply_markup=_cancel_kb(chat_id))

    async def _watch_cancel(tasks):
        # Polls the cancel flag while pages are in flight; the moment /cancel
        # is issued, actively cancels every still-running page task instead
        # of letting gather() wait for all of them to finish naturally.
        while not all(t.done() for t in tasks):
            if is_cancelled(chat_id):
                for t in tasks:
                    if not t.done():
                        t.cancel()
                return
            await asyncio.sleep(0.3)

    try:
        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, 0, 0), reply_markup=_cancel_kb(chat_id))

        tasks = [
            _spawn_task(_run_one(idx, page_num, img))
            for idx, (page_num, img) in enumerate(pages)
        ]
        watcher = _spawn_task(_watch_cancel(tasks))
        await asyncio.gather(*tasks, return_exceptions=True)
        watcher.cancel()
        try:
            await watcher
        except asyncio.CancelledError:
            pass
    finally:
        _active_jobs["count"] = max(0, _active_jobs.get("count", 1) - 1)
        clear_active_job(chat_id)

    results = [r for r in results_by_idx if r is not None]
    return results


async def _pdf_relaxed_last_resort_extract(img, topic, page_num, mcq_count=None) -> list:
    """
    PERMANENT, ALWAYS-ACTIVE last-resort fallback — called ONLY after the
    normal full pipeline (4 attempts, racing/rotating every provider) still
    returned zero for a page. A strict/complex generation prompt can itself
    reject a page's content that a plain reader would still find MCQ-worthy
    material on. This pass uses a deliberately LOOSENED, code-level-triggered
    prompt (still going straight to the vision model, no extra outer retry
    layer needed) so a page is never conceded as empty on the very first
    genuine attempt at extraction leniency. NEVER raises; returns [] only if
    every key/provider is truly exhausted.
    """
    keys = groq_key_rotator.ordered_keys()
    if not keys:
        return []
    data_url = _img_to_data_url_groq(img)
    if not data_url:
        return []
    count_hint = ""
    if isinstance(mcq_count, (tuple, list)) and len(mcq_count) == 2:
        count_hint = f" Aim for roughly {mcq_count[0]}-{mcq_count[1]} MCQs if the page supports it."
    relaxed_prompt = f"""এই পেজে যেকোনো প্রশ্ন-উত্তর ভিত্তিক তথ্য (MCQ, প্রশ্নোত্তর, তথ্যভিত্তিক লাইন, সংজ্ঞা,
তালিকা, ঘটনা) থাকলে সেখান থেকে যতগুলো সম্ভব MCQ বানাও। এই পাস আগের কঠোর extraction থেকে একটু
শিথিল — পেজে সরাসরি MCQ ফরম্যাট না থাকলেও, যেকোনো fact/তথ্য/লাইন থেকে একটা প্রাসঙ্গিক MCQ
বানানো যায় কিনা চেষ্টা করো, বিষয়: {topic}.{count_hint}
পেজে সত্যিই কোনো ব্যবহারযোগ্য তথ্য/টেক্সট না থাকলে (সম্পূর্ণ ফাঁকা/অপ্রাসঙ্গিক ছবি) তখনই শুধু [] দাও।
Output ONLY a valid JSON array, no extra text:
[{{"question":"...","options":["...","...","...","..."],"answer":"A/B/C/D","explanation":"... (Bengali, max 165 chars, covers all 4 options)"}}]"""
    for i, key in enumerate(keys):
        txt, status = await _post_openai_compat(
            "https://api.groq.com/openai/v1/chat/completions",
            key, "qwen/qwen3.6-27b",
            data_url, relaxed_prompt
        )
        if txt:
            groq_key_rotator.mark_healthy(key)
            parsed = _parse_mcq_json(txt)
            if parsed:
                return _cap_mcq_options(_validate_mcq_structure(parsed), 4)
        if status == 429:
            groq_key_rotator.mark_rate_limited(key, daily_exhausted=(_key_429_is_tpm.get(key) is not True))
            continue
    # Groq exhausted -> try Gemini once with the same relaxed prompt as a
    # final code-level fallback before truly conceding zero.
    try:
        gem_txt = await _qbm_gemini_raw(img, relaxed_prompt)
        if gem_txt:
            gem_out = _parse_mcq_json(gem_txt)
            if gem_out:
                return _cap_mcq_options(_validate_mcq_structure(gem_out), 4)
    except Exception as e:
        logger.warning(f"[PDF] relaxed Gemini pass failed: {e}")
    return []


async def process_pdf_pages(
    chat_id: int, uid: int, uname: str,
    pages: list, topic: str, mcq_count: int,
    channel_id: str, csv_only: bool,
    file_name: str = "document.pdf",
    status_msg_id: int = None,
    thread_id: int = None,
    with_image: bool = True,
    skip_generate: bool = False
):
    _active_jobs["count"] = _active_jobs.get("count", 0) + 1
    try:
        return await _process_pdf_pages_inner(
            chat_id, uid, uname, pages, topic, mcq_count,
            channel_id, csv_only, file_name, status_msg_id,
            thread_id, with_image, skip_generate
        )
    finally:
        _active_jobs["count"] = max(0, _active_jobs.get("count", 1) - 1)

async def _process_pdf_pages_inner(
    chat_id: int, uid: int, uname: str,
    pages: list, topic: str, mcq_count: int,
    channel_id: str, csv_only: bool,
    file_name: str = "document.pdf",
    status_msg_id: int = None,
    thread_id: int = None,
    with_image: bool = True,
    skip_generate: bool = False
):
    settings = await db_get_settings()
    tag = settings.get("tag", "")
    exp_footer = settings.get("exp_footer", "")
    session_id = gen_session_id()
    await db_save_session(session_id, {
        "user_id": uid, "user_name": uname, "topic": topic,
        "channel_id": channel_id or "", "total_pages": len(pages),
        "processed_pages": 0, "status": "processing"
    })

    page_status = [{"page": p[0], "done": False, "current": False, "mcq": (len(p[2]) if skip_generate else 0)} for p in pages]
    start_time = time.time()
    total_mcq = sum(len(p[2]) for p in pages) if skip_generate else 0
    total_polls = 0

    if not status_msg_id:
        r = await send_msg(chat_id, "⏳ Processing শুরু হচ্ছে...")
        status_msg_id = r.get("result", {}).get("message_id")

    await edit_msg(chat_id, status_msg_id,
        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

    # PERMANENT FIX: dashboard previously only updated on page start/finish —
    # if one page's generation takes 30-90s, "Elapsed" looked frozen the
    # whole time, making the bot look stuck. A lightweight background ticker
    # refreshes the same message every few seconds purely for the live clock/
    # progress bar, independent of page completion events.
    _dash_stop = asyncio.Event()
    async def _dashboard_ticker():
        # Safety cap: even if the explicit stop call is missed due to an
        # unexpected exception path, this ticker auto-terminates after 30
        # minutes so it can never leak/run forever editing a dead job's message.
        _ticker_deadline = time.time() + 1800
        while not _dash_stop.is_set() and time.time() < _ticker_deadline:
            try:
                await asyncio.wait_for(_dash_stop.wait(), timeout=4)
            except asyncio.TimeoutError:
                pass
            if _dash_stop.is_set():
                break
            try:
                await edit_msg(chat_id, status_msg_id,
                    _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))
            except Exception:
                pass
    _dash_ticker_task = _spawn_task(_dashboard_ticker())

    summary_pages = []
    all_mcqs_csv = []
    all_mcqs_raw = []
    first_image_msg_id = None

    async def _gen_with_retry(img_, page_num_):
        """
        PERMANENT FIX — a page must NEVER be silently skipped/dropped just
        because generation returned empty on the first couple of tries.
        Multi-stage, always-active retry ladder before we ever accept zero:
          Stage 1: up to 4 full-pipeline attempts (was 2), with backoff,
                    each attempt independently races/rotates ALL providers
                    (Groq, Gemini, NVIDIA, OpenRouter, etc. via
                    generate_mcq_from_image -> _generate_mcq_from_image_raw).
          Stage 2: if ALL 4 attempts still return empty, run one final
                    RELAXED extraction pass with a loosened prompt (in case
                    the strict generation prompt itself rejected valid page
                    content) before conceding the page has nothing.
        Only after both stages fail does the page get marked 0 MCQ — and
        even then it's clearly flagged (⚠️) and the owner is alerted with
        the EXACT reason (last exception / "all providers returned empty"),
        never a vague "failed" with no cause.

        Groq-key economy: accumulated_tried_keys carries forward across all
        4 Stage-1 attempts (via _LAST_TRIED_GROQ_KEYS side-channel) so a
        thin/empty page doesn't get a fresh 5-key Groq budget on every
        attempt — without this, one stubborn empty page could touch the
        same handful of already-cooling keys up to ~60 times (4 outer
        attempts x up to 3 inner retries x 5-key cap each) before falling
        through to the relaxed pass, needlessly starving other pages/users
        of those keys in the meantime.
        """
        last_mcqs = []
        last_error = ""
        # Now safe to accumulate: prefetch/overlap was removed (pages are
        # strictly serial in this function now), so this is never called
        # concurrently with another _gen_with_retry — no race on the
        # _LAST_TRIED_GROQ_KEYS side-channel. Carrying tried keys forward
        # across all 4 Stage-1 attempts means a stubborn empty page doesn't
        # get a fresh 5-key Groq budget every attempt.
        accumulated_tried_keys = set()
        for _pg_attempt in range(4):
            try:
                _mcqs = await generate_mcq_from_image(img_, topic, page_num_, mcq_count, exclude_groq_keys=accumulated_tried_keys)
                accumulated_tried_keys = accumulated_tried_keys | set(_LAST_TRIED_GROQ_KEYS.get("keys") or set())
                if _mcqs:
                    return _mcqs, None
                last_mcqs = _mcqs
                last_error = _get_last_generation_error()
            except Exception as _pg_e:
                last_error = f"{type(_pg_e).__name__}: {_pg_e}"
                logger.warning(f"[PDF] Page {page_num_} gen attempt {_pg_attempt+1} failed: {_pg_e}")
            await asyncio.sleep(1.5 * (_pg_attempt + 1))  # backoff: 1.5s, 3s, 4.5s, 6s

        logger.warning(f"[PDF] Page {page_num_} empty after 4 full attempts ({last_error}) — running relaxed last-resort pass.")
        try:
            relaxed = await _pdf_relaxed_last_resort_extract(img_, topic, page_num_, mcq_count)
            if relaxed:
                logger.info(f"[PDF] Page {page_num_} recovered via relaxed last-resort pass ({len(relaxed)} MCQ).")
                return relaxed, None
        except Exception as _relaxed_e:
            last_error = f"{last_error} | Relaxed-pass {type(_relaxed_e).__name__}: {_relaxed_e}"
            logger.warning(f"[PDF] Page {page_num_} relaxed pass crashed: {_relaxed_e}")

        return last_mcqs, last_error

    for idx, page_tuple in enumerate(pages):
        if skip_generate:
            page_num, img, mcqs = page_tuple
        else:
            page_num, img = page_tuple
        page_status[idx]["current"] = True
        await edit_msg(chat_id, status_msg_id,
            _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

        try:
            if not skip_generate:
                # Strictly serial by user request: each page's generation
                # AND sending (polls or image+caption) must fully finish
                # before the next page's generation even starts — no
                # prefetch/overlap across pages, in ANY mode (/pdf, /qbm,
                # /onu, /tf all funnel through this same function).
                mcqs, gen_error = await _gen_with_retry(img, page_num)
            if not mcqs:
                page_status[idx]["current"] = False
                page_status[idx]["done"] = True
                page_status[idx]["mcq"] = 0
                page_status[idx]["failed"] = True
                page_status[idx]["error"] = gen_error or "Unknown"
                logger.warning(f"[PDF] Page {page_num} produced 0 MCQ after retries — reason: {gen_error}")
                await notify_owner(
                    f"⚠️ [PDF] Page {fmt_page(page_num)} ({file_name}) থেকে 0 MCQ।\n"
                    f"কারণ: {gen_error or 'অজানা — সব provider খালি ফলাফল দিয়েছে'}"
                )
                continue

            cache_id = gen_session_id()
            img_bytes = image_to_bytes(img)

            if csv_only:
                for m in mcqs:
                    opts = m.get("options", ["", "", "", ""])
                    opts = [re.sub(r'^[A-Da-dক-ঘ][)\.।]\s*', '', str(o)) for o in opts]
                    ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
                    ans_num = ans_map.get(m.get("answer", "A"), "1")
                    exp = m.get("explanation", "")
                    all_mcqs_csv.append([m["question"], opts[0], opts[1], opts[2], opts[3], ans_num, _strip_img_tag(exp), "1", "1"])
                await db_save_mcq_cache(cache_id, session_id, page_num, topic, mcqs)
            else:
                image_msg_id = None
                image_file_id = None
                if with_image:
                    caption = ""
                    if tag:
                        caption = f"{tag}\n\n"
                    caption += f"🟥ATLAS Special MCQ System\n🎯Topic: {topic}\n🌟Page No: {fmt_page(page_num)}"

                    photo_r = await send_photo(channel_id, img_bytes, caption, message_thread_id=thread_id)
                    if photo_r.get("ok"):
                        image_msg_id = photo_r["result"]["message_id"]
                        image_file_id = photo_r["result"]["photo"][-1]["file_id"]
                        if first_image_msg_id is None:
                            first_image_msg_id = image_msg_id
                            # Item 3: auto-pin the very first image of the job
                            await try_pin_message(channel_id, image_msg_id)

                # repair already ran inside generate_mcq_from_image() — a
                # second call here was pure redundant duplicate work on every page

                poll_links = []
                first_poll_link = ""
                for i, mcq in enumerate(mcqs):
                  try:
                    opts = mcq.get("options", [])[:4]
                    ans_idx = {"A": 0, "B": 1, "C": 2, "D": 3}.get(mcq.get("answer", "A"), 0)
                    q_text = mcq["question"]
                    if tag:
                        q_text = f"{tag}\n\n{q_text}"
                    exp = mcq.get("explanation", "")
                    if exp_footer:
                        exp = f"{exp}\n{exp_footer}"
                    # Retry logic — poll অবশ্যই যেতে হবে
                    poll_r = {"ok": False}
                    for _attempt in range(3):
                        poll_r = await send_poll(
                            channel_id, q_text, opts, ans_idx,
                            explanation=exp,
                            reply_to_message_id=image_msg_id,
                            message_thread_id=thread_id
                        )
                        if poll_r.get("ok"):
                            break
                        logger.warning(f"[Poll] MCQ {i+1} attempt {_attempt+1} failed, retrying...")
                        await asyncio.sleep(2)
                    if poll_r.get("ok") and i == 0:
                        msg_id = poll_r["result"]["message_id"]
                        if str(channel_id).startswith("-100"):
                            first_poll_link = f"https://t.me/c/{str(channel_id)[4:]}/{msg_id}"
                        else:
                            first_poll_link = f"https://t.me/{str(channel_id).lstrip('@')}/{msg_id}"
                        poll_links.append(first_poll_link)
                    total_polls += 1
                    # Telegram allows ~1 message/sec to the same chat —
                    # 0.25s was too fast, causing real 429s.
                    await asyncio.sleep(1.1)
                  except Exception as _mcq_e:
                    logger.error(f"[Poll] MCQ {i+1} unexpected error, skipping: {_mcq_e}")
                    continue

                await db_save_mcq_cache(cache_id, session_id, page_num, topic, mcqs, poll_links, image_file_id, image_msg_id, channel_id)
                all_mcqs_raw.extend(mcqs)

                # FIX: summary_pages was declared but never populated — this is
                # what feeds the end-of-job summary message + its auto-pin
                # further down. Without this, the summary never sent.
                summary_pages.append({
                    "page": page_num,
                    "mcq_count": len(mcqs),
                    "first_poll": first_poll_link or "(লিংক পাওয়া যায়নি)"
                })

                exam_url = f"{GH_PAGES_EXAM_URL}?id={cache_id}"
                solve_pdf_url = f"{CF_WORKER_URL}/api/solve-pdf-view/{cache_id}"
                bot_un = await get_bot_username()
                quiz_url = f"https://t.me/{bot_un}?start=pdf_{cache_id}"
                poll_url = f"https://t.me/{bot_un}?start=poll_{cache_id}"
                new_quiz_url = f"https://t.me/{bot_un}?start=pdfnew_{cache_id}"
                new_poll_url = f"https://t.me/{bot_un}?start=pollnew_{cache_id}"

                end_data = {
                    "chat_id": channel_id,
                    "text": f"🚀Topic: {topic}\n🌟Page No: {fmt_page(page_num)}\n✅MCQ: {len(mcqs)}\n🔗First Poll Link:\n{first_poll_link}",
                    "reply_markup": {"inline_keyboard": [
                        [{"text": "📝 Quiz Solve", "url": quiz_url},
                         {"text": "🆕 New Quiz", "url": new_quiz_url}],
                        [{"text": "🔄 Poll Again", "url": poll_url},
                         {"text": "🆕 New Poll", "url": new_poll_url}],
                        [{"text": "🌐 Website Exam", "url": exam_url},
                         {"text": "📄 Solve PDF", "url": solve_pdf_url}]
                    ]},
                    "reply_to_message_id": image_msg_id
                }
                if thread_id:
                    end_data["message_thread_id"] = thread_id
                end_r = {"ok": False}
                for _end_attempt in range(3):
                    end_r = await tg_post("sendMessage", end_data)
                    if end_r.get("ok"):
                        break
                    logger.warning(f"[EndMsg] Page {page_num} attempt {_end_attempt+1} failed, retrying...")
                    await asyncio.sleep(2)
                if end_r.get("ok"):
                    await db_update_cache(cache_id, {"end_msg_id": end_r["result"]["message_id"]})
                else:
                    err_desc = end_r.get("description") or end_r.get("error") or "unknown"
                    logger.error(f"[EndMsg] Page {page_num} FINAL FAIL: {err_desc}")
                    if "reply" in str(err_desc).lower() or "not found" in str(err_desc).lower():
                        # Reply target message missing/deleted -> retry once without reply_to_message_id
                        end_data.pop("reply_to_message_id", None)
                        retry_r = await tg_post("sendMessage", end_data)
                        if retry_r.get("ok"):
                            await db_update_cache(cache_id, {"end_msg_id": retry_r["result"]["message_id"]})
                        else:
                            await notify_owner(f"⚠️ End message failed for page {fmt_page(page_num)}, topic: {topic}\nReason: {err_desc}")
                    else:
                        await notify_owner(f"⚠️ End message failed for page {fmt_page(page_num)}, topic: {topic}\nReason: {err_desc}")

                # Auto Style1+Style3 PDF এখন সব page শেষে একবারই পাঠানো হবে (নিচে)
                all_mcqs_raw.extend(mcqs)

                for m in mcqs:
                    opts = m.get("options", ["", "", "", ""])
                    opts = [re.sub(r'^[A-Da-dক-ঘ][)\.।]\s*', '', str(o)) for o in opts]
                    ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
                    ans_num = ans_map.get(m.get("answer", "A"), "1")
                    all_mcqs_csv.append([m["question"], opts[0], opts[1], opts[2], opts[3], ans_num, _strip_img_tag(m.get("explanation", "")), "1", "1"])

            total_mcq += len(mcqs)
            page_status[idx]["done"] = True
            page_status[idx]["current"] = False
            page_status[idx]["mcq"] = len(mcqs)
            _model_counts = {}
            for _m in (mcqs or []):
                _prov = _m.get("_provider", "Unknown")
                _model_counts[_prov] = _model_counts.get(_prov, 0) + 1
            if _model_counts:
                page_status[idx]["model"] = ", ".join(f"{k}:{v}" for k, v in _model_counts.items())
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))
            await sb_exec(lambda: sb.table("pdf_sessions").update({"processed_pages": page_num}).eq("id", session_id).execute())

        except Exception as e:
            logger.error(f"[PDF] Page {page_num} error: {e}", exc_info=True)
            page_status[idx]["current"] = False
            page_status[idx]["done"] = True
            await notify_owner(f"[PDF] Page {page_num} error:\n{e}")
        finally:
            # RAM fix: each page's decoded PIL image (dpi=150) can be several MB.
            # Holding all pages of a batch in memory for the whole poll-sending
            # duration was causing OOM kills mid-send on low-RAM instances
            # (looked like the bot dying / auto-restarting mid-channel-post).
            # Drop this page's image the moment we're done with it.
            try:
                pages[idx] = (page_num, None, None) if skip_generate else (page_num, None)
            except Exception:
                pass
            img = None

    _dash_stop.set()
    try:
        await asyncio.wait_for(_dash_ticker_task, timeout=2)
    except Exception:
        pass

    if all_mcqs_csv:
        import io, csv as csv_mod
        buf = io.StringIO()
        writer = csv_mod.writer(buf)
        writer.writerow(["questions","option1","option2","option3","option4","answer","explanation","type","section"])
        for row in all_mcqs_csv:
            writer.writerow(row)
        await send_document(chat_id, buf.getvalue().encode("utf-8"), f"{topic}_mcq.csv",
            caption=f"📄 {topic} — {len(all_mcqs_csv)} MCQ", mime_type="text/csv")

    if not csv_only and summary_pages:
        total_mcq_sum = sum(p["mcq_count"] for p in summary_pages)
        summary = f"🟥ATLAS Special Practice System\n🎯Topic: {topic}\n🚀Total MCQ: {total_mcq_sum}\n\n"
        for p in summary_pages:
            summary += f"🌟Page-{fmt_page(p['page'])} ({p['mcq_count']} MCQ):\n{p['first_poll']}\n"
        summary += (
            f"\n💥শুভকামনা প্রিয় শিক্ষার্থী {uname}...\n"
            '"যেকোনো প্রশ্ন থাকলে মেসেজ দাও "Ask Your Mentor" গ্রুপে।\n'
            "🚀Whatsapp Helpline: wa.me/8801999681290\n🔗Website: Atlascourses.com"
        )
        summary_data = {"chat_id": channel_id, "text": summary, "disable_web_page_preview": True}
        if first_image_msg_id:
            summary_data["reply_to_message_id"] = first_image_msg_id
        sum_r = await tg_post("sendMessage", summary_data)
        if sum_r.get("ok"):
            await try_pin_message(channel_id, sum_r["result"]["message_id"])
        else:
            logger.warning(f"[Summary] send failed: {sum_r.get('description')}")

    # সব poll শেষে combined Style1+Style3 PDF (সব page/poll মিলিয়ে) —
    # first pre-msg (first_image_msg_id) কে reply করে, auto-pin
    if not csv_only and channel_id and all_mcqs_raw and await should_autosend_pdf(channel_id):
        try:
            data_adapted = _adapt_mcqs_for_print(all_mcqs_raw)
            safe_title = re.sub(r"[^\w\u0980-\u09FF\-]+", "_", topic)[:50] or "ATLAS_Sheet"
            _wm_saved = (await db_get_settings()).get("watermark", "")
            for style_key in ("style1", "style3"):
                html_s = PRINT_STYLE_BUILDERS[style_key](data_adapted, topic)
                pdf_bytes = await _html_to_pdf(html_s)
                if not pdf_bytes:
                    logger.error(f"[PDF-AUTOSEND] {style_key} generation returned empty, topic: {topic}")
                    await notify_owner(f"⚠️ Auto-PDF ({style_key}) generate হয়নি — topic: {topic}")
                    continue
                if _wm_saved:
                    try:
                        pdf_bytes = add_watermark_to_pdf(pdf_bytes, _wm_saved)
                    except Exception as _wm_e:
                        logger.warning(f"[PDF-AUTOSEND] watermark apply failed: {_wm_e}")
                style_name = PRINT_STYLE_NAMES[style_key]
                doc_r = await send_document(channel_id, pdf_bytes, f"{safe_title}_{style_key}.pdf",
                    caption=f"📖 Practice Sheet ({style_name})\n🎯 Topic: {topic}\n📝 মোট MCQ: {len(all_mcqs_raw)}\n🚀 ATLAS APP",
                    message_thread_id=thread_id, reply_to_message_id=first_image_msg_id)
                if doc_r and doc_r.get("ok"):
                    doc_msg_id = doc_r.get("result", {}).get("message_id")
                    if doc_msg_id:
                        await try_pin_message(channel_id, doc_msg_id)
                else:
                    err_desc = (doc_r or {}).get("description", "no response")
                    logger.error(f"[PDF-AUTOSEND] send_document failed ({style_key}): {err_desc}")
                    await notify_owner(f"⚠️ Auto-PDF ({style_key}) পাঠাতে ব্যর্থ — topic: {topic}\nReason: {err_desc}")
        except Exception as e:
            logger.error(f"[PDF-AUTOSEND] Error: {e}")
            await notify_owner(f"⚠️ Auto-PDF সিস্টেমে error — topic: {topic}\nReason: {e}")

    await sb_exec(lambda: sb.table("pdf_sessions").update({"status": "done"}).eq("id", session_id).execute())
    elapsed = int(time.time() - start_time)
    mins, secs = divmod(elapsed, 60)
    await edit_msg(chat_id, status_msg_id,
        "✅ <b>Processing Complete!</b>\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📄 File: {file_name}\n🎯 Topic: {topic}\n"
        f"📝 Total MCQ: {total_mcq}\n📋 Pages: {len(pages)}\n⏱️ Time: {mins}:{secs:02d}\n"
        "━━━━━━━━━━━━━━━━━━━━━━")

# ============================================================
# FEATURE: /pdfm — PDF pagewise MCQ to channel
# Usage: /pdfm -p 1-5 -c @channel -m "Topic" -t topicId 10
# ============================================================
async def handle_pdfm(msg: dict):
    """
    /pdfm -p (pages) -c (channel) -m (topic) -t (thread_id) [mcq_count]

    -p না থাকলে: all pages
    -c না থাকলে: channel list → select → poll
    -m না থাকলে: "ATLAS MCQ"
    """
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    uname = msg["from"].get("first_name","User")
    text = msg.get("text","")
    reply = msg.get("reply_to_message")

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ PDF ফাইলে reply করে /pdfm দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/pdfm -p 1-5 -c @channel -m \"Topic\" -t group_id [5]</code>\n\n"
            "📌 -p = page range (না দিলে সব page)\n"
            "📌 -c = channel id (না দিলে list দেখাবে)\n"
            "📌 -m = topic name\n"
            "📌 -t = topic/thread id (group হলে)\n"
            "📌 [N] = per page MCQ count (bracket সহ)"
        )
        return

    params = _parse_pdfm_params(text)
    topic = params["topic"] or "🌟ATLAS MCQ"
    page_range = params["page_range"]
    channel_id = params["channel_id"]
    mcq_count = params["mcq_count"]
    if params.get("mcq_count_min") and params.get("mcq_count_max"):
        mcq_count = (params["mcq_count_min"], params["mcq_count_max"])
    thread_id = params["thread_id"]

    file_id = reply["document"]["file_id"]
    file_unique_id = reply["document"].get("file_unique_id")
    file_name = reply["document"].get("file_name","document.pdf")
    file_size = reply["document"].get("file_size",0)

    status_r = await send_msg(chat_id, "⏳ PDF download হচ্ছে...\n[░░░░░░░░░░ 0%]")
    status_msg_id = status_r.get("result",{}).get("message_id")

    _last_pct6471 = {"v": -1}
    def _dl_progress6471(done, total):
        if not status_msg_id or not total:
            return
        pct = int(done * 100 / total)
        if pct - _last_pct6471["v"] < 10 and pct != 100:
            return
        _last_pct6471["v"] = pct
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        _spawn_task(edit_msg(chat_id, status_msg_id, f"⏳ PDF download হচ্ছে...\n[{bar} {pct}%]"))

    try:
        pdf_bytes = await _download_pdf_cached(file_id, progress_cb=_dl_progress6471, chat_id=chat_id, message_id=reply["message_id"], file_unique_id=file_unique_id)
        ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
        if not ok:
            await send_msg(chat_id, pages)
            return

        if not pages:
            await send_msg(chat_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ Processing...")

        if not channel_id:
            channels = await db_get_channels()
            if not channels:
                await process_pdfm_pages(chat_id, uid, uname, pages, topic,
                    mcq_count, None, True, file_name, status_msg_id, thread_id)
                return

            app.state.pdf_cache = getattr(app.state, "pdf_cache", {})
            app.state.pdf_cache[f"pdfm_img_{uid}"] = pages
            _cap_page_cache(app.state.pdf_cache)
            await sb_exec(lambda: sb.table("quiz_sessions").upsert({
                "key": f"pdfm_pending_{uid}",
                "data": json.dumps({
                    "topic": topic, "mcq_count": mcq_count,
                    "file_name": file_name, "status_msg_id": status_msg_id,
                    "thread_id": thread_id,
                    "file_id": file_id,
                    "page_range": page_range
                }),
                "updated_at": int(time.time())
            }).execute())

            kb = {"inline_keyboard": []}
            for ch in channels:
                ch_id = ch.get("channel_id","")
                ch_name = ch.get("channel_name", ch_id)
                kb["inline_keyboard"].append([{
                    "text": f"📢 {ch_name}",
                    "callback_data": f"pdfmch_{ch_id}_{uid}"
                }])
            kb["inline_keyboard"].append([{
                "text": "📄 CSV Only",
                "callback_data": f"pdfmch_csv_{uid}"
            }])
            await send_msg(chat_id,
                f"📋 <b>{len(pages)} page</b>\n🎯 Topic: {topic}\n\nChannel select করো:",
                reply_markup=kb
            )
            return

        await process_pdfm_pages(chat_id, uid, uname, pages, topic,
            mcq_count, channel_id, False, file_name, status_msg_id, thread_id,
            file_id=file_id, page_range_str=page_range)

    except Exception as e:
        logger.error(f"[PDFM] Error: {e}")
        await _safe_error_reply(chat_id, e)

def _parse_pdfm_params(text: str) -> dict:
    """
    /pdfm -p 1-5 -c @channel -m "Topic" -t 123 10
    সব parameter parse করো
    """
    result = {
        "page_range": None,
        "channel_id": None,
        "topic": None,
        "thread_id": None,
        "mcq_count": None,
        "mcq_count_min": None,
        "mcq_count_max": None
    }

    m = re.search(r'-p\s+([\d,\-]+)', text)
    if m:
        result["page_range"] = m.group(1)

    m = re.search(r'-c\s+(@\S+|-100\d+)', text)
    if m:
        result["channel_id"] = m.group(1)

    m = re.search(r'-m\s+"([^"]+)"', text) or re.search(r"-m\s+'([^']+)'", text) or re.search(r'-m\s+(\S+)', text)
    if m:
        result["topic"] = m.group(1)

    m = re.search(r'-t\s+(\d+)', text)
    if m:
        result["thread_id"] = int(m.group(1))

    m_range = re.search(r'\[(\d+)\s*-\s*(\d+)\]', text)
    if m_range:
        lo, hi = int(m_range.group(1)), int(m_range.group(2))
        result["mcq_count_min"] = min(lo, hi)
        result["mcq_count_max"] = max(lo, hi)
    else:
        m_bracket = re.search(r'\[(\d+)\]', text)
        if m_bracket:
            result["mcq_count"] = int(m_bracket.group(1))
        else:
            cleaned = re.sub(r'-[pcmt]\s+\S+', '', text)
            m2 = re.search(r'(\d+)\s*$', cleaned)
            if m2:
                result["mcq_count"] = int(m2.group(1))

    return result

# Item 10: per-user serialization — if a user fires multiple /pdf, /qbm, /pdfm
# jobs at the same time, queue them so each finishes in order instead of racing
# (which caused RAM spikes / corrupted interleaved output).
_PDFM_USER_LOCKS: dict = {}
_PDFM_USER_QUEUE_LEN: dict = {}

def _get_pdfm_lock(uid: int) -> asyncio.Lock:
    lock = _PDFM_USER_LOCKS.get(uid)
    if lock is None:
        lock = asyncio.Lock()
        _PDFM_USER_LOCKS[uid] = lock
    return lock

async def process_pdfm_pages(
    chat_id: int, uid: int, uname: str,
    pages: list, topic: str, mcq_count,
    channel_id, csv_only: bool,
    file_name: str = "document.pdf",
    status_msg_id: int = None,
    thread_id: int = None,
    file_id: str = None,
    page_range_str: str = None
):
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _process_pdfm_pages_impl(
            chat_id, uid, uname, pages, topic, mcq_count,
            channel_id, csv_only, file_name, status_msg_id, thread_id,
            file_id=file_id, page_range_str=page_range_str
        )


async def _process_pdfm_pages_impl(
    chat_id: int, uid: int, uname: str,
    pages: list, topic: str, mcq_count,
    channel_id, csv_only: bool,
    file_name: str = "document.pdf",
    status_msg_id: int = None,
    thread_id: int = None,
    file_id: str = None,
    page_range_str: str = None
):
    """
    /pdfm এর main processing — /pdf এর মতো কিন্তু নতুন caption format সহ।
    Caption format:
      ⌛ATLAS Special MCQ System
      🌟Topic: (Topic Name)
      📌Page No: (count)
      💎MCQ: (count)

    End message format:
      🎯Topic: ...
      🌟Page No: ...
      🚀MCQ: (count)
      🔗First Poll Link: (link)

    Summary message format:
      ⚙️Summary সহ page count ও MCQ count
    """
    settings = await db_get_settings()
    tag = settings.get("tag","")
    exp_footer = settings.get("exp_footer","")
    session_id = gen_session_id()

    job_id = None
    if file_id and channel_id:  # শুধু actual posting job resumable — channel-select flow-এ না
        job_id = gen_session_id()
        await db_save_page_job(
            job_id, job_type="pdf", uid=uid, chat_id=chat_id, uname=uname,
            file_id=file_id, page_range=page_range_str or "", topic=topic,
            mcq_count=str(mcq_count or ""), channel_id=str(channel_id),
            csv_only=0, file_name=file_name, thread_id=thread_id or 0,
            status_msg_id=status_msg_id or 0, resume_page_num=(pages[0][0] if pages else 0),
            status="running"
        )

    page_status = [{"page":p,"done":False,"current":False,"mcq":0} for p,_ in pages]
    start_time = time.time()
    total_mcq = 0
    total_polls = 0

    if not status_msg_id:
        r = await send_msg(chat_id, "⏳ Processing শুরু হচ্ছে...")
        status_msg_id = r.get("result",{}).get("message_id")

    await edit_msg(chat_id, status_msg_id,
        _build_dashboard(file_name, topic, pages, page_status, start_time, 0, 0), reply_markup=_cancel_kb(chat_id))

    summary_pages = []
    all_mcqs_csv = []
    first_image_msg_id = None
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, f"PDFM MCQ generation + Poll posting ({file_name}, page-by-page)")

    for idx, (page_num, img) in enumerate(pages):
        if is_cancelled(chat_id):
            clear_active_job(chat_id)
            break
        page_status[idx]["current"] = True
        await edit_msg(chat_id, status_msg_id,
            _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

        try:
            mcqs = await generate_mcq_from_image(img, topic, page_num, mcq_count)
            if not mcqs:
                page_status[idx]["current"] = False
                page_status[idx]["done"] = True
                continue

            cache_id = gen_session_id()
            img_bytes = image_to_bytes(img)

            if csv_only:
                for m in mcqs:
                    opts = m.get("options",["","","",""])
                    ans_map = {"A":"1","B":"2","C":"3","D":"4"}
                    ans_num = ans_map.get(m.get("answer","A"),"1")
                    all_mcqs_csv.append([m["question"],opts[0],
                        opts[1] if len(opts)>1 else "",
                        opts[2] if len(opts)>2 else "",
                        opts[3] if len(opts)>3 else "",
                        ans_num, _strip_img_tag(m.get("explanation","")),"1","1"])
                await db_save_mcq_cache(cache_id, session_id, page_num, topic, mcqs)
            else:
                caption = ""
                if tag:
                    caption = f"{tag}\n\n"
                caption += (
                    f"⌛ATLAS Special MCQ System\n"
                    f"🌟Topic: {topic}\n"
                    f"📌Page No: {fmt_page(page_num)}\n"
                    f"💎MCQ: {len(mcqs)}"
                )

                photo_r = await send_photo(channel_id, img_bytes, caption,
                    message_thread_id=thread_id)
                image_msg_id = None
                image_file_id = None
                if photo_r.get("ok"):
                    image_msg_id = photo_r["result"]["message_id"]
                    image_file_id = photo_r["result"]["photo"][-1]["file_id"]
                    if first_image_msg_id is None:
                        first_image_msg_id = image_msg_id
                        # Item 3: auto-pin the very first image of the job
                        await try_pin_message(channel_id, image_msg_id)

                poll_links = []
                first_poll_link = ""
                for i, mcq in enumerate(mcqs):
                    opts = mcq.get("options",[])[:4]
                    ans_idx = {"A":0,"B":1,"C":2,"D":3}.get(mcq.get("answer","A"),0)
                    q_text = mcq["question"]
                    if tag:
                        q_text = f"{tag}\n\n{q_text}"
                    exp = mcq.get("explanation","")
                    if exp_footer:
                        exp = f"{exp}\n{exp_footer}"
                    # Retry logic — poll অবশ্যই যেতে হবে
                    poll_r = {"ok": False}
                    for _attempt in range(3):
                        poll_r = await send_poll(
                            channel_id, q_text, opts, ans_idx,
                            explanation=exp,
                            reply_to_message_id=image_msg_id,
                            message_thread_id=thread_id
                        )
                        if poll_r.get("ok"):
                            break
                        logger.warning(f"[Poll] MCQ {i+1} attempt {_attempt+1} failed, retrying...")
                        await asyncio.sleep(2)
                    if poll_r.get("ok") and i == 0:
                        pmid = poll_r["result"]["message_id"]
                        cid = str(channel_id)
                        first_poll_link = (
                            f"https://t.me/c/{cid[4:]}/{pmid}"
                            if cid.startswith("-100")
                            else f"https://t.me/{cid.lstrip('@')}/{pmid}"
                        )
                        poll_links.append(first_poll_link)
                    total_polls += 1
                    await asyncio.sleep(1.0)

                await db_save_mcq_cache(cache_id, session_id, page_num, topic, mcqs,
                    poll_links, image_file_id, image_msg_id, channel_id)

                end_text = (
                    f"🚀Topic: {topic}\n"
                    f"🌟Page No: {fmt_page(page_num)}\n"
                    f"✅MCQ: {len(mcqs)}\n"
                    f"🔗First Poll Link:\n{first_poll_link}"
                )
                end_data = {
                    "chat_id": channel_id,
                    "text": end_text,
                    "reply_to_message_id": image_msg_id,
                    "disable_web_page_preview": True
                }
                if thread_id:
                    end_data["message_thread_id"] = thread_id
                end_r = await tg_post("sendMessage", end_data)

                if end_r.get("ok"):
                    end_msg_id = end_r["result"]["message_id"]
                    await db_update_cache(cache_id, {"end_msg_id": end_msg_id})

                # /pdf on hole ending message er por auto Style1+Style3 Sheet PDF channel e jabe
                if await should_autosend_pdf(channel_id):
                    try:
                        data_adapted = _adapt_mcqs_for_print(mcqs)
                        reply_target = first_image_msg_id or image_msg_id
                        safe_title = re.sub(r"[^\w\u0980-\u09FF\-]+", "_", topic)[:50] or "ATLAS_Sheet"
                        _wm_saved = (await db_get_settings()).get("watermark", "")
                        for style_key in ("style1", "style3"):
                            html_s = PRINT_STYLE_BUILDERS[style_key](data_adapted, topic)
                            pdf_bytes = await _html_to_pdf(html_s)
                            if not pdf_bytes:
                                logger.error(f"[PDF-AUTOSEND] {style_key} generation returned empty for page {page_num}")
                                await notify_owner(f"⚠️ Auto-PDF ({style_key}) generate হয়নি — page {fmt_page(page_num)}, topic: {topic}")
                                continue
                            if _wm_saved:
                                try:
                                    pdf_bytes = add_watermark_to_pdf(pdf_bytes, _wm_saved)
                                except Exception as _wm_e:
                                    logger.warning(f"[PDF-AUTOSEND] watermark apply failed: {_wm_e}")
                            style_name = PRINT_STYLE_NAMES[style_key]
                            doc_r = await send_document(channel_id, pdf_bytes, f"{safe_title}_p{page_num}_{style_key}.pdf",
                                caption=f"📖 Practice Sheet ({style_name})\n🎯 Topic: {topic}\n🌟 Page: {fmt_page(page_num)}\n📝 মোট MCQ: {len(mcqs)}\n🚀 ATLAS APP",
                                message_thread_id=thread_id, reply_to_message_id=reply_target)
                            if doc_r and doc_r.get("ok"):
                                doc_msg_id = doc_r.get("result", {}).get("message_id")
                                if doc_msg_id:
                                    await try_pin_message(channel_id, doc_msg_id)
                            else:
                                err_desc = (doc_r or {}).get("description", "no response")
                                logger.error(f"[PDF-AUTOSEND] send_document failed ({style_key}): {err_desc}")
                                await notify_owner(f"⚠️ Auto-PDF ({style_key}) পাঠাতে ব্যর্থ — page {fmt_page(page_num)}\nReason: {err_desc}")
                    except Exception as e:
                        logger.error(f"[PDF-AUTOSEND] Error: {e}")
                        await notify_owner(f"⚠️ Auto-PDF সিস্টেমে error — page {fmt_page(page_num)}, topic: {topic}\nReason: {e}")

                summary_pages.append({
                    "page": page_num,
                    "first_poll": first_poll_link,
                    "mcq_count": len(mcqs)
                })

                for m in mcqs:
                    opts = m.get("options",["","","",""])
                    ans_map = {"A":"1","B":"2","C":"3","D":"4"}
                    ans_num = ans_map.get(m.get("answer","A"),"1")
                    all_mcqs_csv.append([m["question"],opts[0],
                        opts[1] if len(opts)>1 else "",
                        opts[2] if len(opts)>2 else "",
                        opts[3] if len(opts)>3 else "",
                        ans_num, _strip_img_tag(m.get("explanation","")),"1","1"])

            total_mcq += len(mcqs)
            page_status[idx]["done"] = True
            page_status[idx]["current"] = False
            page_status[idx]["mcq"] = len(mcqs)
            _model_counts = {}
            for _m in (mcqs or []):
                _prov = _m.get("_provider", "Unknown")
                _model_counts[_prov] = _model_counts.get(_prov, 0) + 1
            if _model_counts:
                page_status[idx]["model"] = ", ".join(f"{k}:{v}" for k, v in _model_counts.items())
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

            if job_id:
                next_page = pages[idx + 1][0] if idx + 1 < len(pages) else -1
                await db_update_page_job_progress(job_id, next_page)

        except Exception as e:
            logger.error(f"[PDFM] Page {page_num} error: {e}")
            page_status[idx]["current"] = False
            page_status[idx]["done"] = True

    clear_active_job(chat_id)
    if job_id:
        await db_finish_page_job(job_id)

    # CSV send
    if all_mcqs_csv:
        import io, csv as csv_mod
        buf = io.StringIO()
        writer = csv_mod.writer(buf)
        writer.writerow(["questions","option1","option2","option3","option4",
                          "answer","explanation","type","section"])
        for row in all_mcqs_csv:
            writer.writerow(row)
        await send_document(chat_id, buf.getvalue().encode("utf-8"),
            f"{topic}_mcq.csv",
            caption=f"📄 {topic} — {len(all_mcqs_csv)} MCQ",
            mime_type="text/csv")

    # Summary message
    if not csv_only and summary_pages:
        total_mcq_sum = sum(p["mcq_count"] for p in summary_pages)
        bd_time = _get_bd_time()
        summary = f"⚙️Summary\n🎯Topic: {topic}\n🚀Total MCQ: {total_mcq_sum}\n\n"
        for p in summary_pages:
            summary += f"🌟Page No: {fmt_page(p['page'])} ({p['mcq_count']} MCQ)\n{p['first_poll']}\n\n"
        summary += f"📅 {bd_time}"

        summary_data = {
            "chat_id": channel_id,
            "text": summary,
            "disable_web_page_preview": True
        }
        if first_image_msg_id:
            summary_data["reply_to_message_id"] = first_image_msg_id
        if thread_id:
            summary_data["message_thread_id"] = thread_id

        sum_r = await tg_post("sendMessage", summary_data)
        if sum_r.get("ok"):
            await try_pin_message(channel_id, sum_r["result"]["message_id"])

    elapsed = int(time.time() - start_time)
    mins, secs = divmod(elapsed, 60)
    await edit_msg(chat_id, status_msg_id,
        "✅ <b>PDFM Complete!</b>\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📄 {file_name}\n🎯 {topic}\n"
        f"📝 Total MCQ: {total_mcq}\n📋 Pages: {len(pages)}\n⏱️ {mins}:{secs:02d}\n"
        "━━━━━━━━━━━━━━━━━━━━━━")

def _get_bd_time() -> str:
    """Bangladesh current time"""
    try:
        bd_tz = pytz.timezone("Asia/Dhaka")
        now = datetime.now(bd_tz)
        return now.strftime("%d %B %Y, %I:%M %p")
    except:
        return ""

# ============================================================
# FEATURE: /qbm — Question Bank Maker (EXTRACT existing MCQ from PDF)
# Ported 100% from AtlasMasterBot's qbm_handler + process_pdf(is_qbm=True)
# Different from /pdfm: extracts MCQs that ALREADY EXIST in the PDF,
# never generates new ones. OCR fallback for scanned PDFs. 3x retry per page.
# ============================================================
# Bump this ANY time QBM_EXTRACT_PROMPT_DEFAULT's text changes -- lets
# qbm_get_active_prompt() auto-detect a stale DB-cached prompt from before
# the code update and self-heal to the new default, without needing a manual
# `DELETE FROM quiz_sessions WHERE key='qbm_active_prompt'` after every edit.
QBM_PROMPT_VERSION = 3

QBM_EXTRACT_PROMPT_DEFAULT = """STRICT MCQ EXTRACTOR — PERMANENT MODE. Extract ONLY MCQs already on this page. Never invent new ones. Follow every rule below, always.

FORBIDDEN (zero tolerance):
- Never create/add extra MCQs from page text/facts; never skip any — extract ALL, exact page order
- MULTI-COLUMN ORDER: 2+ columns → COLUMN-MAJOR — finish ENTIRE left column top-to-bottom first, then next column. Never zigzag (left-Q1,right-Q1,left-Q2... is WRONG). Verify: every left-column question number precedes every right-column number in output.
- Never guess an answer without source proof; never modify question/option wording (only strip numbering like ১./1./Q1./ক.)
- Never translate — keep source language exactly
- 0 MCQs → []. N MCQs → exactly N.

EXTRACTION & COMPLETENESS (zero-tolerance):
- Extract all: Bangla/English/mixed, any font/quality. 3+ internal read-throughs, cross-check before finalizing — don't miss the LAST MCQ on page/column; verify count matches visible MCQs.
- Strip only numbering; keep wording; fix obvious spelling errors without changing meaning. Verify spelling character-by-character throughout — question, all 4 options, explanation.
- VISUALLY-SIMILAR WORD CONFUSION (common OCR/vision misread — check every question word against this): বসতি≠বৃষ্টি, প্রাচীন≠প্রাচীর, দক্ষিণ≠রক্ষণ, রাজধানী≠রাজবাড়ী, সীমান্ত≠সিমেন্ট, অবস্থান≠অবস্থা, বিভাগ≠বিভাজন, জনসংখ্যা≠জনসংখ্যক, স্বাধীনতা≠সাধারণত, কর্তৃক≠কর্তব্য. If a word could plausibly be misread as a different real word, re-examine the actual glyphs/shape before committing — never let semantic plausibility override what is literally printed.
- Never output partial/truncated text — question ends only at proper punctuation (?।) or finished clause; compare word/segment count vs source (fewer = truncated, re-read); same for all 4 options + answer-key text.
- Hard-to-read word/name: never leave blank — use context/partial letters/general knowledge for the best complete word.
- Question unclear but options readable: infer question type from options (e.g. all country names → "কোন দেশের...?"; all dates → "কত সালে/কবে") + general knowledge.

ANSWER DETECTION (triple-check): trace to actual source, never guess. Priority:
A) Any visual mark on an option (circle/tick✓/cross✗/underline/bold/highlight/star) — overrides all, 100%
B) Answer right after the MCQ block  C) Answer table at page bottom (e.g. "1-A, 2-C...") — if no mark
D) Combined answer key on later pages (scan forward, often after 2-3 pages/doc end) — if no mark
E) Answer key on adjacent page(s) — if no mark
Absolute priority A>B>C>D>E, match by question number. None found → "A" + note "Answer not found in source". Convert source format to A/B/C/D. Re-verify twice.

OPTION ORDER (absolute, never reorder):
- Any source label system (A,B,C,D / a,b,c,d / ক,খ,গ,ঘ / ১,২,৩,৪ / bullets/none) → output uses SAME VISUAL POSITION: 1st→A, 2nd→B, 3rd→C, 4th→D. Position matching, not label matching — never sort/reorder text.
- Answer letter = position of correct text in OUTPUT. Example: source order গ,খ,ক,ঘ, correct is "ক" → output slot C (3rd) → answer="C", not "A"
- Verify: (1) 4 slots match source positions, (2) find correct text's slot, (3) confirm answer letter matches
- Numbers/years/dates stay exactly as source (never convert Bengali↔English numerals); verify digit-by-digit (৯↔9, ৬↔6 forbidden).

উদ্দীপক (PASSAGE/STIMULUS) HANDLING:
- Passage/scenario before question(s) → prepend full text to each linked MCQ (self-contained). Multiple MCQs sharing one উদ্দীপক → copy into each individually. Only real passage/scenario content counts.
- Strictly remove ONLY the navigation sentence telling reader which question numbers to answer via the passage — e.g. "উদ্দীপকের আলোকে ২১ ও ২২ নং প্রশ্নের উত্তর দাও", "নিচের উদ্দীপকের ভিত্তিতে ২৩-২৫ নং প্রশ্নের উত্তর দাও", or English "Answer questions 21 and 22 based on the stimulus above" — this pattern (question-number(s) + "প্রশ্নের উত্তর দাও"/"answer question(s)") is page-navigation, never the actual question.
  Do NOT strip any other sentence just for containing "উদ্দীপক" — e.g. "উদ্দীপকে প্রদর্শিত প্রক্রিয়াটি কোন উপদশায় ঘটে?" IS the real question, keep in full.

EXPLANATION RULES (strict priority, max 165 chars Bengali unless case 1):
1) TOP PRIORITY: page has explanation/reasoning text for this MCQ → copy 100% VERBATIM, byte-for-byte, no summarizing/paraphrasing/translating/"improving" (overrides 165-char limit; never edited even if it doesn't cover all 4 options). Skip to case 2 only if truly none exists.
2) No direct explanation but other relevant info exists (paragraph/note/box/table/fact) → build from it as direct fact (see forbidden phrases below), covering all 4 options: why correct is right + why each of the 3 wrong ones is incorrect.
3) Nothing relevant exists → generate best accurate explanation from own knowledge, same all-4-options coverage.
Case 1 always checked first; never mix (verbatim text never edited, self-written always covers all 4).

MATH/CHEMISTRY FORMATTING (always, in question/options/explanation): NEVER output raw LaTeX commands (no \vec, \hat, \frac, \sqrt, \sum, \int, ^, _, {, } used as LaTeX syntax) — always convert to proper Unicode instead:
- Vectors: \vec{A} → A⃗ (or bold+arrow style like **A**⃗), \hat{i} → î, \hat{j} → ĵ, \hat{k} → k̂
- Fractions: \frac{a}{b} → a/b (simple inline) or a⁄b (Unicode fraction slash) — never leave \frac{}{} literally
- Roots: \sqrt{x} → √x, \sqrt[3]{x} → ∛x
- Subscript/superscript: H₂O, CO₂, NaHCO₃, H₂SO₄, Ca(OH)₂, Fe₂O₃, C₆H₁₂O₆ (never H2O style). Ionic: Na⁺, Ca²⁺, Fe³⁺, Cl⁻, SO₄²⁻, O²⁻. Exponents: x², 10³, a⁻¹, E=mc², 6.02×10²³, v₀, xₙ (never x^2, x_0, x{2}).
- Units: °C, °F, m/s², cm³, kg·m/s², × not x, · for dot product/multiplication, ∑ ∫ ∞ ∂ √ ± ≤ ≥ ≠ ≈ ∝ ∆ π θ α β γ λ μ Ω directly as Unicode symbols.
Apply consistently, never mix LaTeX and Unicode within one MCQ. RARE EXCEPTION: only if a specific expression is genuinely impossible to represent in Unicode/plain text with reasonable clarity (e.g. a complex multi-line matrix or nested integral), keep that ONE expression in minimal LaTeX — everything else in the same MCQ still uses Unicode.

FORBIDDEN SOURCE-REFERENCE PHRASES (question and explanation, always): never reference the source itself instead of stating facts directly.
❌ "উল্লেখিত চিত্রে"/"চিত্রে দেখা যাচ্ছে"/"বক্সে"/"ছকে"/"উদ্দীপকে"/"সারণিতে"/"টপিকে"/"পৃষ্ঠায়"/"প্যাসেজে"/"অনুচ্ছেদে"/"গ্রাফে"/"দেখা যাচ্ছে"/"বলা আছে"/"উল্লেখ করা আছে"/"লক্ষ করা যায়"/"দেখানো হয়েছে"/"দেওয়া আছে"/"প্রদত্ত"
❌ English: "as shown in the figure/box/table/diagram/passage", "mentioned in the text/page", "as given"
Always state facts directly and plainly, as general knowledge.

QUESTION has a diagram/figure/chart needed to understand/answer it → add "qsn_bbox":[x1,y1,x2,y2] (0-1000 scale) fully containing the ENTIRE diagram + labels/arrows/text, edge to edge with small margin, never cut off. Omit if no diagram. Options never get bbox.
MANDATORY TRIGGER: figure caption/label near question (e.g. "চিত্র: G", "চিত্র-১", "Figure 1") = PROOF a diagram exists there — MUST add qsn_bbox covering the actual diagram (not the caption text).

OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown. No MCQ → exactly [].
[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"... (max 165 chars Bengali)","qsn_bbox":[100,200,400,450]}]"""


TOPIC_EXTRACT_PROMPT = QBM_EXTRACT_PROMPT_DEFAULT.replace(
    'OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown. No MCQ → exactly [].\n'
    '[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"... (max 165 chars Bengali)","qsn_bbox":[100,200,400,450]}]',
    'ADDITIONALLY (for topic-grouping) extract for EACH MCQ:\n'
    '- "qsn_no": the question\'s own printed serial number on the page, as an integer (e.g. প্রশ্ন-১ → 1, ২১. → 21, Q5 → 5). This is CRITICAL and used to detect topic boundaries — read it carefully and precisely for every single MCQ, never skip it if a number is printed. Use null ONLY if truly zero visible numbering exists for that MCQ.\n'
    '- "topic_hint": the text inside the widest, full-page-width BLACK/DARK BACKGROUND banner bar that this MCQ falls under (e.g. "বাংলাদেশ পরিচিতি", "বর্তমান ও পুরাতন নাম, ভৌগোলিক উপনাম", "বাংলাদেশের অবস্থান, আয়তন ও সীমানা") — this is the actual topic name and is CRITICAL, used to detect topic boundaries. Rules:\n'
    '  a) Do NOT use smaller sub-headers like university/organization names (জাহাঙ্গীরনগর বিশ্ববিদ্যালয়, রাজশাহী বিশ্ববিদ্যালয়, জগন্নাথ বিশ্ববিদ্যালয়, চাকুরি, BUP) or unit labels (বি ইউনিট, এ ইউনিট, এফ ইউনিট, FASS, FSSS) — those are subsections INSIDE one topic, never the topic itself.\n'
    '  b) If a new black-bg banner appears anywhere on THIS page (even partway down, even if a different banner was active at the top of the page), every MCQ from that point onward gets the NEW banner text; MCQs above it on the same page keep the banner that was already active for them.\n'
    '  b2) TWO-COLUMN pages specifically: the left and right columns can each have their OWN active banner, independent of each other — e.g. left column may still be finishing an earlier topic (no new banner in the left column at all) while the right column already starts a completely new banner from its very first MCQ. Determine each MCQ\'s topic_hint by which banner is ACTUALLY above it in ITS OWN column, never by copying the other column\'s current banner. Do not assume a banner that appears in one column also applies to the other column\'s MCQs above the same vertical height.\n'
    '  b3) STRICT RULE — within a single page, a topic must be treated as fully finished in BOTH columns before any MCQ can belong to the next topic. Concretely: if the left column still has MCQs of an OLD topic that haven\'t been read yet (because you are still scanning the right column, or the right column\'s items appear higher up visually), those left-column OLD-topic MCQs do NOT get replaced by a new banner just because the new banner happens to appear next to or between them and the right column. Read each column fully top-to-bottom on its own; a column keeps its topic exactly until ITS OWN text hits a new banner — never inherit a topic change from the other column\'s position on the page.\n'
    '  c) If this specific page has genuinely no black-bg banner visible anywhere on it (pure continuation page, no new banner printed), use "" (empty string) for every MCQ on this page — do not guess or invent one.\n'
    '  d) Every MCQ under the same visible banner on this page must get the EXACT SAME topic_hint string, character-for-character.\n\n'
    'OUTPUT ORDER (CRITICAL — this is a SEGMENT-major order, not a plain column-major order):\n'
    '  A "segment" = the vertical span of the page still under ONE topic banner, before the next banner starts (in either column). A single page can contain multiple segments stacked vertically (e.g. banner1 spans the top ~60% of the page, banner2 starts partway down and spans the rest).\n'
    '  For EACH segment, in top-to-bottom page order:\n'
    '    - output every MCQ from THAT segment\'s left column (top to bottom),\n'
    '    - THEN every MCQ from THAT segment\'s right column (top to bottom, same segment only),\n'
    '    - THEN move to the next segment down the page and repeat (its left column, then its right column).\n'
    '  Do NOT do a single whole-page "entire left column, then entire right column" pass — that WRONGLY pulls a later segment\'s left-column MCQs before an earlier segment\'s right-column MCQs, merging two different topics\' MCQs together out of order. Never zigzag within one segment\'s column (left-Q1,right-Q1,left-Q2 is WRONG), but DO switch back to a new segment\'s left column immediately after finishing that same segment\'s right column, even if the OTHER column still has unrelated old-topic MCQs lower down (those belong to a still-open earlier segment in that column and get appended to that earlier segment, not reordered here).\n'
    '  Example: left column has topicA-Q1,Q2,Q3 then topicB-Q1,Q2; right column at the same vertical range has topicA-Q7...Q13 (no new banner yet) then topicB-Q3,Q4. Correct output order: topicA-Q1,Q2,Q3 (left) → topicA-Q7...Q13 (right) → topicB-Q1,Q2 (left) → topicB-Q3,Q4 (right). NEVER: topicA-left, topicB-left, topicA-right, topicB-right (that scrambles topics together).\n'
    '  Before finalizing output, recount: every MCQ visible on the page (both columns, top to bottom) MUST appear exactly once in the JSON array — zero skipped, zero duplicated. Double-check page edges/corners and column-boundary MCQs specifically, they are the most commonly missed.\n\n'
    'OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown. No MCQ → exactly [].\n'
    '[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"... (max 165 chars Bengali)","qsn_bbox":[100,200,400,450],"qsn_no":1,"topic_hint":"..."}]'
)


UNMESH_EXTRACT_PROMPT = QBM_EXTRACT_PROMPT_DEFAULT.replace(
    'OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown. No MCQ → exactly [].\n'
    '[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"... (max 165 chars Bengali)","qsn_bbox":[100,200,400,450]}]',
    'ADDITIONALLY (for topic-grouping) extract for EACH MCQ:\n'
    '- "qsn_no": the question\'s own printed serial number on the page, as an integer (e.g. প্রশ্ন-১ → 1, ২১. → 21, Q5 → 5). This is CRITICAL and used to detect topic boundaries — read it carefully and precisely for every single MCQ, never skip it if a number is printed. Use null ONLY if truly zero visible numbering exists for that MCQ.\n'
    '- "topic_hint": the topic-heading text that this MCQ falls under. THIS PAGE STYLE uses a DIFFERENT topic-marker design than a plain black banner bar — a topic heading here is identified by ALL THREE of the following together, right before the heading text:\n'
    '  i) the heading text itself sits on a WHITE/plain page background (NOT inside a solid dark/black bar),\n'
    '  ii) the heading text is BOLD BLACK font (visibly heavier/darker than normal question text),\n'
    '  iii) immediately to the LEFT of the heading text (and sometimes duplicated once more further left before it) there is a small ICON MARKER — this can be a solid BLACK/DARK FILLED CIRCLE (●) with 1-3 small WHITE STAR (★) glyphs inside/beside it, OR a HOLLOW/OUTLINE STAR (✪) appearing 1, 2, OR 3 times in a row right before the heading text (the exact count of ✪ does NOT matter — even a single ✪ before a bold-black heading on white/light bg is enough, this is a strong standalone topic marker on its own), OR ANY OTHER small colored/graphical icon repeated exactly TWICE in a row right before the heading text (e.g. two folder icons \U0001F4C2\U0001F4C2, two star icons \u2B50\u2B50, two colored circle icons \U0001F535\U0001F535 of any color, two bullseye/target icons, etc.) — the EXACT icon style, color, or star-count does not matter and does not change the topic; what matters is that some small icon glyph (especially ✪) appears immediately before a bold-black heading line on white background. Always treat this icon + bold-black-heading pattern as a genuine topic marker regardless of which specific icon/emoji/color is used on this particular page — never require it to look identical to markers seen on other pages.\n'
    '  iii-ALT) ALSO treat as a genuine topic marker (equally valid alternative to iii above, do NOT require both): a SINGLE small icon/emoji (book, folder, magnifier, target, pin, star, etc. \u2014 any single small graphical icon, not doubled) placed immediately to the left of a short bold heading line, where that heading line sits inside its OWN distinct bounded box/strip (a thin border, a shaded/colored background rectangle, or a horizontal rule directly above+below just that heading) that visually separates it from the surrounding question text above and below. This boxed-single-icon-heading style is common on pages that number/list topics (e.g. a heading like \u09e9\u09ea (34) followed by a topic title inside its own box) \u2014 such a numbered/titled heading line inside its own box, with any single icon beside it, is a topic_hint exactly like the doubled-icon or black-banner styles; a leading topic-number prefix (if present) is part of the topic_hint text.\n'
    '  A line of text is a topic_hint ONLY when i, ii, and EITHER iii OR iii-ALT are true together. Do NOT treat as topic_hint: plain bold text with no icon marker (doubled or single-boxed) before it, sub-headers like university/organization names, exam-source tags (BCS/MAT/DAT/RU-D/DU-D/JnU-D bracket tags), \u09ac\u09cd\u09af\u09be\u0996\u09cd\u09af\u09be/explanation labels, or a single generic recurring section-label like \"\u09ac\u09bf\u0997\u09a4 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09be\u09ac\u09b2\u09c0\" (past-questions label) that itself carries no icon marker of its own — that label is noise, not a topic name.\n'
    '  a) Do NOT use smaller sub-headers like university/organization names or unit labels (\u098f \u0987\u0989\u09a8\u09bf\u099f, \u09ac\u09bf \u0987\u0989\u09a8\u09bf\u099f, BUP, FASS, FSSS) — those are subsections INSIDE one topic, never the topic itself.\n'
    '  b) If a new doubled-icon heading appears anywhere on THIS page (even partway down), every MCQ from that point onward gets the NEW heading text; MCQs above it on the same page keep the heading that was already active for them.\n'
    '  b2) TWO-COLUMN pages: left and right columns can each have their OWN active heading, independent of each other. Determine each MCQ\'s topic_hint by which doubled-icon heading is ACTUALLY above it in ITS OWN column, never by copying the other column\'s current heading.\n'
    '  b3) A NEW doubled-icon heading ALWAYS immediately changes topic_hint for every MCQ after it in ITS OWN column, the instant it appears — even if that heading is the very last thing on the page (right at the bottom, no MCQ follows it on this page at all) and even if the other column still has old-topic MCQs left. Never wait for "both columns to finish" — that is WRONG. If a heading appears with zero MCQs following it on this page, still report it: emit one extra object at the very end of the JSON array in the form {"trailing_topic_marker":"<heading text>"} (no other fields) so the next page knows this new topic already started.\n'
    '  c) If this specific page has genuinely no doubled-icon heading visible anywhere on it (pure continuation page), use "" (empty string) for every MCQ on this page — do not guess or invent one.\n'
    '  d) Every MCQ under the same visible doubled-icon heading on this page must get the EXACT SAME topic_hint string, character-for-character (do not include the icons themselves in the string, just the heading text).\n\n'
    'OUTPUT ORDER (CRITICAL — this is a SEGMENT-major order, not a plain column-major order):\n'
    '  A "segment" = the vertical span of the page still under ONE doubled-icon heading, before the next such heading starts (in either column). A single page can contain multiple segments stacked vertically.\n'
    '  For EACH segment, in top-to-bottom page order:\n'
    '    - output every MCQ from THAT segment\'s left column (top to bottom),\n'
    '    - THEN every MCQ from THAT segment\'s right column (top to bottom, same segment only),\n'
    '    - THEN move to the next segment down the page and repeat (its left column, then its right column).\n'
    '  Do NOT do a single whole-page "entire left column, then entire right column" pass. Never zigzag within one segment\'s column, but DO switch back to a new segment\'s left column immediately after finishing that same segment\'s right column.\n'
    '  Before finalizing output, recount: every MCQ visible on the page (both columns, top to bottom) MUST appear exactly once in the JSON array — zero skipped, zero duplicated.\n\n'
    'OUTPUT FORMAT: Only a valid JSON array, no extra text/markdown. No MCQ → exactly [].\n'
    '[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"... (max 165 chars Bengali)","qsn_bbox":[100,200,400,450],"qsn_no":1,"topic_hint":"..."}]'
)


def _check_segment_topic_consistency(mcqs: list, context: str = "", forced_boundaries: set = None) -> list:
    """CODE-LEVEL CHECK (used at both Call1 and Call2 stages): walks mcqs in
    read order and finds every 'segment' — the run of MCQs from one
    qsn_no==1 up to (but not including) the NEXT qsn_no==1. Every MCQ inside
    ONE segment must share the exact same effective topic_hint/topic_hint,
    since a segment is by definition one university/unit section that never
    itself contains a real chapter change partway through. If a segment has
    more than one distinct hint, that's a real inconsistency (mid-segment
    banner misread) and gets logged with details so it's visible, and the
    majority hint in that segment is applied to the outliers (self-heals
    the obvious case: one MCQ in the middle got a stray/blank hint while the
    rest of its own segment agree).

    Any MCQ carrying _forced_marker=True (set when /unmesh's independent ✪
    heading-scan hard-confirmed a topic marker at that qsn_no) is NEVER
    treated as a stray outlier to majority-vote away, and always starts a
    new segment boundary — so a genuine mid-segment topic change (no serial
    reset, confirmed by the marker scan) is preserved instead of being
    overwritten by the surrounding majority."""
    if not mcqs:
        return mcqs
    segments = []
    cur = []
    for m in mcqs:
        qn = m.get("qsn_no")
        is_forced = bool(m.get("_forced_marker"))
        if cur and (qn == 1 or is_forced):
            segments.append(cur)
            cur = []
        cur.append(m)
    if cur:
        segments.append(cur)

    for seg in segments:
        hints = [(m.get("topic_hint") or m.get("_effective_hint") or "").strip() for m in seg]
        non_empty = [h for h in hints if h]
        if not non_empty:
            continue
        # A forced/confirmed hint inside this segment (from the ✪ marker
        # scan) always wins outright — skip majority-vote entirely so it
        # can never be treated as an outlier.
        forced_hints = [
            (m.get("topic_hint") or m.get("_effective_hint") or "").strip()
            for m in seg if m.get("_forced_marker")
        ]
        if forced_hints:
            majority = forced_hints[0]
            distinct = set(non_empty)
            if len(distinct) > 1:
                nums = [m.get("qsn_no") for m in seg]
                logger.warning(
                    f"[TOPIC segment-check{(' ' + context) if context else ''}] "
                    f"inconsistent topic within one segment (qsn {nums[0]}-{nums[-1]}): "
                    f"applying CONFIRMED marker hint '{majority[:30]}' (overrides non-forced outliers)"
                )
                for m in seg:
                    if m.get("_forced_marker"):
                        continue
                    h = (m.get("topic_hint") or m.get("_effective_hint") or "").strip()
                    if h and h != majority:
                        if "topic_hint" in m:
                            m["topic_hint"] = majority
                        if "_effective_hint" in m:
                            m["_effective_hint"] = majority
            continue
        distinct = set(non_empty)
        if len(distinct) > 1:
            counts = {h: non_empty.count(h) for h in distinct}
            majority = max(counts, key=counts.get)
            nums = [m.get("qsn_no") for m in seg]
            logger.warning(
                f"[TOPIC segment-check{(' ' + context) if context else ''}] "
                f"inconsistent topic within one segment (qsn {nums[0]}-{nums[-1]}): "
                f"{counts} — applying majority '{majority[:30]}' to outliers"
            )
            for m in seg:
                h = (m.get("topic_hint") or m.get("_effective_hint") or "").strip()
                if h and h != majority:
                    if "topic_hint" in m:
                        m["topic_hint"] = majority
                    if "_effective_hint" in m:
                        m["_effective_hint"] = majority
    return mcqs


def _check_segment_serial_order(mcqs: list, context: str = "") -> list:
    """CODE-LEVEL CHECK (used at both Call1 and Call2 stages, alongside the
    topic-consistency check): within each segment (run of MCQs from one
    qsn_no==1 up to the next qsn_no==1), verifies qsn_no forms a clean
    ascending sequence in list order — no jumbled/out-of-order entries and
    no gap (a missing serial). Does not reorder or invent MCQs (that's
    Call2's missing-recovery job) — this only LOGS what it finds so gaps/
    jumbles are visible per-stage instead of silently slipping through."""
    if not mcqs:
        return mcqs
    segments = []
    cur = []
    for m in mcqs:
        if m.get("qsn_no") == 1 and cur:
            segments.append(cur)
            cur = []
        cur.append(m)
    if cur:
        segments.append(cur)

    for seg in segments:
        nums = [m.get("qsn_no") for m in seg if isinstance(m.get("qsn_no"), int)]
        if len(nums) < 2:
            continue
        if nums != sorted(nums):
            logger.warning(
                f"[TOPIC serial-order{(' ' + context) if context else ''}] "
                f"segment qsn {nums[0]}-{nums[-1]} is OUT OF ORDER in list: {nums}"
            )
        gaps = [n for n in range(nums[0], nums[-1] + 1) if n not in set(nums)]
        if gaps:
            logger.warning(
                f"[TOPIC serial-order{(' ' + context) if context else ''}] "
                f"segment qsn {nums[0]}-{nums[-1]} MISSING serial(s): {gaps}"
            )
    return mcqs


def _build_topic_verify_prompt(mcqs: list) -> str:
    """Call 2 audit prompt: gives the model its own Call1 output back alongside
    the image, and asks it to independently re-check the page against that
    output on 4 axes — (1) left-column count, (2) right-column count,
    (3) serial-number correctness, (4) word-accuracy — then return only the
    corrections needed (not a full re-extraction, keeps Call2 cheap).
    Left/right are checked SEPARATELY (not just a combined page total) so a
    miss confined to one column doesn't get averaged away.
    Deliberately does NOT let Call2 change topic_hint/topic grouping —
    Call1's topic_hint-change boundary logic already gets topic splitting
    right; a prior version let Call2 also rewrite topic_hint and that
    introduced topic-mismatch regressions (sub-headers like চাকরি/BUP wrongly
    promoted to topic names), so Call2 may only FLAG a suspected topic-leak
    for logging, never change it."""
    compact = [
        {"qsn_no": m.get("qsn_no"), "question": m.get("question", ""),
         "options": m.get("options", []), "answer": m.get("answer", ""),
         "topic_hint": m.get("topic_hint", "")}
        for m in mcqs
    ]
    return (
        "You are auditing a previous extraction of this page against the actual image. "
        "Below is what was already extracted:\n"
        f"{json.dumps(compact, ensure_ascii=False)}\n\n"
        "Re-check the page carefully and verify:\n"
        "1) LEFT COLUMN COUNT: if the page has 2 columns, look ONLY at the left column, "
        "top to bottom. Is every MCQ visible in the left column present in the list above? "
        "List any left-column qsn_no that is visible on the page but MISSING from the list.\n"
        "2) RIGHT COLUMN COUNT: same check, but ONLY for the right column, top to bottom. "
        "List any right-column qsn_no that is visible on the page but MISSING from the list. "
        "(If the page is single-column, just do one full top-to-bottom count and skip step 2.)\n"
        "3) SERIAL: for each qsn_no in the list, does it match the actual printed "
        "serial number on the page? List any that are WRONG as {\"qsn_no_wrong\": printed_value, \"was\": extracted_value}.\n"
        "4) WORD ACCURACY: for each entry, does the extracted question/option text exactly "
        "match the words printed on the page (no substituted/misread words, no altered "
        "meaning)? List any with a mismatch as {\"qsn_no\": N, \"field\": \"question\"/\"optionA\"/\"optionB\"/\"optionC\"/\"optionD\", "
        "\"correct_text\": \"<the actual text exactly as printed on the page>\"}. "
        "Only flag genuine misreads — do not flag stylistic differences.\n"
        "5) TOPIC LEAK (flag only, do not fix): does any MCQ's topic_hint in the list "
        "above NOT match the actual full-page-width BLACK/DARK BACKGROUND banner text that "
        "is really above it on the page? (Remember: university/organization names, চাকরি/চাকুরি, "
        "BUP, unit labels like বি ইউনিট are sub-headers, NEVER real topic banners — do not "
        "flag topic_hint as wrong just because a sub-header appears near it.) "
        "List any genuine mismatch as {\"qsn_no\": N, \"extracted_hint\": \"...\", \"actual_banner\": \"...\"} "
        "for review only — this will be logged, not auto-applied.\n"
        "6) ANSWER VERIFY: does the marked answer match what's ACTUALLY marked/printed on the page "
        "(circle/tick/underline/answer-key text)? The page's own marked answer ALWAYS wins — re-confirm "
        "it, never override a genuinely visible page mark with your own judgment. Also catch a misread "
        "word that looks valid but is wrong (wrong city/date/number/name) if the page proves it. "
        "ONLY if the page has NO visible mark/answer-key for that question at all (genuinely unclear/missing "
        "source), pick the single best correct answer yourself using general knowledge. "
        "Add to the SAME word_fixes array as {\"qsn_no\": N, \"field\": \"question\"/\"optionA-D\"/\"answer\", "
        "\"correct_text\": \"...\"}.\n\n"
        "Output ONLY this JSON object, nothing else:\n"
        '{"missing_qsn_no": [<integers, left+right column misses combined>], '
        '"wrong_serials": [{"qsn_no_wrong": <int>, "was": <int>}], '
        '"word_fixes": [{"qsn_no": <int>, "field": "question", "correct_text": "..."}], '
        '"topic_leaks": [{"qsn_no": <int>, "extracted_hint": "...", "actual_banner": "..."}]}\n'
        "If everything is correct, output all empty arrays."
    )


def _parse_count_check_json(text: str) -> dict:
    if not text:
        return {}
    t = text.strip()
    if "```json" in t:
        t = t.split("```json")[1].split("```")[0].strip()
    elif "```" in t:
        t = t.split("```")[1].split("```")[0].strip()
    try:
        m = re.search(r'\{.*\}', t, re.DOTALL)
        return json.loads(m.group()) if m else json.loads(t)
    except Exception:
        return {}


_OPT_FIELD_IDX = {"optiona": 0, "optionb": 1, "optionc": 2, "optiond": 3}


async def _topic_extract_from_image(img, cache_key: tuple = None) -> list:
    """Topic-aware extractor: same strict extraction rules as QBM but the
    prompt also asks for each MCQ's printed serial number (qsn_no) and
    nearest topic heading (topic_hint), used by /topic to detect topic
    boundaries and split into separate per-topic CSVs.

    Call 1: Gemini->Groq->OpenRouter full extraction (as before). SKIPPED
    on a cache hit (cache_key given and found in _topic_mcq_result_cache)
    -- same re-run-same-PDF speedup /qbm has, kept in its OWN cache
    namespace since topic_hint/qsn_no fields differ from /qbm's shape.
    Call 2 (audit): feeds Call1's own output back to the model alongside the
    image and asks it to independently re-check 4 things — (1) count/missing
    MCQs, (2) wrong serial numbers, (3) word-level accuracy of question/option
    text against the page, (4) topic_hint correctness/completeness. Only the
    flagged corrections are applied — cheaper than a full blind re-extraction
    while still catching column-boundary misses, misread words, and
    mis-tagged topics. ALWAYS runs in full, even on a Call1 cache hit."""
    async def _run_extract_call(bypass_cache: bool = False):
        cached = _topic_mcq_result_cache.get(cache_key) if (cache_key and not bypass_cache) else None
        if cached:
            logger.info(f"[TOPIC MCQ Cache] hit for {cache_key} — skipping Call1, still running full Call2 verify")
            return _qbm_dedup_list(cached)
        gem = await _qbm_gemini_extract(img, TOPIC_EXTRACT_PROMPT)
        if gem:
            result = _qbm_dedup_list(gem)
            if result and cache_key:
                _topic_mcq_result_cache[cache_key] = result
                _cap_qbm_mcq_cache(_topic_mcq_result_cache)
            return result
        txt = await _qbm_groq_call(img, TOPIC_EXTRACT_PROMPT)
        result = _qbm_parse_json(txt) if txt else []
        if result:
            result = _qbm_dedup_list(result)
            if result and cache_key:
                _topic_mcq_result_cache[cache_key] = result
                _cap_qbm_mcq_cache(_topic_mcq_result_cache)
            return result
        txt3 = await _qbm_openrouter_call(img, TOPIC_EXTRACT_PROMPT)
        result3 = _qbm_parse_json(txt3) if txt3 else []
        return _qbm_dedup_list(result3)

    mcqs = await _run_extract_call()
    if not mcqs:
        return mcqs

    # CODE-LEVEL CHECK (Call1 stage): within this single page's extraction,
    # every MCQ between one qsn_no==1 and the next must share one topic_hint.
    mcqs = _check_segment_topic_consistency(mcqs, context="Call1")
    mcqs = _check_segment_serial_order(mcqs, context="Call1")

    # Call 2: audit pass against Call1's own output.
    try:
        verify_prompt = _build_topic_verify_prompt(mcqs)
        check_txt = await _qbm_gemini_raw(img, verify_prompt)
        check = _parse_count_check_json(check_txt)

        missing_nums = set(n for n in (check.get("missing_qsn_no") or []) if isinstance(n, int))
        wrong_serials = check.get("wrong_serials") or []
        word_fixes = check.get("word_fixes") or []
        topic_leaks = check.get("topic_leaks") or []

        by_qsn = {m.get("qsn_no"): m for m in mcqs if isinstance(m.get("qsn_no"), int)}

        # 1) Recover missing MCQs — retry up to 2 extraction passes, since a
        # single re-extraction can still miss the same MCQ (same failure
        # mode repeating). Re-checks after each attempt so it stops as soon
        # as everything's recovered instead of always burning both retries.
        if missing_nums:
            logger.warning(f"[TOPIC verify] missing qsn_no {sorted(missing_nums)} — re-extracting page")
            for _retry_attempt in range(2):
                if not missing_nums:
                    break
                retry_mcqs = await _run_extract_call(bypass_cache=True)
                retry_got = {m.get("qsn_no"): m for m in retry_mcqs if isinstance(m.get("qsn_no"), int)}
                recovered = set()
                for n in missing_nums:
                    if n in retry_got:
                        mcqs.append(retry_got[n])
                        by_qsn[n] = retry_got[n]
                        recovered.add(n)
                missing_nums -= recovered
                if missing_nums and _retry_attempt == 0:
                    logger.warning(f"[TOPIC verify] still missing qsn_no {sorted(missing_nums)} after retry 1 — trying once more")

        # 2) Fix wrong serial numbers.
        for fix in wrong_serials:
            was = fix.get("was")
            correct = fix.get("qsn_no_wrong")
            if isinstance(was, int) and isinstance(correct, int) and was in by_qsn:
                by_qsn[was]["qsn_no"] = correct
                logger.warning(f"[TOPIC verify] serial fixed: {was} -> {correct}")

        # 3) Apply word-accuracy fixes.
        for fix in word_fixes:
            n = fix.get("qsn_no")
            field = (fix.get("field") or "").strip().lower().replace(" ", "").replace("_", "")
            text = fix.get("correct_text")
            if not (isinstance(n, int) and text and n in by_qsn):
                continue
            m = by_qsn[n]
            if field == "question":
                m["question"] = text
                logger.warning(f"[TOPIC verify] word fix qsn {n} question")
            elif field == "answer":
                m["answer"] = text
                logger.warning(f"[TOPIC verify] word fix qsn {n} answer -> {text}")
            elif field in _OPT_FIELD_IDX and isinstance(m.get("options"), list) and len(m["options"]) == 4:
                m["options"][_OPT_FIELD_IDX[field]] = text
                logger.warning(f"[TOPIC verify] word fix qsn {n} {field}")

        # 4) Log-only: suspected topic leaks (never auto-applied — this is
        # exactly what caused the earlier topic-mismatch regression when
        # Call2 was allowed to rewrite topic_hint directly).
        _SUBHEADER_BLOCKLIST = (
            "বিশ্ববিদ্যালয়", "চাকরি", "চাকুরি", "bup", "fass", "fsss",
            "ইউনিট", "unit",
        )
        for leak in topic_leaks:
            n = leak.get("qsn_no")
            actual = (leak.get("actual_banner") or "").strip()
            if any(bad in actual.lower() for bad in _SUBHEADER_BLOCKLIST):
                continue  # Call2 misjudged a sub-header as a banner — ignore
            logger.warning(
                f"[TOPIC verify] possible topic leak qsn {n}: "
                f"extracted='{(leak.get('extracted_hint') or '')[:30]}' "
                f"actual='{actual[:30]}' (not auto-fixed)"
            )

        mcqs = _qbm_dedup_list(mcqs)
        # CODE-LEVEL CHECK (Call2 stage): re-run the same segment-consistency
        # check after Call2's fixes (missing-recovery/serial-fix can add or
        # relabel entries), catching anything the Call1-stage check couldn't
        # see yet.
        mcqs = _check_segment_topic_consistency(mcqs, context="Call2")
        mcqs = _check_segment_serial_order(mcqs, context="Call2")
    except Exception as e:
        logger.warning(f"[TOPIC verify] audit pass failed, skipping: {e}")

    return mcqs


def _build_unmesh_heading_scan_prompt() -> str:
    """DEDICATED strict heading-detection pass for /unmesh, run independently
    of the main topic_hint extraction. Asks ONE narrow, unambiguous
    question — scan the whole page top-to-bottom for a TOPIC-LEVEL heading
    only (a broad subject-category title that groups many MCQs together,
    e.g. "বাংলাদেশের নদ-নদী, বঙ্গোপসাগর..."), NOT any small styled label.
    This result is treated as a HARD, code-trusted split signal in
    _unmesh_group_mcqs — not just a logged suggestion — precisely because
    the main extraction prompt's topic_hint field is model-subjective and
    can silently miss heading styles it wasn't primed to recognize."""
    return (
        "Find ONLY genuine TOPIC-LEVEL headings on this page — ignore all MCQ question/option text.\n\n"
        "‼️ HARD RULE — CHECK THIS FIRST, ALWAYS: if you see the HOLLOW/OUTLINE STAR glyph (✪) "
        "appearing 1 time, 2 times, or 3 times in a row immediately before a bold-black heading line "
        "on a white/light background, that line IS a genuine topic heading — no exceptions, no need "
        "to judge whether the wording 'sounds broad enough'. The presence of ✪ (any count 1-3) right "
        "before a bold-black heading is BY ITSELF sufficient proof of a topic heading. Report it.\n\n"
        "A genuine topic heading is a BROAD SUBJECT-CATEGORY TITLE that groups MANY MCQs under it "
        "(e.g. \"বাংলাদেশের নদ-নদী, বঙ্গোপসাগর, দ্বীপ, বাঁধ...\", \"ভূপ্রকৃতি, পাহাড়-পর্বত, উপত্যকা...\"). "
        "It is visually set apart (bold/dark heading font, and/or an icon beside it, and/or its own "
        "box/border/shaded strip/banner bar) AND its wording names a general knowledge subject area, "
        "not a single fact — UNLESS the ✪ hard rule above already applies, in which case report it "
        "regardless of wording.\n\n"
        "STRICTLY DO NOT report any of the following even if styled/boxed/bold — these are NOT topic "
        "headings, they are per-question labels that repeat on nearly every MCQ and never span many "
        "MCQs as one group:\n"
        "  - exam-source bracket tags: [BCS: 17th], [DU-D: 11-12], [MAT: 25-26], [JnU-B: 11-12], etc.\n"
        "  - ব্যাখ্যা:/explanation labels\n"
        "  - university/organization/exam-body names (বিশ্ববিদ্যালয়, BUP, FASS) or unit labels (বি ইউনিট)\n"
        "  - a generic recurring section-label like \"বিগত প্রশ্নাবলি\" or \"সম্ভাব্য আরও প্রশ্ন\" "
        "(these repeat as a running section divider, not a subject-specific topic name)\n"
        "  - page footer/header branding, book title, publisher name, page numbers\n\n"
        "A true topic heading is rare — expect at most 0-2 per page, often ZERO (most pages are pure "
        "continuation of the previous page's topic with no new heading at all). If you are not confident "
        "a line is a genuine broad-subject topic title, do NOT report it.\n\n"
        "For each genuine topic heading found (top to bottom, both columns if 2-column), report:\n"
        "  - its exact text\n"
        "  - the printed qsn_no of the very next MCQ that appears after it on the page "
        "(the first question number below/after that heading in its own column) — use null if the "
        "heading is the last thing on the page with no MCQ following it on this page.\n\n"
        "Output ONLY this JSON array, nothing else, in top-to-bottom page order:\n"
        '[{"heading_text": "...", "next_qsn_no": <int or null>}]\n'
        "If there are zero genuine topic headings on this page, output exactly []."
    )


def _parse_unmesh_heading_scan(text: str) -> list:
    if not text:
        return []
    t = text.strip()
    if "```json" in t:
        t = t.split("```json")[1].split("```")[0].strip()
    elif "```" in t:
        t = t.split("```")[1].split("```")[0].strip()
    try:
        m = re.search(r'\[.*\]', t, re.DOTALL)
        data = json.loads(m.group()) if m else json.loads(t)
        return data if isinstance(data, list) else []
    except Exception:
        return []


async def _unmesh_extract_from_image(img, cache_key: tuple = None) -> list:
    """/unmesh extractor — same Call1+Call2 pipeline as /topic, but topic
    boundaries are detected via the WHITE-bg + BOLD BLACK text + preceding
    black-circle-with-1/2/3-white-stars heading style (UNMESH_EXTRACT_PROMPT),
    instead of /topic's black-background banner bar style. Everything else
    (qsn_no serial detection, segment-major read order, Call2 audit, code-
    level consistency/serial checks) is identical to /topic.

    Call1 result cached in its own namespace (_unmesh_mcq_result_cache) when
    cache_key given — same re-run-same-PDF speedup as /topic/qbm. Only
    Call1's raw extraction is cached; the heading-scan + Call2 audit below
    always re-run in full, unaffected by this cache."""
    async def _run_extract_call(bypass_cache: bool = False):
        cached = _unmesh_mcq_result_cache.get(cache_key) if (cache_key and not bypass_cache) else None
        if cached:
            logger.info(f"[UNMESH MCQ Cache] hit for {cache_key} — skipping Call1, still running full heading-scan + Call2 verify")
            return _qbm_dedup_list(cached)
        gem = await _qbm_gemini_extract(img, UNMESH_EXTRACT_PROMPT)
        if gem:
            result = _qbm_dedup_list(gem)
            if result and cache_key:
                _unmesh_mcq_result_cache[cache_key] = result
                _cap_qbm_mcq_cache(_unmesh_mcq_result_cache)
            return result
        txt = await _qbm_groq_call(img, UNMESH_EXTRACT_PROMPT)
        result = _qbm_parse_json(txt) if txt else []
        if result:
            result = _qbm_dedup_list(result)
            if result and cache_key:
                _unmesh_mcq_result_cache[cache_key] = result
                _cap_qbm_mcq_cache(_unmesh_mcq_result_cache)
            return result
        txt3 = await _qbm_openrouter_call(img, UNMESH_EXTRACT_PROMPT)
        result3 = _qbm_parse_json(txt3) if txt3 else []
        return _qbm_dedup_list(result3)

    mcqs = await _run_extract_call()
    if not mcqs:
        return mcqs

    # CODE-LEVEL STRICT HEADING SCAN — independent narrow pass, run
    # regardless of what topic_hint the main extraction assigned. Any
    # heading found here is a HARD split signal applied directly to the
    # matching qsn_no's topic_hint below, overriding a blank/wrong
    # topic_hint the main prompt may have silently missed (e.g. box-style
    # single-icon headings the main prompt wasn't primed to recognize).
    try:
        scan_txt = await _qbm_gemini_raw(img, _build_unmesh_heading_scan_prompt())
        headings = _parse_unmesh_heading_scan(scan_txt)
    except Exception as e:
        logger.warning(f"[UNMESH heading-scan] failed, skipping: {e}")
        headings = []

    forced_boundaries = set()
    if headings:
        by_qsn_early = {m.get("qsn_no"): m for m in mcqs if isinstance(m.get("qsn_no"), int)}
        page_qnos_sorted = sorted(by_qsn_early.keys())
        # sort headings by their next_qsn_no so multiple markers on one page
        # are applied in page order and don't clobber each other's ranges
        ordered = sorted(
            [h for h in headings if isinstance(h.get("next_qsn_no"), int)],
            key=lambda h: h["next_qsn_no"],
        )
        trailing = [h for h in headings if not isinstance(h.get("next_qsn_no"), int)]
        for idx, h in enumerate(ordered):
            htext = (h.get("heading_text") or "").strip()
            if not htext:
                continue
            next_q = h.get("next_qsn_no")
            if next_q not in by_qsn_early:
                continue
            # this marker's range ends right before the next marker's start
            # (or end of page if it's the last marker)
            range_end = ordered[idx + 1]["next_qsn_no"] if idx + 1 < len(ordered) else None
            old_hint = by_qsn_early[next_q].get("topic_hint", "")
            if old_hint != htext:
                logger.warning(
                    f"[UNMESH heading-scan] applying heading '{htext[:40]}' "
                    f"to qsn_no={next_q} (was topic_hint='{old_hint[:40]}')"
                )
            forced_boundaries.add(next_q)
            # CONFIRMED marker overrides topic_hint for every MCQ in its
            # range, even ones that already carry a (wrong/stale) non-empty
            # hint from the main extraction pass — a hard-confirmed ✪ marker
            # always outranks the main prompt's guess. Stamp _forced_marker
            # so downstream consistency checks (which may run after this
            # page's mcqs are merged with other pages) never majority-vote
            # this confirmed value away.
            for qn in page_qnos_sorted:
                if qn >= next_q and (range_end is None or qn < range_end):
                    by_qsn_early[qn]["topic_hint"] = htext
                    by_qsn_early[qn]["_forced_marker"] = True
        for h in trailing:
            htext = (h.get("heading_text") or "").strip()
            if htext:
                mcqs.append({"trailing_topic_marker": htext})

    # Pull out any trailing_topic_marker sentinel(s) — a marker seen at the
    # bottom of the page with zero MCQs following it on this page. Keep them
    # aside (re-attached at the end) so the checks/dedup below only see real
    # MCQ objects.
    trailing_markers = [m.get("trailing_topic_marker") for m in mcqs if "trailing_topic_marker" in m]
    mcqs = [m for m in mcqs if "trailing_topic_marker" not in m]
    if not mcqs and not trailing_markers:
        return mcqs

    # CODE-LEVEL CHECK (Call1 stage) — same generic segment checks /topic uses.
    mcqs = _check_segment_topic_consistency(mcqs, context="UNMESH-Call1")
    mcqs = _check_segment_serial_order(mcqs, context="UNMESH-Call1")

    # Call 2: audit pass against Call1's own output (same verify prompt/logic
    # as /topic — it only reasons about qsn_no/topic_hint/text, not the
    # visual marker style, so it's reusable unchanged).
    try:
        verify_prompt = _build_topic_verify_prompt(mcqs)
        check_txt = await _qbm_gemini_raw(img, verify_prompt)
        check = _parse_count_check_json(check_txt)

        missing_nums = set(n for n in (check.get("missing_qsn_no") or []) if isinstance(n, int))
        wrong_serials = check.get("wrong_serials") or []
        word_fixes = check.get("word_fixes") or []
        topic_leaks = check.get("topic_leaks") or []

        by_qsn = {m.get("qsn_no"): m for m in mcqs if isinstance(m.get("qsn_no"), int)}

        if missing_nums:
            logger.warning(f"[UNMESH verify] missing qsn_no {sorted(missing_nums)} — re-extracting page")
            for _retry_attempt in range(2):
                if not missing_nums:
                    break
                retry_mcqs = await _run_extract_call(bypass_cache=True)
                retry_got = {m.get("qsn_no"): m for m in retry_mcqs if isinstance(m.get("qsn_no"), int)}
                recovered = set()
                for n in missing_nums:
                    if n in retry_got:
                        mcqs.append(retry_got[n])
                        by_qsn[n] = retry_got[n]
                        recovered.add(n)
                missing_nums -= recovered
                if missing_nums and _retry_attempt == 0:
                    logger.warning(f"[UNMESH verify] still missing qsn_no {sorted(missing_nums)} after retry 1 — trying once more")

        for fix in wrong_serials:
            was = fix.get("was")
            correct = fix.get("qsn_no_wrong")
            if isinstance(was, int) and isinstance(correct, int) and was in by_qsn:
                by_qsn[was]["qsn_no"] = correct
                logger.warning(f"[UNMESH verify] serial fixed: {was} -> {correct}")

        for fix in word_fixes:
            n = fix.get("qsn_no")
            field = (fix.get("field") or "").strip().lower().replace(" ", "").replace("_", "")
            text = fix.get("correct_text")
            if not (isinstance(n, int) and text and n in by_qsn):
                continue
            m = by_qsn[n]
            if field == "question":
                m["question"] = text
                logger.warning(f"[UNMESH verify] word fix qsn {n} question")
            elif field == "answer":
                m["answer"] = text
                logger.warning(f"[UNMESH verify] word fix qsn {n} answer -> {text}")
            elif field in _OPT_FIELD_IDX and isinstance(m.get("options"), list) and len(m["options"]) == 4:
                m["options"][_OPT_FIELD_IDX[field]] = text
                logger.warning(f"[UNMESH verify] word fix qsn {n} {field}")

        _SUBHEADER_BLOCKLIST = (
            "বিশ্ববিদ্যালয়", "চাকরি", "চাকুরি", "bup", "fass", "fsss",
            "ইউনিট", "unit",
        )
        for leak in topic_leaks:
            n = leak.get("qsn_no")
            actual = (leak.get("actual_banner") or "").strip()
            if any(bad in actual.lower() for bad in _SUBHEADER_BLOCKLIST):
                continue
            logger.warning(
                f"[UNMESH verify] possible topic leak qsn {n}: "
                f"extracted='{(leak.get('extracted_hint') or '')[:30]}' "
                f"actual='{actual[:30]}' (not auto-fixed)"
            )

        mcqs = _qbm_dedup_list(mcqs)
        mcqs = _check_segment_topic_consistency(mcqs, context="UNMESH-Call2")
        mcqs = _check_segment_serial_order(mcqs, context="UNMESH-Call2")
    except Exception as e:
        logger.warning(f"[UNMESH verify] audit pass failed, skipping: {e}")

    for marker in trailing_markers:
        if marker:
            mcqs.append({"trailing_topic_marker": marker})
    return mcqs


def _unmesh_group_mcqs(extracted_pages: list) -> list:
    """DEDICATED grouping for /unmesh (fully independent of /topic's
    _topic_group_mcqs). Same two split signals — qsn_no==1 OR the effective
    topic_hint actually changing — PLUS a third: a trailing_topic_marker
    sentinel emitted by UNMESH_EXTRACT_PROMPT when a new doubled-icon
    heading appears at the bottom of a page with zero MCQs following it on
    that page (e.g. ২০১ is the last MCQ on the page, a new heading prints
    right after it, but the next MCQ ২০২ only appears on the next page).
    That marker's text becomes the active hint for every MCQ from that point
    forward, even though nothing on the marker's own page carried it."""
    _FAKE_TOPIC_RE = re.compile(
        r'^(বিশ্ববিদ্যালয়|.{0,20}বিশ্ববিদ্যালয়|বি ইউনিট|এ ইউনিট|সি ইউনিট|ডি ইউনিট|'
        r'এফ ইউনিট|ই ইউনিট|চাকুরি|BUP|FASS|FSSS|[A-Za-z]{1,6}\s*ইউনিট)$',
        re.IGNORECASE
    )
    def _is_fake_topic(hint: str) -> bool:
        h = hint.strip()
        if not h:
            return False
        if _FAKE_TOPIC_RE.match(h):
            return True
        if len(h) <= 25 and (h.endswith("বিশ্ববিদ্যালয়") or h.endswith("ইউনিট")):
            return True
        return False

    flat = []
    last_hint = None
    for _page_idx, (_, _, mcqs) in enumerate(extracted_pages):
        for m in mcqs:
            if "trailing_topic_marker" in m:
                th = (m.get("trailing_topic_marker") or "").strip()
                if th and not _is_fake_topic(th):
                    last_hint = th
                continue  # sentinel only updates carry-forward, not a real MCQ
            m["_page_key"] = _page_idx
            hint = (m.get("topic_hint") or "").strip()
            if hint and _is_fake_topic(hint):
                hint = ""
            if hint:
                last_hint = hint
                m["_effective_hint"] = hint
            else:
                m["_effective_hint"] = last_hint or ""
            flat.append(m)

    flat = _check_segment_topic_consistency(flat, context="unmesh-grouping-stage")

    groups = []
    group_seq = 0
    prev_hint = None
    for m in flat:
        hint = m.get("_effective_hint", "")
        qno = m.get("qsn_no")
        hint_changed = bool(hint) and (prev_hint is not None) and (hint != prev_hint)
        starts_new = (not groups) or (qno == 1) or hint_changed
        if starts_new:
            group_seq += 1
            name = hint if hint else f"Topic {group_seq}"
            groups.append([name, []])
        groups[-1][1].append(m)
        if hint:
            prev_hint = hint

    hint_to_group_idx = {}
    for idx, g in enumerate(groups):
        base_name = re.sub(r'\s*\(\d+\)$', '', g[0])
        hint_to_group_idx.setdefault(base_name, idx)
    for idx, g in enumerate(groups):
        keep, reroute = [], []
        for m in g[1]:
            own_hint = m.get("_effective_hint", "")
            if own_hint and own_hint != re.sub(r'\s*\(\d+\)$', '', g[0]) and own_hint in hint_to_group_idx and hint_to_group_idx[own_hint] < idx:
                reroute.append(m)
            else:
                keep.append(m)
        g[1] = keep
        for m in reroute:
            target_idx = hint_to_group_idx[m.get("_effective_hint", "")]
            logger.warning(
                f"[UNMESH group-order] stray MCQ (qsn_no={m.get('qsn_no')}) with hint "
                f"'{m.get('_effective_hint','')[:30]}' found inside '{g[0][:30]}' — "
                f"rerouted back to earlier group '{groups[target_idx][0][:30]}'"
            )
            groups[target_idx][1].append(m)
    groups = [g for g in groups if g[1]]

    name_counts = {}
    for g in groups:
        name_counts[g[0]] = name_counts.get(g[0], 0) + 1
    seen = {}
    for g in groups:
        base = g[0]
        if name_counts[base] > 1:
            seen[base] = seen.get(base, 0) + 1
            g[0] = f"{base} ({seen[base]})"

    return [(g[0], g[1]) for g in groups]


def _topic_group_mcqs(extracted_pages: list) -> list:
    """Walks all MCQs in ORIGINAL SEGMENT-MAJOR READ ORDER (per the extraction
    prompt: for each topic-segment on a page, top to bottom — that segment's
    left column fully, then that segment's right column fully — before
    moving to the next segment down the page) and splits into topic groups.

    BOUNDARY SIGNAL (per explicit instruction, two independent signals):
    1) qsn_no == 1 marks the start of a NEW topic group, EVERY single time
       it appears in read order — this alone is sufficient to split, no
       other condition required.
    2) topic_hint (the full-width black-background banner text) names the
       group — carried forward across continuation pages/MCQs that report
       no new banner of their own.
    University/unit/org sub-headers (BUP, চাকুরি, এ ইউনিট, university names,
    etc.) must NEVER be treated as topic_hint values (enforced below) — they
    are noise that must not leak into the group name or break carry-forward.

    Returns list of (topic_name, [mcq, ...]) in first-seen order."""
    # CODE-LEVEL GUARD: the vision model sometimes emits a university/org/
    # exam-source sub-header (BUP, চাকুরি, FASS, FSSS, a specific
    # বিশ্ববিদ্যালয় name, বি/এ/এফ/সি/ডি ইউনিট) as topic_hint instead of the
    # real chapter-level black banner, or leaves it blank. Never treat these
    # as real topics — carry forward the last real chapter banner instead.
    _FAKE_TOPIC_RE = re.compile(
        r'^(বিশ্ববিদ্যালয়|.{0,20}বিশ্ববিদ্যালয়|বি ইউনিট|এ ইউনিট|সি ইউনিট|ডি ইউনিট|'
        r'এফ ইউনিট|ই ইউনিট|চাকুরি|BUP|FASS|FSSS|[A-Za-z]{1,6}\s*ইউনিট)$',
        re.IGNORECASE
    )
    def _is_fake_topic(hint: str) -> bool:
        h = hint.strip()
        if not h:
            return False
        if _FAKE_TOPIC_RE.match(h):
            return True
        if len(h) <= 25 and (h.endswith("বিশ্ববিদ্যালয়") or h.endswith("ইউনিট")):
            return True
        return False

    # Pass 1: flatten to one single ordered list preserving exact page/column
    # read order (extracted_pages is already in that order — page N's MCQs
    # list is itself left-column-then-right-column per the extraction
    # prompt's MULTI-COLUMN rule). Carry forward the last real (non-fake,
    # non-empty) topic_hint at the same time.
    flat = []
    last_hint = None
    for _page_idx, (_page_num, _, mcqs) in enumerate(extracted_pages):
        for m in mcqs:
            m["_page_key"] = _page_idx
            m["_page_num"] = _page_num
            hint = (m.get("topic_hint") or "").strip()
            if hint and _is_fake_topic(hint):
                hint = ""  # treat sub-header noise as "no new banner here"
            if hint:
                last_hint = hint
                m["_effective_hint"] = hint
            else:
                m["_effective_hint"] = last_hint or ""
            flat.append(m)

    # CODE-LEVEL CHECK (final stage, across page boundaries): a segment
    # (qsn 1 up to next qsn 1) can span two pages if a section's last few
    # MCQs spill onto the next page — re-run the same consistency check on
    # the fully flattened, page-order-preserved list to catch that case too.
    flat = _check_segment_topic_consistency(flat, context="grouping-stage")

    # Pass 2: build groups walking flat list in strict read order. A NEW
    # group starts exactly when qsn_no == 1 for this MCQ — per explicit
    # instruction, EVERY time the printed serial restarts at 1 that is a
    # genuine new topic boundary, regardless of university/unit sub-header
    # and regardless of whether the chapter banner text changed. The banner
    # (_effective_hint) is used only to NAME the group, not to gate the split.
    groups = []  # list of [topic_name, [mcqs]]
    group_seq = 0
    prev_hint = None
    for m in flat:
        hint = m.get("_effective_hint", "")
        qno = m.get("qsn_no")
        # Two independent split signals (either alone is sufficient):
        # 1) qsn_no resets to 1 (per-topic numbering documents), OR
        # 2) the real (non-fake, non-empty) topic_hint itself changed since
        #    the previous MCQ — needed for documents where numbering runs
        #    CONTINUOUSLY across topic boundaries (e.g. প্রশ্ন ২০১ ends one
        #    topic, ২০২ starts a new one under a new banner) and qsn_no==1
        #    never occurs at all.
        hint_changed = bool(hint) and (prev_hint is not None) and (hint != prev_hint)
        starts_new = (not groups) or (qno == 1) or hint_changed
        if starts_new:
            group_seq += 1
            name = hint if hint else f"Topic {group_seq}"
            groups.append([name, []])
        groups[-1][1].append(m)
        if hint:
            prev_hint = hint

    # CODE-LEVEL GUARD: a straggling old-topic MCQ (its own topic_hint
    # clearly differs from the group it landed in — e.g. old topic's
    # leftover right-column MCQ got appended after a new qsn_no==1 group
    # already started) must NOT silently stay mixed into the new group's
    # CSV. Reroute it back to the most recent EARLIER group that shares its
    # own hint, if one exists; otherwise leave it (better than guessing).
    hint_to_group_idx = {}
    for idx, g in enumerate(groups):
        base_name = re.sub(r'\s*\(\d+\)$', '', g[0])
        hint_to_group_idx.setdefault(base_name, idx)
    for idx, g in enumerate(groups):
        keep, reroute = [], []
        for m in g[1]:
            own_hint = m.get("_effective_hint", "")
            if own_hint and own_hint != re.sub(r'\s*\(\d+\)$', '', g[0]) and own_hint in hint_to_group_idx and hint_to_group_idx[own_hint] < idx:
                reroute.append(m)
            else:
                keep.append(m)
        g[1] = keep
        for m in reroute:
            target_idx = hint_to_group_idx[m.get("_effective_hint", "")]
            logger.warning(
                f"[TOPIC group-order] stray MCQ (qsn_no={m.get('qsn_no')}) with hint "
                f"'{m.get('_effective_hint','')[:30]}' found inside '{g[0][:30]}' — "
                f"rerouted back to earlier group '{groups[target_idx][0][:30]}'"
            )
            groups[target_idx][1].append(m)
    groups = [g for g in groups if g[1]]  # drop any group emptied by reroute

    # Distinguish same-named groups (same chapter banner can legitimately
    # recur for a different qsn_no==1 restart elsewhere) by numbering them
    # in output, so the caller/CSV filenames don't collide or silently
    # overwrite each other.
    name_counts = {}
    for g in groups:
        name_counts[g[0]] = name_counts.get(g[0], 0) + 1
    seen = {}
    for g in groups:
        base = g[0]
        if name_counts[base] > 1:
            seen[base] = seen.get(base, 0) + 1
            g[0] = f"{base} ({seen[base]})"

    # CODE-LEVEL SAFETY NET: normally do NOT sort each group's MCQs by
    # qsn_no — the flat list built in Pass 1 is meant to already be in
    # correct left-column-then-right-column, page-by-page read order (per
    # the extraction prompt's segment-major rule), and that read order IS
    # the true serial. But that rule is prompt-enforced only; the model can
    # still get column interleaving wrong (e.g. old-topic's leftover right-
    # column MCQs and new-topic's left-column MCQs coming out zig-zagged
    # instead of "old topic fully, then new topic fully"). Detect that
    # per-group with a strict-ascending check restricted to each page's own
    # contiguous slice of the group (a legitimate page-boundary spillover
    # keeps its own page's run ascending even if the group as a whole
    # restarts lower after a page break — so this only fires on GENUINE
    # zig-zag/reversal within one page's contiguous run, never on ordinary
    # cross-page continuation). When triggered, sort just that page-slice by
    # qsn_no as the fallback ordering, since qsn_no is the one signal that's
    # always reliable regardless of column-reading mistakes.
    for g in groups:
        mcqs = g[1]
        # split this group's MCQs into contiguous same-page runs
        runs = []
        cur_run = []
        cur_page = object()
        for m in mcqs:
            pg = m.get("_page_key")
            if pg != cur_page and cur_run:
                runs.append(cur_run)
                cur_run = []
            cur_run.append(m)
            cur_page = pg
        if cur_run:
            runs.append(cur_run)
        rebuilt = []
        for run in runs:
            nums = [m.get("qsn_no") for m in run if isinstance(m.get("qsn_no"), int)]
            if len(nums) >= 2 and nums != sorted(nums):
                logger.warning(
                    f"[TOPIC group-order] '{g[0][:30]}' page-run qsn "
                    f"{nums[0]}-{nums[-1]} zig-zagged ({nums}) — sorting by qsn_no"
                )
                run = sorted(
                    run,
                    key=lambda m: (m.get("qsn_no") if isinstance(m.get("qsn_no"), int) else 10**9)
                )
            rebuilt.extend(run)
        g[1] = rebuilt

    # Log total MCQ count per group so under-extraction is visible.
    for name, mcqs in groups:
        logger.info(f"[TOPIC group] '{name[:40]}' — {len(mcqs)} MCQ")

    return [(name, mcqs) for name, mcqs in groups]


# ── QBM PERMANENT PROMPT MEMORY ──
# Active prompt cached in-process; persisted in Supabase (quiz_sessions,
# key="qbm_active_prompt") so it survives restarts. New page-এ গেলে DB আবার
# পড়তে হয় না — RAM cache-এ read, update হলেই DB-তে ও RAM-এ একসাথে save হয়।
_qbm_prompt_cache = {"prompt": None}

async def qbm_get_active_prompt() -> str:
    if _qbm_prompt_cache["prompt"]:
        return _qbm_prompt_cache["prompt"]
    try:
        r = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", "qbm_active_prompt").execute())
        if r.data:
            saved = json.loads(r.data[0]["data"])
            p = saved.get("prompt")
            saved_version = saved.get("version", 0)
            # If this DB row predates a code prompt update (no manual edit since),
            # auto-heal to the new default instead of silently running stale rules.
            if p and saved_version >= QBM_PROMPT_VERSION:
                _qbm_prompt_cache["prompt"] = p
                return p
            elif p:
                logger.info(f"[QBM] DB-cached prompt is stale (v{saved_version} < v{QBM_PROMPT_VERSION}) — auto-healing to new code default")
    except Exception as e:
        logger.warning(f"[QBM] prompt memory load failed: {e}")
    _qbm_prompt_cache["prompt"] = QBM_EXTRACT_PROMPT_DEFAULT
    return QBM_EXTRACT_PROMPT_DEFAULT

async def qbm_set_active_prompt(new_prompt: str, version: int = QBM_PROMPT_VERSION):
    """New prompt update এলে সেটাকে permanent করে save করে — পরের বার থেকে
    (নতুন update না আসা অবধি) এই prompt-ই সবসময় ব্যবহার হবে।"""
    _qbm_prompt_cache["prompt"] = new_prompt
    try:
        await sb_exec(lambda: sb.table("quiz_sessions").upsert({
            "key": "qbm_active_prompt",
            "data": json.dumps({"prompt": new_prompt, "version": version}),
            "updated_at": int(time.time())
        }).execute())
    except Exception as e:
        logger.warning(f"[QBM] prompt memory save failed: {e}")


def _has_mixed_digit_script(text: str) -> bool:
    """একই সংখ্যা token-এ Bengali+English digit মিশে থাকলে সেটা corruption সংকেত।"""
    if not text:
        return False
    bn_digits = set('০১২৩৪৫৬৭৮৯')
    for token in re.findall(r'[০-৯0-9]+', text):
        has_bn = any(c in bn_digits for c in token)
        has_en = any(c.isdigit() and c not in bn_digits for c in token)
        if has_bn and has_en:
            return True
    return False


# Generic phrase patterns typical of an AI-generated explanation (rather than
# text lifted verbatim from a page) -- used only as a cheap, zero-extra-API
# heuristic to catch a mistagged explanation_source="page" claim, since we
# have no independent OCR pass to truly verify the claim against.
_AI_GENERATED_PATTERNS = (
    "সঠিক উত্তর হলো", "সঠিক উত্তর হচ্ছে", "কারণ এটি", "এই কারণে",
    "correct answer is", "the correct option is",
)

def _looks_ai_generated(expl: str) -> bool:
    """Heuristic only -- flags for review, never auto-corrects, since a false
    positive here must never silently alter a legitimate page explanation."""
    if not expl:
        return True  # empty explanation tagged "page" is definitely wrong
    if len(expl) < 15:
        return True  # too short to be a real page-lifted explanation
    low = expl.lower()
    return any(p.lower() in low for p in _AI_GENERATED_PATTERNS)


def _qbm_parse_json(text: str) -> list:
    """Parse extractor JSON output -> list of {question, options[A-D], answer(A-D), explanation}"""
    if not text:
        return []
    t = text.strip()
    if "```json" in t:
        t = t.split("```json")[1].split("```")[0].strip()
    elif "```" in t:
        t = t.split("```")[1].split("```")[0].strip()
    try:
        m = re.search(r'\[.*\]', t, re.DOTALL)
        raw = json.loads(m.group()) if m else json.loads(t)
    except Exception:
        return []
    if not isinstance(raw, list):
        return []
    valid = []
    for mc in raw:
        try:
            q = mc.get("question", "")
            opts = mc.get("options", {})
            if not q or not opts:
                continue
            # Clean numbering prefix + trailing bracket artifacts
            q = re.sub(r'\s*[\[\(].*?[\]\)]\s*$', '', q)
            q = _strip_q_numbering(q)
            q = _clean_mcq_text(q)
            opts_list = [_clean_mcq_text(opts.get("A", "")), _clean_mcq_text(opts.get("B", "")),
                         _clean_mcq_text(opts.get("C", "")), _clean_mcq_text(opts.get("D", ""))]
            expl = _clean_mcq_text(mc.get("explanation", ""))
            expl_source = mc.get("explanation_source", "")
            raw_qbbox = mc.get("qsn_bbox")
            qsn_bbox = raw_qbbox if (isinstance(raw_qbbox, list) and len(raw_qbbox) == 4) else None
            if _has_mixed_digit_script(q) or any(_has_mixed_digit_script(o) for o in opts_list) or _has_mixed_digit_script(expl):
                logger.warning(f"[QBM digit-integrity] Mixed Bengali/English digits detected: {q[:60]}")
            # Cheap, zero-extra-API-cost sanity check: a "page"-tagged explanation
            # (claimed verbatim from source) that is suspiciously short or reads
            # like a generic AI-generated line is almost certainly mistagged --
            # flag it for review instead of trusting the self-report blindly.
            if expl_source == "page" and _looks_ai_generated(expl):
                logger.warning(f"[QBM explanation-tag] Suspect 'page' tag (looks generated): {q[:60]}")
            valid.append({
                "question": q.strip(),
                "options": opts_list,
                "answer": mc.get("answer", "A") if mc.get("answer") in ("A", "B", "C", "D") else "A",
                "explanation": expl,
                "qsn_bbox": qsn_bbox,
                **({"yellow_highlight": mc.get("yellow_highlight")} if "yellow_highlight" in mc else {}),
                **({"qsn_no": mc.get("qsn_no")} if "qsn_no" in mc else {}),
                **({"topic_hint": mc.get("topic_hint")} if "topic_hint" in mc else {}),
            })
        except Exception:
            continue
    return valid


async def _qbm_groq_call(img, prompt: str) -> str:
    """Raw Groq call helper — returns raw text (caller parses).
    Passes the actual prompt text as prompt_len_hint to _img_to_data_url_groq
    so Call 2/3's large, variable-size audit prompts (which embed the
    already-extracted MCQ JSON) get correctly budgeted instead of assuming
    the fixed static-prompt size -- fixes the 429 TPM errors these calls hit
    on pages with many MCQs (large embedded JSON)."""
    keys = groq_key_rotator.ordered_keys(offset=_qbm_key_offset_ctx.get())
    if not keys:
        return ""
    # If every Groq key is either daily-exhausted or currently in a TPM/
    # rate-limit cooldown, skip straight to "no result" (caller falls back
    # to Gemini) instead of live-retrying keys already known unusable right
    # now -- per Rafin's instruction: Call2 should fall back to Gemini once
    # Groq is genuinely exhausted, not after wasting a full retry cycle.
    now = time.time()
    _all_unusable = all(
        _is_groq_key_exhausted_today(k) or groq_key_rotator._cooldown_until.get(k, 0) > now
        for k in keys
    )
    if _all_unusable:
        logger.warning("[QBM] all Groq keys daily-exhausted or cooling — skipping straight to Gemini")
        return ""
    # Filter out individually-unusable keys (not just the all-unusable case
    # above) -- without this, a call with e.g. 8 of 12 keys cooling still
    # tried each of those 8 live and ate a fresh 429 for every one before
    # reaching a healthy key, adding real wall-clock delay per call even
    # though the outcome (skip to a live key) was predictable in advance.
    live_keys = [k for k in keys if not _is_groq_key_exhausted_today(k) and groq_key_rotator._cooldown_until.get(k, 0) <= now]
    if live_keys:
        keys = live_keys
    data_url = _img_to_data_url_groq(img, mcq_count_hint=10, prompt_len_hint=prompt)
    if not data_url:
        return ""
    shrunk_url = None
    shrunk_prompt = None
    for key in keys:
        if is_cancelled():
            return ""
        txt, status = await _post_openai_compat(
            "https://api.groq.com/openai/v1/chat/completions",
            key, "qwen/qwen3.6-27b",
            data_url, prompt, mcq_count_hint=10
        )
        if txt:
            return txt
        if status == 413:
            if shrunk_url is None:
                # prompt itself (embedded MCQ JSON) can be the actual overflow
                # cause on pages with many MCQs -- truncate it harder (2000
                # not 3000 chars) and use a smaller mcq_count_hint (3 not 5)
                # since the original 3000/5 combo still 413'd in practice.
                shrunk_prompt = prompt if len(prompt) < 2000 else prompt[:2000] + "\n...(truncated)"
                shrunk_url = _img_to_data_url_groq(img, mcq_count_hint=3, prompt_len_hint=shrunk_prompt)
            if shrunk_url:
                txt2, status2 = await _post_openai_compat(
                    "https://api.groq.com/openai/v1/chat/completions",
                    key, "qwen/qwen3.6-27b",
                    shrunk_url, shrunk_prompt, mcq_count_hint=3
                )
                if txt2:
                    return txt2
                logger.warning(f"[Groq-QBM] key failed even after shrink (status={status2}), trying next key")
                if status2 == 429:
                    groq_key_rotator.mark_rate_limited(key, daily_exhausted=(_key_429_is_tpm.get(key) is not True))
                continue
        if status == 429:
            groq_key_rotator.mark_rate_limited(key, daily_exhausted=(_key_429_is_tpm.get(key) is not True))
        elif status != 429:
            logger.warning(f"[Groq-QBM] key failed (status={status}), trying next key")
    return ""


_OPENROUTER_VISION_MODELS = [
    "google/gemma-4-31b-it:free",
    "google/gemma-4-26b-a4b-it:free",
    "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free",
]


async def _qbm_openrouter_call(img, prompt: str) -> str:
    """Third-tier QBM fallback -- OpenRouter (free vision-capable models,
    tried in order -- OpenRouter's free-model lineup rotates/gets delisted
    every few weeks, so this list needs occasional refreshing) with the
    same strict extraction prompt used for Gemini/Groq. Only reached when both
    Gemini (all keys) and Groq (all keys) are exhausted/rate-limited, so pages
    keep flowing instead of stalling on quota errors."""
    data_url = _img_to_data_url(img)
    if not data_url:
        return ""
    rotator = or_qwen_rotator
    keys = rotator.ordered_keys() if rotator else []
    if not keys:
        return ""
    for model in _OPENROUTER_VISION_MODELS:
        for key in keys:
            if is_cancelled():
                return ""
            try:
                headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
                payload = {
                    "model": model,
                    "messages": [{
                        "role": "user",
                        "content": [
                            {"type": "text", "text": prompt},
                            {"type": "image_url", "image_url": {"url": data_url}}
                        ]
                    }],
                    "temperature": 0.1,
                    "max_tokens": 3000,
                }
                async with httpx.AsyncClient(timeout=45) as c:
                    r = await c.post("https://openrouter.ai/api/v1/chat/completions", headers=headers, json=payload)
                    if r.status_code >= 400:
                        if r.status_code == 429:
                            rotator.mark_rate_limited(key)
                        else:
                            logger.warning(f"[QBM-OpenRouter] {model} HTTP {r.status_code}")
                        continue
                    j = r.json()
                    rotator.mark_healthy(key)
                    content = j.get("choices", [{}])[0].get("message", {}).get("content", "") or ""
                    if content:
                        return content
            except Exception as e:
                logger.warning(f"[QBM-OpenRouter] {model} err: {e}")
                continue
    return ""


async def _qbm_call1_extract(img) -> list:
    """
    CALL 1 — OWN OCR + strict-prompt MCQ extraction + inline dedup.
    Job: extract every existing MCQ on the page (option-serial strictly
    preserved per active prompt), while checking-as-it-goes so no duplicate
    /ghost MCQ enters the list. Gemini primary (better raw extraction
    quality for the initial make) -> Groq fallback (higher daily budget,
    used if Gemini quota is exhausted) -> OpenRouter last resort.
    """
    try:
        prompt = await qbm_get_active_prompt()
        gem = await _qbm_gemini_extract(img, prompt)
        if gem:
            logger.info(f"[QBM Call1] Gemini succeeded, {len(gem)} MCQ")
            out = _qbm_dedup_list(gem)
            for m in out:
                m["_provider"] = "Gemini"
                m["_call1_provider"] = "Gemini"
            return out
        logger.warning("[QBM Call1] Gemini returned empty/failed -> falling back to Groq for Call1")
        txt = await _qbm_groq_call(img, prompt)
        result = _qbm_parse_json(txt) if txt else []
        if result:
            out = _qbm_dedup_list(result)
            for m in out:
                m["_provider"] = "Groq"
                m["_call1_provider"] = "Groq"
            return out
        txt3 = await _qbm_openrouter_call(img, prompt)
        result3 = _qbm_parse_json(txt3) if txt3 else []
        out = _qbm_dedup_list(result3)
        for m in out:
            m["_provider"] = "OpenRouter"
            m["_call1_provider"] = "OpenRouter"
        return out
    except Exception as e:
        logger.warning(f"[QBM Call1] failed: {e}")
        return []


async def _qbm_lightweight_miss_check(img, call1_mcqs: list) -> list:
    """
    Dedicated MISS-CHECK ONLY call -- lightweight by design. Job is ONLY:
    scan the full page image once, compare against the full existing MCQ
    list (all of it, not chunked -- miss-check needs the complete picture to
    know what's already found), and return ONLY the small number of MISSED
    MCQs (if any). No spelling/answer-source/completeness/column-order
    verification here -- that's Step B's job, done separately per-chunk on
    the (Call1 + these newly-found) combined list. Splitting it out this way
    means: (a) miss-check runs exactly ONCE per page instead of once per
    verify-chunk, (b) its output is small (usually 0, rarely 1-5 new MCQs)
    instead of re-emitting the whole list, so this call stays cheap even on
    dense pages. Returns [] if nothing was missed (the common case).
    """
    if not call1_mcqs:
        return []
    try:
        # Only question text needed here (just enough for the model to know
        # what's already found) -- options/answer/explanation add nothing to
        # a miss-check decision and would only bloat this call for no reason.
        existing_qs = json.dumps(
            [(m.get("question", "") or "")[:150] for m in call1_mcqs],
            ensure_ascii=False
        )
        prompt = f"""You already extracted these MCQ questions from this exact page image:
{existing_qs}

TASK — MISS-CHECK ONLY (do not verify/correct the ones above, that happens separately):
1) Look at the ENTIRE page image now and mentally divide it into regions (top/middle/bottom,
   left/right if multi-column) — scan EACH region for any MCQ block (question + options) that
   exists on the page.
2) For every MCQ block you find, check: is its question already present in the list above (same
   or very similar question)? If NOT present, it was MISSED.
3) Pay special attention to the LAST MCQ on the page and the BOTTOM of the page — most commonly
   missed — but this is in ADDITION to the full scan above, not instead of it.
4) If NOTHING was missed (the common case), output an empty array: []
5) If MCQs were missed, output ONLY those missed MCQs (do not repeat the ones already in the
   list above) in the same strict format: options in the exact source position order, A/B/C/D
   slots by position (never relabeled/sorted); if a missed MCQ belongs under a passage/উদ্দীপক,
   prepend that passage's full text to its question (self-contained).

OUTPUT — ONLY a valid JSON array of the MISSED MCQs (empty array if none), nothing else:
[{{"question":"...","options":{{"A":"...","B":"...","C":"...","D":"..."}},"answer":"A/B/C/D","explanation":"...","explanation_source":"page/generated"}}]"""

        # Gemini-primary miss-check (Call2 verify is now Gemini-primary too,
        # so it already re-scans the full page -- no need to double-spend a
        # Gemini call here on top of it). Groq fallback only if Gemini fails
        # or returns nothing.
        gem_txt = await _qbm_gemini_raw(img, prompt)
        result = _qbm_parse_json(gem_txt) if gem_txt else []
        if not result:
            txt = await _qbm_groq_call(img, prompt)
            result = _qbm_parse_json(txt) if txt else []
        if not result:
            or_txt = await _qbm_openrouter_call(img, prompt)
            result = _qbm_parse_json(or_txt) if or_txt else []
        return result or []
    except Exception as e:
        logger.warning(f"[QBM Miss-Check] failed: {e}")
        return []


async def _qbm_call2_miss_check(img, call1_mcqs: list) -> list:
    """
    CALL 2 (dispatcher) — miss-check (ONE lightweight call, always against
    the FULL list regardless of page density) followed by full verification
    (chunked into <=16 MCQs per call ONLY when Groq has at least one usable
    key right now -- chunking exists purely to keep each Groq verify call
    inside its 8000 TPM ceiling). If Groq has zero usable keys (all
    daily-exhausted or cooling), every chunk would fail Groq instantly and
    fall through to Gemini anyway -- since Gemini has no comparable tight
    per-call ceiling, chunking in that case only adds overhead (re-sending
    the whole page image once per chunk for no reason), so the whole MCQ
    list is sent in ONE unchunked verify call straight to Gemini-first
    instead. Miss-check is now genuinely lightweight (small output, one
    call total) rather than a heavy Step-A-per-chunk pass -- verify chunks
    only do Step B (no miss-check text at all), keeping their prompts
    smaller too.
    """
    if not call1_mcqs:
        return []
    missed = await _qbm_lightweight_miss_check(img, call1_mcqs)
    for m in (missed or []):
        m.setdefault("_call1_provider", "MissCheck")
    combined = call1_mcqs + (missed or [])

    # Gemini is now Call2's primary provider (no tight per-call TPM ceiling
    # like Groq's 8000 TPM, which is what chunking existed to protect) --
    # always send the full page in ONE unchunked verify call. do_miss_check=
    # True here too (on top of the dedicated lightweight miss-check above) --
    # a second independent miss-scan inside the SAME call that also does
    # full verification, so any MCQ the lightweight pass missed still has
    # one more chance to be caught before this page's result is final.
    return await _qbm_call2_single(img, combined, do_miss_check=True)


async def _qbm_call2_single(img, call1_mcqs: list, do_miss_check: bool = True) -> list:
    """
    CALL 2 (single chunk) — MERGED miss-check + full verification (single call,
    no separate Call 3). Job:
    1) MISS-CHECK (only if do_miss_check=True): confirm Call-1 caught every
       existing MCQ on the page (checked region-by-region, especially the last
       MCQ / bottom of page); add any missed ones in the same strict format.
    2) FULL VERIFY on the combined list: option-serial integrity, answer
       matches what's actually marked/given on the source page (scanning other
       pages for an answer key if needed), spelling/context-word correctness
       (Bangla/English), completeness (no truncated words), column-order,
       উদ্দীপক self-containment, diagram bbox, and explanation_source tagging.
    Gemini primary (full-page single call, no chunking) -> Groq fallback ->
    OpenRouter last resort, only if Gemini fails.
    """
    if not call1_mcqs:
        call1_mcqs = []
    try:
        # Gemini is primary here (no tight per-call TPM ceiling like Groq's
        # 8000), so these caps only need to guard the Groq/OpenRouter
        # fallback path -- relaxed well above the old Groq-tuned values to
        # avoid losing question/option detail on Gemini's primary pass.
        _n = len(call1_mcqs) or 1
        _q_cap = 400 if _n <= 5 else (320 if _n <= 10 else (240 if _n <= 16 else 180))
        _opt_cap = 160 if _n <= 5 else (130 if _n <= 10 else (100 if _n <= 16 else 80))
        def _trim_opts(opts):
            if isinstance(opts, dict):
                return {k: (v or "")[:_opt_cap] for k, v in opts.items()}
            if isinstance(opts, list):
                return [(v or "")[:_opt_cap] for v in opts]
            return opts
        mcq_json = json.dumps([
            {"question": (m.get("question", "") or "")[:_q_cap], "options": _trim_opts(m.get("options", [])),
             "answer": m.get("answer", "A"), "explanation": (m.get("explanation", "") or "")[:60],
             "qsn_bbox": m.get("qsn_bbox")}
            for m in call1_mcqs
        ], ensure_ascii=False)

        step_a_text = """STEP A — MISS-CHECK (mandatory, full-image scan every time):
1) Look at the ENTIRE page image now, independent of the list below — mentally divide it into
   regions (top/middle/bottom, left/right if multi-column) and scan EACH region for any MCQ
   block that exists on the page. Do NOT limit your scan to areas "near" the MCQs already in the
   list — a page can have missed MCQs anywhere, including entirely separate regions the list
   below doesn't cover at all (this list is only PART of the page's MCQs when the page has more
   MCQs than fit in one verification chunk).
2) For every MCQ block you find on the page, check: is it already present in the list below
   (same question)? If NOT present, it was MISSED — add it in the SAME strict format (options in
   the exact source position order, A/B/C/D slots by position — never relabeled/sorted). If it
   belongs under a passage/উদ্দীপক, prepend that passage's full text to its question
   (self-contained), same as Call 1's rule.
3) Pay special attention to the LAST MCQ on the page and the BOTTOM of the page — most commonly
   missed — but this is in ADDITION to the full scan above, not instead of it.

""" if do_miss_check else ""
        task_line = ("do BOTH steps below in this single pass" if do_miss_check
                     else "do STEP B below only (miss-check was already done separately -- "
                          "this list is final, just verify/correct it)")
        prompt = f"""You already extracted these MCQs from this exact page image (Call 1 result):
{mcq_json if call1_mcqs else "(none found)"}

TASK — {task_line}, connected to Call 1 (do not redo
full extraction from scratch):

{step_a_text}STEP B — FULL VERIFICATION on this MCQ list — never
skip or shortcut this, regardless of how confident Call 1 was. NOTE: each MCQ's "question",
"options", and "explanation" fields above are truncated to save space (just enough to identify
which MCQ is which) — always re-read the FULL text from the actual page image and output the
complete, untruncated, corrected question/options/explanation in your response:
1) OPTION-SERIAL INTEGRITY: is the answer letter (A/B/C/D) pointing to the option that is
   actually in that position in THIS output list (not the source's original label)? If the
   correct option's text sits in position 2 of the output, answer must be "B", etc. Fix any
   mismatch.
2) ANSWER SOURCE MATCH: does the answer actually match what is marked/given on the page
   (marked option, inline answer, bottom-of-page answer box/table, or answer key found on
   another page — scan forward/backward through all pages as needed)? Fix if wrong.
3) If an MCQ's answer is genuinely unclear from any source → try twice, reasoning it out from
   context, to determine the most likely correct answer. If STILL unclear after 2 tries, choose
   your own best answer, and base the explanation on that chosen answer.
4) SPELLING + CONTEXT-WORD CHECK: check question + all options + explanation for (a) spelling
   mistakes (Bangla or English), and (b) any word that is spelled fine but is CONTEXTUALLY WRONG
   for this MCQ's subject/topic (e.g. an OCR/extraction slip that swapped in a similar-looking but
   unrelated term that doesn't fit the science/subject context) — replace it with the word that
   actually fits the MCQ's context and meaning, cross-checked against the source image. Never
   change a word that is already correct and contextually fitting, even if unusual.
5) COMPLETENESS CHECK: re-read the full question and every option word-by-word against the
   image — fix any truncated/partial word or sentence (e.g. a word cut to only its tail).
6) Re-confirm option order was never reshuffled and math/chemistry sub/superscripts (H₂O, x²,
   Na⁺ etc.) are correctly rendered everywhere.
6c) LATEX CHECK: scan question/options/explanation for any raw LaTeX left over from extraction
   (backslash-vec, backslash-hat, backslash-frac, backslash-sqrt, caret, underscore, curly braces
   used as LaTeX syntax) — convert every one to proper Unicode
   (vectors: A⃗, î, ĵ, k̂; fractions: a/b; roots: √x; sub/superscripts as actual Unicode chars).
   Only leave LaTeX if that ONE specific expression is genuinely impossible to represent clearly
   in Unicode/plain text (rare — e.g. a multi-line matrix) — never leave LaTeX out of laziness.
6b) COLUMN-ORDER CHECK: if the source page has multiple columns, confirm the MCQ list follows
   COLUMN-MAJOR order (entire left column top-to-bottom, then next column top-to-bottom) — never
   zigzag/interleave between columns. Re-order the list if columns got mixed.
7) UDDIPOK CHECK: for any MCQ that depends on a passage/উদ্দীপক, confirm its full passage text
   is prepended to the question (self-contained), and that ONLY the specific navigation sentence
   naming which question numbers to answer (e.g. "উদ্দীপকের আলোকে NN ও NN নং প্রশ্নের উত্তর দাও")
   is removed — never strip a real question just because it mentions "উদ্দীপক" (e.g. "উদ্দীপকে
   প্রদর্শিত প্রক্রিয়াটি কোন উপদশায় ঘটে?" is a genuine question and must stay in full).
8) QUESTION-DIAGRAM CHECK: if this MCQ's question genuinely has a diagram/figure/chart in the
   source image needed to understand/answer it, confirm "qsn_bbox" is present and FULLY contains
   the entire diagram (all labels/arrows/edges, small margin included — never a partial/cut-off
   crop) on a 0-1000 scale. Add or widen qsn_bbox if the diagram was missed or cut off. SPECIAL
   CHECK: if the question text contains a bare figure caption/label like "চিত্র: G", "চিত্র-১",
   "Figure 1" with no qsn_bbox — that caption is proof a diagram exists nearby; you MUST add
   qsn_bbox covering that actual diagram (never leave just the caption text uncropped). If
   qsn_bbox was given but the question has NO actual diagram, remove it (set to null). Never
   invent a bbox for options — options never get any bbox/image.
9) EXPLANATION SOURCE TAG (mandatory, new field): for each MCQ, add "explanation_source" as
   either "page" (the explanation is copied verbatim from text physically present on the page,
   e.g. a written ব্যাখ্যা/answer-reasoning block) or "generated" (no such text exists on the
   page, so the explanation was built from AI knowledge). Be honest and precise about this —
   it is used for quality auditing, not shown to end users.
10) EXPLANATION LENGTH (mandatory) — this MUST fit Telegram's poll-explanation box, hard cap
   ~265 characters. If explanation_source="page" (text is physically on the page): use it as-is
   if it already fits within ~265 characters; if the on-page text is longer than that, trim it
   down to the most essential 2-3 sentences (still page-sourced, just condensed) rather than
   discarding it for a generated one. If explanation_source="generated" (nothing on the page):
   write a fresh 2-3 sentence explanation (why the answer is correct + one relevant fact) that
   stays within ~265 characters — never a single one-line answer restatement, never a wall of
   text past the limit.

CRITICAL: OUTPUT LIST ORDER (mandatory) — never move an MCQ to the end or anywhere else just
because it needed a fix — fix it in place, at its original index.

Output ONLY the full corrected JSON array, all fixes applied, same length/order as input:
[{{"question":"...","options":{{"A":"...","B":"...","C":"...","D":"..."}},"answer":"A/B/C/D","explanation":"...","explanation_source":"page/generated","qsn_bbox":[100,200,400,450]}}]"""

        gem_txt = await _qbm_gemini_raw(img, prompt)
        result = _qbm_parse_json(gem_txt) if gem_txt else []
        call2_provider = "Gemini"
        if not result:
            txt = await _qbm_groq_call(img, prompt)
            result = _qbm_parse_json(txt) if txt else []
            call2_provider = "Groq"
        if not result:
            or_txt = await _qbm_openrouter_call(img, prompt)
            result = _qbm_parse_json(or_txt) if or_txt else []
            call2_provider = "OpenRouter"

        if result and len(result) >= len(call1_mcqs) * 0.8:
            deduped = _qbm_dedup_list(result)
            # sanity: if dedup collapsed it down close to (or below) the pre-check
            # count, trust the deduped version; if dedup removed almost everything
            # (parsing weirdness), fall back to the pre-check list instead.
            if deduped and len(deduped) >= len(call1_mcqs) * 0.8:
                # Match each verified MCQ back to its Call1 counterpart (by
                # question text) so we can carry forward which provider did
                # the ORIGINAL extraction, separate from _provider which now
                # reflects Call2's verification pass -- lets the status line
                # show both stages distinctly instead of Call2 silently
                # overwriting Call1's Gemini/Groq attribution.
                _c1_by_q = {(_c.get("question") or "").strip()[:80]: _c.get("_call1_provider", "?") for _c in call1_mcqs}
                _same_len = len(deduped) == len(call1_mcqs)
                for _idx, m in enumerate(deduped):
                    m["_call2_provider"] = call2_provider
                    # Call2/Groq often rewrites the question text (fixing typos,
                    # de-truncating) so the truncated-text match below can miss --
                    # when the list length didn't change (common case, no
                    # miss-check additions/removals), fall back to positional
                    # match first since order is preserved through this point.
                    _matched = _c1_by_q.get((m.get("question") or "").strip()[:80])
                    if _matched is None and _same_len:
                        _matched = call1_mcqs[_idx].get("_call1_provider")
                    m["_call1_provider"] = _matched or m.get("_call1_provider", "?")
                    m["_provider"] = call2_provider
                    # Defensive code-level cap -- prompt asks for ~265 chars
                    # but never trust model output blindly; hard-truncate so
                    # a page-sourced explanation that ran long never breaks
                    # Telegram's poll-explanation box limit downstream.
                    if m.get("explanation") and len(m["explanation"]) > 265:
                        m["explanation"] = m["explanation"][:265].rstrip()

                # NEVER-LOSE-AN-MCQ BACKFILL: even after passing the 80% floor,
                # verify can still drop a handful of individual MCQs (Gemini
                # skips/merges one while fixing others) with nothing catching
                # it -- the 80% check only guards against MASS loss, not a few
                # silently missing items. Explicitly diff deduped against
                # call1_mcqs by normalized question text and re-append any
                # call1/miss-check MCQ that has NO match in verify's output,
                # so a partial verify degradation can never make a real MCQ
                # disappear from the final result.
                _deduped_norm_qs = {_qbm_normalize_q(m.get("question", "")) for m in deduped}
                _backfilled = list(deduped)
                for _c1 in call1_mcqs:
                    _c1_norm = _qbm_normalize_q(_c1.get("question", ""))
                    if _c1_norm and not _qbm_is_duplicate(_c1_norm, list(_deduped_norm_qs)):
                        _c1.setdefault("_call2_provider", "backfill-call1")
                        _c1.setdefault("_provider", _c1.get("_call1_provider", "?"))
                        _backfilled.append(_c1)
                        _deduped_norm_qs.add(_c1_norm)
                return _cap_mcq_options(_backfilled)
            return _cap_mcq_options(call1_mcqs)
        return call1_mcqs  # call2 failed/degraded -> keep Call1 result, never lose data
    except Exception as e:
        logger.warning(f"[QBM Call2] failed: {e}")
        return call1_mcqs


async def _qbm_final_empty_page_scan(img, onu_mode: bool = False) -> list:
    """
    CALL 3 (empty-page variant) — used ONLY when Call 1 AND Call 2 BOTH
    returned zero MCQs. Two independent empty results is a strong signal but
    not proof (both calls could share the same blind spot, e.g. faint text,
    an MCQ tucked in a corner/footnote, or an OCR gap). This does one final,
    independent, fresh-eyes scan of the raw page image before the pipeline is
    allowed to confirm "this page truly has 0 MCQ".
    Strong combination rule: only when ALL THREE calls (1, 2, and this final
    scan) agree on zero is the page marked confirmed-empty.

    onu_mode=True adds the yellow_highlight field to the prompt/output --
    without this, /onu calling into this fallback path would recover MCQs
    with NO highlight info at all (field defaults to False for every MCQ,
    silently discarding real highlighted questions whenever Call 1 was
    empty/failed, e.g. Gemini quota exhausted).
    """
    try:
        prompt = """Two prior independent passes over this exact page image both concluded
there is NO existing MCQ (multiple-choice question) on this page.

TASK: Do one final, completely fresh scan of the page, ignoring the prior
passes' conclusion. Look carefully at every part of the page including
footnotes, page corners/margins, faint or small text, and any question that
might be split across a passage/উদ্দীপক.

If you find even ONE existing MCQ that was missed, extract it in the strict
format below (options in exact source position order, A/B/C/D by position —
never relabeled/sorted). If it depends on a passage/উদ্দীপক, prepend that
passage's full text to the question (self-contained).

If the page genuinely has no MCQ at all, output exactly: []

Output ONLY a JSON array:
[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"..."}]"""
        if onu_mode:
            prompt += """

ADDITIONALLY, for EVERY extracted MCQ, check if a YELLOW HIGHLIGHTER color
band is visible behind the question line and/or its A/B/C/D options (some
MCQs on the page are highlighted, some are not -- check each independently).
Add "yellow_highlight": true if yellow highlighter color is present in that
MCQ's block, or "yellow_highlight": false if not. Update the output format:
[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","explanation":"...","yellow_highlight":true}]"""
        if onu_mode:
            # onu_mode-e age theke Groq fallback chilo na (highlight-detection
            # accuracy-r jonno Gemini-only rakha hoyeche), tai order same rakhlam
            gem_txt = await _qbm_gemini_raw(img, prompt)
            found = _qbm_parse_json(gem_txt) if gem_txt else []
            provider = "Gemini"
        else:
            txt = await _qbm_groq_call(img, prompt)
            found = _qbm_parse_json(txt) if txt else []
            provider = "Groq"
            if not found:
                gem_txt = await _qbm_gemini_raw(img, prompt)
                found = _qbm_parse_json(gem_txt) if gem_txt else []
                provider = "Gemini"
        if not found:
            txt3 = await _qbm_openrouter_call(img, prompt)
            found = _qbm_parse_json(txt3) if txt3 else []
            provider = "OpenRouter"
        out = _qbm_dedup_list(found) if found else []
        for m in out:
            m.setdefault("_provider", provider)
        return out
    except Exception as e:
        logger.warning(f"[QBM Call3-empty] failed: {e}")
        return []



def _qbm_normalize_q(question: str) -> str:
    """Whitespace/punctuation normalize করে দুইটা pass-এর একই MCQ-কে duplicate ধরার জন্য."""
    q = re.sub(r'\s+', ' ', (question or '').strip().lower())
    q = re.sub(r'[^\w\u0980-\u09FF ]+', '', q)
    return q


def _qbm_is_duplicate(norm_q: str, existing_keys: list, threshold: float = 0.93) -> bool:
    """Exact match না থাকলেও near-identical প্রশ্ন (একই MCQ দুইবার extract হলে, শুধু
    সামান্য spelling/space difference) কে duplicate হিসেবে ধরার জন্য fuzzy match।
    Threshold রাখা হয়েছে খুব high (0.93) এবং substring-containment rule সরিয়ে
    ফেলা হয়েছে -- আগের 0.85 + 70%-substring rule ভিন্ন ভিন্ন MCQ-কে (একই subject/
    chapter-এর কারণে similar wording বা length থাকলে) ভুলবশত duplicate ধরে ফেলে
    দিচ্ছিল, real MCQ silently miss হওয়ার একটা কারণ ছিল এটা।"""
    if not norm_q:
        return True
    if norm_q in existing_keys:
        return True
    for k in existing_keys:
        if not k:
            continue
        if difflib.SequenceMatcher(None, norm_q, k).ratio() >= threshold:
            return True
    return False


def _qbm_dedup_list(mcqs: list) -> list:
    """Fuzzy-dedup a list in place order, dropping duplicate/ghost MCQs."""
    seen_keys: list = []
    out = []
    for mc in mcqs:
        key_q = _qbm_normalize_q(mc.get("question", ""))
        if not key_q:
            continue
        if not _qbm_is_duplicate(key_q, seen_keys):
            seen_keys.append(key_q)
            out.append(mc)
    return out


# v-RAM-fix: caps how many pages (across ALL users) run the 3-call extraction
# pipeline at once. Each in-flight page holds a decoded PIL image + growing
# MCQ list in RAM; on a 512MB free instance, many users uploading at the same
# time without this cap could still spike RAM even with the PDF-convert lock
# (that lock only guards the pdf2image step, not the extraction step after).
# v-RAM-fix: dynamic RAM-aware gate instead of a fixed slot count. Each
# in-flight page holds a decoded image + growing MCQ list; under heavy
# concurrent load (many users at once) a FIXED cap either wastes headroom
# (too low) or risks OOM (too high). This checks live RSS before admitting
# a new page into the pipeline -- lets many run in parallel while RAM is
# free, throttles automatically as it fills, protecting against a 100-user
# spike without hardcoding a number that's wrong for either extreme.
_QBM_EXTRACT_HARD_CAP = asyncio.Semaphore(150)  # was 20 on 512MB Render; raised for 16GB HF Space
_qbm_ram_gate_lock = asyncio.Lock()

async def _qbm_ram_aware_acquire():
    """Blocks until (a) a hard-cap slot is free AND (b) live RSS has headroom."""
    await _QBM_EXTRACT_HARD_CAP.acquire()
    try:
        import psutil
        proc = psutil.Process(os.getpid())
        limit_mb = 14000  # 16GB instance ceiling, matches _ram_guard_task
        safe_ceiling_mb = int(limit_mb * 0.75)  # leave margin under the 85% RAMGuard threshold
        while True:
            rss_mb = proc.memory_info().rss / (1024 * 1024)
            if rss_mb < safe_ceiling_mb:
                return
            await asyncio.sleep(0.5)
    except ImportError:
        return  # psutil unavailable -> fall back to hard cap only


# /qbm-ONLY page-level MCQ cache: keyed by (pdf_content_hash, page_num), so
# re-running /qbm on the identical PDF+page skips Call1 (re-extraction) and
# goes straight to Call2 (full verify), instead of paying for the extraction
# call again. Call2 still runs in full -- cached MCQs are NEVER trusted
# blindly, they're re-checked exactly like a fresh Call1 result would be,
# catching anything that changed (prompt updates, a bad prior extraction).
# Deliberately NOT wired into /onu or /pdf -- only handle_qbm populates/reads
# this, per instruction that this caching is /qbm-specific.
_QBM_MCQ_CACHE_MAX = 300
_qbm_mcq_result_cache = {}  # (content_hash, page_num) -> list[mcq dict] (post-Call1, pre-Call2)
# /topic and /unmesh use their OWN separate Call1 caches -- NOT shared with
# /qbm's cache above, since each extractor's prompt asks for different
# fields (qsn_no/topic_hint) and a shared cache would silently return the
# wrong-shaped result across commands.
_topic_mcq_result_cache = {}  # (content_hash, page_num) -> list[mcq dict]
_unmesh_mcq_result_cache = {}  # (content_hash, page_num) -> list[mcq dict]

def _qbm_page_content_hash(img) -> str:
    """Hash the actual rendered page image bytes (not file_id) so the QBM
    per-page MCQ cache hits correctly regardless of Telegram file_id changing
    across re-uploads/forwards of the identical PDF -- file_id is NOT stable
    content identity, only the pixels are. Short hex digest is enough since
    this only needs to distinguish pages within the small in-memory cache."""
    buf = BytesIO()
    img.save(buf, format="JPEG", quality=85)
    return hashlib.sha256(buf.getvalue()).hexdigest()[:24]


def _cap_qbm_mcq_cache(cache_dict: dict = None):
    d = cache_dict if cache_dict is not None else _qbm_mcq_result_cache
    while len(d) > _QBM_MCQ_CACHE_MAX:
        d.pop(next(iter(d)), None)


async def _qbm_extract_from_image(img, cache_key: tuple = None) -> list:
    """
    2-STAGE CONNECTED PIPELINE (per page) — Call1 extract + Call2 (which
    itself makes 2 sub-calls: miss-check, then verify), so up to 3 Gemini
    requests/page total when all 3 land on Gemini (Groq/OpenRouter fallback
    only if a given sub-call's Gemini attempt fails):

    Call 1 (extract): own-OCR + strict prompt MCQ extraction (question,
        options in exact source serial, answer, explanation, qsn_bbox for
        any question-diagram). SKIPPED on a cache hit (cache_key given and
        found) -- the cached list is used as Call1's output directly.
    Call 2 (miss-check + verify): finds any MCQ Call 1 missed, then runs
        a full re-check pass against the page image — option-serial
        integrity, answer-source match, spelling/completeness, uddipok
        prepending, and qsn_bbox correctness (adds if missed, removes if
        falsely present). Never fabricates new questions. ALWAYS runs in
        full, even on a cache hit -- a cached Call1 result is never trusted
        without this real re-check pass.

    ZERO-SKIP GUARANTEE: a 0-MCQ result from Call 1 is NEVER trusted outright
    — it's indistinguishable from a technical failure (image encode issue,
    Gemini/Groq call errored) which would silently look identical to "page
    genuinely has no MCQ". So one independent final-scan call is run before
    confirming empty, and the whole pipeline retries up to 2 more times (3
    total attempts) before a page is ever confirmed empty.
    """
    await _qbm_ram_aware_acquire()
    try:
        for _pipeline_attempt in range(3):
            cached_call1 = _qbm_mcq_result_cache.get(cache_key) if cache_key else None
            if cached_call1:
                logger.info(f"[QBM MCQ Cache] hit for {cache_key} — skipping Call1, still running full Call2 verify")
                call1 = cached_call1
            else:
                call1 = await _qbm_call1_extract(img)
                if call1 and cache_key:
                    _qbm_mcq_result_cache[cache_key] = call1
                    _cap_qbm_mcq_cache()

            if not call1:
                # ZERO-SKIP GUARANTEE: a single empty Call 1 could be a technical
                # failure (image encode issue, API error) rather than a genuinely
                # empty page -- run one independent final scan before confirming.
                final_check = await _qbm_final_empty_page_scan(img)
                if not final_check:
                    if _pipeline_attempt < 2:
                        logger.warning(f"[QBM] Call1+final-scan both empty on attempt {_pipeline_attempt+1}/3 — retrying full pipeline before confirming empty page")
                        continue
                    return []  # both independent passes agree: genuinely no MCQ
                verified = await _qbm_call2_miss_check(img, final_check)
                verified = _qbm_repair_order(final_check, verified)
                recovered_mcqs = _cap_mcq_options(_qbm_restore_opt_bboxes(final_check, verified))
                return await _qbm_final_safety_net(img, recovered_mcqs)

            call2 = await _qbm_call2_miss_check(img, call1)
            call2 = _qbm_repair_order(call1, call2)
            call2 = _qbm_restore_opt_bboxes(call1, call2)
            final_mcqs = _cap_mcq_options(call2)
            return await _qbm_final_safety_net(img, final_mcqs)
        return []
    finally:
        _QBM_EXTRACT_HARD_CAP.release()


def _qbm_question_looks_truncated(q: str, opts: list) -> bool:
    """Cheap heuristic (no extra API cost) to catch obviously truncated/garbage
    questions that slipped past the prompt/verify calls -- e.g. a lone word
    fragment with no terminal punctuation and far too short vs its options."""
    if not q:
        return True
    qs = q.strip()
    ends_ok = qs.endswith(("?", "।", ":", "-", ")", "”", '"'))
    word_count = len(qs.split())
    # A real MCQ question is almost never a single short word with no
    # question mark/দাঁড়ি and shorter than its own options.
    max_opt_len = max((len(o.strip()) for o in opts if o), default=0)
    if not ends_ok and word_count <= 2 and len(qs) < max(max_opt_len, 12):
        return True
    return False


async def _qbm_reextract_truncated_question_groq_only(img, q: str, opts: list) -> str:
    """
    Targeted re-read: when a question looks truncated, ask Groq (cheap, no
    Gemini-key drain) to look ONLY at the question-stem region of this exact
    page image and report the REAL text — this is still EXTRACTION (reading
    what's actually printed), never invention of new wording. If Groq can't
    recover it, caller queues it for ONE combined page-level Gemini call
    (_qbm_batch_backfill_gemini) instead of spending a Gemini call per MCQ.
    """
    opts_str = ", ".join(o.strip() for o in opts if o and o.strip())
    prompt = f"""This MCQ's question text was cut off during OCR, only this fragment survived: "{q}"
Its 4 options are: {opts_str}

Look CAREFULLY at this exact page image and find the FULL original question
as actually printed — read the complete line/sentence around/above these
options (it is very often phrased as a question ending in ? or কী/কোনটি/কত,
e.g. "{q}-এর পূর্ণরূপ কী?" or "নিচের কোনটি {q}?" IF AND ONLY IF that exact
phrasing is what's printed on the page). Read the real printed text — do not
invent new wording that isn't on the page.
Output ONLY the complete question text as plain text (Bangla/English exactly
as printed, no JSON, no quotes, no extra commentary). If you genuinely cannot
locate any question text on this page at all, output exactly: NOT_FOUND"""
    for _attempt in range(2):
        try:
            txt = (await _qbm_groq_call(img, prompt)).strip()
            if txt and txt != "NOT_FOUND" and len(txt) > len(q.strip()):
                return txt
        except Exception as e:
            logger.warning(f"[QBM] Truncated-question re-extract (groq attempt {_attempt+1}) failed: {e}")
    return ""


def _qbm_reconstruct_question_from_options(q: str, opts: list) -> str:
    """
    Fallback ONLY when the targeted image re-read (_qbm_reextract_truncated_question)
    could not recover the real text. NEVER fabricates a new question — if the
    actual source text can't be recovered, ships the original fragment as-is
    (never a made-up generic filler question), so nothing invented ever reaches
    the user.
    """
    qs = q.strip()
    return qs if qs else "(প্রশ্নের অংশ অস্পষ্ট — মূল পাতায় যাচাই করুন)"


def _qbm_option_looks_truncated(o: str, sibling_opts: list) -> bool:
    """Cheap heuristic: an option that is empty, a single stray character, or
    far shorter than its sibling options (while others are substantial) is
    almost certainly truncated/cut-off rather than genuinely a short answer."""
    os_ = (o or "").strip()
    siblings = [s.strip() for s in sibling_opts if s and s.strip() and s.strip() != os_]
    if not os_:
        return True
    if len(os_) <= 1 and any(len(s) >= 3 for s in siblings):
        return True
    avg_sibling_len = (sum(len(s) for s in siblings) / len(siblings)) if siblings else 0
    if avg_sibling_len >= 4 and len(os_) < avg_sibling_len * 0.3:
        return True
    return False


def _qbm_reconstruct_option_from_siblings(opts: list, idx: int) -> str:
    """
    PURE CODE-LEVEL (zero API cost) option repair: when one option looks
    truncated/missing, use the same category lookup tables (capital/currency/
    legislature) the question-reconstruction uses -- if the other 3 options
    are recognized members of one category, and there's a "reverse" entry
    missing from that category, that's a strong signal, but since we don't
    have a full reverse-lookup corpus we fall back to a clearly-labeled
    placeholder rather than ever leaving the option blank. Never dropped.
    """
    broken = (opts[idx] or "").strip()
    if broken:
        return broken
    return "(অস্পষ্ট বিকল্প)"


def _qbm_balance_answer_with_options(mc: dict) -> None:
    """
    Cross-checks answer/options consistency and fixes in place, code-level
    only: if 'answer' isn't a valid A/B/C/D or points at an option slot that
    was empty/reconstructed, keep the letter valid and consistent rather than
    silently leaving a mismatch. Never removes the MCQ.
    """
    opts = mc.get("options", [])
    ans = mc.get("answer", "A")
    if ans not in ("A", "B", "C", "D"):
        mc["answer"] = "A"
        return
    idx = "ABCD".index(ans)
    if idx >= len(opts) or not (opts[idx] or "").strip():
        # Answer points at a missing/blank option slot -- reassign to the
        # first option slot that actually has real text, if any, instead of
        # leaving an inconsistent answer/option pairing.
        for i, o in enumerate(opts):
            if (o or "").strip() and (o or "").strip() != "(অস্পষ্ট বিকল্প)":
                mc["answer"] = "ABCD"[i]
                return


def _qbm_restore_opt_bboxes(source_mcqs: list, verified_mcqs: list) -> list:
    """Call3-verify's own prompt schema doesn't ask for qsn_bbox, so its
    output would silently lose it. Verify keeps the same length/order as
    its input (per its own contract), so restore by index position."""
    if not verified_mcqs:
        return verified_mcqs
    for i, mc in enumerate(verified_mcqs):
        if i < len(source_mcqs) and not mc.get("qsn_bbox"):
            mc["qsn_bbox"] = source_mcqs[i].get("qsn_bbox")
    return verified_mcqs


def _qbm_repair_order(source_mcqs: list, verified_mcqs: list) -> list:
    """CODE-LEVEL safety net: even with an explicit prompt instruction, a
    model can still occasionally move an MCQ (typically one it had to fix,
    e.g. adding qsn_bbox) to a different position in its output list. This
    re-sorts verified_mcqs back to source_mcqs's original order by matching
    normalized question text -- any MCQ that can't be matched (rare, e.g.
    text changed too much) is kept in its verify-output position at the end,
    never dropped."""
    if not verified_mcqs or len(verified_mcqs) != len(source_mcqs):
        return verified_mcqs  # length mismatch -> trust verify's own order, don't risk misalignment
    source_order = [_qbm_normalize_q(mc.get("question", "")) for mc in source_mcqs]
    by_key = {}
    leftovers = []
    for mc in verified_mcqs:
        key = _qbm_normalize_q(mc.get("question", ""))
        if key and key not in by_key:
            by_key[key] = mc
        else:
            leftovers.append(mc)
    ordered = []
    used = set()
    for key in source_order:
        if key in by_key and key not in used:
            ordered.append(by_key[key])
            used.add(key)
    ordered.extend(leftovers)
    return ordered if len(ordered) == len(verified_mcqs) else verified_mcqs


async def _attach_option_images_if_missing(mcqs: list, img) -> list:
    """/qbm: if a source MCQ's QUESTION part has a diagram/figure (per qsn_bbox
    from the extraction prompt), tightly crop JUST that diagram, upload it,
    and embed <img src="..."> into the question text so it flows through to
    CSV/DB as-is. Options never get images."""
    try:
        from pdf_handler import crop_option_image
    except Exception:
        return mcqs
    for mc in mcqs or []:
        bbox = mc.get("qsn_bbox")
        q = mc.get("question") or ""
        if not bbox or "<img" in q.lower():
            continue
        try:
            url = await asyncio.to_thread(crop_option_image, img, bbox)
        except Exception as e:
            logger.warning(f"[QBM QsnImage] crop/upload failed: {e}")
            url = ""
        if url:
            mc["question"] = f'{q} <img src="{url}">'.strip()
    return mcqs


_FIGURE_CAPTION_RE = re.compile(
    r'চিত্র\s*[:\-]?\s*\S+|figure\s*[:\-]?\s*\d+|diagram\s*[:\-]?\s*\S+', re.IGNORECASE
)

async def _qbm_recover_missed_diagram_bbox(img, question: str) -> list:
    """Code-level fallback: question text has a figure caption (e.g. 'চিত্র: G')
    but no qsn_bbox was ever produced by Call1/Call3 -- do one targeted, cheap
    Gemini call asking ONLY for that diagram's box, instead of losing the
    diagram silently."""
    prompt = f"""This exact page image contains an MCQ whose question text includes a figure
caption/label: "{question[:200]}"

TASK: Find the actual diagram/figure/chart that this caption labels (the drawing itself, not
the caption text) on this page image. Output ONLY a tight JSON bounding box (0-1000 scale) that
fully contains that diagram including its labels/arrows, with a small margin. If you genuinely
cannot find any diagram matching this caption, output exactly: null

Output ONLY: [x1,y1,x2,y2] or null -- no other text."""
    try:
        txt = await _qbm_gemini_raw(img, prompt)
        if not txt:
            return None
        t = txt.strip()
        if t.lower() == "null" or not t:
            return None
        m = re.search(r'\[\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\]', t)
        if m:
            bbox = json.loads(m.group())
            if len(bbox) == 4:
                return bbox
    except Exception as e:
        logger.warning(f"[QBM] Diagram bbox recovery failed: {e}")
    return None


async def _qbm_batch_backfill_gemini(img, items: list) -> dict:
    """ONE Gemini call for an entire page's worth of flagged issues (truncated
    questions that Groq couldn't recover + missing diagram bboxes), instead of
    a separate Gemini call per MCQ. items: [{'idx':i,'type':'question','q':..,
    'opts':[...]} , {'idx':i,'type':'bbox','question':...}]. Returns
    {idx: result_str_or_bbox_list}. Empty dict on failure -> callers keep
    their existing deterministic/no-op fallback."""
    if not items:
        return {}
    parts = []
    for it in items:
        if it["type"] == "question":
            opts_str = ", ".join(o.strip() for o in it["opts"] if o and o.strip())
            parts.append(
                f'{{"idx":{it["idx"]},"task":"question","fragment":{json.dumps(it["q"])},"options":{json.dumps(opts_str)}}}'
            )
        else:
            parts.append(
                f'{{"idx":{it["idx"]},"task":"bbox","caption":{json.dumps(it["question"][:200])}}}'
            )
    prompt = f"""This exact page image has {len(items)} unresolved issue(s) from earlier extraction. Fix ALL of them in one pass by looking at the page image:

{chr(10).join(parts)}

For each item with "task":"question" -> find the REAL complete question text as printed on the page for that fragment (read the actual line, do not invent wording). If not found output "NOT_FOUND".
For each item with "task":"bbox" -> find the diagram/figure this caption labels and output a tight [x1,y1,x2,y2] box (0-1000 scale) including labels/arrows with small margin. If not found output null.

Return ONLY a JSON array, same order as input, one object per item:
[{{"idx":<idx>,"result":"<question text or NOT_FOUND>"}}, {{"idx":<idx>,"result":[x1,y1,x2,y2] or null}}]
No markdown, no extra text."""
    try:
        txt = (await _qbm_gemini_raw(img, prompt)).strip()
        if "```" in txt:
            txt = txt.split("```")[1].split("```")[0].strip()
            if txt.startswith("json"):
                txt = txt[4:].strip()
        arr = json.loads(txt)
        return {int(o["idx"]): o.get("result") for o in arr if "idx" in o}
    except Exception as e:
        logger.warning(f"[QBM] Batch backfill call failed: {e}")
        return {}


async def _qbm_final_safety_net(img, mcqs: list) -> list:
    """
    Last-line, zero-trust, CODE-LEVEL (not prompt-level) safety net applied to
    every MCQ right before it leaves the extraction pipeline. Balances and
    repairs question, options, and answer together so nothing ships broken
    and no MCQ is ever dropped/skipped:
      1) Question truncated/garbage -> deterministically rebuild from option
         pattern (no extra API call).
      2) Any option truncated/blank -> deterministically repair or clearly
         mark, never left blank, never dropped.
      3) Answer letter invalid or pointing at a broken/blank option slot ->
         reassigned to a real, non-blank option so answer/options stay
         consistent with each other.
      4) Explanation empty/missing -> build one now (4-option covering).
      5) Question has a figure caption (e.g. "চিত্র: G") but no qsn_bbox was
         ever attached -> one targeted recovery call to find that diagram's
         box, so the caption never ships without its actual image.
    """
    if not mcqs:
        return mcqs
    fixed = []
    batch_items = []  # collected across the whole page -> ONE Gemini call at the end
    pending_question_idx = {}  # idx in fixed -> (q, opts) for batch fallback
    pending_bbox_idx = {}

    for mc in mcqs:
        q = (mc.get("question") or "").strip()
        opts = mc.get("options", [])

        if _qbm_question_looks_truncated(q, opts):
            # Cheap, non-Gemini attempt first (Groq only, no gemini fallback here
            # -- gemini fallback now happens once for the whole page in the batch call below).
            reread = await _qbm_reextract_truncated_question_groq_only(img, q, opts)
            if reread:
                mc["question"] = reread
            else:
                pending_question_idx[len(fixed)] = (q, opts)
                batch_items.append({"idx": len(fixed), "type": "question", "q": q, "opts": opts})

        for i, o in enumerate(opts):
            if _qbm_option_looks_truncated(o, opts):
                opts[i] = _qbm_reconstruct_option_from_siblings(opts, i)
        mc["options"] = opts

        _qbm_balance_answer_with_options(mc)

        if not (mc.get("explanation") or "").strip():
            ans = mc.get("answer", "A")
            try:
                mc["explanation"] = await _qbm_build_explanation_for_known_answer(mc, ans)
            except Exception as e:
                logger.warning(f"[QBM safety-net] Explanation backfill attempt 1 failed: {e}, retrying once")
                try:
                    mc["explanation"] = await _qbm_build_explanation_for_known_answer(mc, ans)
                except Exception as e2:
                    logger.error(f"[QBM safety-net] Explanation backfill retry also failed: {e2}")
            if not (mc.get("explanation") or "").strip():
                opt_letters = ["A", "B", "C", "D"]
                idx = opt_letters.index(ans) if ans in opt_letters else 0
                ans_text = opts[idx] if idx < len(opts) else ""
                mc["explanation"] = f"সঠিক উত্তর: {ans} ({ans_text})" if ans_text else f"সঠিক উত্তর: {ans}"

        if not mc.get("qsn_bbox") and "<img" not in mc["question"].lower() and _FIGURE_CAPTION_RE.search(mc["question"]):
            pending_bbox_idx[len(fixed)] = mc["question"]
            batch_items.append({"idx": len(fixed), "type": "bbox", "question": mc["question"]})

        fixed.append(mc)

    # ── ONE combined Gemini call for the whole page instead of one per MCQ ──
    if batch_items:
        results = await _qbm_batch_backfill_gemini(img, batch_items)
        for idx, (q, opts) in pending_question_idx.items():
            r = results.get(idx)
            reread = r if (isinstance(r, str) and r and r != "NOT_FOUND") else ""
            fixed[idx]["question"] = reread if reread else _qbm_reconstruct_question_from_options(q, opts)
        for idx, question in pending_bbox_idx.items():
            r = results.get(idx)
            if isinstance(r, list) and len(r) == 4:
                fixed[idx]["qsn_bbox"] = r
                logger.info(f"[QBM safety-net] Recovered missed diagram bbox for: {question[:50]}")

    fixed = await _attach_option_images_if_missing(fixed, img)
    return fixed


async def _qbm_gemini_raw(img, prompt: str) -> str:
    """Direct Gemini call with any given prompt -> raw text (caller parses).
    Tries keys in healthiest-first order, one after another, until one
    succeeds -- a single key's 429 RESOURCE_EXHAUSTED (daily quota, only 20
    RPD/key on free tier) or rate limit must never kill the whole call while
    any other key in the pool is still usable. If every Gemini key is
    exhausted/failing, falls back to Groq vision (qwen) so the caller still
    gets a result instead of an empty string."""
    try:
        from pdf_handler import key_rotator, image_to_base64, _is_gemini_key_exhausted_today
        if not key_rotator.keys:
            return await _gen_groq_raw_text(img, prompt)
        # Same persistent, process-lifetime exhaustion memory /tf and /img
        # use -- if every key was already confirmed daily-exhausted by an
        # earlier call in this process, skip straight to Groq instead of
        # burning a fresh 429 per key on every single /qbm page.
        if all(_is_gemini_key_exhausted_today(k) for k in key_rotator.keys):
            logger.warning("[QBM] all Gemini keys already known daily-exhausted — skipping straight to Groq")
            return await _gen_groq_raw_text(img, prompt)
        from google import genai as gai
        from google.genai import types
        img_b64 = image_to_base64(img)
        img_bytes = base64.b64decode(img_b64)

        def _call(key):
            client = gai.Client(api_key=key)
            return client.models.generate_content(
                model="gemini-3.6-flash",
                contents=[
                    types.Part.from_text(text=prompt),
                    types.Part.from_bytes(data=img_bytes, mime_type="image/jpeg")
                ],
                config=types.GenerateContentConfig(temperature=0.1)
            )

        keys_to_try = key_rotator.ordered_keys(offset=_qbm_key_offset_ctx.get()) or key_rotator.keys
        # Skip keys already confirmed daily-exhausted (by an earlier call this
        # process) when at least one non-exhausted key remains -- ordered_keys()
        # sorts exhausted keys last but doesn't remove them, so without this
        # filter every call still re-tries and re-429s each known-dead key
        # before reaching a live one, wasting calls on a predictable outcome.
        _live = [k for k in keys_to_try if not _is_gemini_key_exhausted_today(k)]
        if _live:
            keys_to_try = _live
        for key in keys_to_try:
            if is_cancelled():
                return ""
            try:
                response = await asyncio.to_thread(_call, key)
                key_rotator.mark_healthy(key)
                return response.text or ""
            except Exception as e:
                msg = str(e)
                # SDK's str(e) sometimes truncates the JSON body before the
                # 'violations'/quota_id details that distinguish PerDay vs
                # PerMinute — pull the raw response body too if available.
                extra = ""
                try:
                    resp_obj = getattr(e, "response", None)
                    if resp_obj is not None:
                        extra = getattr(resp_obj, "text", "") or ""
                except Exception:
                    pass
                full_msg = msg + " " + extra
                if "RESOURCE_EXHAUSTED" in msg or "429" in msg:
                    daily = "PerDay" in full_msg
                    retry_s = None
                    try:
                        rd_match = re.search(r"'retryDelay':\s*'(\d+)s'", full_msg)
                        if rd_match:
                            retry_s = int(rd_match.group(1))
                    except Exception:
                        pass
                    key_rotator.mark_rate_limited(key, daily_exhausted=daily, retry_after_seconds=retry_s)
                    logger.warning(f"[QBM] Gemini key {key[:12]}... {'daily-exhausted' if daily else 'rate-limited'}, trying next key | raw_error={full_msg[:1500]}")
                    continue
                logger.warning(f"[QBM] Gemini key {key[:12]}... non-quota error, trying next key: {e}")
                continue
        # All Gemini keys exhausted/rate-limited/errored — fall back to Groq vision
        logger.warning("[QBM] All Gemini keys exhausted — falling back to Groq vision")
        return await _gen_groq_raw_text(img, prompt)
    except Exception as e:
        logger.warning(f"[QBM] Gemini raw call failed: {e}")
        return await _gen_groq_raw_text(img, prompt)


async def _ai_gemini_text_call(prompt: str) -> str:
    """Text-only Gemini call (no image) for /ai's explanation generation.
    Same key-rotation/exhaustion handling as _qbm_gemini_raw, minus the
    image part -- tries every non-exhausted key in order before giving up."""
    try:
        from pdf_handler import key_rotator, _is_gemini_key_exhausted_today
        if not key_rotator.keys:
            return ""
        from google import genai as gai
        from google.genai import types

        def _call(key):
            client = gai.Client(api_key=key)
            return client.models.generate_content(
                model="gemini-3.6-flash",
                contents=[types.Part.from_text(text=prompt)],
                config=types.GenerateContentConfig(temperature=0.2, max_output_tokens=65536)
            )

        keys_to_try = key_rotator.ordered_keys() or key_rotator.keys
        _live = [k for k in keys_to_try if not _is_gemini_key_exhausted_today(k)]
        if _live:
            keys_to_try = _live
        for key in keys_to_try:
            if is_cancelled():
                return ""
            try:
                response = await asyncio.to_thread(_call, key)
                key_rotator.mark_healthy(key)
                return response.text or ""
            except Exception as e:
                msg = str(e)
                if "RESOURCE_EXHAUSTED" in msg or "429" in msg:
                    daily = "PerDay" in msg
                    key_rotator.mark_rate_limited(key, daily_exhausted=daily)
                    logger.warning(f"[AI] Gemini key {key[:12]}... {'daily-exhausted' if daily else 'rate-limited'}, trying next key")
                    continue
                logger.warning(f"[AI] Gemini key {key[:12]}... non-quota error, trying next key: {e}")
                continue
        logger.warning("[AI] all Gemini keys exhausted/failed -- falling back to Groq text")
        return await _qbm_groq_text_call(prompt)
    except Exception as e:
        logger.warning(f"[AI] Gemini text call failed: {e}")
        return await _qbm_groq_text_call(prompt)


_AI_EXPLAIN_CHUNK_SIZE = 8
_AI_EXPLAIN_CONCURRENCY = 3


def _ai_parse_explanations_json(text: str, expected_len: int) -> list:
    """Lightweight parser for /ai's explanation-only output
    ([{"explanation":"..."}]) -- unlike _qbm_parse_json this does NOT
    require 'question'/'options' fields (those aren't in this output shape),
    so it must NOT reuse that MCQ-schema-specific parser. Returns [] if the
    array can't be parsed or its length doesn't match expected_len."""
    if not text:
        return []
    t = text.strip()
    if "```json" in t:
        t = t.split("```json")[1].split("```")[0].strip()
    elif "```" in t:
        t = t.split("```")[1].split("```")[0].strip()
    try:
        m = re.search(r'\[.*\]', t, re.DOTALL)
        raw = json.loads(m.group()) if m else json.loads(t)
    except Exception:
        return []
    if not isinstance(raw, list) or len(raw) != expected_len:
        return []
    return raw


async def _ai_generate_explanations_chunk(chunk: list) -> dict:
    """Given a chunk of MCQ dicts (with 'question','options','answer'),
    returns {index_in_chunk: explanation_text} for whichever ones Gemini
    successfully answered. Explanation is NOT length-capped here -- the
    correct-answer's key info is required to land within the first ~200
    chars (Telegram poll explanation's hard limit) since that's the part
    guaranteed to survive when a poll is sent; anything after that is
    still stored in full in CSV/DB and simply gets trimmed off (not
    rejected) if/when the poll is actually sent, which is fine since the
    essential info already landed earlier."""
    if not chunk:
        return {}
    items_json = json.dumps([
        {"question": c["question"], "options": c["options"], "answer": c["answer"]}
        for c in chunk
    ], ensure_ascii=False)
    prompt = f"""তুমি একজন বিষয়বিশেষজ্ঞ শিক্ষক। নিচে কিছু MCQ (প্রশ্ন + অপশন + সঠিক উত্তর) দেওয়া আছে, প্রতিটার জন্য একটা তথ্যবহুল explanation লিখতে হবে।

কঠোর নিয়ম (Structure — এই order মেনেই লিখতে হবে):
- **প্রথম অংশ (≈১৯৯ ক্যারেক্টারের মধ্যে অবশ্যই শেষ করতে হবে)**: সঠিক option-টা সম্পর্কে প্রশ্ন-প্রাসঙ্গিক মূল তথ্য/কারণ (কেন এটাই সঠিক উত্তর) — এটা সবচেয়ে জরুরি অংশ, কারণ Telegram poll-এ এই ১৯৯ ক্যারেক্টারের পর বাকিটা কেটে যেতে পারে, তাই মূল উত্তরের তথ্য এই সীমার মধ্যেই সম্পূর্ণ থাকা আবশ্যক।
- **দ্বিতীয় অংশ (এর পরে — এইটা বাধ্যতামূলক, কখনো বাদ দেওয়া যাবে না, ছোট রাখা যাবে না)**: বাকি প্রতিটা ভুল option নিয়ে আলাদা আলাদা ২-৩ বাক্য করে বিস্তারিত তথ্য — প্রতিটা option আসলে কী/কে/কোন ঘটনা/কোন সাল, প্রশ্নের টপিকের সাথে ওর প্রাসঙ্গিক সম্পর্ক কী, এবং নির্দিষ্টভাবে কেন সেটা এই প্রশ্নের উত্তর না। ২-৩টা option থাকলে পুরো explanation মিলিয়ে কমপক্ষে ৪-৬ বাক্য/৫০০-৮০০ ক্যারেক্টার হওয়া উচিত — একটা মাত্র লাইনে সব option একসাথে সংক্ষেপে সেরে ফেলা চলবে না, প্রতিটা option-এর নিজস্ব প্যারা/অংশ থাকতে হবে।
- পুরো explanation একটাই প্যারা/স্ট্রিং হিসেবে দিতে হবে, দুই অংশের মাঝে কোনো heading/label ছাড়া — শুধু স্বাভাবিকভাবে প্রথম অংশ শেষ হয়ে দ্বিতীয় অংশ শুরু হবে।
- explanation সরাসরি তথ্য দিয়ে শুরু করবে -- "সঠিক উত্তর X।" জাতীয় কোনো লাইন/prefix লেখা যাবে না, answer letter (A/B/C/D) কোথাও mention করা যাবে না।
- generic/এক-লাইনের ফাঁকা কথা লেখা যাবে না -- প্রতিটা option সম্পর্কে নির্দিষ্ট (specific), তথ্যবহুল বাক্য থাকতে হবে, "এটা ভুল কারণ এটা সঠিক না" জাতীয় ফাঁকা logic চলবে না।
- ভাষা: প্রশ্ন যে ভাষায় (বাংলা/ইংরেজি) সেই ভাষাতেই লিখতে হবে।
- যদি input-এ আগে থেকেই কোনো explanation থাকে সেটা উপেক্ষা করে নতুন করে সঠিক ও তথ্যবহুল explanation বানাও।

INPUT MCQs (in order):
{items_json}

OUTPUT — ONLY a valid JSON array, exactly {len(chunk)} items, same order, nothing else:
[{{"explanation":"..."}}]"""

    txt = await _ai_gemini_text_call(prompt)
    if not txt:
        return {}
    parsed = _ai_parse_explanations_json(txt, len(chunk))
    if not parsed:
        return {}
    out = {}
    # Defensive cleanup: strip a leading "সঠিক উত্তর X।"/"Correct answer: X."
    # style prefix if the model adds one anyway despite the prompt rule --
    # this line adds no value (option letters aren't shown in the poll UI
    # the same way) and eats into the critical first-199-char budget.
    _answer_prefix_re = re.compile(
        r'^\s*(সঠিক\s*উত্তর|উত্তর)\s*[:\-]?\s*[A-Eক-ঙ১-৫][\)\.।]?\s*[।\.\-:]?\s*',
        re.IGNORECASE
    )
    for i, item in enumerate(parsed):
        exp = (item.get("explanation") or "").strip() if isinstance(item, dict) else ""
        if exp:
            exp = _answer_prefix_re.sub("", exp).strip()
            out[i] = exp
    return out


async def _ai_generate_all_explanations(mcqs: list, progress_cb=None) -> None:
    """Fills mcqs[i]['explanation'] in-place. Tries the WHOLE file in a
    single Gemini call first (one key, one call) -- works fine for typical
    CSV sizes since Gemini has no small TPM ceiling like Groq. Only falls
    back to chunked (8/call, 3 concurrent) calls if the single-call attempt
    fails or Gemini's response gets truncated/malformed (large files can
    still hit output-token limits). progress_cb(done_count) is called after
    every completed chunk so the caller can show live %/elapsed status."""
    if not mcqs:
        return
    single = await _ai_generate_explanations_chunk(mcqs)
    if len(single) == len(mcqs):
        for idx, exp in single.items():
            mcqs[idx]["explanation"] = exp
        if progress_cb:
            progress_cb(len(mcqs))
        return

    logger.warning(f"[AI] single-call attempt covered {len(single)}/{len(mcqs)} -- falling back to chunked calls")
    chunks = [mcqs[i:i + _AI_EXPLAIN_CHUNK_SIZE] for i in range(0, len(mcqs), _AI_EXPLAIN_CHUNK_SIZE)]
    sem = asyncio.Semaphore(_AI_EXPLAIN_CONCURRENCY)
    _done = {"n": 0}

    async def _run_chunk(chunk):
        async with sem:
            result = await _ai_generate_explanations_chunk(chunk)
            for idx, exp in result.items():
                chunk[idx]["explanation"] = exp
            _done["n"] += len(chunk)
            if progress_cb:
                progress_cb(_done["n"])

    await asyncio.gather(*[_run_chunk(c) for c in chunks])


async def handle_ai(msg: dict):
    """
    /ai — reply দাও একটা CSV ফাইলে (questions,option1-5,answer,explanation,
    type,section format)। প্রতিটা MCQ-র question+options+answer বুঝে Gemini
    দিয়ে relevant explanation বসায় explanation column-এ (Telegram poll
    explanation-এর ~200 ক্যারেক্টার লিমিটের মধ্যে), বাকি সব column অপরিবর্তিত
    রেখে নতুন CSV ফাইল রিটার্ন করে।
    """
    chat_id = msg["chat"]["id"]
    reply = msg.get("reply_to_message")
    doc = reply.get("document") if reply else None
    if not doc or not doc.get("file_name", "").lower().endswith(".csv"):
        await send_msg(chat_id,
            "❌ একটা CSV ফাইলে reply করে /ai দাও!\n\n"
            "📌 CSV format: questions, option1-5, answer, explanation, type, section\n"
            "📌 প্রতিটা MCQ-র জন্য Gemini দিয়ে relevant explanation বসাবে (answer + topic info সহ, ~200 ক্যারেক্টারের মধ্যে)")
        return

    file_id = doc["file_id"]
    status_r = await send_msg(chat_id, "⏳ CSV পড়া হচ্ছে...")
    status_msg_id = status_r.get("result", {}).get("message_id")

    try:
        csv_bytes = await download_tg_file(file_id)
        content = csv_bytes.decode("utf-8-sig")
        import io as _io_ai, csv as _csv_mod_ai
        reader = _csv_mod_ai.DictReader(_io_ai.StringIO(content))
        fieldnames = reader.fieldnames or []
        rows = list(reader)
        if not rows:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ CSV-তে কোনো MCQ পাওয়া যায়নি!")
            return

        ans_map_to_letter = {"1": "A", "2": "B", "3": "C", "4": "D", "5": "E",
                              "A": "A", "B": "B", "C": "C", "D": "D", "E": "E"}
        mcqs = []
        for row in rows:
            q = (row.get("questions") or row.get("question") or "").strip()
            opts = {}
            for letter, col in zip("ABCDE", ["option1", "option2", "option3", "option4", "option5"]):
                v = (row.get(col) or "").strip()
                if v:
                    opts[letter] = v
            ans_letter = ans_map_to_letter.get(str(row.get("answer", "1")).strip().upper(), "A")
            mcqs.append({"question": q, "options": opts, "answer": ans_letter,
                         "explanation": row.get("explanation", "").strip(), "_row": row})

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id, f"⏳ {len(mcqs)}টা MCQ পাওয়া গেছে, Gemini দিয়ে explanation বসানো হচ্ছে...\n[░░░░░░░░░░ 0%] | 0/{len(mcqs)} | 0s")

        _ai_start = time.time()
        _total_mcqs = len(mcqs)
        _last_shown = {"pct": -1}

        def _ai_progress(done: int):
            if not status_msg_id:
                return
            pct = int(done * 100 / _total_mcqs) if _total_mcqs else 100
            if pct - _last_shown["pct"] < 10 and pct != 100:
                return
            _last_shown["pct"] = pct
            bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
            elapsed = int(time.time() - _ai_start)
            _spawn_task(edit_msg(chat_id, status_msg_id,
                f"⏳ Explanation বসানো হচ্ছে...\n[{bar} {pct}%] | {done}/{_total_mcqs} | {elapsed}s"))

        await _ai_generate_all_explanations(mcqs, progress_cb=_ai_progress)
        _total_elapsed = int(time.time() - _ai_start)
        _filled_count = sum(1 for m in mcqs if m["explanation"])
        if _filled_count == 0:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ Gemini থেকে কোনো explanation পাওয়া যায়নি (API/key সমস্যা)। আবার চেষ্টা করো।")
            return

        buf = _io_ai.StringIO()
        out_fields = fieldnames if fieldnames else ["questions", "option1", "option2", "option3", "option4", "option5", "answer", "explanation", "type", "section"]
        writer = _csv_mod_ai.DictWriter(buf, fieldnames=out_fields)
        writer.writeheader()
        for m in mcqs:
            row = dict(m["_row"])
            if "explanation" in row or "explanation" in out_fields:
                row["explanation"] = m["explanation"]
            writer.writerow(row)

        base_name = doc.get("file_name", "quiz.csv").rsplit(".", 1)[0]
        await send_document(chat_id, buf.getvalue().encode("utf-8"),
            f"{base_name}_AI.csv",
            caption=f"✅ {len(mcqs)}টা MCQ-তে explanation যোগ করা হয়েছে",
            mime_type="text/csv")
        if status_msg_id:
            await edit_msg(chat_id, status_msg_id, f"✅ সম্পূর্ণ! {len(mcqs)}টা MCQ-তে explanation যোগ করা হয়েছে।\n⏱ সময় লেগেছে: {_total_elapsed}s")
    except Exception as e:
        logger.error(f"[AI] Error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)


async def _qbm_gemini_extract(img, prompt: str = None) -> list:
    """Direct Gemini call with the strict extraction prompt (fallback path)."""
    txt = await _qbm_gemini_raw(img, prompt or await qbm_get_active_prompt())
    return _qbm_parse_json(txt) if txt else []


async def _qbm_groq_text_call(prompt: str, model: str = "openai/gpt-oss-120b") -> str:
    """Text-only Groq call (no image) -- used for pure-reasoning tasks like
    last-resort answer resolution, where no image/page content is left to read."""
    keys = groq_key_rotator.ordered_keys()
    if not keys:
        return ""
    for key in keys:
        try:
            headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
            payload = {
                "model": model,
                "messages": [{"role": "user", "content": prompt}],
                "temperature": 0.0,
                "max_tokens": 300,
            }
            async with httpx.AsyncClient(timeout=30) as c:
                r = await c.post("https://api.groq.com/openai/v1/chat/completions", headers=headers, json=payload)
                if r.status_code >= 400:
                    if r.status_code == 429:
                        groq_key_rotator.mark_rate_limited(key)
                    else:
                        logger.warning(f"[Groq-text] {model} HTTP {r.status_code}")
                    continue
                j = r.json()
                groq_key_rotator.mark_healthy(key)
                return j.get("choices", [{}])[0].get("message", {}).get("content", "") or ""
        except Exception as e:
            logger.warning(f"[Groq-text] err: {e}")
            continue
    return ""


async def _qbm_web_resolve_answer(mc: dict) -> dict | None:
    """
    LAST-RESORT answer resolution -- used ONLY when the answer could not be
    found anywhere in the page/PDF (no mark, no inline answer, no answer-key
    table, no nearby-page lookahead match). Groq-only, pure model-knowledge
    best-effort (no image/web tool). Strengthened for max accuracy:
    - forces step-by-step reasoning + elimination BEFORE committing to a letter
    - runs the reasoning TWICE independently (self-consistency check) and
      only accepts the answer if both passes agree
    - explicit confidence gate: model must say NONE rather than guess
    - also produces a clean 4-option-covering explanation (max 165 chars,
      Bengali) with NO mention of "answer not found", "AI knowledge", "web
      search", or any other meta/source-reference note -- explanation must
      read exactly like a normal question-related explanation.
    Returns {"answer": "A/B/C/D", "explanation": "..."} or None if unresolved.
    """
    try:
        q = mc.get("question", "")
        opts = mc.get("options", [])
        opts_txt = "\n".join(f"{L}) {o}" for L, o in zip("ABCD", opts))
        prompt = f"""This MCQ's answer could not be found anywhere in its source document (no
mark, no inline answer, no answer-key table, no nearby page match). You must now determine
the correct answer purely from your own factual knowledge.

প্রশ্ন: {q}
{opts_txt}

STRICT PROCESS (follow all steps, do not skip any):
1) Identify exactly what the question is asking (topic, subject area, specific fact type).
2) Go through EACH of the 4 options one by one and evaluate it against your factual knowledge:
   state briefly why it could be correct or why it must be wrong/eliminated.
3) Cross-check: are any options obviously wrong/irrelevant/a distractor pattern (opposite
   meaning, wrong category, wrong time period, wrong entity)? Eliminate those first.
4) Of the remaining option(s), pick the one you are most factually confident is correct based
   on real, verifiable knowledge -- NOT a plausible-sounding guess.
5) Rate your own confidence: only proceed to a final answer if you are genuinely confident
   (would bet on it being factually correct) -- if there is real doubt or the fact is obscure/
   unverifiable from memory, do NOT guess.
6) If confident, write a Bengali explanation (max 165 characters) that briefly covers ALL 4
   options: why the correct one is right, and why each of the other 3 is wrong -- stated as
   plain direct fact, exactly like a normal textbook explanation. NEVER mention that the
   answer was missing from the source, found via AI/web/search, or reference this process in
   any way -- the explanation must read as pure, ordinary subject-matter content.

OUTPUT FORMAT (mandatory, in this exact order, nothing else):
Line 1: one-line internal reasoning summary (max 20 words) -- for logging only
Line 2: ONLY the final answer letter A/B/C/D, or the word NONE if not genuinely confident
Line 3: the 165-char-max Bengali explanation (omit this line entirely if Line 2 is NONE)"""

        async def _one_pass() -> dict | None:
            txt = (await _qbm_groq_text_call(prompt, model="openai/gpt-oss-120b")).strip()
            lines = [l.strip() for l in txt.splitlines() if l.strip()]
            if len(lines) < 2:
                return None
            ans_line = lines[1].upper()
            if "NONE" in ans_line:
                return None
            m = re.search(r'[ABCD]', ans_line)
            if not m:
                return None
            expl = lines[2][:165].strip() if len(lines) >= 3 else ""
            return {"answer": m.group(), "explanation": expl}

        # Self-consistency: two independent reasoning passes must agree on the
        # ANSWER LETTER before it's trusted -- a single pass alone is not
        # enough for a knowledge-only (no source) answer.
        pass1 = await _one_pass()
        if pass1 is None:
            return None
        pass2 = await _one_pass()
        if pass2 is None:
            return None
        if pass1["answer"] == pass2["answer"]:
            # Prefer whichever pass produced a non-empty explanation.
            return pass1 if pass1["explanation"] else pass2
        # Disagreement between two independent reasoning passes -> genuinely
        # uncertain, do not guess; leave unresolved rather than risk a wrong answer.
        logger.warning(f"[QBM] Web-resolve self-consistency mismatch: {pass1['answer']} vs {pass2['answer']} for Q: {q[:60]}")
        return None
    except Exception as e:
        logger.warning(f"[QBM] Web answer-resolve failed: {e}")
        return None


async def _qbm_build_explanation_for_known_answer(mc: dict, answer_letter: str) -> str:
    """
    Builds a clean, question-related, 4-option-covering Bengali explanation
    (max 165 chars) when the correct answer is already known (e.g. matched
    from an answer-key on a nearby page) but no real explanation text came
    with it. NEVER references the source, page, or how the answer was found.
    """
    try:
        q = mc.get("question", "")
        opts = mc.get("options", [])
        opts_txt = "\n".join(f"{L}) {o}" for L, o in zip("ABCD", opts))
        prompt = f"""প্রশ্ন: {q}
{opts_txt}
সঠিক উত্তর: {answer_letter}

Write a Bengali explanation (max 165 characters) that briefly covers ALL 4 options: why the
correct option ({answer_letter}) is right, and why each of the other 3 is wrong -- stated as
plain direct fact, exactly like a normal textbook explanation. NEVER mention the source, page,
answer key, or how the answer was determined. Output ONLY the explanation text, nothing else."""
        txt = (await _qbm_groq_text_call(prompt)).strip()
        return txt[:165]
    except Exception as e:
        logger.warning(f"[QBM] Explanation build failed: {e}")
        return ""


async def handle_auto_command(msg: dict):
    """
    /auto
    বাংলা
    প্রথম পত্র
    অধ্যায় ১
    টপিক ১
    ---
    (আরেকটা independent run, চাইলে)

    Clicks through chorcha.net using the given button-text labels (one per
    line, in order per run; "---" separates independent runs), grabs each
    run's final page HTML, and extracts MCQs directly from the DOM
    (parse_mhtml_to_mcqs) -- no screenshot/AI-vision. Each run produces
    its own CSV; multiple runs = multiple CSVs from one command. Requires
    CHORCHA_TOKEN env var to be set with a valid session token.
    """
    from atlas_autoscrape import AutoScrapeError
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    _auto_uid = msg.get("from", {}).get("id")
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, "/auto (chorcha extraction)")

    lines = [l.rstrip() for l in text.split("\n")[1:] if l.strip() != ""]

    # Save-only shortcut: if EVERY line in the command is a "লেখা=link"
    # pair (one or more, no other step types, no "---" runs), just
    # persist all of them to D1 and reply -- do NOT launch a browser or
    # scrape. Lets the user pre-teach unmatchable (image-only) card links
    # in bulk ahead of time, then later run a normal text-button /auto
    # using just the label, which will resolve via this saved mapping.
    if lines and all(
        "=" in l and not l.lower().startswith(("input:", "goto:")) and l.split("=", 1)[1].strip().startswith("http")
        for l in lines
    ):
        import unicodedata as _ud
        from core import auto_link_map_set
        saved, failed = [], []
        for l in lines:
            _label_part, _url_part = l.split("=", 1)
            _label_part, _url_part = _ud.normalize("NFC", _label_part.strip()), _url_part.strip()
            try:
                await auto_link_map_set(_label_part, _url_part)
                saved.append((_label_part, _url_part))
            except Exception as e:
                failed.append((_label_part, str(e)))
        reply_lines = [f"✅ সেভ হয়েছে ({len(saved)}টা):"]
        reply_lines += [f"\"{lbl}\" → {url}" for lbl, url in saved]
        if failed:
            reply_lines.append(f"\n❌ সেভ ব্যর্থ ({len(failed)}টা):")
            reply_lines += [f"\"{lbl}\": {err}" for lbl, err in failed]
        reply_lines.append("\nপরে শুধু ওই লেখাগুলো লিখলেই bot এই লিংকগুলোতে যাবে।")
        await send_msg(chat_id, "\n".join(reply_lines))
        return

    # Shorthand runs: a run consisting of a single "OldName>NewName" line
    # reuses the FIRST run's steps verbatim, replacing every occurrence of
    # OldName with NewName. "(new)" suffix on NewName is cosmetic and
    # stripped. Lets the user avoid retyping the whole step sequence for
    # every sibling topic under the same parent.
    if lines:
        _groups = [[]]
        for _l in lines:
            if _l.strip() in ("---", "***"):
                _groups.append([])
            else:
                _groups[-1].append(_l)
        _groups = [g for g in _groups if g]
        if len(_groups) > 1:
            base_group = _groups[0]
            expanded_groups = [base_group]
            for g in _groups[1:]:
                if len(g) == 1 and ">" in g[0]:
                    old, new = g[0].split(">", 1)
                    old = old.strip()
                    new = re.sub(r"\(new\)\s*$", "", new.strip()).strip()
                    new_group = [ln.replace(old, new) for ln in base_group]
                    expanded_groups.append(new_group)
                else:
                    expanded_groups.append(g)
            lines = []
            for i, g in enumerate(expanded_groups):
                if i > 0:
                    lines.append("---")
                lines.extend(g)

    if not lines:
        await send_msg(chat_id,
            "❌ Format:\n\n"
            "<code>/auto\n"
            "বাংলা\n"
            "প্রথম পত্র\n"
            "অধ্যায় ১\n"
            "টপিক ১</code>\n\n"
            "📌 প্রতি লাইনে একটা button/link-এর নাম, ক্রমানুসারে — bot একে একে click করে "
            "শেষ পেজে পৌঁছে সেই page-এর HTML থেকে সরাসরি MCQ extract করবে (screenshot/AI-vision লাগে না, তাই নির্ভুল)।\n\n"
            "📌 একাধিক আলাদা topic থেকে আলাদা আলাদা CSV চাইলে <code>---</code> অথবা <code>***</code> দিয়ে ভাগ করো:\n"
            "<code>/auto\nইতিহাস,ব্রিটিশ শাসনামলে বাংলা\ninput:25\nএগিয়ে যাও\n***\nইতিহাস,মুসলিম শাসন ও সালতানাত\ninput:25\nএগিয়ে যাও</code>\n\n"
            "📌 শুধু topic নাম বদলাতে চাইলে পুরো step আবার না লিখে <code>---</code>/<code>***</code>-এর পর শুধু <code>OldName&gt;NewName</code> দিলেই হবে (১ম run-এর step-গুলো reuse হবে, শুধু OldName→NewName replace হয়ে):\n"
            "<code>/auto\nইতিহাস,ব্রিটিশ শাসনামলে বাংলা\ninput:25\nএগিয়ে যাও\n***\nব্রিটিশ শাসনামলে বাংলা&gt;প্রাচীন বাংলার ইতিহাস(new)\n***\nব্রিটিশ শাসনামলে বাংলা&gt;মুসলিম শাসন ও সালতানাত(new)</code>\n\n"
            "📌 কোনো card image-only হলে (text দিয়ে খুঁজে পাওয়া যায় না), সরাসরি লিংক দিয়ে দাও — <code>লেখা=লিংক</code> ফরম্যাটে। এটা একবার সেভ হয়ে যাবে (bot restart-এও থাকবে) — পরের বার শুধু ঐ লেখা দিলেই bot নিজে সেভ করা লিংকে যাবে:\n"
            "<code>/auto\nজীববিজ্ঞান ১ম পত্র=https://chorcha.net/...\ninput:25\nএগিয়ে যাও</code>\n\n"
            "📌 কোনো button-এর নামের ভেতরেই comma (,) থাকলে (যেমন <code>বিস্তার ও সংরক্ষণ, জীবের পরিবেশ</code>), সেটাকে double-quote দিয়ে ঘিরে দাও — নাহলে bot ওই comma দেখে আলাদা ২টা step মনে করে ভুল করবে:\n"
            "<code>/auto\nপ্রশ্নব্যাংক\nজীববিজ্ঞান ১ম পত্র\n\"বিস্তার ও সংরক্ষণ, জীবের পরিবেশ\"</code>",
            parse_mode="HTML"
        )
        return

    if not os.environ.get("CHORCHA_TOKEN", "").strip():
        await send_msg(chat_id, "❌ CHORCHA_TOKEN সেট করা নেই — আগে login session token env var-এ সেভ করতে হবে।")
        return

    run_count = sum(1 for l in lines if l.strip() in ("---", "***")) + 1
    status = await send_msg(chat_id, f"🌐 <b>ATLAS AutoScrape</b>\n[{_mhtml_progress_bar(0)}] 0%\nশুরু হচ্ছে... ({run_count}টা run)", parse_mode="HTML")
    status_msg_id = status.get("result", {}).get("message_id") if isinstance(status, dict) else None

    _start_time = time.time()
    _tz = timezone(timedelta(hours=6))  # Bangladesh time

    def _fmt_secs(s):
        s = max(0, int(s))
        if s < 60:
            return f"{s}সে"
        m, s = divmod(s, 60)
        if m < 60:
            return f"{m}মি {s}সে"
        h, m = divmod(m, 60)
        return f"{h}ঘ {m}মি"

    def _fmt_clock(ts):
        return datetime.fromtimestamp(ts, _tz).strftime("%I:%M:%S %p")

    _last_edit_at = {"t": 0.0}
    _completed_steps = []  # list of "✅ label" lines that stay visible once done
    _last_seen_label = {"v": None}
    _last_seen_stage = {"v": None}

    def _render_status(current_line, pct):
        bar = _mhtml_progress_bar(pct)
        elapsed = time.time() - _start_time
        lines_out = [
            f"🕐 শুরু হয়েছে: {_fmt_clock(_start_time)}",
            f"⏱️ চলছে: {_fmt_secs(elapsed)}",
        ]
        if pct and pct > 0:
            eta = (elapsed / pct) * (100 - pct)
            lines_out.append(f"⏳ আনুমানিক বাকি: {_fmt_secs(eta)}")
            lines_out.append(f"🏁 আনুমানিক শেষ হবে: {_fmt_clock(time.time() + eta)}")
        header = f"🌐 <b>ATLAS AutoScrape</b>\n[{bar}] {pct}%\n" + "\n".join(lines_out) + "\n"
        # Cap how many completed lines we show inline so the message never
        # blows past Telegram's length limit on very long step sequences --
        # keep the most recent ones, summarize the rest as a count.
        shown = _completed_steps[-15:]
        hidden_count = len(_completed_steps) - len(shown)
        body = ""
        if hidden_count > 0:
            body += f"…({hidden_count}টা আগের ধাপ সম্পন্ন)…\n"
        if shown:
            body += "\n".join(shown) + "\n"
        return header + body + current_line

    async def _progress(i, total, label):
        # /cancel didn't work for /auto -- CANCEL_FLAGS was never checked
        # anywhere in this flow (only PDF/QBM MCQ generation wired it in).
        # progress_cb is awaited on every single click step inside
        # run_auto_click_sequence, so raising here is the one place that
        # reaches every step without touching atlas_autoscrape.py's click
        # loop / multi-line / vector-arrow logic at all -- the exception
        # propagates straight up through the existing AutoScrapeError
        # handler below, which already sends a clean message and returns.
        if is_cancelled(chat_id):
            raise AutoScrapeError("🛑 /cancel দিয়ে বন্ধ করা হয়েছে।")
        now_t = time.time()
        if _auto_uid is not None:
            _prev = _USER_LAST_STATUS.get(_auto_uid, {})
            _USER_LAST_STATUS[_auto_uid] = {
                "command": "/auto",
                "stage": f"{label} ({i}/{total})",
                "started_at": _prev.get("started_at", now_t) if _prev.get("command") == "/auto" else now_t,
                "last_update_at": now_t,
            }

        run_tag = ""
        m = re.match(r"^\[run (\d+)/(\d+)\]\s*(.*)$", label)
        display_label, run_no, run_total = (m.group(3), m.group(1), m.group(2)) if m else (label, None, None)
        if run_no:
            run_tag = f"রান {run_no}/{run_total} · "

        # A NEW label (different from the last one we saw) means the
        # previous step is now done -- lock it into the completed list
        # with a ✓ so it stays visible, instead of vanishing when the
        # message gets overwritten for the next step.
        _stage_key = re.sub(r'[\d০-৯/]+.*$', '', label).strip()
        if _last_seen_stage["v"] is not None and _last_seen_stage["v"] != _stage_key:
            _completed_steps.append(f"✅ {_last_seen_label['v']}")
        _last_seen_stage["v"] = _stage_key
        _last_seen_label["v"] = html_lib.escape(label)

        if not status_msg_id:
            return
        # Throttle edits to avoid Telegram rate limits on fast steps.
        if now_t - _last_edit_at["t"] < 0.6 and i != total:
            return
        _last_edit_at["t"] = now_t
        pct = max(0, min(100, round((i / total) * 100))) if total else 0
        current_line = f"{run_tag}ধাপ {i}/{total}: \"{html_lib.escape(display_label)}\" (চলছে...)"
        text = _render_status(current_line, pct)
        try:
            await edit_msg(chat_id, status_msg_id, text, parse_mode="HTML")
        except Exception:
            pass

    # Recompute per-run topic labels (last click-label of each run, for
    # the filename/caption) by re-splitting the same way the backend did.
    run_line_groups = [[]]
    for l in lines:
        if l.strip() in ("---", "***"):
            run_line_groups.append([])
        else:
            run_line_groups[-1].append(l)
    run_line_groups = [g for g in run_line_groups if any(x.strip() for x in g)]

    sent_any = {"v": False}  # mutable so the closure below can flip it

    async def _on_run_complete(html_bytes, run_no, run_total):
        # Sends this run's CSV right away instead of waiting for every
        # run to finish first -- so a completed topic's file arrives
        # immediately while later runs are still processing.
        if is_cancelled(chat_id):
            raise AutoScrapeError("🛑 /cancel দিয়ে বন্ধ করা হয়েছে।")
        topic = run_line_groups[run_no - 1][-1].strip() if run_no - 1 < len(run_line_groups) else f"run{run_no}"
        run_tag = f"রান {run_no}/{run_total} · " if run_total > 1 else ""

        async def _final_stage_update(text):
            if _auto_uid is not None:
                _prev = _USER_LAST_STATUS.get(_auto_uid, {})
                _USER_LAST_STATUS[_auto_uid] = {
                    "command": "/auto",
                    "stage": f"{run_tag}{text}",
                    "started_at": _prev.get("started_at", time.time()),
                    "last_update_at": time.time(),
                }
            if not status_msg_id:
                return
            # Lock the last-seen click-step into the completed list (once,
            # first time we reach the final stage) so it stays visible
            # with a ✓ instead of vanishing.
            if _last_seen_label["v"] is not None:
                _completed_steps.append(f"✅ {_last_seen_label['v']}")
                _last_seen_label["v"] = None
            current_line = f"{run_tag}{text}"
            rendered = _render_status(current_line, 100)
            try:
                await edit_msg(chat_id, status_msg_id, rendered, parse_mode="HTML")
            except Exception:
                pass

        await _final_stage_update("📄 HTML থেকে MCQ বের করা হচ্ছে...")
        try:
            parsed = await asyncio.to_thread(parse_mhtml_to_mcqs, html_bytes, "auto-scrape.html")
            results = parsed["results"]
            skipped = parsed.get("skipped") or []
            total_seen = parsed.get("total_cards_seen")

            # RECHECK PASS: re-parse the SAME captured HTML a second time.
            # parse_mhtml_to_mcqs is deterministic on identical bytes, so a
            # differing count between passes only happens from something
            # non-deterministic slipping in (GC/interning edge cases, a
            # lazy-rendered section timing out differently, etc). Whichever
            # pass recovered MORE MCQs is kept -- this guarantees a transient
            # hiccup on the first parse can never silently drop a question.
            recheck = await asyncio.to_thread(parse_mhtml_to_mcqs, html_bytes, "auto-scrape.html")
            recheck_results = recheck["results"]
            context_only = parsed.get("context_only_count", 0)
            if len(recheck_results) != len(results):
                logger.warning(
                    f"[/auto] recheck mismatch (run {run_no}): pass1={len(results)} pass2={len(recheck_results)} -- keeping the larger result set")
                if len(recheck_results) > len(results):
                    results, skipped, total_seen = recheck_results, recheck.get("skipped") or [], recheck.get("total_cards_seen")
                    context_only = recheck.get("context_only_count", 0)

            logger.info(f"[/auto] parsed {len(results)} MCQs from captured HTML (run {run_no}/{run_total}), recheck confirmed")
            if skipped:
                reason_lines = "\n".join(f"  • কার্ড #{ci}: {reason}" for ci, reason in skipped[:10])
                more = f"\n  …আরও {len(skipped)-10}টা" if len(skipped) > 10 else ""
                logger.warning(f"[/auto] {len(skipped)} card(s) skipped during parse (run {run_no}): {skipped}")
                await send_msg(chat_id,
                    f"⚠️ রান {run_no}: HTML-এ মোট {total_seen}টা কার্ড পাওয়া গেছে, কিন্তু {len(skipped)}টা MCQ হিসেবে বসেনি (রিচেক করা হয়েছে):\n{reason_lines}{more}")
            elif total_seen is not None and total_seen != len(results):
                # Cards were present in total_cards_seen's count but the
                # extracted-results count is lower, with NO skip reasons
                # logged. Some of that gap is EXPECTED: parent/passage
                # cards (উদ্দীপক/চিত্র সহ প্রশ্ন) have no options of their
                # own and correctly produce 0 results -- their content
                # gets folded into the nested child MCQ(s) that follow.
                # Only flag+attach debug HTML if the gap ISN'T fully
                # explained by that, i.e. a genuinely unaccounted-for drop.
                unexplained_gap = total_seen - len(results) - context_only
                if unexplained_gap > 0:
                    logger.warning(f"[/auto] UNEXPLAINED card/result gap (run {run_no}): {total_seen} cards seen, {len(results)} MCQs extracted, {context_only} context-only parent(s) accounted for, gap={unexplained_gap} still unexplained, no skip reasons logged")
                    try:
                        await send_document(chat_id, html_bytes, f"debug_captured_{run_no}.html",
                            caption=f"⚠️ রান {run_no}: {total_seen}টা কার্ড পাওয়া গেছে, {context_only}টা passage/context কার্ড (এগুলো নিজে MCQ না, স্বাভাবিক) বাদ দিয়ে {len(results)}টা MCQ বের হয়েছে, তবু {unexplained_gap}টা ব্যাখ্যাহীন পার্থক্য (রিচেক করেও একই ফলাফল)। এই HTML file-টা bot নিজে যা দিয়ে parse করেছে ঠিক তাই -- ডায়াগনস্টিকের জন্য পাঠানো হলো।",
                            mime_type="text/html")
                    except Exception:
                        pass
                else:
                    logger.info(f"[/auto] gap fully explained (run {run_no}): {total_seen} cards = {len(results)} MCQs + {context_only} context-only parent(s), nothing missing")
            else:
                logger.info(f"[/auto] recheck OK (run {run_no}): {len(results)}/{total_seen} cards accounted for, no MCQ dropped")
        except Exception as e:
            logger.error(f"[/auto] HTML parse failed (run {run_no}): {e}")
            await send_msg(chat_id, f"❌ রান {run_no}: MCQ extract ব্যর্থ হয়েছে: {e}")
            return

        if not results:
            # MCQ-format-এ কিছু পাওয়া যায়নি -- ফাইনালি হাল ছাড়ার আগে চেক করি এটা
            # Q&A/CQ ফরম্যাট (চর্চা ক-ভান্ডার/খ-ভান্ডার/CQ) কিনা, ঠিক যেভাবে সরাসরি
            # HTML file পাঠালে bot নিজে থেকে detect করে -- একই power এখন /auto-তেও।
            try:
                qa_data = await asyncio.to_thread(parse_chorcha_file, html_bytes)
            except Exception:
                qa_data = None
            if qa_data and qa_data.get("items"):
                await send_msg(chat_id,
                    f"📋 রান {run_no} ({topic}): এই পেজটা Q&A/CQ ফরম্যাটের (MCQ না), তাই CSV বানানো যায়নি। "
                    f"এই ধরনের কনটেন্টের জন্য PDF বানাতে চাইলে ক্যাপচার করা HTML file-এ reply করে <code>/qpdf</code> দাও।",
                    parse_mode="HTML")
            else:
                await send_msg(chat_id, f"❌ রান {run_no} ({topic}): কোনো MCQ খুঁজে পাওয়া যায়নি।")
            return

        await _final_stage_update(f"📊 CSV তৈরি হচ্ছে... ({len(results)}টা MCQ)")
        csv_bytes = await asyncio.to_thread(results_to_csv_bytes, results)
        safe_title = re.sub(r"[^\w\u0980-\u09FF\-]+", "_", topic)[:50] or f"ATLAS_AutoScrape_{run_no}"

        await _final_stage_update(f"📤 CSV পাঠানো হচ্ছে... ({len(results)}টা MCQ)")
        await send_document(chat_id, csv_bytes, f"ATLAS_{safe_title}.csv",
            caption=f"📚 {topic}\n📝 মোট MCQ: {len(results)}\n⏱️ সময় লেগেছে: {_fmt_secs(time.time() - _start_time)}\n🕐 শুরু: {_fmt_clock(_start_time)} → 🏁 শেষ: {_fmt_clock(time.time())}\n🚀 ATLAS APP (HTML-parse, no AI-vision)"
                    + (f"\n({run_no}/{run_total})" if run_total > 1 else ""),
            mime_type="text/csv")
        sent_any["v"] = True

    from atlas_autoscrape import run_auto_click_sequence
    run_count_for_timeout = sum(1 for l in lines if l.strip() in ("---", "***")) + 1
    # Hard ceiling for the WHOLE /auto flow (all runs combined), so any
    # unforeseen hang -- browser stuck, chorcha.net not responding, a
    # selector looping forever -- can never stall silently forever. Scales
    # with run count since multi-run sequences legitimately take longer.
    overall_timeout_s = 2700 * run_count_for_timeout
    try:
        try:
            html_results = await asyncio.wait_for(
                run_auto_click_sequence(lines, progress_cb=_progress, on_run_complete=_on_run_complete),
                timeout=overall_timeout_s,
            )
        except asyncio.TimeoutError:
            logger.error(f"[/auto] entire flow timed out after {overall_timeout_s}s ({run_count_for_timeout} run(s))")
            if status_msg_id:
                try:
                    await tg_post("deleteMessage", {"chat_id": chat_id, "message_id": status_msg_id})
                except Exception:
                    pass
            await send_msg(chat_id,
                f"❌ {overall_timeout_s}s পার হয়ে গেছে, কাজ আটকে গিয়েছিল — বন্ধ করে দেওয়া হলো। "
                f"যতগুলো run/CSV এর মধ্যে হয়ে গেছে ততগুলো ইতিমধ্যে পাঠানো হয়ে থাকতে পারে (উপরে দেখো)। আবার চেষ্টা করো।")
            return
        except AutoScrapeError as e:
            msg_text = str(e)
            if msg_text.startswith("🛑"):
                await send_msg(chat_id, msg_text)
            else:
                await send_msg(chat_id, f"❌ {e}")
            return
        except Exception as e:
            logger.error(f"[/auto] navigation failed: {e}")
            await send_msg(chat_id, f"❌ Navigation ব্যর্থ হয়েছে: {e}")
            return
    finally:
        clear_active_job(chat_id)
        if _auto_uid is not None:
            _USER_LAST_STATUS.pop(_auto_uid, None)

    sent_any = sent_any["v"]

    if status_msg_id:
        try:
            await tg_post("deleteMessage", {"chat_id": chat_id, "message_id": status_msg_id})
        except Exception:
            pass

    if not sent_any:
        await send_msg(chat_id, "❌ কোনো run থেকেই MCQ পাওয়া যায়নি।")


async def handle_qbm(msg: dict):
    """
    /qbm -p (pages) -c (channel) -m (topic) -t (thread_id)
    PDF-এ থাকা EXISTING MCQ extract করে (নতুন MCQ বানায় না)।
    """
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _handle_qbm_impl(msg)


async def _handle_qbm_impl(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    uname = msg["from"].get("first_name", "User")
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not (reply.get("document") or reply.get("photo")):
        await send_msg(chat_id,
            "❌ PDF বা Image-এ reply করে /qbm দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/qbm -p 1-5 -c @channel -m \"Topic\" -t group_id</code>\n\n"
            "📌 এই ফিচার PDF/Image-এ আগে থেকে থাকা MCQ extract করে (নতুন বানায় না)\n"
            "📌 -p = page range, PDF-only (না দিলে সব page)\n"
            "📌 -c = channel id (না দিলে list দেখাবে)\n"
            "📌 -m = topic name\n"
            "📌 -t = topic/thread id (group হলে)"
        )
        return

    is_image_reply = bool(reply.get("photo")) or (
        reply.get("document") and not reply["document"].get("file_name", "").lower().endswith(".pdf")
        and (reply["document"].get("mime_type", "").startswith("image/"))
    )

    if reply.get("document") and not is_image_reply and not reply["document"].get("file_name", "").lower().endswith(".pdf"):
        await send_msg(chat_id, "❌ শুধু PDF বা Image file support করে!")
        return

    params = _parse_pdfm_params(text)
    topic = params["topic"] or "🌟ATLAS Question Bank"
    page_range = params["page_range"]
    channel_id = params["channel_id"]
    thread_id = params["thread_id"]

    if is_image_reply:
        if reply.get("photo"):
            file_id = reply["photo"][-1]["file_id"]
            file_unique_id = reply["photo"][-1].get("file_unique_id")
        else:
            file_id = reply["document"]["file_id"]
            file_unique_id = reply["document"].get("file_unique_id")
        file_name = reply.get("document", {}).get("file_name", "image.jpg")
    else:
        file_id = reply["document"]["file_id"]
        file_unique_id = reply["document"].get("file_unique_id")
        file_name = reply["document"].get("file_name", "document.pdf")

    _is_cache_hit = (not is_image_reply) and (
        file_id in _pdf_bytes_cache
        or (file_unique_id and _pdf_unique_id_index.get(file_unique_id) in _pdf_bytes_cache)
    )
    status_r = await send_msg(chat_id, ("✅ Cached PDF ব্যবহার হচ্ছে...\n📄 " + file_name) if _is_cache_hit else
        ("⏳ " + ("Image" if is_image_reply else "PDF") + f" download হচ্ছে...\n📄 {file_name}\n[░░░░░░░░░░ 0%]"))
    status_msg_id = status_r.get("result", {}).get("message_id")

    _last_pct = {"v": -1}
    _dl_start = time.time()
    def _dl_progress_pdf(done, total):
        if not status_msg_id or not total:
            return
        pct = int(done * 100 / total)
        if pct - _last_pct["v"] < 10 and pct != 100:
            return
        _last_pct["v"] = pct
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        label = "Image" if is_image_reply else "PDF"
        elapsed = time.time() - _dl_start
        eta_txt = ""
        if pct > 0 and pct < 100:
            eta_s = int(elapsed * (100 - pct) / pct)
            eta_txt = f" | ETA {eta_s}s"
        _spawn_task(edit_msg(chat_id, status_msg_id, f"⏳ {label} download হচ্ছে...\n📄 {file_name}\n[{bar} {pct}%{eta_txt}]"))

    try:
        if is_image_reply:
            img_bytes = await download_tg_file(file_id, progress_cb=_dl_progress_pdf, chat_id=chat_id, message_id=reply["message_id"])
            from PIL import Image as PILImage
            img = PILImage.open(BytesIO(img_bytes))
            pages = [(1, img)]
        else:
            pdf_bytes = await _download_pdf_cached(file_id, progress_cb=_dl_progress_pdf, chat_id=chat_id,
                                                    message_id=reply["message_id"], file_unique_id=file_unique_id)
            ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
            if not ok:
                await send_msg(chat_id, pages)
                return

            # OCR fallback if truly no pages/images came back (scanned/corrupt PDF).
            # NOTE: previous check `len(str(pages[0][1])) < 100` was always true (PIL repr
            # string is always short) so this branch fired on every PDF and ignored
            # page_range — fixed to only trigger on genuine empty extraction, and to
            # respect page_range when it does.
            if not pages:
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id, "🔍 OCR Scanning (scanned PDF detected)...")
                try:
                    from pdf2image import convert_from_bytes
                    if page_range:
                        parts = str(page_range).split("-")
                        first = int(parts[0])
                        last = int(parts[1]) if len(parts) > 1 else first
                        ocr_images = await asyncio.to_thread(
                            convert_from_bytes, pdf_bytes, dpi=150, first_page=first, last_page=last
                        )
                        pages = list(zip(range(first, last + 1), ocr_images))
                    else:
                        ocr_images = await asyncio.to_thread(convert_from_bytes, pdf_bytes, dpi=150)
                        pages = list(enumerate(ocr_images, 1))
                except Exception as e:
                    logger.warning(f"[QBM] OCR fallback failed: {e}")

        if not pages:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ MCQ Extraction শুরু হচ্ছে...")

        # ── MCQ Extraction ALWAYS runs first (3-call pipeline, per page) ──
        # Channel selection + CSV file generation happen only AFTER extraction
        # is fully complete, so the person picks a channel already knowing
        # exactly how many MCQs were found.
        extracted_pages = await qbm_extract_all_pages(
            chat_id, pages, topic, file_name, status_msg_id, file_id=file_id
        )

        if not channel_id:
            channels = await db_get_channels()
            if not channels:
                await process_qbm_pages(chat_id, uid, uname, extracted_pages, topic,
                    channel_id, True, file_name, status_msg_id, thread_id, skip_extract=True)
                return

            app.state.qbm_cache = getattr(app.state, "qbm_cache", {})
            app.state.qbm_cache[f"qbm_img_{uid}"] = extracted_pages
            _cap_page_cache(app.state.qbm_cache)
            await sb_exec(lambda: sb.table("quiz_sessions").upsert({
                "key": f"qbm_pending_{uid}",
                "data": json.dumps({
                    "topic": topic, "file_name": file_name,
                    "status_msg_id": status_msg_id, "thread_id": thread_id,
                    "file_id": file_id, "page_range": page_range
                }),
                "updated_at": int(time.time())
            }).execute())

            total_mcq_found = sum(len(mcqs) for _, _, mcqs in extracted_pages)
            page_breakdown = "\n".join(
                f"✅ Page {fmt_page(p)}: {len(mcqs)} MCQ ✓" for p, _, mcqs in extracted_pages
            )

            # Extraction শেষ হওয়ার সাথে সাথেই CSV auto-send — channel select
            # এর জন্য অপেক্ষা করতে হবে না, সব MCQ সাথে সাথেই CSV আকারে হাতে পেয়ে যাবে
            if total_mcq_found:
                _missing_exp_qbm = [m for _, _, mcqs in extracted_pages for m in mcqs if not (m.get("explanation") or "").strip()]
                if _missing_exp_qbm:
                    try:
                        await _ai_generate_all_explanations(_missing_exp_qbm)
                    except Exception as e:
                        logger.warning(f"[QBM] fallback explanation fill failed: {e}")
                import io as _io_qbm, csv as _csv_mod_qbm
                _buf_qbm = _io_qbm.StringIO()
                _w_qbm = _csv_mod_qbm.writer(_buf_qbm)
                _w_qbm.writerow(["questions", "option1", "option2", "option3", "option4", "option5",
                                  "answer", "explanation", "type", "section"])
                _ans_map_qbm = {"A": "1", "B": "2", "C": "3", "D": "4"}
                for _, _, mcqs in extracted_pages:
                    for m in mcqs:
                        opts = m.get("options", ["", "", "", ""])
                        _w_qbm.writerow([
                            m.get("question", ""), opts[0] if len(opts) > 0 else "",
                            opts[1] if len(opts) > 1 else "", opts[2] if len(opts) > 2 else "",
                            opts[3] if len(opts) > 3 else "", opts[4] if len(opts) > 4 else "",
                            _ans_map_qbm.get(m.get("answer", "A"), "1"),
                            _strip_img_tag(m.get("explanation", "")), "1", "1"
                        ])
                await send_document(chat_id, _buf_qbm.getvalue().encode("utf-8"),
                    f"{topic}_QBM.csv",
                    caption=f"📋 {topic} — {total_mcq_found} MCQ (Extracted)",
                    mime_type="text/csv")

            kb = {"inline_keyboard": []}
            for ch in channels:
                ch_id = ch.get("channel_id", "")
                ch_name = ch.get("channel_name", ch_id)
                kb["inline_keyboard"].append([{
                    "text": f"📢 {ch_name}",
                    "callback_data": f"qbmch_{ch_id}_{uid}"
                }])
            kb["inline_keyboard"].append([{
                "text": "📄 CSV Only",
                "callback_data": f"qbmch_csv_{uid}"
            }])
            await send_msg(chat_id,
                "✅ <b>Extraction Complete!</b>\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"📝 Total MCQ: {total_mcq_found}  |  📋 Pages: {len(pages)}\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{page_breakdown}\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🎯 Topic: {topic}\n\nChannel select করো:",
                reply_markup=kb
            )
            return

        await process_qbm_pages(chat_id, uid, uname, extracted_pages, topic,
            channel_id, False, file_name, status_msg_id, thread_id, skip_extract=True)

    except Exception as e:
        logger.error(f"[QBM] Error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)


async def _post_topic_groups_to_channel(channel_id, topic_groups: list, thread_id: int = None):
    """Posts topic_groups (from _topic_group_mcqs / _unmesh_group_mcqs) as
    live Telegram polls directly to a channel — one header message per
    topic (name + MCQ count), followed by that topic's polls in order,
    followed by an end message (replying to the header) with 3 buttons —
    Poll Again, Quiz Solve, Website Exam — same as /csv. Channel gets a
    score-asking prompt in the end message; group/thread does not.
    Used by /topic and /unmesh when -c <channel_id> is given, instead of
    the default CSV-file output."""
    settings = await db_get_settings()
    tag = settings.get("tag", "")
    exp_footer = settings.get("exp_footer", "")
    chat_type = await _get_chat_type(channel_id)
    ask_score = chat_type == "channel"
    bot_un = await get_bot_username()
    total_polls = 0
    for name, mcqs in topic_groups:
        header_text = f"📂 {name}\n💎 MCQ: {len(mcqs)}"
        header_data = {"chat_id": channel_id, "text": header_text}
        if thread_id:
            header_data["message_thread_id"] = thread_id
        header_r = await tg_post("sendMessage", header_data)
        header_msg_id = header_r.get("result", {}).get("message_id") if header_r.get("ok") else None
        for mcq in mcqs:
            opts = mcq.get("options", [])[:4]
            ans_idx = {"A": 0, "B": 1, "C": 2, "D": 3}.get(mcq.get("answer", "A"), 0)
            q_text = mcq.get("question", "")
            if tag:
                q_text = f"{tag}\n\n{q_text}"
            exp = mcq.get("explanation", "")
            if exp_footer:
                exp = f"{exp}\n{exp_footer}"
            poll_r = {"ok": False}
            for _attempt in range(3):
                poll_r = await send_poll(
                    channel_id, q_text, opts, ans_idx,
                    explanation=exp,
                    reply_to_message_id=header_msg_id,
                    message_thread_id=thread_id
                )
                if poll_r.get("ok"):
                    break
                await asyncio.sleep(2)
            total_polls += 1
            await asyncio.sleep(1.0)

        # Polls শেষে: cache করে Style1 PDF (caption + 4 button) পাঠাও,
        # header-কে reply করে। তারপর score-ask আলাদা message (channel only),
        # PDF-msg কে reply করে — /csv এর মতোই structure।
        cache_id = gen_session_id()
        await db_save_mcq_cache(cache_id, cache_id, 0, name, mcqs)

        pdf_bytes = await _generate_style1_pdf_guaranteed(mcqs, name, channel_id)
        pdf_msg_id = header_msg_id
        if pdf_bytes:
            safe_title = re.sub(r"[^\w\u0980-\u09FF\-]+", "_", name)[:50] or "ATLAS_Sheet"
            btn_kb = await _csv_pre_buttons(cache_id)
            doc_r = await send_document(
                channel_id, pdf_bytes, f"{safe_title}_style1.pdf",
                caption=csv_get_pdf_caption(name),
                message_thread_id=thread_id,
                reply_to_message_id=header_msg_id
            )
            if doc_r and doc_r.get("ok"):
                doc_msg_id = doc_r.get("result", {}).get("message_id")
                if doc_msg_id:
                    pdf_msg_id = doc_msg_id
                    try:
                        await tg_post("editMessageReplyMarkup", {
                            "chat_id": channel_id, "message_id": doc_msg_id,
                            "reply_markup": btn_kb
                        })
                    except Exception as e:
                        logger.warning(f"[TOPIC-C] PDF button attach failed: {e}")

        end_text = csv_get_ending_message(name, len(mcqs), ask_score=ask_score)
        end_data = {
            "chat_id": channel_id,
            "text": end_text,
            "disable_web_page_preview": True,
        }
        if pdf_msg_id:
            end_data["reply_to_message_id"] = pdf_msg_id
        if thread_id:
            end_data["message_thread_id"] = thread_id
        for _end_attempt in range(3):
            end_r = await tg_post("sendMessage", end_data)
            if end_r.get("ok"):
                break
            await asyncio.sleep(2)
    return total_polls


async def handle_topic(msg: dict):
    """/topic -p (pages) — same arg style as /pdf/qbm. Extracts existing MCQ
    like /qbm, but ALSO detects topic boundaries via each MCQ's printed
    serial number resetting to 1 (or dropping) and/or a changed topic
    heading. Sends ONE separate CSV per detected topic, named after the
    topic heading text."""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _handle_topic_impl(msg)


async def _handle_topic_impl(msg: dict):
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ PDF-এ reply করে /topic দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/topic -p 1-10</code>\n\n"
            "📌 Page-এ থাকা MCQ extract করে (নতুন বানায় না), কিন্তু serial number/topic heading "
            "দেখে আলাদা টপিক ধরে প্রতিটার জন্য আলাদা CSV পাঠায়।\n"
            "📌 -p = page range (না দিলে সব page)\n"
            "📌 -c <channel_id> = দিলে CSV না, প্রতি টপিকের নামসহ header দিয়ে channel-এ সরাসরি poll পাঠাবে"
        )
        return

    file_name = reply["document"].get("file_name", "document.pdf")
    if not file_name.lower().endswith(".pdf"):
        await send_msg(chat_id, "❌ শুধু PDF file support করে!")
        return

    file_id = reply["document"]["file_id"]
    file_unique_id = reply["document"].get("file_unique_id")
    params = _parse_pdfm_params(text)
    page_range = params["page_range"]
    topic_channel_id = params["channel_id"]
    topic_thread_id = params["thread_id"]

    status_r = await send_msg(chat_id, f"⏳ PDF download হচ্ছে...\n📄 {file_name}")
    status_msg_id = status_r.get("result", {}).get("message_id") if status_r.get("ok") else None

    try:
        pdf_bytes = await _download_pdf_cached(file_id, chat_id=chat_id,
                                                message_id=reply["message_id"], file_unique_id=file_unique_id)
        ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
        if not ok:
            await send_msg(chat_id, pages)
            return
        if not pages:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id, f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ MCQ Extraction শুরু হচ্ছে (topic detect সহ)...")

        extracted_pages = await qbm_extract_all_pages(
            chat_id, pages, "Topic Extract", file_name, status_msg_id,
            extractor=_topic_extract_from_image, file_id=file_id
        )

        total_mcq_found = sum(len(mcqs) for _, _, mcqs in extracted_pages)
        if not total_mcq_found:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ কোনো MCQ পাওয়া যায়নি!")
            return

        topic_groups = _topic_group_mcqs(extracted_pages)

        _missing_exp = [m for _, mcqs in topic_groups for m in mcqs if len((m.get("explanation") or "").strip()) < 80]
        if _missing_exp:
            try:
                await _ai_generate_all_explanations(_missing_exp)
            except Exception as e:
                logger.warning(f"[TOPIC] explanation fill failed: {e}")

        if status_msg_id:
            breakdown = "\n".join(f"📂 {name}: {len(mcqs)} MCQ" for name, mcqs in topic_groups)
            next_step = "channel-এ poll পাঠানো হচ্ছে..." if topic_channel_id else "CSV পাঠানো হচ্ছে..."
            await edit_msg(chat_id, status_msg_id,
                f"✅ Extraction Complete!\n📝 Total MCQ: {total_mcq_found} | 📂 Topics: {len(topic_groups)}\n\n{breakdown}\n\n⏳ {next_step}")

        if topic_channel_id:
            total_polls = await _post_topic_groups_to_channel(topic_channel_id, topic_groups, topic_thread_id)
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id,
                    f"✅ সম্পন্ন! মোট {total_mcq_found} MCQ, {len(topic_groups)}টি টপিকে ভাগ করে {total_polls}টি poll channel-এ পাঠানো হয়েছে।")
            return

        _ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
        import io as _io_topic, csv as _csv_topic
        _running_count = 0
        _cmd_msg_id = msg.get("message_id")
        for name, mcqs in topic_groups:
            buf = _io_topic.StringIO()
            w = _csv_topic.writer(buf)
            w.writerow(["questions", "option1", "option2", "option3", "option4", "option5",
                        "answer", "explanation", "type", "section"])
            for m in mcqs:
                opts = m.get("options", ["", "", "", ""])
                w.writerow([
                    m.get("question", ""), opts[0] if len(opts) > 0 else "",
                    opts[1] if len(opts) > 1 else "", opts[2] if len(opts) > 2 else "",
                    opts[3] if len(opts) > 3 else "", opts[4] if len(opts) > 4 else "",
                    _ans_map.get(m.get("answer", "A"), "1"),
                    _strip_img_tag(m.get("explanation", "")), "1", "1"
                ])
            safe_name = re.sub(r'[\\/:*?"<>|]', '_', name).strip() or "Topic"
            range_start = _running_count + 1
            range_end = _running_count + len(mcqs)
            _running_count = range_end
            _pg_nums = sorted({m.get("_page_num") for m in mcqs if m.get("_page_num") is not None})
            if _pg_nums:
                page_range_text = f"{_pg_nums[0]}" if len(_pg_nums) == 1 else f"{_pg_nums[0]}–{_pg_nums[-1]}"
            else:
                page_range_text = "N/A"
            await send_document(chat_id, buf.getvalue().encode("utf-8"),
                f"{safe_name}.csv",
                caption=(f"📂 <code>{_html_escape(_clean_topic_name_for_copy(name))}</code>\n"
                         f"📄 PDF Page: {page_range_text}\n"
                         f"🔢 MCQ Range: {range_start}–{range_end}\n"
                         f"💎 Total: {len(mcqs)}"),
                mime_type="text/csv",
                reply_to_message_id=_cmd_msg_id)

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ সম্পন্ন! মোট {total_mcq_found} MCQ, {len(topic_groups)}টি টপিকে ভাগ করে CSV পাঠানো হয়েছে।")

    except Exception as e:
        logger.error(f"[TOPIC] Error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)


async def handle_unmesh(msg: dict):
    """/unmesh -p (pages) — same arg style as /topic. Extracts existing MCQ
    like /topic, but detects topic boundaries via the WHITE-bg + BOLD BLACK
    text + preceding black-circle-with-white-star(s) heading style, instead
    of /topic's black-background banner bar style. Sends ONE separate CSV
    per detected topic, named after the topic heading text."""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _handle_unmesh_impl(msg)


async def _handle_unmesh_impl(msg: dict):
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ PDF-এ reply করে /unmesh দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/unmesh -p 1-10</code>\n\n"
            "📌 Page-এ থাকা MCQ extract করে (নতুন বানায় না), কিন্তু ডাবল-আইকন "
            "heading (⚫★, 📂📂, ⭐⭐, 🔵🔵 — যেকোনো icon দুইবার পাশাপাশি + সাদা background + bold black text) দেখে আলাদা টপিক ধরে প্রতিটার জন্য আলাদা CSV পাঠায়।\n"
            "📌 -p = page range (না দিলে সব page)"
        )
        return

    file_name = reply["document"].get("file_name", "document.pdf")
    if not file_name.lower().endswith(".pdf"):
        await send_msg(chat_id, "❌ শুধু PDF file support করে!")
        return

    file_id = reply["document"]["file_id"]
    file_unique_id = reply["document"].get("file_unique_id")
    params = _parse_pdfm_params(text)
    page_range = params["page_range"]
    unmesh_channel_id = params["channel_id"]
    unmesh_thread_id = params["thread_id"]

    status_r = await send_msg(chat_id, f"⏳ PDF download হচ্ছে...\n📄 {file_name}")
    status_msg_id = status_r.get("result", {}).get("message_id") if status_r.get("ok") else None

    try:
        pdf_bytes = await _download_pdf_cached(file_id, chat_id=chat_id,
                                                message_id=reply["message_id"], file_unique_id=file_unique_id)
        ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
        if not ok:
            await send_msg(chat_id, pages)
            return
        if not pages:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id, f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ MCQ Extraction শুরু হচ্ছে (⚫★ topic detect সহ)...")

        extracted_pages = await qbm_extract_all_pages(
            chat_id, pages, "Unmesh Extract", file_name, status_msg_id,
            extractor=_unmesh_extract_from_image, file_id=file_id
        )

        total_mcq_found = sum(
            1 for _, _, mcqs in extracted_pages for m in mcqs if "trailing_topic_marker" not in m
        )
        if not total_mcq_found:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ কোনো MCQ পাওয়া যায়নি!")
            return

        topic_groups = _unmesh_group_mcqs(extracted_pages)

        _missing_exp = [m for _, mcqs in topic_groups for m in mcqs if len((m.get("explanation") or "").strip()) < 80]
        if _missing_exp:
            try:
                await _ai_generate_all_explanations(_missing_exp)
            except Exception as e:
                logger.warning(f"[UNMESH] explanation fill failed: {e}")

        if status_msg_id:
            breakdown = "\n".join(f"📂 {name}: {len(mcqs)} MCQ" for name, mcqs in topic_groups)
            next_step = "channel-এ poll পাঠানো হচ্ছে..." if unmesh_channel_id else "CSV পাঠানো হচ্ছে..."
            await edit_msg(chat_id, status_msg_id,
                f"✅ Extraction Complete!\n📝 Total MCQ: {total_mcq_found} | 📂 Topics: {len(topic_groups)}\n\n{breakdown}\n\n⏳ {next_step}")

        if unmesh_channel_id:
            total_polls = await _post_topic_groups_to_channel(unmesh_channel_id, topic_groups, unmesh_thread_id)
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id,
                    f"✅ সম্পন্ন! মোট {total_mcq_found} MCQ, {len(topic_groups)}টি টপিকে ভাগ করে {total_polls}টি poll channel-এ পাঠানো হয়েছে।")
            return

        _ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
        import io as _io_unmesh, csv as _csv_unmesh
        _running_count = 0
        _cmd_msg_id = msg.get("message_id")
        for name, mcqs in topic_groups:
            buf = _io_unmesh.StringIO()
            w = _csv_unmesh.writer(buf)
            w.writerow(["questions", "option1", "option2", "option3", "option4", "option5",
                        "answer", "explanation", "type", "section"])
            for m in mcqs:
                opts = m.get("options", ["", "", "", ""])
                w.writerow([
                    m.get("question", ""), opts[0] if len(opts) > 0 else "",
                    opts[1] if len(opts) > 1 else "", opts[2] if len(opts) > 2 else "",
                    opts[3] if len(opts) > 3 else "", opts[4] if len(opts) > 4 else "",
                    _ans_map.get(m.get("answer", "A"), "1"),
                    _strip_img_tag(m.get("explanation", "")), "1", "1"
                ])
            safe_name = re.sub(r'[\\/:*?"<>|]', '_', name).strip() or "Topic"
            range_start = _running_count + 1
            range_end = _running_count + len(mcqs)
            _running_count = range_end
            _pg_nums = sorted({m.get("_page_num") for m in mcqs if m.get("_page_num") is not None})
            if _pg_nums:
                page_range_text = f"{_pg_nums[0]}" if len(_pg_nums) == 1 else f"{_pg_nums[0]}–{_pg_nums[-1]}"
            else:
                page_range_text = "N/A"
            await send_document(chat_id, buf.getvalue().encode("utf-8"),
                f"{safe_name}.csv",
                caption=(f"📂 <code>{_html_escape(_clean_topic_name_for_copy(name))}</code>\n"
                         f"📄 PDF Page: {page_range_text}\n"
                         f"🔢 MCQ Range: {range_start}–{range_end}\n"
                         f"💎 Total: {len(mcqs)}"),
                mime_type="text/csv",
                reply_to_message_id=_cmd_msg_id)

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ সম্পন্ন! মোট {total_mcq_found} MCQ, {len(topic_groups)}টি টপিকে ভাগ করে CSV পাঠানো হয়েছে।")

    except Exception as e:
        logger.error(f"[UNMESH] Error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)


# ============================================================
# /onu — same as /qbm (existing-MCQ extraction) but with STRICT inclusion:
#   ONLY MCQs whose QUESTION text has a YELLOW HIGHLIGHT mark are kept — this
#   is the sole indicator (checked via ONU_EXTRACT_PROMPT / yellow_highlight
#   field). Additionally SKIPS (as before):
#   1) any MCQ that has an image attached to a question/option/explanation
#      (opt_bboxes present, or an <img> tag already embedded)
#   2) "roman/serial-combination" MCQs — i.e. উদ্দীপক-style questions where
#      the options are combinations of numbered/roman statements, e.g.
#      "A) i, ii  B) i, iii  C) ii, iii  D) i, ii, iii" or "A) I ও II" etc.
#      These need the statement list to make sense and don't stand alone.
# ============================================================

_ROMAN_COMBO_OPTION_RE = re.compile(
    r'^\s*(?:[iIvVxX]{1,4}\s*(?:[,ওoO&]|and)\s*)+[iIvVxX]{1,4}\s*$'
    r'|^\s*(?:[১২৩৪]\s*(?:[,ওoO&]|and)\s*)+[১২৩৪]\s*$'
    r'|^\s*[iIvVxX]{1,4}\s*(?:,\s*[iIvVxX]{1,4}\s*)+$'
)

def _onu_mcq_has_image(m: dict) -> bool:
    """True if this MCQ has any image attached — question diagram (qsn_bbox),
    or an <img> tag already embedded in question/explanation."""
    if m.get("qsn_bbox"):
        return True
    q = m.get("question", "") or ""
    if "<img" in q.lower():
        return True
    exp = m.get("explanation", "") or ""
    if "<img" in exp.lower():
        return True
    return False

def _onu_mcq_is_roman_combo(m: dict) -> bool:
    """True if this MCQ's options look like i/ii/iii or ১/২/৩ style
    roman-numeral / serial-number COMBINATIONS (a উদ্দীপক-dependent MCQ that
    doesn't stand alone without the numbered statement list above it)."""
    opts = m.get("options")
    if isinstance(opts, dict):
        opt_values = list(opts.values())
    elif isinstance(opts, list):
        opt_values = opts
    else:
        return False
    if len(opt_values) < 2:
        return False
    hits = sum(1 for o in opt_values if _ROMAN_COMBO_OPTION_RE.match(str(o).strip()))
    # If most/all options match the roman-combo pattern, treat as a
    # উদ্দীপক-combination MCQ and skip it.
    return hits >= max(2, len(opt_values) - 1)

def _onu_filter_mcqs(mcqs: list):
    """Returns (kept_list, reason_counts dict) so callers can show the
    exact root-cause breakdown of why MCQs were dropped."""
    kept = []
    reasons = {"no_highlight": 0, "has_image": 0, "roman_combo": 0}
    for m in mcqs:
        if not m.get("yellow_highlight"):
            reasons["no_highlight"] += 1
            continue
        if _onu_mcq_has_image(m):
            reasons["has_image"] += 1
            continue
        if _onu_mcq_is_roman_combo(m):
            reasons["roman_combo"] += 1
            continue
        kept.append(m)
    return kept, reasons


# ── /onu highlight-detection extraction prompt ──
# Only MCQs whose QUESTION text has a yellow highlight marking are kept.
# This is the SOLE indicator for /onu — no other rule decides inclusion.
# Kept intentionally SHORT (not built on QBM_EXTRACT_PROMPT_DEFAULT) so it
# fits Groq's 8000 TPM budget alongside a full-quality image -- /onu only
# needs: extract existing MCQs as-is, detect yellow highlight, detect the
# marked answer (red circle/box around an option). No passage handling, no
# math formatting, no explanation-generation rules -- those aren't part of
# /onu's job and were only bloating the prompt for QBM's use case.
ONU_EXTRACT_PROMPT = """STRICT MCQ EXTRACTOR — HIGHLIGHTED ONLY. Scan every MCQ block on this page (question + 4 options), one block at a time. For EACH block, look specifically at the pixels directly behind its question line AND its 4 options. If ANY yellow marker-pen color OR ANY green marker-pen color is visible there (a light/pale/faint tint of either still counts, not just bright/saturated), INCLUDE this MCQ in the output — this is a MUST-TAKE rule, never miss a highlighted MCQ even if faint. If the background is plain white/no-color for this block, SKIP it entirely — do NOT include it in the output at all. Do not assume based on other MCQs on the page — each block gets its own independent check, since a page can mix highlighted and non-highlighted blocks. Never invent new MCQs, exact order, exact wording (Bangla stays Bangla, English stays English). 0 highlighted MCQs → return [].

For each INCLUDED MCQ, find the RED-MARKED option: the option with a RED CIRCLE or RED BOX drawn around its letter/text (A/B/C/D by position, 1st option=A...4th=D). This red mark is ONLY a visual pointer to what someone marked — it is NOT automatically correct. You must INDEPENDENTLY VERIFY using your own subject knowledge which option is actually, factually correct:
- If the red-marked option IS the factually correct answer → output that as "answer", set "marked_answer_wrong":false.
- If the red-marked option is NOT the factually correct answer (the mark is wrong) → output the ACTUALLY CORRECT option as "answer" (not the red-marked one), set "marked_answer_wrong":true, and in the explanation clearly state the red-marked option was wrong and give the correct one.
- If no red mark is visible at all, determine the correct answer purely from subject knowledge, set "marked_answer_wrong":false.

Also write a short explanation (1-2 sentences, Bangla if the MCQ is in Bangla) for why the correct answer is correct — from any ব্যাখ্যা text physically printed on the page near this MCQ if present, otherwise from your own knowledge of the subject. If marked_answer_wrong is true, the explanation MUST also mention the marked option was incorrect and state the correct one.

OUTPUT FORMAT — ONLY valid JSON array containing ONLY the highlighted MCQs, nothing else:
[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","marked_answer_wrong":false,"explanation":"...","yellow_highlight":true}]"""

# Gemini-only variant of the same prompt — used ONLY when the call actually
# goes to Gemini (no TPM ceiling to protect there, unlike Groq's 8000 TPM
# pool), so this can afford to be far more explicit/step-by-step about the
# highlight check without risking a 413/429 the way the short Groq prompt
# has to. Same output contract (identical JSON shape) as ONU_EXTRACT_PROMPT
# so nothing downstream (_qbm_parse_json, dedup, verify/repair pipeline)
# needs to know or care which prompt variant produced the data — this is
# purely a Gemini-side accuracy upgrade, not a pipeline change.
ONU_EXTRACT_PROMPT_GEMINI = """STRICT MCQ EXTRACTOR — HIGHLIGHTED ONLY, with careful visual highlight detection. Never invent new MCQs. 0 highlighted MCQs → return [].

STEP 1 — First, list every MCQ block on the page in order (question + its 4 options), without judging highlight yet.

STEP 2 — Now go back through that list ONE MCQ AT A TIME and, for EACH one individually, zoom your attention onto ONLY the background area directly behind that MCQ's question line and its 4 options (ignore the rest of the page while judging this one block):
   - Is there ANY yellow marker/highlighter tint behind this specific block? (bright yellow, pale yellow, faded yellow — all count)
   - Is there ANY green marker/highlighter tint behind this specific block? (bright green, pale green, faded green — all count)
   - If either is present, even faintly, this block IS highlighted — KEEP it for the output. This is a MUST-TAKE rule — never skip a highlighted MCQ even by mistake.
   - If the background is genuinely plain white/uncolored paper behind THIS block, this block is NOT highlighted — DROP it, do not include it in the output at all.
   - A page can legitimately mix highlighted and non-highlighted blocks — never copy the previous block's verdict for the next one; judge each block completely independently, as if it were the only MCQ on the page.
   - Faint/light highlighter marks are the most commonly missed case — when in doubt about a pale tint, look again before deciding it's not highlighted.

STEP 3 — For each KEPT (highlighted) MCQ, find the RED-MARKED option: the option with a RED CIRCLE or RED BOX drawn around its letter/text (A/B/C/D by position, 1st option=A...4th=D). This red mark only shows what someone marked — it can be WRONG. Independently verify with your own subject knowledge which option is actually, factually correct:
   - Red-marked option IS factually correct → "answer" = that option, "marked_answer_wrong":false.
   - Red-marked option is NOT factually correct → "answer" = the ACTUALLY correct option (ignore the wrong red mark), "marked_answer_wrong":true.
   - No red mark visible at all → determine correct answer from subject knowledge, "marked_answer_wrong":false.

STEP 4 — For each KEPT MCQ, write a short explanation (1-2 sentences, Bangla if the MCQ is in Bangla) for why the correct answer is correct — use any ব্যাখ্যা text physically printed on the page near this MCQ if present, otherwise use your own knowledge of the subject. If marked_answer_wrong is true, the explanation MUST also state the red-marked option was wrong and give the correct one.

OUTPUT FORMAT — ONLY valid JSON array of the KEPT (highlighted) MCQs only, exact order, exact wording (Bangla stays Bangla, English stays English), nothing else, no commentary, no markdown fences:
[{"question":"...","options":{"A":"...","B":"...","C":"...","D":"..."},"answer":"A/B/C/D","marked_answer_wrong":false,"explanation":"...","yellow_highlight":true}]"""




async def _onu_call1_extract(img) -> list:
    """Same as _qbm_call1_extract but uses ONU_EXTRACT_PROMPT (adds yellow_highlight field, which covers yellow OR green marker color).
    Gemini primary / Groq fallback (matches /qbm's provider order) -- Gemini
    generally reads highlight color/marks more reliably than Groq's vision
    model, so it's tried first; Groq only kicks in if Gemini fails/is
    exhausted, same fallback order as the rest of the pipeline."""
    try:
        gem = await _qbm_gemini_extract(img, ONU_EXTRACT_PROMPT_GEMINI)
        out = _qbm_dedup_list(gem) if gem else []
        for m in out:
            m["_provider"] = "Gemini"
        if out:
            return out
        txt = await _qbm_groq_call(img, ONU_EXTRACT_PROMPT)
        result = _qbm_parse_json(txt) if txt else []
        if result:
            out = _qbm_dedup_list(result)
            for m in out:
                m["_provider"] = "Groq"
            return out
        or_txt = await _qbm_openrouter_call(img, ONU_EXTRACT_PROMPT)
        result3 = _qbm_parse_json(or_txt) if or_txt else []
        out = _qbm_dedup_list(result3)
        for m in out:
            m["_provider"] = "OpenRouter"
        return out
    except Exception as e:
        logger.warning(f"[ONU Call1] failed: {e}")
        return []


async def _onu_verify_pass(img, mcqs: list) -> list:
    """/onu-ONLY verify pass — fully independent from QBM's miss-check
    pipeline (_qbm_call2_miss_check). /onu never needs QBM's "find MCQs
    Call1 missed" logic, since a missed MCQ that also happens to be
    highlighted would simply not exist in call1 to begin with, and /onu's
    filter already drops anything without yellow_highlight -- so there's
    nothing for a miss-check pass to usefully add here, only risk (it can
    add/rewrite/split MCQs from a codepath that has no concept of the
    yellow_highlight field).

    This pass instead just re-confirms, for the SAME list Call1 already
    found: option text accuracy, answer-letter correctness, and exact
    source wording -- a light proofreading pass, never adding or removing
    MCQs. yellow_highlight is carried through untouched (same list, same
    order, same length always) so there is no restore/re-map step needed
    anywhere in this path."""
    if not mcqs:
        return mcqs
    try:
        mcq_json = json.dumps([{k: v for k, v in m.items() if k in ("question", "options", "answer", "explanation")} for m in mcqs], ensure_ascii=False)
        prompt = f"""Re-check this already-extracted MCQ list against the page image ONE more time. Do NOT add or remove any MCQ -- output exactly {len(mcqs)} items, same order.

For each MCQ, verify against the image:
- question and option text match the source exactly (fix only if you spot a typo/OCR error)
- answer letter is correct (re-check the marked option: red circle/box, or other clear mark)
- explanation is a short, correct 1-2 sentence reason for the answer (fix if wrong/missing; keep Bangla if the MCQ is Bangla)

EXISTING LIST:
{mcq_json}

OUTPUT — ONLY a JSON array of exactly {len(mcqs)} items, same order, corrected if needed:
[{{"question":"...","options":{{"A":"...","B":"...","C":"...","D":"..."}},"answer":"A/B/C/D","explanation":"..."}}]"""
        txt = await _qbm_gemini_raw(img, prompt)
        if not txt:
            txt = await _qbm_groq_call(img, prompt)
        if not txt:
            txt = await _qbm_openrouter_call(img, prompt)
        if not txt:
            return mcqs  # verify failed entirely -- keep Call1's result as-is rather than losing highlighted MCQs
        fixed = _qbm_parse_json(txt)
        if not fixed or len(fixed) != len(mcqs):
            return mcqs  # length mismatch -- untrustworthy, keep Call1's result
        for orig, corrected in zip(mcqs, fixed):
            if corrected.get("question"):
                orig["question"] = corrected["question"]
            if corrected.get("options"):
                orig["options"] = corrected["options"]
            if corrected.get("answer"):
                orig["answer"] = corrected["answer"]
            if corrected.get("explanation"):
                orig["explanation"] = corrected["explanation"]
        return mcqs
    except Exception as e:
        logger.warning(f"[ONU-verify] failed: {e} — keeping Call1 result unverified rather than dropping it")
        return mcqs


async def _onu_extract_from_image(img) -> list:
    """/onu's fully independent extraction pipeline — does NOT call into
    any QBM pipeline function (_qbm_call2_miss_check, _qbm_repair_order,
    _qbm_restore_opt_bboxes, _qbm_final_safety_net, _qbm_final_empty_page_scan
    are all QBM-only and never invoked from here). /onu only shares pure,
    stateless utilities with QBM (_qbm_parse_json, _qbm_dedup_list,
    _qbm_ram_aware_acquire, _cap_mcq_options, _qbm_groq_call, _qbm_gemini_raw)
    -- none of these know or care about "MCQ pipeline" semantics, they're
    just JSON/text/image helpers, so sharing them carries no cross-command
    behavior risk.

    Steps (exactly 2 API calls per page): Call1 (extract — highlighted MCQs
    ONLY, non-highlighted blocks are skipped directly inside the extraction
    prompt itself) -> Call2 (_onu_verify_pass — full proofread/verification
    of exactly what Call1 found, never adds/removes MCQs). _onu_filter_mcqs
    (caller-side, no API call) then drops anything without
    yellow_highlight=true plus image-attached/roman-combo MCQs."""
    await _qbm_ram_aware_acquire()
    try:
        call1 = await _onu_call1_extract(img)
        if not call1:
            return []
        verified = await _onu_verify_pass(img, call1)
        verified = _cap_mcq_options(verified)
        # Safety net: if either call still left explanation empty (model
        # skipped the field despite the prompt asking for it), never post an
        # MCQ with a blank explanation — build one from the known answer.
        for m in verified:
            if not (m.get("explanation") or "").strip():
                try:
                    m["explanation"] = await _qbm_build_explanation_for_known_answer(m, m.get("answer", "A"))
                except Exception as e:
                    logger.warning(f"[ONU] explanation fallback failed: {e}")
        return verified
    finally:
        _QBM_EXTRACT_HARD_CAP.release()


async def handle_onu(msg: dict):
    """
    /onu -p (pages) -c (channel) -m (topic) -t (thread_id)
    /qbm-এর মতোই EXISTING MCQ extract করে, কিন্তু শুধু সেগুলো রাখে যাদের
    প্রশ্নে yellow highlight মার্ক আছে (একমাত্র শর্ত), এবং ছবিযুক্ত MCQ ও
    roman/সংখ্যাভিত্তিক combination-type (i,ii,iii / ১,২,৩) MCQ বাদ দিয়ে।
    """
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    lock = _get_pdfm_lock(uid)
    if lock.locked():
        _PDFM_USER_QUEUE_LEN[uid] = _PDFM_USER_QUEUE_LEN.get(uid, 0) + 1
        pos = _PDFM_USER_QUEUE_LEN[uid]
        try:
            await send_msg(chat_id, f"⏳ আগের PDF/PPT কাজ শেষ হচ্ছে... তোমার এই request queue তে #{pos} নম্বরে আছে, একে একে সব হয়ে যাবে।")
        except Exception:
            pass
    async with lock:
        _PDFM_USER_QUEUE_LEN[uid] = max(0, _PDFM_USER_QUEUE_LEN.get(uid, 1) - 1)
        return await _handle_onu_impl(msg)


async def _handle_onu_impl(msg: dict):
    """Identical to _handle_qbm_impl, except extraction uses ONU_EXTRACT_PROMPT
    (yellow_highlight detection) and after extraction it keeps ONLY MCQs with
    yellow_highlight=true, also filtering out image-attached and roman-combo
    MCQs, before channel-select/CSV/posting."""
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    uname = msg["from"].get("first_name", "User")
    text = msg.get("text", "")
    reply = msg.get("reply_to_message")

    if not reply or not (reply.get("document") or reply.get("photo")):
        await send_msg(chat_id,
            "❌ PDF বা Image-এ reply করে /onu দাও!\n\n"
            "<b>Format:</b>\n"
            "<code>/onu -p 1-5 -c @channel -m \"Topic\" -t group_id</code>\n\n"
            "📌 /qbm-এর মতোই existing MCQ extract করে (নতুন বানায় না)\n"
            "📌 শুধুমাত্র সেই MCQ নেবে যার প্রশ্নে yellow highlight মার্ক করা আছে\n"
            "📌 বাকি সব বাদ: highlight নেই এমন MCQ, ছবিযুক্ত MCQ, roman/সংখ্যা combination (i,ii,iii) MCQ\n"
            "📌 -p = page range, PDF-only (না দিলে সব page)\n"
            "📌 -c = channel id (না দিলে list দেখাবে)\n"
            "📌 -m = topic name\n"
            "📌 -t = topic/thread id (group হলে)"
        )
        return

    is_image_reply = bool(reply.get("photo")) or (
        reply.get("document") and not reply["document"].get("file_name", "").lower().endswith(".pdf")
        and (reply["document"].get("mime_type", "").startswith("image/"))
    )

    if reply.get("document") and not is_image_reply and not reply["document"].get("file_name", "").lower().endswith(".pdf"):
        await send_msg(chat_id, "❌ শুধু PDF বা Image file support করে!")
        return

    params = _parse_pdfm_params(text)
    topic = params["topic"] or "🌟ATLAS Question Bank"
    page_range = params["page_range"]
    channel_id = params["channel_id"]
    thread_id = params["thread_id"]

    if is_image_reply:
        if reply.get("photo"):
            file_id = reply["photo"][-1]["file_id"]
            file_unique_id = reply["photo"][-1].get("file_unique_id")
        else:
            file_id = reply["document"]["file_id"]
            file_unique_id = reply["document"].get("file_unique_id")
        file_name = reply.get("document", {}).get("file_name", "image.jpg")
    else:
        file_id = reply["document"]["file_id"]
        file_unique_id = reply["document"].get("file_unique_id")
        file_name = reply["document"].get("file_name", "document.pdf")

    status_r = await send_msg(chat_id, "⏳ " + ("Image" if is_image_reply else "PDF") + f" download হচ্ছে...\n📄 {file_name}\n[░░░░░░░░░░ 0%]")
    status_msg_id = status_r.get("result", {}).get("message_id")

    _last_pct = {"v": -1}
    _dl_start = time.time()
    def _dl_progress_pdf(done, total):
        if not status_msg_id or not total:
            return
        pct = int(done * 100 / total)
        if pct - _last_pct["v"] < 10 and pct != 100:
            return
        _last_pct["v"] = pct
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        label = "Image" if is_image_reply else "PDF"
        elapsed = time.time() - _dl_start
        eta_txt = ""
        if pct > 0 and pct < 100:
            eta_s = int(elapsed * (100 - pct) / pct)
            eta_txt = f" | ETA {eta_s}s"
        _spawn_task(edit_msg(chat_id, status_msg_id, f"⏳ {label} download হচ্ছে...\n📄 {file_name}\n[{bar} {pct}%{eta_txt}]"))

    try:
        if is_image_reply:
            img_bytes = await download_tg_file(file_id, progress_cb=_dl_progress_pdf, chat_id=chat_id, message_id=reply["message_id"])
            from PIL import Image as PILImage
            img = PILImage.open(BytesIO(img_bytes))
            pages = [(1, img)]
        else:
            pdf_bytes = await _download_pdf_cached(file_id, progress_cb=_dl_progress_pdf, chat_id=chat_id,
                                                    message_id=reply["message_id"], file_unique_id=file_unique_id)
            ok, pages = await asyncio.to_thread(_render_pdf_cached, file_id, pdf_bytes, page_range)
            if not ok:
                await send_msg(chat_id, pages)
                return

            if not pages:
                if status_msg_id:
                    await edit_msg(chat_id, status_msg_id, "🔍 OCR Scanning (scanned PDF detected)...")
                try:
                    from pdf2image import convert_from_bytes
                    if page_range:
                        parts = str(page_range).split("-")
                        first = int(parts[0])
                        last = int(parts[1]) if len(parts) > 1 else first
                        ocr_images = await asyncio.to_thread(
                            convert_from_bytes, pdf_bytes, dpi=150, first_page=first, last_page=last
                        )
                        pages = list(zip(range(first, last + 1), ocr_images))
                    else:
                        ocr_images = await asyncio.to_thread(convert_from_bytes, pdf_bytes, dpi=150)
                        pages = list(enumerate(ocr_images, 1))
                except Exception as e:
                    logger.warning(f"[ONU] OCR fallback failed: {e}")

        if not pages:
            if status_msg_id:
                await edit_msg(chat_id, status_msg_id, "❌ Page পাওয়া যায়নি!")
            return

        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                f"✅ {len(pages)} page পাওয়া গেছে!\n⏳ MCQ Extraction শুরু হচ্ছে...")

        extracted_pages = await qbm_extract_all_pages(
            chat_id, pages, topic, file_name, status_msg_id,
            extractor=_onu_extract_from_image
        )

        # ── /onu-specific step: keep ONLY yellow-highlighted questions, ──
        # ── also excluding image-attached & roman-combo MCQs ──
        filtered_pages = []
        total_before = 0
        total_after = 0
        agg_reasons = {"no_highlight": 0, "has_image": 0, "roman_combo": 0}
        for page_num, img, mcqs in extracted_pages:
            total_before += len(mcqs)
            kept, reasons = _onu_filter_mcqs(mcqs)
            for k in agg_reasons:
                agg_reasons[k] += reasons[k]
            total_after += len(kept)
            filtered_pages.append((page_num, img, kept))
        extracted_pages = filtered_pages
        skipped_count = total_before - total_after
        if status_msg_id and skipped_count:
            reason_lines = []
            if agg_reasons["no_highlight"]:
                reason_lines.append(f"🟡 Yellow highlight নেই: {agg_reasons['no_highlight']}টি")
            if agg_reasons["has_image"]:
                reason_lines.append(f"🖼 ছবিযুক্ত প্রশ্ন: {agg_reasons['has_image']}টি")
            if agg_reasons["roman_combo"]:
                reason_lines.append(f"🔢 Roman/combination-type: {agg_reasons['roman_combo']}টি")
            reason_text = "\n".join(reason_lines)
            await edit_msg(chat_id, status_msg_id,
                f"✅ Extraction সম্পূর্ণ! {total_before} MCQ পাওয়া গেছে, {skipped_count}টি বাদ দেওয়া হলো:\n"
                f"{reason_text}\n\n"
                f"বাকি {total_after}টি এগোচ্ছে...")

        # ── /onu always ends with CSV-only output — no channel list/keyboard,
        # no posting to any channel, regardless of -c flag or saved channels. ──
        total_mcq_found = sum(len(mcqs) for _, _, mcqs in extracted_pages)

        # ── Fallback explanation fill: ONU_EXTRACT_PROMPT already asks the
        # model to write an explanation per MCQ, so this only fires for the
        # rare MCQ that came back with an empty explanation (model skipped
        # it) -- avoids a separate /ai run being needed after the fact. ──
        if total_mcq_found:
            _missing_exp = [m for _, _, mcqs in extracted_pages for m in mcqs if len((m.get("explanation") or "").strip()) < 80]
            if _missing_exp:
                try:
                    await _ai_generate_all_explanations(_missing_exp)
                except Exception as e:
                    logger.warning(f"[ONU] fallback explanation fill failed: {e}")

        if total_mcq_found:
            import io as _io_onu, csv as _csv_mod_onu
            _buf_onu = _io_onu.StringIO()
            _w_onu = _csv_mod_onu.writer(_buf_onu)
            _w_onu.writerow(["questions", "option1", "option2", "option3", "option4", "option5",
                              "answer", "explanation", "type", "section"])
            _ans_map_onu = {"A": "1", "B": "2", "C": "3", "D": "4"}
            for _, _, mcqs in extracted_pages:
                for m in mcqs:
                    opts = m.get("options", ["", "", "", ""])
                    _w_onu.writerow([
                        m.get("question", ""), opts[0] if len(opts) > 0 else "",
                        opts[1] if len(opts) > 1 else "", opts[2] if len(opts) > 2 else "",
                        opts[3] if len(opts) > 3 else "", opts[4] if len(opts) > 4 else "",
                        _ans_map_onu.get(m.get("answer", "A"), "1"),
                        _strip_img_tag(m.get("explanation", "")), "1", "1"
                    ])
            await send_document(chat_id, _buf_onu.getvalue().encode("utf-8"),
                f"{topic}_ONU.csv",
                caption=f"📋 {topic} — {total_mcq_found} MCQ (Extracted, filtered)",
                mime_type="text/csv")
        else:
            await send_msg(chat_id, "❌ কোনো yellow-highlighted MCQ পাওয়া যায়নি।")
        return

    except Exception as e:
        logger.error(f"[ONU] Error: {e}", exc_info=True)
        await _safe_error_reply(chat_id, e)


async def _qbm_scan_answer_key(img, unresolved_mcqs: list) -> dict:
    """
    Given a page image and a list of MCQs whose answer wasn't found on their
    own page, check if THIS page contains an answer key (table, boxed list,
    or "1-A, 2-C..." style) that matches any of these questions by text.
    Returns {question_text_first_80_chars: answer_letter} for matches found.
    Never guesses — only returns a match if the page genuinely contains one.
    """
    if not unresolved_mcqs:
        return {}
    try:
        q_list = "\n".join(
            f"{i+1}. {(m.get('question') or '').strip()[:150]}"
            for i, m in enumerate(unresolved_mcqs)
        )
        prompt = f"""This image may contain an ANSWER KEY (a table, boxed list, or a line
like "1-A, 2-C, 3-B..." mapping question numbers to correct options).

Here are questions whose answers are still missing, in order:
{q_list}

Task: If this page contains an answer key that matches ANY of these questions
(by matching question number sequence, or by recognizing the question topic),
return a JSON array like:
[{{"question_index": 1, "answer": "A"}}, {{"question_index": 3, "answer": "C"}}]

Only include entries where you found a genuine, confident match on this page.
If this page has no answer key at all, or no match for these specific questions,
return exactly: []
Return ONLY the JSON array, nothing else."""

        keys = groq_key_rotator.ordered_keys()
        result_json = None
        if keys:
            data_url = _img_to_data_url_groq(img)
            if data_url:
                for key in keys:
                    txt, status = await _post_openai_compat(
                        "https://api.groq.com/openai/v1/chat/completions",
                        key, "qwen/qwen3.6-27b",
                        data_url, prompt
                    )
                    if txt:
                        groq_key_rotator.mark_healthy(key)
                        result_json = _qbm_parse_json(txt)
                        break
                    if status == 429:
                        groq_key_rotator.mark_rate_limited(key, daily_exhausted=(_key_429_is_tpm.get(key) is not True))
                        continue
                    logger.warning(f"[Groq-QBM2] key failed (status={status}), falling through to Gemini")
                    break

        if not result_json:
            try:
                from pdf_handler import key_rotator, image_to_base64
                _gkeys = key_rotator.ordered_keys()
                if _gkeys:
                    gkey = _gkeys[0]
                    from google import genai as gai
                    from google.genai import types
                    client = gai.Client(api_key=gkey)
                    img_b64 = image_to_base64(img)

                    def _call():
                        return client.models.generate_content(
                            model="gemini-3.6-flash",
                            contents=[
                                types.Part.from_text(text=prompt),
                                types.Part.from_bytes(data=base64.b64decode(img_b64), mime_type="image/jpeg")
                            ]
                        )
                    response = await asyncio.to_thread(_call)
                    result_json = _qbm_parse_json(response.text)
            except Exception as e:
                logger.warning(f"[QBM] answer-key scan gemini fallback failed: {e}")

        if not result_json or not isinstance(result_json, list):
            return {}

        found = {}
        for entry in result_json:
            try:
                q_idx = int(entry.get("question_index", 0)) - 1
                ans = str(entry.get("answer", "")).strip().upper()[:1]
                if 0 <= q_idx < len(unresolved_mcqs) and ans in ("A", "B", "C", "D"):
                    key_text = (unresolved_mcqs[q_idx].get("question") or "").strip()[:80]
                    found[key_text] = ans
            except (ValueError, TypeError, AttributeError):
                continue
        return found
    except Exception as e:
        logger.warning(f"[QBM] answer-key scan failed: {e}")
        return {}


async def qbm_extract_all_pages(
    chat_id: int, pages: list, topic: str,
    file_name: str, status_msg_id: int = None,
    extractor=None, file_id: str = None
) -> list:
    """
    Phase 1 -- runs the full 3-call connected extraction pipeline for every
    page BEFORE any channel selection or posting happens. Also performs the
    cross-page answer backfill lookahead here (same as before), so by the
    time this returns, every page's MCQ list is fully final.
    Returns list of (page_num, img, mcqs) tuples.

    file_id (optional): when given, enables the /qbm-only page-level MCQ
    cache -- re-running /qbm on the identical PDF+page skips re-extraction
    (Call1) and goes straight to a full Call2 verify pass on the cached
    result. Intentionally opt-in (only /qbm passes this) so /onu and other
    callers of this same function are completely unaffected.
    """
    _extract_fn = extractor or _qbm_extract_from_image
    page_status = [{"page": p, "done": False, "current": False, "mcq": 0} for p, _ in pages]
    start_time = time.time()
    total_mcq = 0
    results = [None] * len(pages)
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, f"QBM extraction ({file_name}, page-by-page)")

    if status_msg_id:
        await edit_msg(chat_id, status_msg_id,
            _build_dashboard(file_name, topic, pages, page_status, start_time, 0, 0), reply_markup=_cancel_kb(chat_id))

    # Live ticker: QBM's 2-call pipeline (full Call1+Call2, no shortcuts)
    # can take 30-90s per page, and the dashboard previously only refreshed on
    # page start/finish -- elapsed time looked frozen the whole time. This
    # refreshes the same message every few seconds purely for the live clock,
    # independent of page completion events (same pattern as /pdf's ticker).
    _qbm_dash_stop = asyncio.Event()
    async def _qbm_dashboard_ticker():
        _ticker_deadline = time.time() + 1800
        while not _qbm_dash_stop.is_set() and time.time() < _ticker_deadline:
            try:
                await asyncio.wait_for(_qbm_dash_stop.wait(), timeout=4)
            except asyncio.TimeoutError:
                pass
            if _qbm_dash_stop.is_set():
                break
            if status_msg_id:
                try:
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, 0), reply_markup=_cancel_kb(chat_id))
                except Exception:
                    pass
    _qbm_ticker_task = _spawn_task(_qbm_dashboard_ticker())

    async def _extract_one(idx, page_num, img):
        nonlocal total_mcq
        _current_job_chat_id_ctx.set(chat_id)
        if is_cancelled(chat_id):
            return idx, page_num, img, []
        page_status[idx]["current"] = True
        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, 0), reply_markup=_cancel_kb(chat_id))
        mcqs = []

        async def _run_extract():
            _ck = (_qbm_page_content_hash(img), page_num) if file_id else None
            return await _extract_fn(img, cache_key=_ck) if _ck else await _extract_fn(img)

        async def _watch_cancel_inner(task):
            # Call1/Call2 (এবং lookahead/web-resolve) মিলিয়ে একটা page
            # 30-90s পর্যন্ত লাগতে পারে — আগে cancel চেক শুধু page শুরুর
            # আগে হতো, তাই বাটনে চাপলেও চলমান page শেষ না হওয়া পর্যন্ত
            # কিছু হতো না। এখন প্রতি 0.3s cancel flag পোল করে, flag উঠলে
            # সাথে সাথে চলমান extract task cancel করে দেয়।
            while not task.done():
                if is_cancelled(chat_id):
                    task.cancel()
                    return
                await asyncio.sleep(0.3)

        try:
            ex_task = _spawn_task(_run_extract())
            watcher = _spawn_task(_watch_cancel_inner(ex_task))
            try:
                mcqs = await ex_task
            except asyncio.CancelledError:
                mcqs = []
            finally:
                watcher.cancel()
                try:
                    await watcher
                except asyncio.CancelledError:
                    pass

            if is_cancelled(chat_id):
                page_status[idx]["current"] = False
                return idx, page_num, img, mcqs

            unresolved = [m for m in mcqs if "Answer not found in source" in (m.get("explanation") or "")]
            if unresolved and idx + 1 < len(pages) and not is_cancelled(chat_id):
                # Scan ALL remaining pages (not just the next 2) — an answer
                # key/table can legitimately sit many pages later, and giving
                # up early would mean falling back to an AI-guessed answer
                # instead of the real one actually present in the source.
                for lookahead_offset in range(1, len(pages) - idx):
                    if not unresolved or is_cancelled(chat_id):
                        break
                    _, lookahead_img = pages[idx + lookahead_offset]
                    found_map = await _qbm_scan_answer_key(lookahead_img, unresolved)
                    if found_map:
                        for m in mcqs:
                            key = (m.get("question") or "").strip()[:80]
                            if key in found_map:
                                m["answer"] = found_map[key]
                                m["explanation"] = (m.get("explanation") or "").replace(
                                    "Answer not found in source", ""
                                ).strip()
                                if not m["explanation"]:
                                    m["explanation"] = await _qbm_build_explanation_for_known_answer(m, m["answer"])
                        unresolved = [m for m in mcqs if "Answer not found in source" in (m.get("explanation") or "")]

            # Still unresolved after scanning nearby pages -> last-resort Groq
            # knowledge-based resolution, never a blind guess.
            if unresolved and not is_cancelled(chat_id):
                for m in unresolved:
                    if is_cancelled(chat_id):
                        break
                    resolved = await _qbm_web_resolve_answer(m)
                    if resolved:
                        m["answer"] = resolved["answer"]
                        m["explanation"] = resolved["explanation"] or (m.get("explanation") or "").replace(
                            "Answer not found in source", ""
                        ).strip()
        except Exception as e:
            logger.error(f"[QBM Extract] Page {page_num} error: {e} — retrying once before giving up (page must never be silently skipped)")
            if not is_cancelled(chat_id):
                try:
                    _ck = (_qbm_page_content_hash(img), page_num) if file_id else None
                    mcqs = await _extract_fn(img, cache_key=_ck) if _ck else await _extract_fn(img)
                except Exception as e2:
                    logger.error(f"[QBM Extract] Page {page_num} retry also failed: {e2}")
                    mcqs = []

        page_status[idx]["current"] = False
        page_status[idx]["done"] = True
        page_status[idx]["mcq"] = len(mcqs)
        _counts = {}
        for _m in (mcqs or []):
            _prov = _m.get("_provider", "")
            if _prov:
                _counts[_prov] = _counts.get(_prov, 0) + 1
        page_status[idx]["model"] = ", ".join(f"{k}:{v}" for k, v in _counts.items())
        total_mcq += len(mcqs)
        if status_msg_id:
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, pages, page_status, start_time, total_mcq, 0), reply_markup=_cancel_kb(chat_id))
        return idx, page_num, img, mcqs

    # Parallel window. WINDOW=1 was strict-sequential (avoided same-key TPM
    # collisions, but wall-clock = sum of every page's time -- very slow on
    # dense-MCQ PDFs). Each concurrent slot sets _qbm_key_offset_ctx to a
    # different starting Groq key (round-robin via ordered_keys(offset=)),
    # so pages in a window pull from different keys first instead of
    # hammering the same one. With 12 Groq keys total, WINDOW=4 keeps every
    # slot on its own starting key with headroom to spare (still leaves 8
    # other keys as fallback per slot if its primary key is cooling), so
    # accuracy/collision-safety is preserved while roughly halving wall-clock
    # time again vs WINDOW=2. Pages still complete in strict index order
    # (gather waits for the whole window before moving to the next), so
    # ordering guarantees and the cross-page answer-lookahead (which needs
    # earlier pages already resolved) are unaffected.
    WINDOW = 4

    async def _extract_one_slotted(slot, idx, page_num, img):
        _qbm_key_offset_ctx.set(slot)
        return await _extract_one(idx, page_num, img)

    for start in range(0, len(pages), WINDOW):
        if is_cancelled(chat_id):
            break
        chunk = pages[start:start + WINDOW]
        tasks = [
            _extract_one_slotted(i, start + i, page_num, img)
            for i, (page_num, img) in enumerate(chunk)
        ]
        chunk_results = await asyncio.gather(*tasks)
        for idx, page_num, img, mcqs in chunk_results:
            results[idx] = (page_num, img, mcqs)

    _qbm_dash_stop.set()
    try:
        await asyncio.wait_for(_qbm_ticker_task, timeout=2)
    except Exception:
        pass
    clear_active_job(chat_id)

    # Cross-page dedup: each page is extracted independently (no shared
    # context between pages), so an MCQ whose question/answer block visually
    # straddles a page boundary (or simply repeats — e.g. a reprinted MCQ,
    # or the SAME physical page rendered twice due to a PDF split overlap)
    # can get pulled out by both pages' Call1/Call2 passes, producing an
    # extra duplicate poll on posting. Dedup runs across the FULL combined
    # list (not just within one page) using the same fuzzy-match logic
    # already used per-page, keeping the first (earlier-page) occurrence.
    final_results = [r for r in results if r is not None]
    combined_mcqs = []
    for page_num, img, mcqs in final_results:
        combined_mcqs.extend(mcqs or [])
    deduped_mcqs = _qbm_dedup_list(combined_mcqs)
    if len(deduped_mcqs) < len(combined_mcqs):
        dropped = len(combined_mcqs) - len(deduped_mcqs)
        logger.info(f"[QBM Cross-Page Dedup] dropped {dropped} duplicate MCQ(s) across pages")
        deduped_ids = {id(m) for m in deduped_mcqs}
        rebuilt = []
        for page_num, img, mcqs in final_results:
            kept = [m for m in (mcqs or []) if id(m) in deduped_ids]
            rebuilt.append((page_num, img, kept))
        final_results = rebuilt

    return final_results


async def process_qbm_pages(
    chat_id: int, uid: int, uname: str,
    pages: list, topic: str,
    channel_id, csv_only: bool,
    file_name: str = "document.pdf",
    status_msg_id: int = None,
    thread_id: int = None,
    skip_extract: bool = False,
    file_id: str = None,
    page_range_str: str = None
):
    """
    QBM posting loop. If skip_extract=True, `pages` is already a list of
    (page_num, img, mcqs) tuples from qbm_extract_all_pages() -- extraction
    (and the 3-call pipeline + answer backfill) already happened in Phase 1,
    so this function only posts to Telegram / builds the CSV.
    """
    settings = await db_get_settings()
    tag = settings.get("tag", "")
    exp_footer = settings.get("exp_footer", "")

    if skip_extract:
        page_tuples = pages  # (page_num, img, mcqs)
        display_pages = [(p, img) for p, img, _ in page_tuples]
    else:
        page_tuples = None
        display_pages = pages

    job_id = None
    if file_id and channel_id:  # শুধু actual posting job resumable
        job_id = gen_session_id()
        await db_save_page_job(
            job_id, job_type="qbm", uid=uid, chat_id=chat_id, uname=uname,
            file_id=file_id, page_range=page_range_str or "", topic=topic,
            mcq_count="", channel_id=str(channel_id),
            csv_only=0, file_name=file_name, thread_id=thread_id or 0,
            status_msg_id=status_msg_id or 0,
            resume_page_num=(display_pages[0][0] if display_pages else 0),
            status="running"
        )

    page_status = [{"page": p, "done": False, "current": False, "mcq": 0} for p, _ in display_pages]
    start_time = time.time()
    total_mcq = 0
    total_polls = 0

    if not status_msg_id:
        r = await send_msg(chat_id, "⏳ Posting শুরু হচ্ছে...")
        status_msg_id = r.get("result", {}).get("message_id")

    await edit_msg(chat_id, status_msg_id,
        _build_dashboard(file_name, topic, display_pages, page_status, start_time, 0, 0), reply_markup=_cancel_kb(chat_id))

    summary_pages = []
    all_mcqs_csv = []
    first_image_msg_id = None
    page_provider_tally = {}  # page_num -> {"Gemini": n, "Groq": n} for final model-usage summary (post-verify)
    page_call1_tally = {}  # page_num -> {"Gemini": n, "Groq": n} -- ORIGINAL Call1 extraction provider, before Call2 verify relabels it
    new_job_id(chat_id)
    set_active_job(chat_id, f"QBM Poll posting ({file_name}, page-by-page)")

    iterable = page_tuples if skip_extract else [(p, img, None) for p, img in pages]
    # Running set of already-seen question keys across ALL pages processed
    # so far in this loop — catches an MCQ that visually straddles a page
    # boundary (or a duplicated/overlapping source page) and got extracted
    # on more than one page, before it gets posted twice. skip_extract=True
    # doesn't need this (qbm_extract_all_pages already deduped globally).
    _qbm_seen_q_keys: list = [] if not skip_extract else None

    for idx, (page_num, img, precomputed_mcqs) in enumerate(iterable):
        _current_job_chat_id_ctx.set(chat_id)
        if is_cancelled(chat_id):
            clear_active_job(chat_id)
            break
        page_status[idx]["current"] = True
        await edit_msg(chat_id, status_msg_id,
            _build_dashboard(file_name, topic, display_pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

        try:
            _ck = (_qbm_page_content_hash(img), page_num) if file_id else None
            mcqs = precomputed_mcqs if skip_extract else (
                await _qbm_extract_from_image(img, cache_key=_ck) if _ck else await _qbm_extract_from_image(img)
            )
            if not mcqs:
                page_status[idx]["current"] = False
                page_status[idx]["done"] = True
                await edit_msg(chat_id, status_msg_id,
                    _build_dashboard(file_name, topic, display_pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))
                continue

            if _qbm_seen_q_keys is not None:
                _kept = []
                for m in mcqs:
                    _key = _qbm_normalize_q(m.get("question", ""))
                    if _key and _qbm_is_duplicate(_key, _qbm_seen_q_keys):
                        continue
                    if _key:
                        _qbm_seen_q_keys.append(_key)
                    _kept.append(m)
                if len(_kept) < len(mcqs):
                    logger.info(f"[QBM Cross-Page Dedup] page {page_num}: dropped {len(mcqs) - len(_kept)} duplicate MCQ(s) already seen on an earlier page")
                mcqs = _kept
                if not mcqs:
                    page_status[idx]["current"] = False
                    page_status[idx]["done"] = True
                    await edit_msg(chat_id, status_msg_id,
                        _build_dashboard(file_name, topic, display_pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))
                    continue

            # ── Cross-page answer backfill — SKIPPED here if skip_extract=True
            # (Phase 1 / qbm_extract_all_pages already ran this lookahead) ──
            if not skip_extract:
                unresolved = [m for m in mcqs if "Answer not found in source" in (m.get("explanation") or "")]
                if unresolved and idx + 1 < len(display_pages):
                    for lookahead_offset in range(1, len(display_pages) - idx):
                        if not unresolved:
                            break
                        _, lookahead_img = display_pages[idx + lookahead_offset]
                        found_map = await _qbm_scan_answer_key(lookahead_img, unresolved)
                        if found_map:
                            for m in mcqs:
                                key = (m.get("question") or "").strip()[:80]
                                if key in found_map:
                                    m["answer"] = found_map[key]
                                    m["explanation"] = (m.get("explanation") or "").replace(
                                        "Answer not found in source", ""
                                    ).strip()
                                    if not m["explanation"]:
                                        m["explanation"] = await _qbm_build_explanation_for_known_answer(m, m["answer"])
                            unresolved = [m for m in mcqs if "Answer not found in source" in (m.get("explanation") or "")]
                if unresolved:
                    for m in unresolved:
                        resolved = await _qbm_web_resolve_answer(m)
                        if resolved:
                            m["answer"] = resolved["answer"]
                            m["explanation"] = resolved["explanation"] or (m.get("explanation") or "").replace(
                                "Answer not found in source", ""
                            ).strip()

            # Two-stage tally: Call1 = who did the original extraction,
            # Call2 = who verified/recovered it (only differs from Call1
            # when a verify pass actually ran and changed provider).
            _counts = {}
            _c1_counts = {}
            for _m in (mcqs or []):
                _prov = _m.get("_provider", "Unknown")
                _counts[_prov] = _counts.get(_prov, 0) + 1
                _c1_prov = _m.get("_call1_provider", _prov)
                _c1_counts[_c1_prov] = _c1_counts.get(_c1_prov, 0) + 1
            page_call1_tally[page_num] = _c1_counts
            page_provider_tally[page_num] = _counts

            img_bytes = image_to_bytes(img) if not isinstance(img, (bytes, bytearray)) else img

            if csv_only:
                for m in mcqs:
                    opts = m.get("options", ["", "", "", ""])
                    ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
                    ans_num = ans_map.get(m.get("answer", "A"), "1")
                    all_mcqs_csv.append([m["question"], opts[0],
                        opts[1] if len(opts) > 1 else "",
                        opts[2] if len(opts) > 2 else "",
                        opts[3] if len(opts) > 3 else "",
                        opts[4] if len(opts) > 4 else "",
                        ans_num, _strip_img_tag(m.get("explanation", "")), "1", "1"])
            else:
                caption = ""
                if tag:
                    caption = f"{tag}\n\n"
                caption += (
                    f"📋ATLAS Question Bank Extraction\n"
                    f"🌟Topic: {topic}\n"
                    f"📌Page No: {fmt_page(page_num)}\n"
                    f"💎MCQ: {len(mcqs)}"
                )

                photo_r = await send_photo(channel_id, img_bytes, caption, message_thread_id=thread_id)
                image_msg_id = None
                if photo_r.get("ok"):
                    image_msg_id = photo_r["result"]["message_id"]
                    if first_image_msg_id is None:
                        first_image_msg_id = image_msg_id
                        # Item 3: auto-pin the very first image of the job
                        await try_pin_message(channel_id, image_msg_id)

                first_poll_link = ""
                for i, mcq in enumerate(mcqs):
                    opts = mcq.get("options", [])[:4]
                    ans_idx = {"A": 0, "B": 1, "C": 2, "D": 3}.get(mcq.get("answer", "A"), 0)
                    q_text = mcq["question"]
                    if tag:
                        q_text = f"{tag}\n\n{q_text}"
                    exp = mcq.get("explanation", "")
                    if exp_footer:
                        exp = f"{exp}\n{exp_footer}"
                    poll_r = {"ok": False}
                    for _attempt in range(3):
                        poll_r = await send_poll(
                            channel_id, q_text, opts, ans_idx,
                            explanation=exp,
                            reply_to_message_id=image_msg_id,
                            message_thread_id=thread_id
                        )
                        if poll_r.get("ok"):
                            break
                        await asyncio.sleep(2)
                    if poll_r.get("ok") and i == 0:
                        pmid = poll_r["result"]["message_id"]
                        cid = str(channel_id)
                        first_poll_link = (
                            f"https://t.me/c/{cid[4:]}/{pmid}"
                            if cid.startswith("-100")
                            else f"https://t.me/{cid.lstrip('@')}/{pmid}"
                        )
                    total_polls += 1
                    await asyncio.sleep(1.0)

                end_text = (
                    f"🚀Topic: {topic}\n"
                    f"🌟Page No: {fmt_page(page_num)}\n"
                    f"✅MCQ: {len(mcqs)}\n"
                    f"🔗First Poll Link:\n{first_poll_link}"
                )
                end_data = {
                    "chat_id": channel_id, "text": end_text,
                    "reply_to_message_id": image_msg_id,
                    "disable_web_page_preview": True
                }
                if thread_id:
                    end_data["message_thread_id"] = thread_id
                await tg_post("sendMessage", end_data)

                summary_pages.append({"page": page_num, "first_poll": first_poll_link, "mcq_count": len(mcqs)})

                for m in mcqs:
                    opts = m.get("options", ["", "", "", ""])
                    ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
                    ans_num = ans_map.get(m.get("answer", "A"), "1")
                    all_mcqs_csv.append([m["question"], opts[0],
                        opts[1] if len(opts) > 1 else "",
                        opts[2] if len(opts) > 2 else "",
                        opts[3] if len(opts) > 3 else "",
                        opts[4] if len(opts) > 4 else "",
                        ans_num, _strip_img_tag(m.get("explanation", "")), "1", "1"])

            total_mcq += len(mcqs)
            page_status[idx]["done"] = True
            page_status[idx]["current"] = False
            page_status[idx]["mcq"] = len(mcqs)
            # Show Call1 (original extraction) and Call2 (verify) separately
            # when they differ, so it's clear e.g. Gemini extracted but Groq
            # verified -- a plain merged tally hid this distinction before.
            # Always show Call1 (original extraction) alongside Verify (Call2)
            # -- collapsing them into one string when they matched hid real
            # attribution bugs (e.g. Call1 tag lost to text-mismatch during
            # merge) behind what looked like "nothing to show separately".
            # Showing both plainly, always, makes any future attribution loss
            # immediately visible instead of silently indistinguishable.
            # Order shown = actual try-order (Gemini tried first in Call1,
            # then Groq, then OpenRouter last-resort) rather than dict/MCQ
            # insertion order, which could show e.g. "Groq:5, Gemini:15" even
            # though Gemini was the FIRST provider actually attempted --
            # misleadingly implying Groq was primary when it wasn't.
            _PROVIDER_TRY_ORDER = ["Gemini", "Groq", "OpenRouter", "MissCheck", "Unknown"]
            def _ordered_tally_str(tally: dict) -> str:
                items = sorted(tally.items(), key=lambda kv: _PROVIDER_TRY_ORDER.index(kv[0]) if kv[0] in _PROVIDER_TRY_ORDER else len(_PROVIDER_TRY_ORDER))
                return ", ".join(f"{k}:{v}" for k, v in items)
            _c1_str = _ordered_tally_str(page_call1_tally.get(page_num, {}))
            _c2_str = _ordered_tally_str(page_provider_tally.get(page_num, {}))
            page_status[idx]["model"] = f"Call1[{_c1_str}] Verify[{_c2_str}]"
            await edit_msg(chat_id, status_msg_id,
                _build_dashboard(file_name, topic, display_pages, page_status, start_time, total_mcq, total_polls), reply_markup=_cancel_kb(chat_id))

            if job_id:
                next_page = display_pages[idx + 1][0] if idx + 1 < len(display_pages) else -1
                await db_update_page_job_progress(job_id, next_page)

        except Exception as e:
            logger.error(f"[QBM] Page {page_num} error: {e}")
            page_status[idx]["current"] = False
            page_status[idx]["done"] = True

    clear_active_job(chat_id)
    if job_id:
        await db_finish_page_job(job_id)

    if all_mcqs_csv:
        import io as _io, csv as _csv_mod
        buf = _io.StringIO()
        writer = _csv_mod.writer(buf)
        writer.writerow(["questions", "option1", "option2", "option3", "option4", "option5",
                          "answer", "explanation", "type", "section"])
        for row in all_mcqs_csv:
            writer.writerow(row)
        await send_document(chat_id, buf.getvalue().encode("utf-8"),
            f"{topic}_QBM.csv",
            caption=f"📋 {topic} — {len(all_mcqs_csv)} MCQ (Extracted)",
            mime_type="text/csv")

    if not csv_only and summary_pages:
        total_mcq_sum = sum(p["mcq_count"] for p in summary_pages)
        bd_time = _get_bd_time()
        summary = f"⚙️QBM Summary\n📋Topic: {topic}\n🚀Total Extracted MCQ: {total_mcq_sum}\n\n"
        for p in summary_pages:
            summary += f"🌟Page No: {fmt_page(p['page'])} ({p['mcq_count']} MCQ)\n{p['first_poll']}\n\n"
        summary += f"📅 {bd_time}"

        summary_data = {"chat_id": channel_id, "text": summary, "disable_web_page_preview": True}
        if first_image_msg_id:
            summary_data["reply_to_message_id"] = first_image_msg_id
        if thread_id:
            summary_data["message_thread_id"] = thread_id
        sum_r = await tg_post("sendMessage", summary_data)
        if sum_r.get("ok"):
            await try_pin_message(channel_id, sum_r["result"]["message_id"])

    elapsed = int(time.time() - start_time)
    mins, secs = divmod(elapsed, 60)
    # Per-page model breakdown: which provider (Gemini/Groq) actually produced
    # each page's MCQs, tallied from the _provider tag stamped on each MCQ
    # during extraction (_qbm_call1_extract / _qbm_final_empty_page_scan).
    page_model_map = page_provider_tally
    page_breakdown_final = "\n".join(
        f"✅ Page {fmt_page(p)}: {ps['mcq']} MCQ"
        + (f" ({', '.join(f'{k}:{v}' for k, v in page_model_map.get(p, {}).items())})" if page_model_map.get(p) else "")
        for p, ps in zip([pp for pp, _ in display_pages], page_status)
    )
    model_totals = {}
    for counts in page_model_map.values():
        for k, v in counts.items():
            model_totals[k] = model_totals.get(k, 0) + v
    model_totals_line = ", ".join(f"{k}: {v}" for k, v in model_totals.items()) if model_totals else "N/A"
    await edit_msg(chat_id, status_msg_id,
        "✅ <b>QBM Extraction Complete!</b>\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📄 {file_name}\n📋 {topic}\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{page_breakdown_final}\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📝 Total MCQ Extracted: {total_mcq}\n📋 Pages: {len(display_pages)}\n⏱️ {mins}:{secs:02d}\n"
        f"🤖 Model Usage: {model_totals_line}\n"
        "━━━━━━━━━━━━━━━━━━━━━━")

# ============================================================
# FEATURE: /rapid — CSV রিপ্লাই করে Topic দিলে, channel + local time select
# করার পর, সেই সময়ে topic message পাঠিয়ে প্রতি 10s এ একটা করে প্রশ্ন
# (Comment-এ ছাত্ররা উত্তর দেবে), প্রশ্ন আসার 12s পর reply করে উত্তর+ব্যাখ্যা।
# শেষে topic message কে reply করে closing message, আর শুধু Q+A+Explanation
# এর একটা PDF (CSV-এর option ছাড়া) admin-কে পাঠানো হয়।
# ============================================================
RAPID_Q_INTERVAL = 10   # সেকেন্ড — প্রতি প্রশ্নের গ্যাপ
RAPID_ANS_DELAY = 8     # সেকেন্ড — প্রশ্ন আসার পর উত্তর reveal (8s পর answer, তারপর 2s এ নতুন প্রশ্ন)

_RAPID_ANS_EMOJIS = ["✅", "🎯", "💡", "🔥", "📌", "⭐"]


def _rapid_get_answer_text(mcq: dict) -> str:
    """mcq['answer'] হলো letter (A-D) — options থেকে আসল answer text বের করো।"""
    opts = mcq.get("options", [])
    idx = {"A": 0, "B": 1, "C": 2, "D": 3}.get(mcq.get("answer", "A"), 0)
    return opts[idx] if idx < len(opts) else (opts[0] if opts else "")


async def handle_rapid_command(msg: dict):
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "").strip()
    reply = msg.get("reply_to_message")

    topic = text.replace("/rapid", "").strip()
    if not topic:
        await send_msg(chat_id,
            "❌ Correct format:\n<code>/rapid টপিক নাম</code>\n\n"
            "📌 CSV ফাইলে reply করে দাও।"
        )
        return

    if not reply or not reply.get("document"):
        await send_msg(chat_id, "❌ CSV ফাইলে reply করে /rapid (Topic Name) দাও!")
        return

    doc = reply["document"]
    if not doc.get("file_name", "").lower().endswith(".csv"):
        await send_msg(chat_id, "❌ শুধু .csv file support করে!")
        return

    file_name = doc.get("file_name", "")
    file_size = doc.get("file_size", 0)
    size_kb = round(file_size / 1024, 1) if file_size else "?"
    loading = await send_msg(chat_id, f"⏳ CSV download হচ্ছে...\n📄 {file_name}\n📦 {size_kb} KB\n[░░░░░░░░░░ 0%]")
    loading_id = loading.get("result", {}).get("message_id")

    _last_pct_rapid = {"v": -1}
    def _dl_progress_rapid(done, total):
        if not loading_id or not total:
            return
        pct = int(done * 100 / total)
        if pct - _last_pct_rapid["v"] < 15 and pct != 100:
            return
        _last_pct_rapid["v"] = pct
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        _spawn_task(edit_msg(chat_id, loading_id, f"⏳ CSV download হচ্ছে...\n📄 {file_name}\n📦 {size_kb} KB\n[{bar} {pct}%]"))

    try:
        csv_bytes = await download_tg_file(doc["file_id"], progress_cb=_dl_progress_rapid)
        if loading_id:
            await edit_msg(chat_id, loading_id, f"✅ Download সম্পূর্ণ!\n[██████████ 100%]\n⏳ CSV parse হচ্ছে...")
        mcqs = _parse_csv_bytes(csv_bytes)
        if not mcqs:
            if loading_id:
                await edit_msg(chat_id, loading_id, "❌ CSV-এ কোনো valid প্রশ্ন পাওয়া যায়নি!")
            return
        if loading_id:
            await edit_msg(chat_id, loading_id, f"✅ {len(mcqs)} টি MCQ পাওয়া গেছে!")

        RAPID_PENDING[uid] = {
            "step": "awaiting_channel",
            "topic": topic,
            "mcqs": mcqs,
            "admin_chat": chat_id,
        }

        if loading_id:
            await edit_msg(chat_id, loading_id,
                f"✅ {len(mcqs)} টি প্রশ্ন পাওয়া গেছে!\n📢 Channel select করো:")

        channels = await db_get_channels()
        if not channels:
            await send_msg(chat_id, "❌ Channel নেই! /channel দিয়ে add করো।")
            RAPID_PENDING.pop(uid, None)
            return

        kb = {"inline_keyboard": []}
        for ch in channels:
            ch_id = ch.get("channel_id", "")
            ch_name = ch.get("channel_name", ch_id)
            kb["inline_keyboard"].append([{
                "text": f"📢 {ch_name}",
                "callback_data": f"rapidch_{ch_id}_{uid}"
            }])
        kb["inline_keyboard"].append([{
            "text": "❌ Cancel",
            "callback_data": f"rapidcancel_{uid}"
        }])
        await send_msg(chat_id,
            f"🚀 Topic: {topic}\n📝 প্রশ্ন: {len(mcqs)} টি\n\n📢 Channel select করো:",
            reply_markup=kb
        )

    except Exception as e:
        logger.error(f"[RAPID] error: {e}")
        await _safe_error_reply(chat_id, e)


def _parse_local_time_text(text: str):
    """'9:00 AM', '10:02 PM', '21:15' ইত্যাদি parse করে (hour24, minute) রিটার্ন করে। Fail হলে None।"""
    text = text.strip().upper().replace(".", "")
    m = re.match(r"^(\d{1,2}):(\d{2})\s*(AM|PM)?$", text)
    if not m:
        return None
    hour = int(m.group(1))
    minute = int(m.group(2))
    ampm = m.group(3)
    if minute > 59:
        return None
    if ampm:
        if hour < 1 or hour > 12:
            return None
        if ampm == "AM":
            hour24 = 0 if hour == 12 else hour
        else:
            hour24 = 12 if hour == 12 else hour + 12
    else:
        if hour > 23:
            return None
        hour24 = hour
    return hour24, minute


async def handle_rapid_time_text(msg: dict) -> bool:
    """uid যদি RAPID_PENDING-এ awaiting_time state-এ থাকে, এই text কে time হিসেবে নেয়।
    Consumed হলে True রিটার্ন করে (handle_message এর router-কে জানানোর জন্য)।"""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    state = RAPID_PENDING.get(uid)
    if not state or state.get("step") != "awaiting_time":
        return False

    text = (msg.get("text") or "").strip()
    parsed = _parse_local_time_text(text)
    if not parsed:
        await send_msg(chat_id,
            "❌ সময়ের ফরম্যাট ঠিক নেই!\n\n"
            "<b>Example:</b> <code>9:00 AM</code> অথবা <code>10:02 PM</code>"
        )
        return True

    hour24, minute = parsed
    bd_tz = pytz.timezone("Asia/Dhaka")
    now = datetime.now(bd_tz)
    run_at = now.replace(hour=hour24, minute=minute, second=0, microsecond=0)
    if run_at <= now:
        run_at += timedelta(days=1)

    state["step"] = "scheduled"
    job_id = gen_session_id()
    state["job_id"] = job_id
    state["run_at_ts"] = run_at.timestamp()

    # persist (so a restart before fire-time doesn't silently lose it — see _recover_rapid_jobs)
    await sb_exec(lambda: sb.table("quiz_sessions").upsert({
        "key": f"rapid_job_{job_id}",
        "data": json.dumps({
            "topic": state["topic"],
            "mcqs": state["mcqs"],
            "channel_id": state["channel_id"],
            "admin_chat": state["admin_chat"],
            "run_at_ts": state["run_at_ts"],
            "status": "pending",
        }),
        "updated_at": int(time.time())
    }).execute())

    delay = (run_at - now).total_seconds()
    task = _spawn_task(_rapid_wait_and_run(job_id, delay))
    RAPID_TASKS[job_id] = task

    await send_msg(chat_id,
        f"✅ <b>Scheduled!</b>\n\n"
        f"🚀 Topic: {state['topic']}\n"
        f"📝 প্রশ্ন: {len(state['mcqs'])} টি\n"
        f"📢 Channel: <code>{state['channel_id']}</code>\n"
        f"🕐 সময়: {run_at.strftime('%d %B, %I:%M %p')} (BD time)\n\n"
        f"⏳ নির্ধারিত সময়ে শুরু হবে।"
    )
    RAPID_PENDING.pop(uid, None)
    return True


async def _rapid_wait_and_run(job_id: str, delay_seconds: float):
    try:
        if delay_seconds > 0:
            await asyncio.sleep(delay_seconds)
        await _run_rapid_job(job_id)
    except asyncio.CancelledError:
        pass
    finally:
        RAPID_TASKS.pop(job_id, None)


async def _run_rapid_job(job_id: str):
    row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"rapid_job_{job_id}").execute())
    if not row.data:
        return
    job = json.loads(row.data[0]["data"])
    if job.get("status") == "done":
        return  # already ran (defensive, in case of duplicate triggers)

    topic = job["topic"]
    mcqs = job["mcqs"]
    channel_id = job["channel_id"]
    admin_chat = job["admin_chat"]
    total = len(mcqs)

    try:
        topic_text = (
            f"🌟 ATLAS Rapid Fire 🌟\n\n"
            f"🚀 Topic: {topic}\n"
            f"📝 প্রশ্ন সংখ্যা: {total}\n\n"
            f"✍️ Comment-এ উত্তর লিখো! প্রতি {RAPID_Q_INTERVAL} সেকেন্ডে নতুন প্রশ্ন আসবে।"
        )
        topic_r = await tg_post("sendMessage", {"chat_id": channel_id, "text": topic_text})
        topic_msg_id = topic_r.get("result", {}).get("message_id") if topic_r.get("ok") else None

        async def _reveal_answer(i, mcq, q_msg_id):
            """প্রশ্ন আসার RAPID_ANS_DELAY সেকেন্ড পর উত্তর reply করে — প্রশ্নের
            নিজের 10s cadence থেকে independent, যাতে timeline ovelap করতে পারে
            (spec অনুযায়ী: Q প্রতি 10s, কিন্তু A প্রতিটা Q এর 12s পরে)।"""
            await asyncio.sleep(RAPID_ANS_DELAY)
            ans_text = _rapid_get_answer_text(mcq)
            emoji = _RAPID_ANS_EMOJIS[i % len(_RAPID_ANS_EMOJIS)]
            reveal = f"{emoji} <b>সঠিক উত্তর:</b> {ans_text}"
            exp = mcq.get("explanation", "").strip()
            if exp:
                reveal += f"\n\n📖 <b>ব্যাখ্যা:</b> {exp}"
            await tg_post("sendMessage", {
                "chat_id": channel_id,
                "text": reveal,
                "parse_mode": "HTML",
                "reply_to_message_id": q_msg_id or topic_msg_id
            })

        reveal_tasks = []
        for i, mcq in enumerate(mcqs, 1):
            q_text = f"❓ প্রশ্ন {i}/{total}\n\n{mcq['question']}"
            q_r = await tg_post("sendMessage", {
                "chat_id": channel_id,
                "text": q_text,
                "reply_to_message_id": topic_msg_id
            })
            q_msg_id = q_r.get("result", {}).get("message_id") if q_r.get("ok") else None

            reveal_tasks.append(_spawn_task(_reveal_answer(i, mcq, q_msg_id)))

            if i < total:
                await asyncio.sleep(RAPID_Q_INTERVAL)

        # সব প্রশ্ন পাঠানো শেষ — কিন্তু শেষ ১-২টা প্রশ্নের উত্তর reveal হতে তখনও
        # কিছু সময় বাকি থাকতে পারে (RAPID_ANS_DELAY > RAPID_Q_INTERVAL হলে)।
        # Closing message-টা সব উত্তর reveal হওয়ার পরেই পাঠাও।
        if reveal_tasks:
            await asyncio.gather(*reveal_tasks)

        closing = (
            f"🎉 ধন্যবাদ! \"{topic}\" এর {total} টি প্রশ্ন শেষ হলো।\n\n"
            f"⁉️ কতগুলো সঠিক করতে পেরেছো? কমেন্টে জানাও! 👇"
        )
        await tg_post("sendMessage", {
            "chat_id": channel_id,
            "text": closing,
            "reply_to_message_id": topic_msg_id
        })

        # PDF → channel-এ topic_msg reply হিসেবে + admin-এও কপি
        try:
            html_out = _build_rapid_pdf_html(topic, mcqs)
            pdf_bytes = await _html_to_pdf(html_out)
            pdf_bytes = await _apply_saved_watermark(pdf_bytes)
            if pdf_bytes:
                safe_topic = re.sub(r"[^\w\u0980-\u09FF\-]+", "_", topic)[:40] or "Rapid"
                pdf_fname = f"{safe_topic}_Rapid_QA.pdf"
                pdf_caption = (
                    f"📄 <b>{topic}</b> — Rapid Fire Q+A\n"
                    f"📝 {total} টি প্রশ্ন | উত্তর + ব্যাখ্যা সহ"
                )
                # Channel-এ first message (topic_msg) reply হিসেবে
                await send_document(channel_id, pdf_bytes, pdf_fname,
                    caption=pdf_caption, mime_type="application/pdf",
                    reply_to_message_id=topic_msg_id)
                # Admin-এও কপি
                await send_document(admin_chat, pdf_bytes, pdf_fname,
                    caption=f"✅ \"{topic}\" Rapid Fire শেষ!\n📝 {total} টি প্রশ্ন\n📄 Q+A+Explanation PDF")
        except Exception as e:
            logger.error(f"[RAPID] PDF error: {e}")

        await sb_exec(lambda: sb.table("quiz_sessions").update({"data": json.dumps({**job, "status": "done"})}) \
            .eq("key", f"rapid_job_{job_id}").execute())

    except Exception as e:
        logger.error(f"[RAPID] job {job_id} run error: {e}")
        try:
            await send_msg(admin_chat, f"❌ /rapid \"{topic}\" চালাতে সমস্যা হয়েছে: {e}")
        except Exception:
            pass


def _build_rapid_pdf_html(topic: str, mcqs: list) -> str:
    """শুধু Question + Answer + Explanation — CSV এর option ছাড়া।"""
    items = ""
    for i, mcq in enumerate(mcqs, 1):
        ans_text = _rapid_get_answer_text(mcq)
        exp = mcq.get("explanation", "").strip()
        items += f"""<div class="qa-box">
  <div class="q-row"><span class="q-no">{i}.</span>
    <div class="q-text">{html_lib.escape(mcq['question'])}</div></div>
  <div class="a-row"><span class="a-label">উত্তর:</span>
    <div class="a-text">{html_lib.escape(ans_text)}</div></div>
  {f'<div class="exp-row"><span class="exp-label">ব্যাখ্যা:</span><div class="exp-text">{html_lib.escape(exp)}</div></div>' if exp else ''}
</div>"""

    return f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8"><style>
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400;600;700;800&display=swap');
@page{{size:A4;margin:12mm 10mm;}}
*{{margin:0;padding:0;box-sizing:border-box;}}
body{{font-family:'Noto Sans Bengali',sans-serif;background:#fff;color:#1a1a2e;font-size:12.5px;}}
.hdr{{text-align:center;padding:16px 18px;background:linear-gradient(135deg,#1a237e,#3949ab);color:#fff;border-radius:10px;margin-bottom:14px;}}
.hdr h1{{font-size:18px;font-weight:800;}}
.hdr .sub{{font-size:12px;color:#c5cae9;margin-top:5px;}}
.qa-box{{border:1.5px solid #d4dce6;border-radius:9px;margin-bottom:9px;overflow:hidden;break-inside:avoid;page-break-inside:avoid;}}
.q-row{{display:flex;gap:8px;background:#eef4fb;padding:9px 12px;border-bottom:1px solid #d4dce6;}}
.q-no{{font-weight:800;color:#0d4a8f;flex-shrink:0;}}
.q-text{{color:#0d2438;font-weight:600;line-height:1.6;}}
.a-row{{display:flex;gap:8px;background:#fff8ec;padding:8px 12px;}}
.a-label{{font-weight:800;color:#a15c00;flex-shrink:0;}}
.a-text{{color:#4a3000;line-height:1.6;}}
.exp-row{{display:flex;gap:8px;background:#eefaf1;padding:8px 12px;border-top:1px solid #d4dce6;}}
.exp-label{{font-weight:800;color:#1b5e20;flex-shrink:0;}}
.exp-text{{color:#1b3a1f;line-height:1.6;}}
.footer{{text-align:center;font-size:9.5px;color:#9aa5b1;margin-top:14px;}}
</style></head>
<body>
<div class="hdr"><h1>🚀 {html_lib.escape(topic)}</h1><div class="sub">Rapid Fire — Q + A + Explanation</div></div>
{items}
<div class="footer">🚀 ATLAS APP — Atlascourses.com</div>
</body></html>"""


async def _recover_rapid_jobs():
    """App restart হলে যেসব /rapid job এখনো fire হয়নি (run_at_ts ভবিষ্যতে), সেগুলো
    আবার schedule করে। Past হয়ে গেলে (process অনেকক্ষণ বন্ধ ছিল) মিস হিসেবে গণ্য করে skip করে।"""
    try:
        rows = await sb_exec(lambda: sb.table("quiz_sessions").select("key,data") \
            .like("key", "rapid_job_%").execute())
        now_ts = time.time()
        for row in (rows.data or []):
            try:
                job = json.loads(row["data"])
            except Exception:
                continue
            if job.get("status") == "done":
                continue
            run_at_ts = job.get("run_at_ts", 0)
            job_id = row["key"].replace("rapid_job_", "")
            if run_at_ts <= now_ts:
                logger.warning(f"[RAPID] job {job_id} missed its scheduled time during downtime — skipping")
                await sb_exec(lambda: sb.table("quiz_sessions").update({"data": json.dumps({**job, "status": "missed"})}) \
                    .eq("key", row["key"]).execute())
                continue
            delay = run_at_ts - now_ts
            task = _spawn_task(_rapid_wait_and_run(job_id, delay))
            RAPID_TASKS[job_id] = task
            logger.info(f"[RAPID] recovered job {job_id}, fires in {int(delay)}s")
    except Exception as e:
        logger.error(f"[RAPID] recovery error: {e}")


# ============================================================
# FEATURE: /live — Live Quiz System (v4)
# ============================================================
LIVE_POLL_MAP = {}  # poll_id -> group_id

async def handle_live_command(msg: dict):
    chat_id = msg["chat"]["id"]
    uid     = msg["from"]["id"]
    text    = msg.get("text", "").strip()
    reply   = msg.get("reply_to_message")

    topic = text.replace("/live", "").strip()
    if not topic:
        topic = "ATLAS Live Quiz"

    if not reply or not reply.get("document"):
        await send_msg(chat_id,
            "❌ CSV ফাইলে reply করে /live দাও!\n\n"
            "<b>Example:</b>\n"
            "<code>/live জাতীয় বাজেট-২০২৬</code>"
        )
        return

    doc = reply.get("document", {})
    if not doc.get("file_name", "").lower().endswith(".csv"):
        await send_msg(chat_id, "❌ শুধু .csv file support করে!")
        return

    file_name = doc.get("file_name", "")
    file_size = doc.get("file_size", 0)
    size_kb = round(file_size / 1024, 1) if file_size else "?"
    loading    = await send_msg(chat_id, f"⏳ CSV download হচ্ছে...\n📄 {file_name}\n📦 {size_kb} KB\n[░░░░░░░░░░ 0%]")
    loading_id = loading.get("result", {}).get("message_id")

    _last_pct_live = {"v": -1}
    def _dl_progress_live(done, total):
        if not loading_id or not total:
            return
        pct = int(done * 100 / total)
        if pct - _last_pct_live["v"] < 15 and pct != 100:
            return
        _last_pct_live["v"] = pct
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        _spawn_task(edit_msg(chat_id, loading_id, f"⏳ CSV download হচ্ছে...\n📄 {file_name}\n📦 {size_kb} KB\n[{bar} {pct}%]"))

    try:
        csv_bytes  = await download_tg_file(doc["file_id"], progress_cb=_dl_progress_live)
        if loading_id:
            await edit_msg(chat_id, loading_id, "✅ Download সম্পূর্ণ!\n[██████████ 100%]\n⏳ CSV parse হচ্ছে...")
        mcqs       = _parse_csv_bytes(csv_bytes)

        if not mcqs:
            await send_msg(chat_id, "❌ CSV-এ কোনো MCQ পাওয়া যায়নি!")
            return

        if loading_id:
            await edit_msg(chat_id, loading_id, f"✅ {len(mcqs)} টি MCQ পাওয়া গেছে!")

        session_id = gen_session_id()

        await sb_exec(lambda: sb.table("quiz_sessions").upsert({
            "key":        f"live_pending_{uid}",
            "data":       json.dumps({
                "session_id": session_id,
                "topic":      topic,
                "mcqs":       mcqs,
                "admin_chat": chat_id
            }),
            "updated_at": int(time.time())
        }).execute())

        if loading_id:
            await edit_msg(chat_id, loading_id,
                f"✅ {len(mcqs)} MCQ পাওয়া গেছে!\n"
                f"📢 Group select করো:")

        channels = await db_get_channels()
        if not channels:
            await send_msg(chat_id, "❌ কোনো group save নেই! /channel দিয়ে add করো।")
            return

        kb = {"inline_keyboard": []}
        for ch in channels:
            ch_id   = ch.get("channel_id", "")
            ch_name = ch.get("channel_name", ch_id)
            kb["inline_keyboard"].append([{
                "text":          f"📢 {ch_name}",
                "callback_data": f"livechannel_{ch_id}_{uid}"
            }])
        kb["inline_keyboard"].append([{
            "text":          "❌ Cancel",
            "callback_data": f"livecancel_{uid}"
        }])

        await send_msg(chat_id,
            f"🎯 Topic: {topic}\n"
            f"📝 MCQ: {len(mcqs)} টি\n\n"
            f"📢 Group select করো:",
            reply_markup=kb
        )

    except Exception as e:
        logger.error(f"[LIVE] error: {e}")
        await _safe_error_reply(chat_id, e)


async def start_live_quiz(group_id, session_id: str, topic: str,
                           mcqs: list, admin_chat: int, per_q_time: int, *args, **kwargs):
    """Live Quiz main runner (v4). Backward-compatible signature."""
    bd_time = _get_bd_time()
    total   = len(mcqs)

    pre_text = (
        f"🌟ATLAS Live Quiz🌟\n\n"
        f"🚀Topic: {topic}\n"
        f"🔗সময়: {bd_time}\n"
        f"🎯MCQ: {total} টি\n"
        f"⚡Per Quiz Time: {per_q_time} sec\n\n"
        f"Are Your Ready?"
    )
    await tg_post("sendMessage", {"chat_id": group_id, "text": pre_text})

    await asyncio.sleep(2)
    await tg_post("sendMessage", {"chat_id": group_id, "text": "3️⃣"})
    await asyncio.sleep(2)
    await tg_post("sendMessage", {"chat_id": group_id, "text": "2️⃣"})
    await asyncio.sleep(2)
    await tg_post("sendMessage", {"chat_id": group_id, "text": "1️⃣ 🚀 শুরু!"})
    await asyncio.sleep(1)

    quiz_start = time.time()
    live_state = {
        "session_id":          session_id,
        "topic":               topic,
        "mcqs":                mcqs,
        "total":               total,
        "current_idx":         0,
        "per_q_time":          per_q_time,
        "group_id":            group_id,
        "admin_chat":          admin_chat,
        "active":              True,
        "quiz_start_time":     quiz_start,
        "scores":              {},
        "current_poll_id":     None,
        "current_poll_msg_id": None,
        "current_correct_idx": 0,
        # নতুন: কে কোন option দাগিয়েছে track করার জন্য
        "option_voters":       {},  # poll_id -> {option_idx: [user_name, ...]}
    }
    LIVE_QUIZ_STATE[group_id] = live_state

    settings   = await db_get_settings()
    tag        = settings.get("tag", "")
    exp_footer = settings.get("exp_footer", "")

    for idx, mcq in enumerate(mcqs):
        if not LIVE_QUIZ_STATE.get(group_id, {}).get("active"):
            break

        live_state["current_idx"]         = idx
        live_state["current_correct_idx"] = {"A": 0, "B": 1, "C": 2, "D": 3}.get(
            mcq.get("answer", "A"), 0
        )

        opts    = mcq.get("options", [])
        ans_idx = live_state["current_correct_idx"]

        q_text = f"[{idx+1}/{total}] {mcq['question']}"
        if tag:
            q_text = f"{tag}\n\n{q_text}"

        exp = mcq.get("explanation", "")
        if exp_footer:
            exp = f"{exp}\n{exp_footer}"

        # Try non-anonymous first (for groups with View Votes feature)
        poll_r = await tg_post("sendPoll", {
            "chat_id":           group_id,
            "question":          q_text[:300],
            "options":           opts[:4],
            "type":              "regular",
            "is_anonymous":      False,
            "open_period":       per_q_time
        })

        # Fallback: If channel doesn't allow non-anonymous, use anonymous
        if not poll_r.get("ok") and "non-anonymous" in str(poll_r.get("description", "")):
            logger.warning(f"[LIVE] Target {group_id} is a channel, switching to anonymous poll")
            await send_msg(admin_chat, 
                f"⚠️ <b>Live Quiz Warning</b>\n\nTarget <code>{group_id}</code> is a <b>channel</b>.\nLive Quiz works best in <b>groups</b> for View Votes feature.\n\n✅ Quiz will continue with anonymous voting.")
            poll_r = await tg_post("sendPoll", {
                "chat_id":           group_id,
                "question":          q_text[:300],
                "options":           opts[:4],
                "type":              "regular",
                "is_anonymous":      True,
                "open_period":       per_q_time
            })

        poll_id = ""
        poll_msg_id = None
        if poll_r.get("ok"):
            poll_id = poll_r["result"].get("poll", {}).get("id", "")
            poll_msg_id = poll_r["result"]["message_id"]
            live_state["current_poll_id"] = poll_id
            live_state["current_poll_msg_id"] = poll_msg_id
            if poll_id:
                LIVE_POLL_MAP[poll_id] = group_id


        else:
            logger.warning(
                f"[LIVE] Poll {idx+1} failed: {poll_r.get('description')}"
            )

        # ✅ Timer শেষ হলে instant next — 0.5s delay only (আগে per_q_time + 2 ছিল)
        # open_period দিয়ে Telegram নিজেই timer manage করে।
        # আমরা শুধু open_period সেকেন্ড wait করব, তারপর 0.5s buffer।
        await asyncio.sleep(per_q_time + 0.5)

        if poll_r.get("ok"):
            try:
                # Stop the poll to show results
                stop_result = await tg_post("stopPoll", {
                    "chat_id":    group_id,
                    "message_id": poll_r["result"]["message_id"]
                })

                # ✅ Send correct answer reveal message
                correct_idx = live_state.get("current_correct_idx", 0)
                correct_letter = ["A", "B", "C", "D"][correct_idx] if correct_idx < 4 else "A"
                correct_option = opts[correct_idx] if correct_idx < len(opts) else opts[0]

                reveal_text = (
                    f"✅ <b>Correct Answer:</b> ({correct_letter}) {correct_option}\n"
                    f"📖 <b>Explanation:</b> {exp[:199]}"
                )
                await tg_post("sendMessage", {
                    "chat_id": group_id,
                    "text": reveal_text,
                    "parse_mode": "HTML",
                    "reply_to_message_id": poll_r["result"]["message_id"],
                    "disable_notification": True
                })
            except Exception:
                pass
            if poll_id:
                LIVE_POLL_MAP.pop(poll_id, None)

        # ✅ Instant next — 0s delay
        await asyncio.sleep(0)

    live_state["active"] = False
    LIVE_QUIZ_STATE.pop(group_id, None)
    await _send_live_grand_result(group_id, live_state)


async def handle_live_poll_answer(pa: dict):
    """
    Handle poll answers for regular poll (type: "poll").
    Tracks user votes and calculates scores.
    """
    poll_id    = pa.get("poll_id", "")
    option_ids = pa.get("option_ids", [])
    chosen     = option_ids[0] if option_ids else None

    group_id = LIVE_POLL_MAP.get(poll_id)
    if not group_id:
        # Fallback: legacy in-memory active state
        for ch_id, st in LIVE_QUIZ_STATE.items():
            if st.get("active") and st.get("current_poll_id") == poll_id:
                group_id = ch_id
                break
    if not group_id:
        return

    state = LIVE_QUIZ_STATE.get(group_id)
    if not state or not state.get("active"):
        return

    user      = pa.get("user", {})
    uid_str   = str(user.get("id", "unknown"))
    user_name = user.get("first_name", "User")
    username  = user.get("username", "")
    now       = time.time()
    idx       = state["current_idx"]

    if "scores" not in state:
        state["scores"] = {}

    if uid_str not in state["scores"]:
        state["scores"][uid_str] = {
            "name":             user_name,
            "username":         username,
            "correct":          0,
            "wrong":            0,
            "answered_qs":      set(),
            "last_answer_time": now,
            "first_seen_time":  now,
        }

    s = state["scores"][uid_str]
    s["name"]             = user_name
    s["username"]         = username
    s["last_answer_time"] = now

    if idx in s["answered_qs"]:
        return

    s["answered_qs"].add(idx)

    correct_idx = state.get("current_correct_idx", 0)
    if chosen == correct_idx:
        s["correct"] += 1
    else:
        s["wrong"]   += 1

    # ✅ Track which option each user voted for
    if chosen is not None:
        poll_id_key = state.get("current_poll_id", "current")
        if "option_voters" not in state:
            state["option_voters"] = {}
        if poll_id_key not in state["option_voters"]:
            state["option_voters"][poll_id_key] = {0: [], 1: [], 2: [], 3: []}
        voters_for_poll = state["option_voters"][poll_id_key]
        if chosen in voters_for_poll:
            voters_for_poll[chosen].append(s["name"])


async def _send_live_grand_result(group_id, state: dict):
    try:
        from pdf_handler import get_live_motivation_and_ayat
    except Exception:
        def get_live_motivation_and_ayat(pct):
            return ("চেষ্টা চালিয়ে যাও!", "\"নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে।\" — সূরা আল-ইনশিরাহ, ৯৪:৫")

    topic             = state["topic"]
    total             = state["total"]
    scores            = state.get("scores", {})
    session_id        = state["session_id"]
    quiz_start        = state["quiz_start_time"]
    participant_count = len(scores)

    score_list = []
    for uid_str, s in scores.items():
        correct  = s["correct"]
        wrong    = s["wrong"]
        answered = len(s["answered_qs"])
        skipped  = total - answered

        score = round(correct - wrong * 0.25, 2)

        total_secs = s["last_answer_time"] - quiz_start
        total_secs = max(0, total_secs)
        mins       = int(total_secs // 60)
        secs_rem   = int(total_secs % 60)
        if mins > 0:
            time_str = f"{mins}m {secs_rem:02d}s"
        else:
            time_str = f"{secs_rem}s"

        participation_pct = round(answered / total * 100, 1) if total else 0
        mark_pct          = round(correct / total * 100, 1)  if total else 0

        score_list.append({
            "user_id":            int(uid_str) if uid_str.isdigit() else 0,
            "name":               s["name"],
            "username":           s.get("username", ""),
            "correct":            correct,
            "wrong":              wrong,
            "skipped":            skipped,
            "score":              score,
            "total":              total,
            "time_str":           time_str,
            "total_secs":         total_secs,
            "participation_pct":  participation_pct,
            "mark_pct":           mark_pct,
        })

        try:
            await db_save_live_result(
                session_id,
                int(uid_str) if uid_str.isdigit() else 0,
                s["name"], correct, wrong, skipped, total,
                total_secs / answered if answered else 0
            )
        except Exception as e:
            logger.error(f"[LIVE] db_save_live_result error: {e}")

    qualified = [s for s in score_list if s["participation_pct"] >= 15]
    qualified.sort(key=lambda x: (-x["score"], x["total_secs"]))

    medals = ["🥇", "🥈", "🥉"]

    def _fmt(i: int, s: dict) -> str:
        medal  = medals[i] if i < 3 else f"{i+1}."
        uname  = f" @{s['username']}" if s.get("username") else ""
        prefix = "───────────────\n" if i == 0 else ""
        return (
            f"{prefix}"
            f"{medal} {s['name']}{uname}\n"
            f"   ✅: {s['correct']}  "
            f"❌: {s['wrong']}  "
            f"⏭ Skip: {s['skipped']}\n"
            f"   📊 Score: {s['score']} / {s['total']}  "
            f"⏱️ {s['time_str']}"
        )

    header = (
        f"🟥Grand Result of ATLAS Live Quiz\n\n"
        f"🌟Topic: {topic}\n"
        f"🎯Total MCQ: {total}\n"
        f"⚡Total Participants: {participant_count}\n\n"
        f"💎Best Scorers💎\n"
    )

    footer = (
        "\n──────────────────────────────\n"
        "🎉 Congratulations everyone! "
        "Stay ready for our next quiz."
    )

    parts        = []
    current_part = []
    current_len  = len(header)

    for i, s in enumerate(qualified):
        line     = _fmt(i, s)
        line_len = len(line) + 1

        if current_len + line_len > 3800:
            parts.append(current_part)
            current_part = [line]
            current_len  = line_len
        else:
            current_part.append(line)
            current_len += line_len

    if current_part:
        parts.append(current_part)

    if not parts:
        await tg_post("sendMessage", {
            "chat_id": group_id,
            "text":    header +
                       "\n(কেউ ১৫% বা তার বেশি প্রশ্নের উত্তর দেননি)" +
                       footer
        })
    else:
        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)
            if i == 0:
                text = header + "\n".join(part)
            else:
                text = f"🚀Grand Result — Part {i+1}\n\n" + "\n".join(part)
            if is_last:
                text += footer

            await tg_post("sendMessage", {
                "chat_id": group_id,
                "text":    text
            })
            await asyncio.sleep(0.5)

    bd_time = _get_bd_time()

    for s in score_list:
        if s["participation_pct"] >= 70 and s["mark_pct"] < 50 and s["user_id"]:
            motivation, ayat = get_live_motivation_and_ayat(s["mark_pct"])

            dm_text = (
                f"আসসালামু আলাইকুম, প্রিয় শিক্ষার্থী {s['name']}!\n\n"
                f"আপনি ({bd_time}) তে {topic} এ এটলাসের লাইভ কুইজে "
                f"অংশগ্রহণ করেছিলেন। হয়তোবা কিছু ঘাটতির কারণে আপনার "
                f"বেস্ট রেজাল্ট পাননি, টেনশন করবেন না, পরবর্তী কুইজে "
                f"আরো ভালো প্রস্তুতি নিয়ে কুইজ দিবেন, এটলাস টিম "
                f"আশাবাদী আপনি আরো ভালো করবেন।\n\n"
                f"{motivation}\n\n"
                f"{ayat}\n\n"
                f"✅শুভকামনায়-Team ATLAS\n\n"
                f"⚙️পরবর্তী কুইজে অংশগ্রহণ করতে যুক্ত থাকুন "
                f"এটলাসের সাথেই।\n\n"
                f"🌟লাইভ কুইজ গ্রুপ:\n"
                f"https://t.me/LiveQuizByAtlas\n"
                f"🌟এটলাসের সকল গ্রুপ+চ্যানেল:\n"
                f"https://t.me/addlist/GECHwfEIZ_ozZmVl\n"
                f"📌ATLAS Website: Atlascourses.com"
            )
            try:
                await send_msg(s["user_id"], dm_text)
                await asyncio.sleep(0.5)
            except Exception:
                pass

# ============================================================
# FEATURE: /pdfc image collection → /done → PDF
# ============================================================
async def handle_pdf_image_mode(msg: dict):
    """
    /pdfc দিলে bot image চাইবে।
    User একটার পর একটা image পাঠাবে।
    /done দিলে সব image দিয়ে ATLAS.pdf বানাবে।
    """
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text","").strip()

    if text in ("/pdfc", "/pdf_collect"):
        IMG_COLLECTION[uid] = {"imgs": [], "collecting": True, "chat_id": chat_id}
        await send_msg(chat_id,
            "📸 Image collection mode চালু!\n\n"
            "একটার পর একটা image পাঠাও।\n"
            "শেষ হলে /done দাও — ATLAS.pdf বানিয়ে দেব।\n\n"
            "❌ বাতিল করতে /cancel দাও।"
        )
        return

    if text == "/done":
        if uid not in IMG_COLLECTION or not IMG_COLLECTION[uid].get("collecting"):
            await send_msg(chat_id, "❌ আগে /pdfc দিয়ে image collection শুরু করো!")
            return
        imgs = IMG_COLLECTION[uid].get("imgs",[])
        if not imgs:
            await send_msg(chat_id, "❌ কোনো image পাওয়া যায়নি!")
            return

        loading = await send_msg(chat_id, f"⏳ {len(imgs)} টি image দিয়ে PDF বানানো হচ্ছে...")
        IMG_COLLECTION.pop(uid, None)

        try:
            from PIL import Image as PILImage
            import io as _io
            pdf_images = []
            for img_bytes in imgs:
                im = PILImage.open(_io.BytesIO(img_bytes)).convert("RGB")
                pdf_images.append(im)

            buf = _io.BytesIO()
            pdf_images[0].save(buf, format="PDF", save_all=True, append_images=pdf_images[1:])
            pdf_bytes = buf.getvalue()

            await send_document(chat_id, pdf_bytes, "ATLAS.pdf",
                caption=f"📄 ATLAS.pdf — {len(pdf_images)} pages",
                mime_type="application/pdf")

            loading_id = loading.get("result",{}).get("message_id")
            if loading_id:
                await edit_msg(chat_id, loading_id,
                    f"✅ ATLAS.pdf তৈরি হয়েছে! ({len(pdf_images)} pages)")

        except Exception as e:
            await send_msg(chat_id, f"❌ PDF বানাতে error: {e}")
        return

    if text == "/cancel":
        IMG_COLLECTION.pop(uid, None)
        if uid in RAPID_PENDING:
            RAPID_PENDING.pop(uid, None)
            await send_msg(chat_id, "❌ /rapid scheduling বাতিল।")
            return
        await send_msg(chat_id, "❌ Image collection বাতিল।")
        return

async def handle_incoming_image_for_collection(msg: dict):
    """User যদি image collection mode-এ থাকে, image save করো"""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]

    if uid not in IMG_COLLECTION or not IMG_COLLECTION[uid].get("collecting"):
        return False

    photo = msg.get("photo") or (msg.get("document") if msg.get("document",{}).get("mime_type","").startswith("image") else None)
    if not photo:
        return False

    if isinstance(photo, list):
        file_id = photo[-1]["file_id"]
    else:
        file_id = photo["file_id"]

    try:
        img_bytes = await download_tg_file(file_id)
        IMG_COLLECTION[uid]["imgs"].append(img_bytes)
        count = len(IMG_COLLECTION[uid]["imgs"])
        await send_msg(chat_id, f"✅ Image {count} save হয়েছে! (আরো দাও বা /done)")
    except Exception as e:
        await send_msg(chat_id, f"❌ Image save error: {e}")
    return True

