# MISTAKE / SPECIAL PRACTICE
# ============================================================
async def handle_quiz_practice(uid: int, chat_id: int, uname: str, kind: str):
    last = await lq_get(uid)
    if not last:
        last = await db_get_last_quiz(uid)
    if not last:
        await send_msg(chat_id, "❌ কোনো quiz history পাওয়া যায়নি!\nআগে একটা quiz শেষ করো।")
        return

    if kind == "mis":
        indices = list(last["wrong_idx"])
        title = "❌ <b>Mistake Practice শুরু হচ্ছে!</b>"
        if not indices:
            await send_msg(chat_id, "🎉 কোনো ভুল নেই — দারুণ পারফরম্যান্স!")
            return
    else:
        indices = sorted(set(last["wrong_idx"] + last["skip_idx"]))
        title = "🔥 <b>Special Practice শুরু হচ্ছে!</b>"
        if not indices:
            await send_msg(chat_id, "🎉 কোনো ভুল বা skip নেই — পারফেক্ট!")
            return

    src = last.get("src_indices")
    if src is not None:
        indices = [src[i] for i in indices if i < len(src)]

    count = len(indices)
    await send_msg(chat_id, f"📝 {count} টি প্রশ্ন নিয়ে practice শুরু হচ্ছে...")
    await start_sequential_quiz(chat_id, uid, uname, last["cache_id"], indices=indices, mode="practice", title=title)



async def handle_collect_command(msg: dict):
    """Poll collection from forwarded polls"""
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "").strip()

    if text == "/collect":
        await send_msg(chat_id,
            "📊 Poll collection started!\n\n"
            "Forward polls to collect.\n"
            "/cstatus — check count\n"
            "/cdone — download CSV\n"
            "/ccancel — clear"
        )
        return
    if text == "/cstatus":
        rows = await d1_select(
            "SELECT COUNT(*) as c FROM poll_collection WHERE user_id=?1", [uid]
        )
        await send_msg(chat_id, f"📊 Total collected: {rows[0]['c'] if rows else 0} polls")
        return
    if text == "/cdone":
        rows = await d1_select(
            "SELECT poll_data FROM poll_collection WHERE user_id=?1", [uid]
        )
        if not rows:
            await send_msg(chat_id, "❌ No polls collected!")
            return
        import io as _io, csv as _csv
        buf = _io.StringIO()
        writer = _csv.writer(buf)
        writer.writerow(["questions","option1","option2","option3","option4","answer","explanation","type","section"])
        for r in rows:
            pd = json.loads(r["poll_data"])
            opts = pd.get("options", [])
            while len(opts) < 4:
                opts.append("")
            ans = str((pd.get("correct", 0) or 0) + 1)
            writer.writerow([pd.get("question",""), opts[0], opts[1], opts[2], opts[3],
                             ans, pd.get("explanation",""), "1", "1"])
        await send_document(chat_id, buf.getvalue().encode("utf-8"),
            f"collected_{len(rows)}.csv",
            caption=f"✅ {len(rows)} polls collected!",
            mime_type="text/csv")
        await d1_run("DELETE FROM poll_collection WHERE user_id=?1", [uid])
        return
    if text == "/ccancel":
        await d1_run("DELETE FROM poll_collection WHERE user_id=?1", [uid])
        await send_msg(chat_id, "❌ Collection cancelled!")
        return


_LABEL_KV_PREFIX = "autolms_label:"
_LABEL_INDEX_KEY = "autolms_label_index"


async def _label_index_add(name: str):
    idx = await d1_get(_LABEL_INDEX_KEY) or {}
    names = set(idx.get("names", []))
    names.add(name)
    await d1_set(_LABEL_INDEX_KEY, {"names": sorted(names)}, ttl=3153600000)


async def _label_index_remove(name: str):
    idx = await d1_get(_LABEL_INDEX_KEY) or {}
    names = set(idx.get("names", []))
    names.discard(name)
    await d1_set(_LABEL_INDEX_KEY, {"names": sorted(names)}, ttl=3153600000)


async def _resolve_click_steps(chat_id: int, step_lines: list) -> list | None:
    """
    /autolms-only resolver for "use:<name>" (a /savelabel-saved
    multi-step sequence, expanded in-place). The "text=link" inline
    shortcut and its plain-text lookup are NOT handled here -- that's
    already built into atlas_autoscrape.py itself (via
    core.auto_link_map_set/get), shared with /auto, so passing those
    lines through unchanged lets the existing, working implementation
    handle them exactly as it already does for /auto.

    Returns the resolved list, or None (after sending an error message)
    if a referenced "use:" name can't be found.
    """
    resolved = []
    for l in step_lines:
        raw = l.strip()
        if raw.lower().startswith("use:"):
            label_name = raw[len("use:"):].strip()
            saved = await d1_get(f"{_LABEL_KV_PREFIX}{label_name}")
            if not saved or not saved.get("steps"):
                await send_msg(chat_id, f"❌ এই নামে কোনো সেভ করা label পাওয়া যায়নি: {label_name}\n/labels দিয়ে তালিকা দেখো।")
                return None
            resolved.extend(saved["steps"])
            continue
        resolved.append(l)
    return resolved


async def handle_savelabel_command(msg: dict):
    """
    /savelabel <name>
    বাংলা
    প্রথম পত্র
    অধ্যায় ১
    টপিক ১

    Saves the click-step lines (everything after the first line) under
    <name> so future /autolms runs can reuse them with "use:<name>"
    instead of retyping the whole path every time.

    Special case: a single raw URL line (starts with http) is treated as
    a direct-navigate shortcut, useful for saving the link behind a
    text-less image/icon button on chorcha.net so you can drop "use:name"
    into any click-sequence in place of that one un-clickable step.
    """
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    lines = text.split("\n")
    first = lines[0].strip()
    name = first[len("/savelabel"):].strip()
    step_lines = [l.rstrip() for l in lines[1:] if l.strip() != ""]
    if len(step_lines) == 1 and step_lines[0].strip().lower().startswith("http"):
        step_lines = [f"goto:{step_lines[0].strip()}"]

    if not name or not step_lines:
        await send_msg(chat_id,
            "❌ Format:\n\n"
            "<code>/savelabel টপিক১নাম\n"
            "বাংলা\n"
            "প্রথম পত্র\n"
            "অধ্যায় ১\n"
            "টপিক ১</code>\n\n"
            "প্রথম লাইনে <code>/savelabel</code>-এর পর একটা নাম দাও, তারপর প্রতি লাইনে chorcha.net-এর ক্লিক-স্টেপ। "
            "পরে <code>/autolms</code>-এ <code>use:টপিক১নাম</code> লিখলেই এই স্টেপগুলো আবার লিখতে হবে না।",
            parse_mode="HTML")
        return

    await d1_set(f"{_LABEL_KV_PREFIX}{name}", {"steps": step_lines}, ttl=3153600000)  # ~100 years, effectively permanent
    await _label_index_add(name)
    await send_msg(chat_id,
        f"✅ সেভ হয়েছে: <b>{name}</b> ({len(step_lines)} ধাপ)\n"
        f"পরে ব্যবহার করতে: <code>/autolms\\nuse:{name}\\n---\\nsub=...</code>",
        parse_mode="HTML")


async def handle_list_labels_command(msg: dict):
    """/labels -- lists all saved shortcut names from /savelabel."""
    chat_id = msg["chat"]["id"]
    idx = await d1_get(_LABEL_INDEX_KEY) or {}
    names = sorted(idx.get("names", []))
    if not names:
        await send_msg(chat_id, "কোনো সেভ করা label নেই। /savelabel দিয়ে একটা বানাও।")
        return
    listing = "\n".join(f"• {n}" for n in names)
    await send_msg(chat_id, f"📌 সেভ করা label গুলো:\n\n{listing}")


async def handle_dellabel_command(msg: dict):
    """/dellabel <name> -- deletes a saved shortcut."""
    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    name = text[len("/dellabel"):].strip()
    if not name:
        await send_msg(chat_id, "❌ Format: <code>/dellabel টপিক১নাম</code>", parse_mode="HTML")
        return
    await d1_del(f"{_LABEL_KV_PREFIX}{name}")
    await _label_index_remove(name)
    await send_msg(chat_id, f"🗑️ মুছে ফেলা হয়েছে: {name}")


async def handle_autolms_command(msg: dict):
    """
    /autolms
    বাংলা
    প্রথম পত্র
    অধ্যায় ১
    টপিক ১
    ---
    sub=বাংলা
    chap=অধ্যায় ১
    pt=
    b/c=
    s/sc=
    rfc=

    Same chorcha.net click-sequence scrape as /auto (single run only --
    no "---" multi-run support here, keep it simple), but instead of
    sending a CSV file back, uploads the extracted MCQs directly into
    the LMS (atlascourses.com) Supabase as a new Readymade exam. The
    LMS website reads straight from that Supabase project, so once the
    insert succeeds the exam is already live on the site -- no separate
    "upload to website" step.

    Everything after a line containing exactly "---" is metadata (one
    key=value per line, matching the Exam Form's Readymade fields; all
    optional except sub). Everything before "---" is chorcha.net click
    steps, one label per line, exactly like /auto.
      sub=      -> Subject (required)
      chap=     -> Chapter
      pt=       -> Parent Topic (readymade_topic)
      b/c=      -> Board/Category (readymade_category)
      s/sc=     -> Session/Sub-Chapter (readymade_sub_chapter)
      rfc=      -> Readymade For Courses -- comma-separated course IDs
                    (readymade_course_ids); blank = not tied to any course
      marks=    -> total marks; blank = auto (1 mark/question)
      negative= -> negative marks per wrong answer; blank = 0 (none)
      start=    -> ISO datetime (e.g. 2026-08-15T00:00:00) when the exam
                    becomes accessible; blank = accessible now. No
                    end-time limit is ever set -- access never expires.
      title=    -> custom exam title; blank = last click-step's label
      free=yes/no -> visible on Free exams tab (default no)
      restrict_solution=yes/no -> hide solutions after submit (default no)
      only_live=yes/no -> only accessible during a live window (default no)
      no_timer_deduct=yes/no -> disable per-second timer deduction (default no)

    Duration is ALWAYS auto-calculated as 35 seconds per MCQ -- not
    configurable. Exam is always is_readymade=True, is_published=True,
    exam_type="practice".

    For sub/chap/pt/b/c/s/sc -- if the value you type already exists in
    the Exam Form's dropdown it's reused as-is; if it's new, it gets
    added to that dropdown too (exactly like typing a new value in the
    Exam Form would).

    Exam title = the LAST click-step label (deepest topic name), matching
    how /auto derives its `topic` for the CSV filename.
    """
    from atlas_autoscrape import AutoScrapeError, run_auto_click_sequence
    from atlas_mhtml import parse_mhtml_to_mcqs
    from lms_upload import upload_mcqs_to_lms, LmsUploadError

    chat_id = msg["chat"]["id"]
    text = msg.get("text", "")
    clear_cancel(chat_id)
    new_job_id(chat_id)
    set_active_job(chat_id, "/autolms (chorcha -> LMS)")

    raw_lines = [l.rstrip() for l in text.split("\n")[1:] if l.strip() != ""]

    # Everything after a line that is exactly "---" is metadata (one
    # key=value per line). Everything before it is chorcha.net click steps.
    step_lines = []
    meta_lines = []
    in_meta = False
    for l in raw_lines:
        if l.strip() == "---":
            in_meta = True
            continue
        if in_meta:
            meta_lines.append(l.strip())
        else:
            step_lines.append(l)

    def _fmt_help():
        return (
            "❌ Format (প্রতিটা তথ্য আলাদা লাইনে লেখো, একসাথে গুলিয়ে ফেলো না):\n\n"
            "<code>/autolms\n"
            "বাংলা\n"
            "প্রথম পত্র\n"
            "অধ্যায় ১\n"
            "টপিক ১\n"
            "---\n"
            "sub=বাংলা\n"
            "chap=অধ্যায় ১\n"
            "pt=\n"
            "b/c=\n"
            "s/sc=\n"
            "rfc=\n"
            "marks=\n"
            "negative=\n"
            "start=\n"
            "free=no\n"
            "restrict_solution=no\n"
            "only_live=no\n"
            "no_timer_deduct=no</code>\n\n"
            "📌 <code>---</code> এর <b>উপরে</b>: chorcha.net-এ ক্লিক করার button/link নাম, একটা লাইনে একটা, ক্রমানুসারে (একদম /auto-এর মতো)।\n"
            "📌 <code>---</code> এর <b>নিচে</b>: প্রতিটা তথ্য এক লাইনে — শুধু <code>sub=</code> লাগবেই, বাকিগুলো ঐচ্ছিক (খালি রাখলেও চলবে, লাইনটা মুছে দিলেও চলবে):\n\n"
            "<code>sub=</code> — Subject / বিষয় (আবশ্যক)\n"
            "<code>chap=</code> — Chapter / অধ্যায়\n"
            "<code>pt=</code> — Parent Topic\n"
            "<code>b/c=</code> — Board/Category\n"
            "<code>s/sc=</code> — Session/Sub-Chapter\n"
            "<code>rfc=</code> — Readymade For Courses (একাধিক course ID কমা দিয়ে)\n"
            "<code>marks=</code> — মোট নম্বর, খালি রাখলে ১ নম্বর/প্রশ্ন\n"
            "<code>negative=</code> — ভুল উত্তরে কাটা নম্বর, খালি রাখলে নেই\n"
            "<code>start=</code> — কবে থেকে চালু (যেমন: 2026-08-15T00:00:00), খালি রাখলে এখনই। কোনো শেষ সময়সীমা থাকবে না — আনলিমিটেড চলবে।\n"
            "<code>title=</code> — Exam-এর নাম নিজে থেকে দাও, খালি রাখলে সবচেয়ে শেষ ক্লিক-স্টেপের নাম ব্যবহার হবে।\n"
            "<code>free=yes/no</code> — Free exam ট্যাবে দেখাবে কিনা (default: no)\n"
            "<code>restrict_solution=yes/no</code> — সাবমিটের পর সমাধান লুকানো (default: no)\n"
            "<code>only_live=yes/no</code> — শুধু লাইভ উইন্ডোতে চলবে কিনা (default: no)\n"
            "<code>no_timer_deduct=yes/no</code> — সেকেন্ড-ভিত্তিক টাইমার কর্তন বন্ধ (default: no)\n\n"
            "⏱️ Duration সবসময় অটো: প্রতি MCQ-তে ৩৫ সেকেন্ড হিসেবে।\n"
            "✅ Exam সবসময় Readymade + Published থাকবে।\n"
            "📌 sub/chap/pt/b·c/s·sc-এ যা লিখবে, আগে থেকে dropdown-এ থাকলে সেটাই ব্যবহার হবে, না থাকলে নতুন যোগ হয়ে যাবে (dropdown-এও পরে দেখা যাবে)।\n"
            "📌 Exam-এর title হবে সবচেয়ে শেষ ক্লিক-স্টেপের নাম। একই নামে exam আগে থেকে থাকলে <code>(New)</code> যোগ হবে, পুরনোটা অক্ষত থাকবে।\n\n"
            "🔖 বারবার একই path না লিখতে চাইলে: <code>/savelabel নাম</code> দিয়ে একবার সেভ করে রাখো, "
            "পরে ক্লিক-স্টেপের জায়গায় শুধু <code>use:নাম</code> লিখলেই চলবে। "
            "<code>/labels</code> দিয়ে তালিকা, <code>/dellabel নাম</code> দিয়ে মুছে ফেলা যায়।\n\n"
            "🖼️ Text নেই এমন image/icon button-এর জন্য: ক্লিক-স্টেপের জায়গায় সরাসরি <code>নাম=লিংক</code> লিখে দাও — "
            "প্রথমবার এই লিংকটাই সেভ হয়ে যাবে ও ব্যবহার হবে। পরের বার শুধু <code>নাম</code> (বা <code>নাম=</code>) লিখলেই আগের সেভ করা লিংকে চলে যাবে, বারবার পুরো লিংক লেখা লাগবে না।"
        )

    if not step_lines or not meta_lines:
        await send_msg(chat_id, _fmt_help(), parse_mode="HTML")
        return

    # Resolve "use:<name>" and inline "text=link" shortcuts (see
    # _resolve_click_steps docstring).
    step_lines = await _resolve_click_steps(chat_id, step_lines)
    if step_lines is None:
        return

    def _yn(v: str, default: bool) -> bool:
        v = v.strip().lower()
        if v in ("yes", "y", "true", "1"):
            return True
        if v in ("no", "n", "false", "0"):
            return False
        return default

    # Parse "key=value" lines where key may itself contain "/" (b/c, s/sc)
    # -- split only on the FIRST "=" per line.
    fields = {}
    for part in meta_lines:
        part = part.strip()
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        fields[k.strip().lower()] = v.strip()

    subject = fields.get("sub") or fields.get("subject") or ""
    chapter = fields.get("chap") or fields.get("chapter") or ""
    parent_topic = fields.get("pt") or ""
    board_category = fields.get("b/c") or ""
    session_subchapter = fields.get("s/sc") or ""
    rfc_raw = fields.get("rfc") or ""
    readymade_course_ids = [c.strip() for c in rfc_raw.split(",") if c.strip()] or None

    def _num(key):
        v = fields.get(key, "")
        if not v:
            return None
        try:
            return float(v) if "." in v else int(v)
        except ValueError:
            return None

    total_marks = _num("marks")
    negative_mark = _num("negative")
    time_window_start = fields.get("start", "").strip() or None
    custom_title = fields.get("title", "").strip() or None
    is_visible_on_free = _yn(fields.get("free", ""), False)
    restrict_solution = _yn(fields.get("restrict_solution", ""), False)
    is_only_live = _yn(fields.get("only_live", ""), False)
    no_timer_deduct = _yn(fields.get("no_timer_deduct", ""), False)

    if not subject:
        await send_msg(chat_id, "❌ sub= খালি রাখা যাবে না।")
        return

    if not os.environ.get("CHORCHA_TOKEN", "").strip():
        await send_msg(chat_id, "❌ CHORCHA_TOKEN সেট করা নেই — আগে login session token env var-এ সেভ করতে হবে।")
        return

    topic = custom_title or step_lines[-1].split(">")[-1].strip()
    status = await send_msg(chat_id, f"⏳ চর্চা.নেট থেকে '{topic}' স্ক্র্যাপ করা হচ্ছে...")
    status_msg_id = status.get("result", {}).get("message_id") if isinstance(status, dict) else None

    async def _progress(step_index, total_steps, label):
        if status_msg_id:
            try:
                await edit_msg(chat_id, status_msg_id,
                    f"⏳ ধাপ {step_index}/{total_steps}: {label}")
            except Exception:
                pass

    try:
        html_results = await asyncio.wait_for(
            run_auto_click_sequence(step_lines, progress_cb=_progress),
            timeout=2700,
        )
    except asyncio.TimeoutError:
        await send_msg(chat_id, "❌ স্ক্র্যাপিং সময়সীমা পার হয়ে গেছে, বন্ধ করে দেওয়া হলো।")
        return
    except AutoScrapeError as e:
        await send_msg(chat_id, f"❌ স্ক্র্যাপ ব্যর্থ: {e}")
        return
    except Exception as e:
        logger.error(f"[/autolms] scrape failed: {e}")
        await send_msg(chat_id, f"❌ অপ্রত্যাশিত ত্রুটি: {e}")
        return

    if not html_results:
        await send_msg(chat_id, "❌ কোনো পেজ পাওয়া যায়নি।")
        return
    html_bytes = html_results[0]

    if status_msg_id:
        try:
            await edit_msg(chat_id, status_msg_id, "📄 HTML থেকে MCQ বের করা হচ্ছে...")
        except Exception:
            pass

    try:
        parsed = await asyncio.to_thread(parse_mhtml_to_mcqs, html_bytes, "autolms-scrape.html")
        results = parsed["results"]
    except Exception as e:
        logger.error(f"[/autolms] parse failed: {e}")
        await send_msg(chat_id, f"❌ MCQ extract ব্যর্থ হয়েছে: {e}")
        return

    if not results:
        await send_msg(chat_id, f"❌ '{topic}' পেজে কোনো MCQ পাওয়া যায়নি।")
        return

    if status_msg_id:
        try:
            await edit_msg(chat_id, status_msg_id, f"📤 LMS-এ আপলোড করা হচ্ছে... ({len(results)}টা MCQ)")
        except Exception:
            pass

    try:
        upload_result = await upload_mcqs_to_lms(
            results=results,
            title=topic,
            subject=subject,
            chapter=chapter,
            readymade_topic=parent_topic or None,
            readymade_category=board_category or None,
            readymade_sub_chapter=session_subchapter or None,
            readymade_course_ids=readymade_course_ids,
            total_marks=total_marks,
            negative_mark_per_question=negative_mark,
            time_window_start=time_window_start,
            is_visible_on_free=is_visible_on_free,
            restrict_solution=restrict_solution,
            disable_second_timer_deduction=no_timer_deduct,
            is_only_live=is_only_live,
        )
    except LmsUploadError as e:
        await send_msg(chat_id, f"❌ LMS আপলোড ব্যর্থ: {e}")
        return
    except Exception as e:
        logger.error(f"[/autolms] upload failed: {e}")
        await send_msg(chat_id, f"❌ অপ্রত্যাশিত আপলোড ত্রুটি: {e}")
        return

    await send_msg(chat_id,
        f"✅ Exam তৈরি হয়েছে: {upload_result['title']}\n"
        f"📝 মোট MCQ: {upload_result['count']}\n"
        f"🌐 LMS-এ এখনই দেখা যাবে (atlascourses.com)")


async def handle_poll_auto_collect(msg: dict):
    """Auto-collect forwarded polls"""
    poll = msg.get("poll")
    if not poll or not msg.get("forward_date"):
        return False
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    try:
        poll_data = {
            "question": poll.get("question", ""),
            "options": [o.get("text", "") for o in poll.get("options", [])],
            "correct": poll.get("correct_option_id"),
            "explanation": poll.get("explanation", "")
        }
        await d1_run(
            "INSERT INTO poll_collection (user_id, poll_data) VALUES (?1, ?2)",
            [uid, json.dumps(poll_data)]
        )
        rows = await d1_select("SELECT COUNT(*) as c FROM poll_collection WHERE user_id=?1", [uid])
        await send_msg(chat_id, f"📊 Collected! Total: {rows[0]['c'] if rows else 0} polls")
        return True
    except Exception as e:
        logger.error(f"[Collect] Error: {e}")
    return False


async def handle_merge_command(msg: dict):
    """CSV file merge + PDF file merge (auto-detected by reply file type)"""
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "").strip()
    reply = msg.get("reply_to_message")

    args = text.replace("/merge", "").strip()

    if args == "done":
        csv_row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_{uid}").execute())
        pdf_row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_pdf_{uid}").execute())
        csv_files = json.loads(csv_row.data[0]["data"]).get("files", []) if csv_row.data else []
        pdf_file_ids = json.loads(pdf_row.data[0]["data"]).get("file_ids", []) if pdf_row.data else []

        if not csv_files and not pdf_file_ids:
            await send_msg(chat_id, "❌ No files to merge!")
            return

        if csv_files:
            all_rows = []
            header = None
            for content in csv_files:
                lines = [l for l in content.split("\n") if l.strip()]
                if not header:
                    header = lines[0]
                    all_rows.append(header)
                all_rows.extend(lines[1:])
            merged = "\n".join(all_rows)
            await send_document(chat_id, merged.encode("utf-8"),
                f"merged_{len(all_rows)-1}.csv",
                caption=f"✅ Merged: {len(all_rows)-1} rows from {len(csv_files)} files",
                mime_type="text/csv")
            await sb_exec(lambda: sb.table("quiz_sessions").delete().eq("key", f"merge_{uid}").execute())

        if pdf_file_ids:
            status = await send_msg(chat_id, f"⏳ {len(pdf_file_ids)}টা PDF merge হচ্ছে...")
            status_id = status.get("result", {}).get("message_id")
            try:
                from pypdf import PdfReader, PdfWriter
                import io as _io
                writer = PdfWriter()
                total_pages = 0
                for fid in pdf_file_ids:
                    pdf_bytes = await download_tg_file(fid)
                    reader = PdfReader(_io.BytesIO(pdf_bytes))
                    for page in reader.pages:
                        writer.add_page(page)
                    total_pages += len(reader.pages)
                out_buf = _io.BytesIO()
                writer.write(out_buf)
                merged_pdf_bytes = out_buf.getvalue()
                await send_document(chat_id, merged_pdf_bytes,
                    f"merged_{len(pdf_file_ids)}files_{total_pages}pages.pdf",
                    caption=f"✅ Merged: {len(pdf_file_ids)} PDF, মোট {total_pages} page",
                    mime_type="application/pdf")
                if status_id:
                    await edit_msg(chat_id, status_id, "✅ PDF merge সম্পন্ন!")
            except Exception as e:
                logger.error(f"[Merge] PDF merge failed: {e}")
                if status_id:
                    await edit_msg(chat_id, status_id, "❌ PDF merge করতে সমস্যা হয়েছে।")
                else:
                    await _safe_error_reply(chat_id, e)
            await sb_exec(lambda: sb.table("quiz_sessions").delete().eq("key", f"merge_pdf_{uid}").execute())
        return

    if args == "status":
        csv_row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_{uid}").execute())
        pdf_row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_pdf_{uid}").execute())
        csv_count = len(json.loads(csv_row.data[0]["data"]).get("files", [])) if csv_row.data else 0
        pdf_count = len(json.loads(pdf_row.data[0]["data"]).get("file_ids", [])) if pdf_row.data else 0
        await send_msg(chat_id, f"📊 CSV files: {csv_count}\n📊 PDF files: {pdf_count}")
        return

    if args == "cancel":
        await sb_exec(lambda: sb.table("quiz_sessions").delete().eq("key", f"merge_{uid}").execute())
        await sb_exec(lambda: sb.table("quiz_sessions").delete().eq("key", f"merge_pdf_{uid}").execute())
        await send_msg(chat_id, "❌ Merge cancelled!")
        return

    if reply and reply.get("document"):
        doc = reply["document"]
        fname = (doc.get("file_name") or "").lower()
        is_pdf = fname.endswith(".pdf") or doc.get("mime_type") == "application/pdf"

        if is_pdf:
            try:
                row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_pdf_{uid}").execute())
                file_ids = json.loads(row.data[0]["data"]).get("file_ids", []) if row.data else []
                file_ids.append(doc["file_id"])
                await sb_exec(lambda: sb.table("quiz_sessions").upsert({
                    "key": f"merge_pdf_{uid}",
                    "data": json.dumps({"file_ids": file_ids}),
                    "updated_at": int(time.time())
                }).execute())
                await send_msg(chat_id, f"📎 PDF {len(file_ids)} received! Total: {len(file_ids)}\n/merge done when ready")
            except Exception as e:
                await _safe_error_reply(chat_id, e)
            return

        try:
            csv_bytes = await download_tg_file(doc["file_id"])
            content = csv_bytes.decode("utf-8-sig")
            row = await sb_exec(lambda: sb.table("quiz_sessions").select("data").eq("key", f"merge_{uid}").execute())
            files = json.loads(row.data[0]["data"]).get("files", []) if row.data else []
            files.append(content)
            await sb_exec(lambda: sb.table("quiz_sessions").upsert({
                "key": f"merge_{uid}",
                "data": json.dumps({"files": files}),
                "updated_at": int(time.time())
            }).execute())
            await send_msg(chat_id, f"📎 File {len(files)} received! Total: {len(files)}\n/merge done when ready")
        except Exception as e:
            await _safe_error_reply(chat_id, e)
        return

    await send_msg(chat_id,
        "🔗 CSV বা PDF ফাইলে reply করে /merge দাও\n"
        "/merge done — merge করো\n"
        "/merge status — count দেখো\n"
        "/merge cancel — বাতিল"
    )


async def handle_error_command(msg: dict):
    """Owner/Admin only — আজকের error log file-এর শেষ অংশ raw text হিসেবে
    দেখায় (AtlasBot-style, simple file-based, কোনো DB/structured parsing ছাড়াই)।
    উপরে classified failure summary (exact cause, category, provider) ও দেখায়
    যদি এই restart-এ কোনো AI provider failure classify হয়ে থাকে।"""
    chat_id = msg["chat"]["id"]
    uid = msg["from"]["id"]
    text = msg.get("text", "").strip()

    if not await db_is_owner_or_admin(uid):
        await send_msg(chat_id, "❌ Owner/Admin only!")
        return

    if text.strip() in ("/error clear", "/errors clear"):
        await clear_error_logs()
        await send_msg(chat_id, "✅ Error log clear করা হয়েছে!")
        return

    # Classified summary first — exact provider/category/page for the most
    # recent AI-provider failure, plus a full breakdown by category.
    summary_lines = []
    lf = _LAST_FAILURE_DETAIL
    if lf["provider"]:
        summary_lines.append(
            f"🔍 <b>সর্বশেষ exact cause:</b> {lf['provider']} — {lf['category']}"
            f" (page {lf['page'] or 'N/A'}, {lf['time']})\n<code>{lf['detail']}</code>"
        )
    any_failures = any(any(v > 0 for v in cat.values()) for cat in _FAILURE_COUNTS.values())
    if any_failures:
        _label_map = {
            "timeout": "⏱️ Timeout", "rate_limit_429": "🚦 429", "daily_quota": "📅 Daily quota",
            "suspended_banned": "🚫 Suspended", "overloaded_503": "🔥 503", "payload_too_large_413": "📦 413",
            "empty_parse": "❔ Empty parse", "network": "🌐 Network", "other": "❓ Other",
        }
        for provider, cats in _FAILURE_COUNTS.items():
            nonzero = {k: v for k, v in cats.items() if v > 0}
            if nonzero:
                parts = ", ".join(f"{_label_map.get(k, k)}: {v}" for k, v in nonzero.items())
                summary_lines.append(f"  • <b>{provider}</b> — {parts}")
    if summary_lines:
        await send_msg(chat_id, "\n".join(summary_lines))

    # Per-call detailed reasons — these carry richer context (e.g. "all 5
    # keys failed — [key#1: 413; key#2: SSL error; ...]") that the single
    # most-recent-event classifier above doesn't capture, since a single
    # page can hit several different keys/errors within one call.
    extras = []
    if _LAST_GEMINI_ERROR["reason"]:
        extras.append(f"<b>Gemini (latest call):</b>\n<code>{_LAST_GEMINI_ERROR['reason'][:500]}</code>")
    if _LAST_GROQ_ERROR["reason"]:
        extras.append(f"<b>Groq (latest call):</b>\n<code>{_LAST_GROQ_ERROR['reason'][:500]}</code>")
    if _LAST_FALLBACK_ERROR["reason"]:
        extras.append(f"<b>Fallback providers (latest call):</b>\n<code>{_LAST_FALLBACK_ERROR['reason'][:500]}</code>")
    if extras:
        await send_msg(chat_id, "\n\n".join(extras))

    # /poll FloodWait root-cause breakdown -- exact stage, message ID,
    # wait duration, and time for every FloodWait hit this process's run.
    try:
        from poll_extract import get_floodwait_summary
        fw_summary = get_floodwait_summary()
        if fw_summary:
            await send_msg(chat_id, fw_summary, parse_mode="HTML")
    except Exception:
        pass

    content = await get_recent_errors()
    if not content.strip():
        if not summary_lines:
            await send_msg(chat_id, "✅ আজ কোনো error নেই!")
        return

    tail = content[-3800:]
    await send_msg(chat_id, f"🚨 Latest Errors:\n\n{tail}")


async def handle_watermark_command(msg: dict):
    """v1.2: /watermark — ask the user to send a PDF, then ask for watermark
    text, then return the watermarked PDF. Ported from AtlasMasterBot."""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    WATERMARK_PENDING[uid] = {"step": "awaiting_pdf"}
    await send_msg(chat_id, "📄 যে PDF-এ watermark বসাতে চান, সেটা পাঠান।")

async def handle_watermark_document(msg: dict) -> bool:
    """Called from the document/text router. Returns True if the message
    was consumed by the watermark flow, False otherwise (so other PDF
    handlers can still process it)."""
    uid = msg["from"]["id"]
    chat_id = msg["chat"]["id"]
    state = WATERMARK_PENDING.get(uid)
    if not state:
        return False

    if state.get("step") == "awaiting_pdf":
        doc = msg.get("document")
        if not doc or not (doc.get("file_name") or "").lower().endswith(".pdf"):
            await send_msg(chat_id, "❌ দয়া করে একটি PDF file পাঠান।")
            return True
        try:
            pdf_bytes = await download_tg_file(doc["file_id"], chat_id=chat_id, message_id=msg["message_id"])
        except Exception as e:
            logger.error(f"[Watermark] download error: {e}")
            await send_msg(chat_id, f"❌ PDF download করতে সমস্যা হয়েছে: {e}")
            WATERMARK_PENDING.pop(uid, None)
            return True
        state["pdf_bytes"] = pdf_bytes
        state["step"] = "awaiting_text"
        await send_msg(chat_id, "✏️ Watermark-এ কী লেখা থাকবে? (যেমন: তোমার নাম/চ্যানেল)")
        return True

    if state.get("step") == "awaiting_text":
        text = (msg.get("text") or "").strip()
        if not text:
            await send_msg(chat_id, "❌ দয়া করে watermark text লিখুন।")
            return True
        pdf_bytes = state.get("pdf_bytes")
        WATERMARK_PENDING.pop(uid, None)
        loading = await send_msg(chat_id, "⏳ Watermark বসানো হচ্ছে...")
        try:
            watermarked = add_watermark_to_pdf(pdf_bytes, text)
            await send_document(chat_id, watermarked, filename="watermarked.pdf", caption="✅ Watermark বসানো হয়েছে!")
        except Exception as e:
            logger.error(f"[Watermark] process error: {e}")
            await send_msg(chat_id, f"❌ Watermark বসাতে সমস্যা হয়েছে: {e}")
        return True

    return False

async def handle_convert_command(msg: dict):
    """CSV ↔ JSON convert"""
    chat_id = msg["chat"]["id"]
    reply = msg.get("reply_to_message")
    if not reply or not reply.get("document"):
        await send_msg(chat_id, "❌ CSV বা JSON ফাইলে reply করে /convert দাও!")
        return
    try:
        file_bytes = await download_tg_file(reply["document"]["file_id"])
        file_name = reply["document"].get("file_name", "")

        if file_name.lower().endswith(".csv"):
            mcqs = _parse_csv_bytes(file_bytes)
            json_data = []
            for i, mcq in enumerate(mcqs):
                opts = mcq.get("options", [])
                json_data.append({
                    "question_number": str(i + 1),
                    "question": mcq["question"],
                    "options": {
                        "A": opts[0] if len(opts) > 0 else "",
                        "B": opts[1] if len(opts) > 1 else "",
                        "C": opts[2] if len(opts) > 2 else "",
                        "D": opts[3] if len(opts) > 3 else ""
                    },
                    "correct_answer": mcq.get("answer", "A"),
                    "explanation": mcq.get("explanation", "")
                })
            out = json.dumps(json_data, ensure_ascii=False, indent=2).encode("utf-8")
            await send_document(chat_id, out,
                file_name.replace(".csv", ".json"),
                caption=f"✅ CSV → JSON Converted! {len(json_data)} questions",
                mime_type="application/json")

        elif file_name.lower().endswith(".json"):
            json_data = json.loads(file_bytes.decode("utf-8-sig"))
            import io as _io, csv as _csv
            buf = _io.StringIO()
            writer = _csv.writer(buf)
            writer.writerow(["questions","option1","option2","option3","option4","answer","explanation","type","section"])
            for item in json_data:
                opts = item.get("options", {})
                ans_map = {"A": "1", "B": "2", "C": "3", "D": "4"}
                ans = ans_map.get(item.get("correct_answer", "A"), "1")
                writer.writerow([
                    item.get("question", ""),
                    opts.get("A", ""), opts.get("B", ""),
                    opts.get("C", ""), opts.get("D", ""),
                    ans, _strip_img_tag(item.get("explanation", "")), "1", "1"
                ])
            await send_document(chat_id, buf.getvalue().encode("utf-8"),
                file_name.replace(".json", ".csv"),
                caption=f"✅ JSON → CSV Converted! {len(json_data)} questions",
                mime_type="text/csv")
        else:
            await send_msg(chat_id, "❌ Only CSV or JSON files!")
    except Exception as e:
        await _safe_error_reply(chat_id, e)


# ============================================================
# WEBHOOK HANDLER
# ============================================================
WEBHOOK_SECRET = os.environ.get("WEBHOOK_SECRET", "")

# Fire-and-forget _spawn_task() calls can be silently garbage-collected
# mid-execution if nothing holds a reference to the Task object — this is a
# well-known asyncio pitfall and matches "first command silent, retry works"
# (the very first task in a fresh loop has nothing else referencing it yet).
# Keep a strong-reference set for every background task spawned from the
# webhook so none of them can be GC'd before completion.
_BACKGROUND_TASKS = set()

def _spawn_task(coro):
    task = asyncio.create_task(coro)
    _BACKGROUND_TASKS.add(task)
    task.add_done_callback(_BACKGROUND_TASKS.discard)
    return task

# Per-user command queue — same user firing a command again while a previous
# one is still running now waits its turn instead of running concurrently
# and colliding (shared session rows, etc). Different users never block
# each other; only same-user overlap is serialized.
#
# Most command handlers dispatch their real work via a top-level
# _spawn_task(handle_X(msg)) call inside handle_message(), which then
# returns right away — a lock held only around "await handle_message(...)"
# releases instantly and never covers the actual work. _spawn_command_task()
# is used ONLY at those top-level dispatch sites (not for nested/long-lived
# background jobs like quiz timers, which must NOT hold up the next command)
# and registers the task so process_update can wait for it before releasing
# this user's lock.
_USER_LOCKS = {}
_USER_LOCKS_ORDER = deque(maxlen=5000)
_active_command_task = {}  # uid -> the currently-dispatched top-level command Task

def _get_user_lock(uid: int) -> asyncio.Lock:
    lock = _USER_LOCKS.get(uid)
    if lock is None:
        lock = asyncio.Lock()
        _USER_LOCKS[uid] = lock
        _USER_LOCKS_ORDER.append(uid)
        if len(_USER_LOCKS_ORDER) == _USER_LOCKS_ORDER.maxlen:
            while len(_USER_LOCKS) > _USER_LOCKS_ORDER.maxlen:
                old_uid = _USER_LOCKS_ORDER.popleft()
                old_lock = _USER_LOCKS.get(old_uid)
                if old_lock is not None and not old_lock.locked():
                    _USER_LOCKS.pop(old_uid, None)
    return lock

def _spawn_command_task(uid, coro):
    task = _spawn_task(coro)
    _active_command_task[uid] = task
    return task

@app.post("/webhook")
async def webhook(request: Request):
    if WEBHOOK_SECRET:
        if request.headers.get("X-Telegram-Bot-Api-Secret-Token") != WEBHOOK_SECRET:
            return Response(status_code=403)
    try:
        update = await request.json()
        _spawn_task(process_update(update))
        return Response("OK")
    except Exception as e:
        logger.error(f"[Webhook] Parse error: {e}")
        return Response("OK")

_LOCK_ACQUIRED_AT = {}  # uid -> timestamp the currently-held lock was acquired
_STALE_LOCK_SECONDS = 600  # 10 min — generous even for the slowest /pdf jobs
_USER_PENDING_QUEUE = {}  # uid -> list of queued update dicts waiting their turn

_USER_QUEUE_RUNNING = set()  # uid currently has an active drain-worker running
_USER_LAST_STATUS = {}  # uid -> {"command": str, "stage": str, "started_at": float, "last_update_at": float}

async def _drain_user_queue(uid: int):
    """Single worker per user that drains _USER_PENDING_QUEUE strictly in
    FIFO order. Only one of these ever runs per uid at a time (guarded by
    _USER_QUEUE_RUNNING) — this replaces the old lock.locked()-check dispatch,
    which had a race window: two updates for the same uid could each pass the
    `lock.locked()` check before either had actually entered the lock body,
    letting both proceed to run concurrently/out of order instead of strictly
    one-after-another in arrival order."""
    while True:
        queue = _USER_PENDING_QUEUE.get(uid)
        if not queue:
            _USER_QUEUE_RUNNING.discard(uid)
            # Re-check after removing from running-set — another update may
            # have been enqueued in the tiny gap between the empty-check above
            # and this line, and would have skipped starting a new worker
            # (since uid was still marked running).
            if _USER_PENDING_QUEUE.get(uid):
                _USER_QUEUE_RUNNING.add(uid)
                continue
            return
        update = queue.pop(0)
        _LOCK_ACQUIRED_AT[uid] = time.time()
        try:
            await handle_message(update["message"])
            task = _active_command_task.pop(uid, None)
            if task is not None and not task.done():
                await asyncio.gather(task, return_exceptions=True)
        except Exception as e:
            logger.error(f"[Queue] uid={uid} command error: {e}")
        finally:
            _LOCK_ACQUIRED_AT.pop(uid, None)

_seen_update_ids = deque(maxlen=2000)
_seen_update_ids_set = set()

def _is_duplicate_update(update_id) -> bool:
    """Telegram redelivers the same update on webhook timeout/retry — without
    dedup, this caused rare double-processing of a single command (e.g. /poll
    running twice, with one run occasionally hitting a cold is_auth cache/DB
    race and wrongly falling through to the unauthorized message even though
    the SAME owner uid succeeded moments earlier on the other run)."""
    if update_id is None:
        return False
    if update_id in _seen_update_ids_set:
        return True
    _seen_update_ids.append(update_id)
    _seen_update_ids_set.add(update_id)
    while len(_seen_update_ids_set) > _seen_update_ids.maxlen:
        old = _seen_update_ids.popleft()
        _seen_update_ids_set.discard(old)
    return False


async def process_update(update: dict):
    try:
        if _is_duplicate_update(update.get("update_id")):
            logger.info(f"[Update] Duplicate update_id={update.get('update_id')} ignored")
            return
        if "message" in update:
            uid = update["message"].get("from", {}).get("id")
            _msg = update.get("message", {})
            _txt_check = (_msg.get("text") or "").strip()
            # /csv, /csvS, /ping, /cancel, /merge + other stateless/quick
            # commands bypass the per-user serialize queue entirely. /csv
            # and /csvS reply to an already-uploaded document with an
            # independent cache_id, so they never share mutable state
            # with other running commands (unlike /txt, /pdf which mutate
            # shared per-user progress state). /ping is a pure status check
            # with no shared state at all. /cancel MUST always run instantly
            # regardless of what's running -- its entire purpose is to stop a
            # stuck/long job, so it can never be allowed to sit queued behind
            # the very job it's meant to cancel (that made /cancel useless
            # for its main use case: a runaway /qbm or /auto job). Previously
            # these silently waited behind any earlier still-running command
            # for the same uid — the actual cause of "/csv stuck at 0%" /
            # "/ping late" / "/cancel doesn't work" reports; the underlying
            # work was always fast, the command just hadn't started yet.
            # /merge (file-collect + done/status/cancel) and other small
            # read-only/quick commands (/getid, /id, /menu, /pin, /keys,
            # /channel, /channelist, /labels, /qlist, /info, /info2) are
            # instant, don't mutate the same shared progress state as the
            # heavy extraction commands, and users expect them to respond
            # immediately even while a long /qbm or /auto job is running.
            _QUEUE_EXEMPT_EXACT = {"/ping", "/error", "/status", "/getid", "/id",
                                     "/keys", "/channelist", "/qlist", "/info", "/info2"}
            _QUEUE_EXEMPT_PREFIX = ("/csv", "/csvS", "/cancel", "/errors", "/merge",
                                     "/menu", "/pin", "/channel", "/labels")
            if (_txt_check in _QUEUE_EXEMPT_EXACT
                    or _txt_check.startswith(_QUEUE_EXEMPT_PREFIX)):
                _spawn_task(handle_message(_msg))
                return
            if uid is not None:
                _USER_PENDING_QUEUE.setdefault(uid, []).append(update)
                if len(_USER_PENDING_QUEUE[uid]) > 20:
                    # Safety cap — drop oldest queued item rather than growing unbounded
                    _USER_PENDING_QUEUE[uid].pop(0)
                elif uid in _USER_QUEUE_RUNNING:
                    # Aager command akhono cholche - silent wait er bodole
                    # sathe sathe janano hocche je queue te ache (root cause
                    # of "stuck at 0%" reports: /csv silently queued behind a
                    # slow earlier command from same user, no feedback shown).
                    _msg_obj = update.get("message", {})
                    _cid = _msg_obj.get("chat", {}).get("id")
                    _txt = (_msg_obj.get("text") or "").strip().split()[0] if _msg_obj.get("text") else "command"
                    if _cid:
                        _spawn_task(send_msg(_cid, f"⏳ Ager command sesh howar opekkhay ache — {_txt} ektu porei shuru hobe..."))
                if uid not in _USER_QUEUE_RUNNING:
                    # Stale-worker guard: if a previous worker for this uid
                    # died without clearing _USER_QUEUE_RUNNING (crash/restart
                    # mid-task), a stuck flag would silently block this user's
                    # commands forever. Cross-check against the lock-acquired
                    # timestamp same as before.
                    acquired_at = _LOCK_ACQUIRED_AT.get(uid)
                    if acquired_at and (time.time() - acquired_at) > _STALE_LOCK_SECONDS:
                        logger.warning(f"[Queue] Stale worker for uid={uid} "
                                        f"({time.time()-acquired_at:.0f}s old) — force-resetting")
                        _LOCK_ACQUIRED_AT.pop(uid, None)
                    _USER_QUEUE_RUNNING.add(uid)
                    _spawn_task(_drain_user_queue(uid))
            else:
                await handle_message(update["message"])
        elif "callback_query" in update:
            await handle_callback(update["callback_query"])
        elif "poll_answer" in update:
            await handle_poll_answer(update["poll_answer"])
        elif "chat_member" in update:
            cm = update["chat_member"]
            old_status = cm.get("old_chat_member", {}).get("status")
            new_status = cm.get("new_chat_member", {}).get("status")
            if old_status not in ("member", "administrator", "creator") and new_status == "member":
                chat_id_j = cm.get("chat", {}).get("id")
                user_id_j = cm.get("new_chat_member", {}).get("user", {}).get("id")
                if chat_id_j and user_id_j:
                    _spawn_task(on_channel_join(chat_id_j, user_id_j))
        elif "chat_join_request" in update:
            cjr = update["chat_join_request"]
            chat_id_r = cjr.get("chat", {}).get("id")
            user_id_r = cjr.get("from", {}).get("id")
            if chat_id_r and user_id_r:
                _spawn_task(maybe_approve_join_request(chat_id_r, user_id_r))
    except Exception as e:
        logger.error(f"[Update] Error: {e}")
        await notify_owner(f"[Update] Unhandled error:\n{str(e)[:500]}")

