async def _scheduled_restart_task() -> None:
    """v-RAM-fix: clean self-exit every 12h so Render restarts the process
    fresh, fully resetting RAM regardless of any leak."""
    await asyncio.sleep(12 * 3600)
    logger.info("[Restart] Scheduled restart: exiting cleanly for fresh RAM")
    os._exit(0)


async def _memory_cleanup_task() -> None:
    """v-RAM-fix: periodic gc + re-enforce cache caps every 30 min, so leaks
    never accumulate over days/weeks/months even if a cap write is missed."""
    import gc
    await asyncio.sleep(300)
    while True:
        try:
            for attr in ("pdf_cache", "qbm_cache", "img_cache"):
                cache = getattr(app.state, attr, None)
                if cache is not None:
                    _cap_page_cache(cache)
            gc.collect()
            logger.info(
                f"[MemCleanup] pdf_cache={len(getattr(app.state,'pdf_cache',{}) or {})} "
                f"qbm_cache={len(getattr(app.state,'qbm_cache',{}) or {})} "
                f"img_cache={len(getattr(app.state,'img_cache',{}) or {})}"
            )
        except Exception as e:
            logger.warning(f"[MemCleanup] {e}")
        await asyncio.sleep(1800)


_active_jobs = {"count": 0}

async def _ram_guard_task() -> None:
    """Proactive RSS watchdog. Was tuned for 512MB Render free tier; now on
    16GB HF Space, threshold raised proportionally so restarts only trigger
    on genuine leaks, not normal heavy-load usage."""
    try:
        import psutil
    except ImportError:
        logger.warning("[RAMGuard] psutil not installed -> proactive RAM guard disabled")
        return
    proc = psutil.Process(os.getpid())
    limit_mb = 14000  # 16GB instance, ~14GB usable ceiling (leave OS/runtime headroom)
    threshold_mb = int(limit_mb * 0.75)
    await asyncio.sleep(60)
    while True:
        try:
            rss_mb = proc.memory_info().rss / (1024 * 1024)
            hard_cap_mb = int(limit_mb * 0.88)
            if rss_mb >= hard_cap_mb:
                logger.warning(f"[RAMGuard] RSS {rss_mb:.0f}MB >= hard cap {hard_cap_mb}MB -> forced restart (job or not)")
                await asyncio.sleep(1)
                os._exit(0)
            if rss_mb >= threshold_mb:
                if _active_jobs["count"] > 0:
                    logger.warning(f"[RAMGuard] RSS {rss_mb:.0f}MB >= threshold but {_active_jobs['count']} job(s) active -> deferring restart")
                else:
                    logger.warning(f"[RAMGuard] RSS {rss_mb:.0f}MB >= {threshold_mb}MB threshold -> clean self-restart")
                    await asyncio.sleep(1)
                    os._exit(0)
            elif rss_mb >= threshold_mb * 0.9:
                logger.info(f"[RAMGuard] RSS {rss_mb:.0f}MB approaching threshold ({threshold_mb}MB)")
        except Exception as e:
            logger.warning(f"[RAMGuard] check failed: {e}")
        await asyncio.sleep(60)


async def _keepalive_task() -> None:
    """Self-ping own service URL /health every 5 min for 24/7 uptime
    (prevents platform sleep). Alerting disabled — AtlasBot handles
    monitoring/alerts now."""
    await asyncio.sleep(60)
    logger.info("[App] Keep-alive task started")
    while True:
        if RENDER_URL:
            try:
                async with httpx.AsyncClient(timeout=40) as client:
                    await client.get(f"{RENDER_URL.rstrip('/')}/health")
            except Exception:
                pass
        await asyncio.sleep(300)


async def _cf_connection_warmer_task() -> None:
    """CF Worker-এর pooled connection warm রাখে (shared client-এর
    keepalive_expiry=60s এর চেয়ে ছোট interval-এ ping করে), যাতে user কোনো
    command দেওয়ার সময় cold connection-এ পড়তে না হয়। Measured impact:
    cold connection ~950ms, warm connection ~30-60ms — তাই প্রথম command
    সবসময় দ্রুত response পাবে।"""
    from core import _get_shared_http_client, TG_API
    await asyncio.sleep(20)
    logger.info("[App] CF connection warmer started")
    while True:
        try:
            client = await _get_shared_http_client()
            await client.get(f"{TG_API}/getMe", timeout=10)
        except Exception:
            pass
        await asyncio.sleep(45)


async def _webhook_healer_task() -> None:
    """Every 2 min, checks Telegram webhook is set, non-empty, and has all
    required allowed_updates (message/callback_query/poll_answer/poll). Runs
    regardless of direct or cf-proxy mode. If broken, re-sets webhook using
    whichever URL is already configured (preserving direct-mode Render URLs
    instead of force-switching to the CF proxy), falling back to HF Space
    only as a last resort if re-setting fails outright."""
    await asyncio.sleep(120)
    logger.info("[App] Webhook healer task started")
    _REQUIRED_UPDATES = {"message", "callback_query", "poll_answer", "poll", "chat_member", "chat_join_request"}
    while True:
        try:
            if True:  # v4.4: healer now runs in BOTH direct and cf-proxy modes —
                      # previously gated to cf-proxy only, so Render/direct-mode
                      # deployments never self-healed a narrowed allowed_updates.
                info = await tg_post("getWebhookInfo", {})
                current_url = info.get("result", {}).get("url", "") if info.get("ok") else ""
                current_allowed = set(info.get("result", {}).get("allowed_updates", []) or [])
                # allowed_updates empty/missing in getWebhookInfo response means
                # Telegram is NOT restricting - i.e. ALL update types are sent
                # (this is Telegram's actual documented behavior). Only treat
                # it as broken if it's non-empty AND missing something we need
                # (e.g. some earlier setWebhook call - ours or an external one
                # like a GitHub Action / manual call - narrowed it and silently
                # dropped poll_answer, which is exactly what caused quiz
                # answers to stop auto-advancing while timeouts kept working).
                missing_updates = bool(current_allowed) and not _REQUIRED_UPDATES.issubset(current_allowed)
                if not current_url or missing_updates:
                    if missing_updates:
                        logger.warning(f"[App] Webhook healer: allowed_updates missing required types! "
                                       f"current={current_allowed} required={_REQUIRED_UPDATES} — repairing")
                    if current_url:
                        # Keep whatever URL is already correctly working — only
                        # allowed_updates needs fixing. Force-switching to
                        # CF_WORKER_URL here would be wrong in direct/Render mode.
                        target_webhook = current_url
                    elif _tg_mode == "direct":
                        target_webhook = RENDER_URL.rstrip("/") + f"/webhook/{BOT_TOKEN}"
                    else:
                        target_webhook = CF_WORKER_URL.rstrip("/") + "/webhook"
                    payload = {"url": target_webhook, "drop_pending_updates": False, "max_connections": 40,
                               "allowed_updates": ["message", "callback_query", "poll_answer", "poll", "chat_member", "chat_join_request"]}
                    if WEBHOOK_SECRET:
                        payload["secret_token"] = WEBHOOK_SECRET
                    result = await tg_post("setWebhook", payload)
                    if result.get("ok"):
                        logger.info(f"[App] Webhook healer: re-set webhook → {result}")
                        if missing_updates:
                            await notify_owner(
                                "⚠️ Webhook Healer: allowed_updates ছিল অসম্পূর্ণ (poll_answer বা অন্য কিছু বাদ পড়েছিল) — "
                                "auto-repair করা হয়েছে। এই কারণে quiz answer দিলে next question আসছিল না।"
                            )
                    else:
                        logger.warning(f"[App] Webhook healer: re-set attempt failed: {result}")
                        # CF proxy target failed (DNS/routing) — fall back to
                        # setting the webhook directly against HF Space so
                        # the bot recovers instead of staying silently dead.
                        if HF_SPACE_URL:
                            hf_webhook = HF_SPACE_URL.rstrip("/") + "/webhook"
                            payload["url"] = hf_webhook
                            try:
                                import httpx as _httpx_local
                                async with _httpx_local.AsyncClient(timeout=10) as _c:
                                    r = await _c.post(f"https://api.telegram.org/bot{BOT_TOKEN}/setWebhook", json=payload)
                                    r2 = r.json()
                                if r2.get("ok"):
                                    logger.info(f"[App] Webhook healer: HF direct fallback succeeded → {hf_webhook}")
                                else:
                                    logger.warning(f"[App] Webhook healer: HF direct fallback also failed: {r2}")
                            except Exception as fe:
                                logger.warning(f"[App] Webhook healer: HF direct fallback error: {fe}")
        except Exception as e:
            logger.warning(f"[App] Webhook healer error: {e}")
        await asyncio.sleep(120)


async def _watchdog_task() -> None:
    """Independent watchdog — separate ping loop (offset timing) that
    double-checks the bot is alive. If keep-alive silently dies (task
    crash) this loop still detects downtime and wakes/alerts."""
    await asyncio.sleep(150)  # offset from _keepalive_task so they don't overlap
    logger.info("[App] Watchdog task started")
    fails = 0
    was_down = False
    while True:
        healthy = False
        try:
            async with httpx.AsyncClient(timeout=40) as client:
                if RENDER_URL:
                    r = await client.get(f"{RENDER_URL.rstrip('/')}/health")
                    healthy = r.status_code == 200
        except Exception:
            healthy = False

        if healthy:
            fails = 0
            if was_down:
                try:
                    await notify_owner("✅ QuizBot WATCHDOG: service reachable again.")
                except Exception:
                    pass
                was_down = False
        else:
            fails += 1
            logger.warning(f"[Watchdog] health check failed ({fails} in a row)")
            if fails >= 4:
                if not was_down:
                    try:
                        await notify_owner(f"🚨 QuizBot WATCHDOG: service unreachable ({fails}x) — attempting self-wake.")
                    except Exception:
                        pass
                    was_down = True
                # self-wake attempt: hit health endpoint directly again
                try:
                    async with httpx.AsyncClient(timeout=30) as client:
                        if RENDER_URL:
                            await client.get(f"{RENDER_URL.rstrip('/')}/health")
                except Exception:
                    pass
        await asyncio.sleep(300)


async def _watchdog2_task() -> None:
    """3rd independent ping layer — different offset/interval than keep-alive
    and watchdog, so all three never crash/miss at the same moment."""
    await asyncio.sleep(240)
    logger.info("[App] Watchdog-2 task started")
    fails = 0
    was_down2 = False
    while True:
        healthy = False
        try:
            async with httpx.AsyncClient(timeout=25) as client:
                if RENDER_URL:
                    r = await client.get(f"{RENDER_URL.rstrip('/')}/health")
                    healthy = r.status_code == 200
        except Exception:
            healthy = False
        if healthy:
            fails = 0
            if was_down2:
                try:
                    await notify_owner("✅ QuizBot WATCHDOG-2: service reachable again.")
                except Exception:
                    pass
                was_down2 = False
        else:
            fails += 1
            if fails >= 4:
                if not was_down2:
                    try:
                        await notify_owner(f"🚨 QuizBot WATCHDOG-2: unreachable ({fails}x) — self-wake attempt.")
                    except Exception:
                        pass
                    was_down2 = True
                if RENDER_URL:
                    for _ in range(2):
                        try:
                            async with httpx.AsyncClient(timeout=30) as client:
                                await client.get(f"{RENDER_URL.rstrip('/')}/health")
                            break
                        except Exception:
                            await asyncio.sleep(5)
        await asyncio.sleep(420)


async def _cross_bot_watchdog_task() -> None:
    """Mutual watchdog: pings AtlasBot's health endpoint (set via
    ATLASBOT_URL env). If AtlasBot looks down, alerts owner — mirrors
    AtlasBot's own cross-check on this bot."""
    atlasbot_url = os.environ.get("ATLASBOT_URL", "").rstrip("/")
    if not atlasbot_url:
        return
    await asyncio.sleep(200)
    logger.info("[App] Cross-bot watchdog (-> AtlasBot) started")
    fails = 0
    while True:
        healthy = False
        try:
            async with httpx.AsyncClient(timeout=40) as client:
                r = await client.get(f"{atlasbot_url}/health")
                healthy = r.status_code == 200
        except Exception:
            healthy = False
        if healthy:
            fails = 0
        else:
            fails += 1
            if fails >= 4:
                try:
                    await notify_owner(f"🚨 AtlasBot unreachable via cross-bot check ({fails}x) — checked from QuizBot.")
                except Exception:
                    pass
        await asyncio.sleep(300)


@app.get("/health")
async def health():
    return {"status": "ok", "db": sb is not None, "gemini_keys": len(key_rotator.keys), "bot_token": bool(BOT_TOKEN)}

@app.on_event("startup")
async def startup():
    global BOT_START_TIME
    BOT_START_TIME = time.time()
    logger.info("[App] ATLAS BOT v4.1 starting...")

    # SPEED: Pyrogram client cold-start (connect+auth handshake) prothom
    # download request-ei hoile user wait kore. Startup-e pre-warm kore rakhle
    # first real download-e ei latency lage na.
    try:
        from core import _get_pyro_client
        pc = await _get_pyro_client()
        if pc:
            logger.info("[App] Pyrogram client pre-warmed at startup")
        else:
            logger.info("[App] Pyrogram not configured (TELEGRAM_API_ID/HASH missing), skip pre-warm")
    except Exception as e:
        logger.warning(f"[App] Pyrogram pre-warm failed (will lazy-init later): {e}")

    # SPEED: pre-warm the shared httpx client's connection to the CF Worker
    # (used by every send_msg/tg_post call) and the Supabase client, so the
    # very first real command doesn't pay a cold TLS-handshake/DNS cost that
    # could otherwise eat into tg_post's timeout and make the first reply
    # silently miss its window.
    try:
        from core import _get_shared_http_client, CF_WORKER_URL
        _warm_client = await _get_shared_http_client()
        await _warm_client.get(f"{CF_WORKER_URL}/", timeout=10)
        logger.info("[App] CF Worker connection pre-warmed at startup")
    except Exception as e:
        logger.warning(f"[App] CF Worker pre-warm failed (non-fatal): {e}")

    try:
        if sb is not None:
            await sb_exec(lambda: sb.table("pdf_users").select("user_id").limit(1).execute(), timeout=10)
            logger.info("[App] Supabase connection pre-warmed at startup")
    except Exception as e:
        logger.warning(f"[App] Supabase pre-warm failed (non-fatal): {e}")

    # Start mhtml/html auto-queue worker (serial processing, one file at a time)
    global _mhtml_worker_started
    if not _mhtml_worker_started:
        _spawn_task(_mhtml_auto_worker())
        _mhtml_worker_started = True
        logger.info("[App] mhtml auto-queue worker started")

    # RESUME incomplete /csv poll jobs from before a restart/crash — DISABLED
    # per request: bot restart হলে আগের অসম্পূর্ণ /csv poll job আর auto-resume
    # হবে না। DB-তে থাকা 'running' status job গুলো just untouched থাকবে (আবার
    # চালু করতে চাইলে ম্যানুয়ালি /csv আবার দিতে হবে)।
    # try:
    #     _incomplete_jobs = await db_get_incomplete_csv_jobs()
    #     if _incomplete_jobs:
    #         logger.info(f"[App] Found {len(_incomplete_jobs)} incomplete CSV job(s) from before restart — resuming")
    #         for _job in _incomplete_jobs:
    #             _spawn_task(_resume_csv_job(_job))
    # except Exception as e:
    #     logger.warning(f"[App] CSV job resume check failed (non-fatal): {e}")

    # RESUME incomplete /pdf page-jobs (PDF/PPT poll posting) — same idea:
    # restart হলে resume_page_num থেকে বাকি page গুলো নিয়ে চালিয়ে যায়,
    # আগের page গুলো আবার post হয় না (duplicate polls avoid হয়)।
    try:
        _incomplete_page_jobs = await db_get_incomplete_page_jobs()
        if _incomplete_page_jobs:
            logger.info(f"[App] Found {len(_incomplete_page_jobs)} incomplete page-job(s) from before restart — resuming")
            for _pjob in _incomplete_page_jobs:
                _spawn_task(_resume_page_job(_pjob))
    except Exception as e:
        logger.warning(f"[App] Page-job resume check failed (non-fatal): {e}")

    # RESUME in-progress D1-quiz sessions (mid-quiz, per-question, /q-created
    # quizzes) — a bot restart mid-quiz used to silently lose the user's
    # entire in-memory session (QUIZ_SESSIONS is RAM-only). Now resumes them
    # from their last-persisted snapshot instead.
    try:
        from quiz import resume_live_quiz_sessions
        _spawn_task(resume_live_quiz_sessions())
    except Exception as e:
        logger.warning(f"[App] Quiz session resume check failed (non-fatal): {e}")

    async def _supervised(coro_fn, name):
        """Core background task crash korle silently die na kore auto-restart hobe.
        Exponential backoff + alert-spam prevent (repeated crash e max 3 alert)."""
        fail_count = 0
        while True:
            try:
                await coro_fn()
                return
            except asyncio.CancelledError:
                raise
            except Exception as e:
                fail_count += 1
                wait = min(10 * (2 ** min(fail_count - 1, 5)), 300)
                logger.error(f"⚠️ [Supervisor] {name} crashed ({fail_count}x): {e} — restarting in {wait}s")
                if fail_count <= 3:
                    try:
                        await send_msg(OWNER_ID, f"⚠️ Background task '{name}' crashed ({fail_count}x), auto-restarting: {e}")
                    except Exception:
                        pass
                await asyncio.sleep(wait)

    # Self-ping keep-alive: prevents platform sleep. Watchdog alert tasks
    # disabled per request — AtlasBot now handles all external monitoring.
    _spawn_task(_supervised(_keepalive_task, "_keepalive_task"))
    _spawn_task(_supervised(_cf_connection_warmer_task, "_cf_connection_warmer_task"))
    _spawn_task(_supervised(_webhook_healer_task, "_webhook_healer_task"))
    _spawn_task(_supervised(_memory_cleanup_task, "_memory_cleanup_task"))
    _spawn_task(_supervised(_ram_guard_task, "_ram_guard_task"))
    _spawn_task(_supervised(_scheduled_restart_task, "_scheduled_restart_task"))
    # _spawn_task(_supervised(_watchdog_task, "_watchdog_task"))  # DISABLED — AtlasBot monitors instead
    # _spawn_task(_supervised(_watchdog2_task, "_watchdog2_task"))  # DISABLED — AtlasBot monitors instead
    # _spawn_task(_supervised(_cross_bot_watchdog_task, "_cross_bot_watchdog_task"))  # DISABLED

    if not BOT_TOKEN:
        logger.error("[App] BOT_TOKEN missing!")
        return
    logger.info("[App] Using CF Worker proxy for TG API")

    # ── Auto webhook set ──
    # নিয়ম: Render শুধু webhook নিজের দিকে নেবে যদি বর্তমানে webhook
    # ইতিমধ্যেই Render-এ set থাকে (restart এর পর হারিয়ে না যায়) —
    # HF সচল থাকলে HF থেকে কেড়ে নেবে না, CF cron-ই auto-switch handle করে।
    try:
        import httpx as _hx, os as _os
        running_on = _os.environ.get("RUNNING_ON", "") or "HuggingFace Space"
        self_url = RENDER_URL or ""

        if running_on == "Render" or (self_url and "onrender.com" in self_url):
            webhook_url = self_url.rstrip("/") + "/webhook"
            async with _hx.AsyncClient(timeout=10) as _c:
                info_r = await _c.get(f"https://api.telegram.org/bot{BOT_TOKEN}/getWebhookInfo")
                current_url = info_r.json().get("result", {}).get("url", "")

                if "onrender.com" in current_url:
                    # ইতিমধ্যেই Render-এ ছিল — restart এর পর re-confirm করছি
                    _r_payload = {"url": webhook_url, "drop_pending_updates": True, "max_connections": 40,
                                  "allowed_updates": ["message", "callback_query", "poll_answer", "poll", "chat_member", "chat_join_request"]}
                    if WEBHOOK_SECRET:
                        _r_payload["secret_token"] = WEBHOOK_SECRET
                    r = await _c.post(
                        f"https://api.telegram.org/bot{BOT_TOKEN}/setWebhook",
                        json=_r_payload
                    )
                    result = r.json()
                    if result.get("ok"):
                        logger.info(f"[App] ✅ Render webhook re-confirmed → {webhook_url}")
                    else:
                        logger.warning(f"[App] Render webhook failed: {result.get('description')}")
                else:
                    logger.info(f"[App] Webhook currently on '{current_url}' (not Render) — leaving as-is, CF cron handles failover")
        else:
            # HF তে আছি — webhook CF Worker URL-এ থাকা উচিত, প্রতি startup-এ verify+force-set করি
            # (direct api.telegram.org call HF-এ blocked, tai tg_post() proxy babohar)
            worker_webhook = CF_WORKER_URL.rstrip("/") + "/webhook"
            info_r = await tg_post("getWebhookInfo", {})
            current_url = info_r.get("result", {}).get("url", "")

            if current_url != worker_webhook or WEBHOOK_SECRET:
                _wh_payload = {"url": worker_webhook, "drop_pending_updates": True, "max_connections": 40,
                               "allowed_updates": ["message", "callback_query", "poll_answer", "poll", "chat_member", "chat_join_request"]}
                if WEBHOOK_SECRET:
                    _wh_payload["secret_token"] = WEBHOOK_SECRET
                result = await tg_post("setWebhook", _wh_payload)
                if result.get("ok"):
                    logger.info(f"[App] ✅ HF: webhook set → {worker_webhook} (secret={'yes' if WEBHOOK_SECRET else 'no'})")
                else:
                    logger.warning(f"[App] HF: webhook correction failed: {result.get('description')}")
            else:
                logger.info(f"[App] HF: webhook already correct → {worker_webhook}")
    except Exception as e:
        logger.error(f"[App] Webhook setup error: {e}")

    try:
        ok = False
        for attempt in range(3):
            ok, admin_ok, admin_total = await set_bot_commands()
            if ok:
                break
            logger.warning(f"[App] Command menu setup attempt {attempt+1}/3 failed, retrying...")
            await asyncio.sleep(2 * (attempt + 1))
        logger.info(f"[App] Command menu set on startup: default={ok}, admins={admin_ok}/{admin_total}")
        if not ok:
            await notify_owner("⚠️ Command menu (/) setup failed after 3 retries on startup — bot commands list may be stale/missing. Run /setcommand manually to fix.")
    except Exception as e:
        logger.error(f"[App] Failed to set command menu on startup: {e}")
    try:
        await _recover_rapid_jobs()
    except Exception as e:
        logger.error(f"[App] /rapid job recovery failed: {e}")


